package com.example.fieldtrack.domain.convergence
import com.example.fieldtrack.data.local.entity.PricingMode import com.example.fieldtrack.domain.billing.BillingModeDefinition import com.example.fieldtrack.domain.billing.BillingModeRegistry import com.example.fieldtrack.domain.billing.QuantityPresentation import com.example.fieldtrack.domain.billing.WorkQuantitySummary import com.example.fieldtrack.domain.job.BillingMode import com.example.fieldtrack.domain.job.JobCapability import com.example.fieldtrack.domain.job.JobPhase
/** * ARCHITECTURAL CONVERGENCE — PART 2: Canonical Presentation Pipeline. * * ONE entry point for ALL operational presentation formatting. * Delegates to QuantityPresentation and WorkQuantitySummary internally * but provides a unified, deterministic interface. * * Responsibilities: * - hero value * - compact value * - toolbar subtitle * - resume label * - operational identity * - quantity formatting * - accessibility labels * - timeline labels * * Pure logic, zero Android dependencies. */ object CanonicalOperationalPresentation {
/** * Full operational presentation for an active workspace. * This is the ONLY function that active UI should call. */ fun forActiveWork( phase: JobPhase, capability: JobCapability?, billingMode: BillingMode?, machineName: String?, customerName: String?, quantity: Number = 0, rate: Double = 0.0, totalAmount: Double = 0.0, elapsedFormatted: String = "00:00:00", fatigueLevel: Int = 0 ): ActivePresentation { val def = billingMode?.let { BillingModeRegistry.getDefinition(it) } val emoji = capability?.emoji ?: def?.emoji ?: ""
// Quantity presentation val quantityPres = if (def != null) { QuantityPresentation.from(def, quantity, rate, totalAmount) } else null
// Toolbar subtitle val subtitle = when { phase == JobPhase.PAUSED -> "⏸ Paused" phase == JobPhase.SAVING -> "Saving…" phase == JobPhase.SAVED -> "✓ Saved" phase == JobPhase.SETUP -> "Setting up" quantityPres != null -> quantityPres.operationalSubtitle else -> "" }
// Hero value val heroValue = when { phase == JobPhase.PAUSED -> quantityPres?.heroValue ?: "⏸" def?.supportsTimer == true -> elapsedFormatted quantityPres != null -> quantityPres.heroValue else -> "—" }
// Hero label val heroLabel = when { phase == JobPhase.PAUSED -> "paused" quantityPres != null -> quantityPres.heroLabel else -> "" }
// Identity line val identityLine = buildIdentityLine(emoji, capability, machineName, customerName)
// Resume label val resumeLabel = when { phase == JobPhase.PAUSED -> "$emoji ⏸ Paused" quantityPres != null -> quantityPres.resumeLabel else -> "$emoji Resume" }
// Compact operational val compactValue = when { fatigueLevel >= 3 -> quantityPres?.compactOperational ?: heroValue quantityPres != null -> quantityPres.compactSummary else -> subtitle }
// Accessibility label val accessibilityLabel = buildString { capability?.let { append("${it.displayName}. ") } customerName?.let { append("Customer: $it. ") } machineName?.let { append("Machine: $it. ") } quantityPres?.let { append(it.heroAccessibilityLabel) } }
return ActivePresentation( heroValue = heroValue, heroLabel = heroLabel, toolbarSubtitle = subtitle, identityLine = identityLine, resumeLabel = resumeLabel, compactValue = compactValue, emoji = emoji, accessibilityLabel = accessibilityLabel, billingSummary = quantityPres?.billingSummary ?: "—" ) }
/** * Presentation for a completed/historical work. * Used in SummaryScreen, CustomerDetails, exports. */ fun forCompletedWork( pricingMode: PricingMode, capability: JobCapability?, customerName: String?, durationMinutes: Int = 0, elapsedFormatted: String = "00:00:00", loadCount: Int = 0, packetCount: Int = 0, acreQuantity: Double = 0.0, distanceKm: Double = 0.0, finalAmount: Double = 0.0 ): CompletedPresentation { val summary = WorkQuantitySummary.from( pricingMode = pricingMode, durationMinutes = durationMinutes, elapsedFormatted = elapsedFormatted, loadCount = loadCount, packetCount = packetCount, acreQuantity = acreQuantity, distanceKm = distanceKm, finalAmount = finalAmount ) val emoji = capability?.emoji ?: summary.emoji
return CompletedPresentation( primary = summary.primary, compact = summary.compact, heroValue = summary.heroValue, heroLabel = summary.heroLabel, emoji = emoji, timelineLabel = "${capability?.displayName ?: "Work"} — ${summary.compact}", customerLabel = customerName ?: "Unknown" ) }
private fun buildIdentityLine( emoji: String, capability: JobCapability?, machineName: String?, customerName: String? ): String = buildString { append(emoji) append(" ") val parts = listOfNotNull( capability?.displayName, machineName, customerName ) append(parts.joinToString(" • ")) } }
/** * Presentation state for an active/in-progress workspace. */ data class ActivePresentation( val heroValue: String, val heroLabel: String, val toolbarSubtitle: String, val identityLine: String, val resumeLabel: String, val compactValue: String, val emoji: String, val accessibilityLabel: String, val billingSummary: String )
/** * Presentation state for a completed/historical work. */ data class CompletedPresentation( val primary: String, val compact: String, val heroValue: String, val heroLabel: String, val emoji: String, val timelineLabel: String, val customerLabel: String )

package com.example.fieldtrack.domain.convergence
import com.example.fieldtrack.data.local.entity.PricingMode import com.example.fieldtrack.domain.billing.BillingModeRegistry import com.example.fieldtrack.domain.billing.QuantityPresentation import com.example.fieldtrack.domain.billing.WorkQuantitySummary import com.example.fieldtrack.domain.job.BillingMode import com.example.fieldtrack.domain.job.JobCapability import com.example.fieldtrack.domain.job.JobPhase
/** * ARCHITECTURAL CONVERGENCE — PART 2: Canonical Presentation Pipeline. * * ONE entry point for ALL operational presentation formatting. * Delegates to QuantityPresentation and WorkQuantitySummary internally * but provides a unified, deterministic interface. * * Responsibilities: * - hero value * - compact value * - toolbar subtitle * - resume label * - operational identity * - quantity formatting * - accessibility labels * - timeline labels * * Pure logic, zero Android dependencies. */ object CanonicalOperationalPresentation {
/** * Full operational presentation for an active workspace. * This is the ONLY function that active UI should call. */ fun forActiveWork( phase: JobPhase, capability: JobCapability?, billingMode: BillingMode?, machineName: String?, customerName: String?, quantity: Number = 0, rate: Double = 0.0, totalAmount: Double = 0.0, elapsedFormatted: String = "00:00:00", fatigueLevel: Int = 0 ): ActivePresentation { val def = billingMode?.let { BillingModeRegistry.getDefinition(it) } val emoji = capability?.emoji ?: def?.emoji ?: ""
// Quantity presentation val quantityPres = if (def != null) { QuantityPresentation.from(def, quantity, rate, totalAmount) } else null
// Toolbar subtitle val subtitle = when { phase == JobPhase.PAUSED -> "⏸ Paused" phase == JobPhase.SAVING -> "Saving…" phase == JobPhase.SAVED -> "✓ Saved" phase == JobPhase.SETUP -> "Setting up" quantityPres != null -> quantityPres.operationalSubtitle else -> "" }
// Hero value val heroValue = when { phase == JobPhase.PAUSED -> quantityPres?.heroValue ?: "⏸" def?.supportsTimer == true -> elapsedFormatted quantityPres != null -> quantityPres.heroValue else -> "—" }
// Hero label val heroLabel = when { phase == JobPhase.PAUSED -> "paused" quantityPres != null -> quantityPres.heroLabel else -> "" }
// Identity line val identityLine = buildIdentityLine(emoji, capability, machineName, customerName)
// Resume label val resumeLabel = when { phase == JobPhase.PAUSED -> "$emoji ⏸ Paused" quantityPres != null -> quantityPres.resumeLabel else -> "$emoji Resume" }
// Compact operational val compactValue = when { fatigueLevel >= 3 -> quantityPres?.compactOperational ?: heroValue quantityPres != null -> quantityPres.compactSummary else -> subtitle }
// Accessibility label val accessibilityLabel = buildString { capability?.let { append("${it.displayName}. ") } customerName?.let { append("Customer: $it. ") } machineName?.let { append("Machine: $it. ") } quantityPres?.let { append(it.heroAccessibilityLabel) } }
return ActivePresentation( heroValue = heroValue, heroLabel = heroLabel, toolbarSubtitle = subtitle, identityLine = identityLine, resumeLabel = resumeLabel, compactValue = compactValue, emoji = emoji, accessibilityLabel = accessibilityLabel, billingSummary = quantityPres?.billingSummary ?: "—" ) }
/** * Presentation for a completed/historical work. * Used in SummaryScreen, CustomerDetails, exports. */ fun forCompletedWork( pricingMode: PricingMode, capability: JobCapability?, customerName: String?, durationMinutes: Int = 0, elapsedFormatted: String = "00:00:00", loadCount: Int = 0, packetCount: Int = 0, acreQuantity: Double = 0.0, distanceKm: Double = 0.0, finalAmount: Double = 0.0 ): CompletedPresentation { val summary = WorkQuantitySummary.from( pricingMode = pricingMode, durationMinutes = durationMinutes, elapsedFormatted = elapsedFormatted, loadCount = loadCount, packetCount = packetCount, acreQuantity = acreQuantity, distanceKm = distanceKm, finalAmount = finalAmount ) val emoji = capability?.emoji ?: summary.emoji
return CompletedPresentation( primary = summary.primary, compact = summary.compact, heroValue = summary.heroValue, heroLabel = summary.heroLabel, emoji = emoji, timelineLabel = "${capability?.displayName ?: "Work"} — ${summary.compact}", customerLabel = customerName ?: "Unknown" ) }
private fun buildIdentityLine( emoji: String, capability: JobCapability?, machineName: String?, customerName: String? ): String = buildString { append(emoji) append(" ") val parts = listOfNotNull( capability?.displayName, machineName, customerName ) append(parts.joinToString(" • ")) } }
/** * Presentation state for an active/in-progress workspace. */ data class ActivePresentation( val heroValue: String, val heroLabel: String, val toolbarSubtitle: String, val identityLine: String, val resumeLabel: String, val compactValue: String, val emoji: String, val accessibilityLabel: String, val billingSummary: String )
/** * Presentation state for a completed/historical work. */ data class CompletedPresentation( val primary: String, val compact: String, val heroValue: String, val heroLabel: String, val emoji: String, val timelineLabel: String, val customerLabel: String )

