/**
 * Shared customer-level payment bottom sheet.
 * Used from both CustomerDetailsScreen and EditJobScreen.
 *
 * Payment applies to the entire customer due (FIFO across all jobs).
 *
 * @param customerName The customer's display name
 * @param totalDue Total amount due across all customer jobs
 * @param contextHint Optional context hint (e.g., "From: Tractor job")
 * @param paymentInput Current payment input text
 * @param onPaymentInputChange Callback for amount text changes
 * @param selectedMethod Currently selected payment method
 * @param onMethodChange Callback for method selection
 * @param note Current note text
 * @param onNoteChange Callback for note changes
 * @param isSaving Whether a save is in progress
 * @param onConfirm Callback to confirm payment
 * @param onDismiss Callback to dismiss sheet
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustomerPaymentSheet(
    customerName: String,
    totalDue: Double,
    contextHint: String? = null,
    paymentMode: PaymentMode = PaymentMode.PAY_ALL_DUES,
    onPaymentModeChange: ((PaymentMode) -> Unit)? = null,
    isModeLocked: Boolean = false,
    jobRemaining: Double = 0.0,
    otherJobsDue: Double = 0.0,
    paymentModeHint: String? = null,
    paymentInput: String,
    onPaymentInputChange: (String) -> Unit,
    selectedMethod: PaymentMethod,
    onMethodChange: (PaymentMethod) -> Unit,
    note: String,
    onNoteChange: (String) -> Unit,
    isSaving: Boolean,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit
) {
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    val focusRequester = remember { FocusRequester() }
    val keyboardController = LocalSoftwareKeyboardController.current

    val inputAmount = paymentInput.toDoubleOrNull() ?: 0.0
    val effectiveCap = if (paymentMode == PaymentMode.PAY_THIS_JOB && jobRemaining > 0) jobRemaining else totalDue
    val willApply = minOf(inputAmount, effectiveCap).coerceAtLeast(0.0)
    val exceedsCap = paymentInput.isNotEmpty() && inputAmount > effectiveCap
    val isValid = inputAmount > 0 && !isSaving &&
        !(paymentMode == PaymentMode.PAY_THIS_JOB && jobRemaining <= 0)
    // PART 6: Hide PAY_THIS_JOB when job is already paid
    val showModeToggle = onPaymentModeChange != null && otherJobsDue > 0 && jobRemaining > 0

    // Animation for chip selection
    var lastSelectedChip by remember { mutableStateOf<String?>(null) }
    val chipScale by animateFloatAsState(
        targetValue = if (lastSelectedChip != null) 1.05f else 1f,
        animationSpec = tween(100),
        finishedListener = { lastSelectedChip = null },
        label = "chipScale"
    )

    // Note field expansion state
    var isNoteExpanded by remember { mutableStateOf(note.isNotEmpty()) }

    // Dismiss confirmation dialog state
    var showDiscardDialog by remember { mutableStateOf(false) }

    // Focus state for empty input hint
    var isAmountFocused by remember { mutableStateOf(false) }

    // Shake animation for invalid input
    val shakeOffset = remember { Animatable(0f) }
    var showInvalidHint by remember { mutableStateOf(false) }

    // CTA press animation
    val ctaInteractionSource = remember { MutableInteractionSource() }
    val isCtaPressed by ctaInteractionSource.collectIsPressedAsState()
    val ctaScale by animateFloatAsState(
        targetValue = if (isCtaPressed) 0.97f else 1f,
        animationSpec = tween(100),
        label = "ctaScale"
    )

    // Handle dismiss with confirmation (only for Cancel button, not system gestures)
    val handleCancelClick: () -> Unit = {
        if (!isSaving && inputAmount > 0) {
            showDiscardDialog = true
        } else if (!isSaving) {
            onDismiss()
        }
    }

    // Focus the amount input on open
    LaunchedEffect(Unit) {
        focusRequester.requestFocus()
    }

    // Shake animation trigger
    suspend fun triggerShake() {
        showInvalidHint = true
        for (i in 0 until 4) {
            shakeOffset.animateTo(
                targetValue = if (i % 2 == 0) 8f else -8f,
                animationSpec = spring(stiffness = 2000f)
            )
        }
        shakeOffset.animateTo(0f)
        delay(2000)
        showInvalidHint = false
    }

    // Discard confirmation dialog
    if (showDiscardDialog) {
        AlertDialog(
            onDismissRequest = { showDiscardDialog = false },
            title = { Text(stringResource(R.string.payment_discard_title)) },
            text = {
                Text(stringResource(R.string.payment_discard_message, formatAmountWithCommas(inputAmount)))
            },
            confirmButton = {
                Button(
                    onClick = {
                        showDiscardDialog = false
                        onDismiss()
                    },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = MaterialTheme.colorScheme.error
                    )
                ) {
                    Text(stringResource(R.string.payment_discard_button))
                }
            },
            dismissButton = {
                TextButton(onClick = { showDiscardDialog = false }) {
                    Text(stringResource(R.string.payment_keep_editing))
                }
            }
        )
    }

    val scope = rememberCoroutineScope()

    ModalBottomSheet(
        onDismissRequest = { if (!isSaving) onDismiss() },
        sheetState = sheetState
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp)
                .padding(bottom = 16.dp)
                .navigationBarsPadding()
                .imePadding(),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            // ====== HEADER ======
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    text = " Add Payment",
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(4.dp))
                Text(
                    text = "$customerName • ${formatAmountWithCommas(totalDue)} total due",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )

                // Context hint
                if (contextHint != null) {
                    Spacer(Modifier.height(6.dp))
                    Surface(
                        shape = RoundedCornerShape(8.dp),
                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f)
                    ) {
                        Text(
                            text = contextHint,
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                        )
                    }
                }

                // PART 1: Payment Mode Toggle
                if (showModeToggle) {
                    Spacer(Modifier.height(10.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp, Alignment.CenterHorizontally)
                    ) {
                        PaymentModeChip(
                            label = "This Job",
                            subtitle = formatAmountWithCommas(jobRemaining),
                            isSelected = paymentMode == PaymentMode.PAY_THIS_JOB,
                            enabled = !isSaving,
                            onClick = { onPaymentModeChange?.invoke(PaymentMode.PAY_THIS_JOB) }
                        )
                        PaymentModeChip(
                            label = "All Dues",
                            subtitle = formatAmountWithCommas(totalDue),
                            isSelected = paymentMode == PaymentMode.PAY_ALL_DUES,
                            enabled = !isSaving,
                            onClick = { onPaymentModeChange?.invoke(PaymentMode.PAY_ALL_DUES) }
                        )
                    }
                }
            }

            Spacer(Modifier.height(4.dp))
            HorizontalDivider()
            Spacer(Modifier.height(4.dp))

            // ====== AMOUNT INPUT SECTION ======
            Column(modifier = Modifier.fillMaxWidth()) {
                // Mode label + lock indicator (PART 1)
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = if (paymentMode == PaymentMode.PAY_THIS_JOB)
                            "Paying for this job only"
                        else
                            "Paying across all dues",
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.8f)
                    )
                    if (isModeLocked) {
                        Spacer(Modifier.width(6.dp))
                        Text(
                            text = "",
                            style = MaterialTheme.typography.labelSmall
                        )
                    }
                }
                // Max hint
                val maxAmount = if (paymentMode == PaymentMode.PAY_THIS_JOB) jobRemaining else totalDue
                if (maxAmount > 0) {
                    Text(
                        text = "Max: ${formatAmountWithCommas(maxAmount)}",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.5f)
                    )
                }
                // Mode switch / clamp hint (PART 2 + 4)
                if (paymentModeHint != null) {
                    Text(
                        text = paymentModeHint,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.tertiary,
                        fontWeight = FontWeight.Medium
                    )
                }
                Spacer(Modifier.height(8.dp))

                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .graphicsLayer { translationX = shakeOffset.value },
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                    tonalElevation = 2.dp
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 20.dp, vertical = 16.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = "₹",
                            style = MaterialTheme.typography.headlineMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Spacer(Modifier.width(12.dp))
                        BasicTextField(
                            value = paymentInput,
                            onValueChange = { newValue ->
                                val filtered = newValue.filter { it.isDigit() || it == '.' }
                                if (filtered.count { it == '.' } <= 1) {
                                    onPaymentInputChange(filtered)
                                    showInvalidHint = false
                                }
                            },
                            modifier = Modifier
                                .focusRequester(focusRequester)
                                .onFocusChanged { isAmountFocused = it.isFocused }
                                .weight(1f),
                            textStyle = LocalTextStyle.current.copy(
                                fontSize = 32.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface,
                                textAlign = TextAlign.Start
                            ),
                            keyboardOptions = KeyboardOptions(
                                keyboardType = KeyboardType.Decimal,
                                imeAction = ImeAction.Done
                            ),
                            keyboardActions = KeyboardActions(
                                onDone = {
                                    keyboardController?.hide()
                                    if (isValid) {
                                        onConfirm()
                                    } else {
                                        scope.launch { triggerShake() }
                                    }
                                }
                            ),
                            singleLine = true,
                            enabled = !isSaving,
                            cursorBrush = SolidColor(MaterialTheme.colorScheme.primary),
                            decorationBox = { innerTextField ->
                                Box(contentAlignment = Alignment.CenterStart) {
                                    if (paymentInput.isEmpty()) {
                                        Text(
                                            text = "0",
                                            style = LocalTextStyle.current.copy(
                                                fontSize = 32.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f),
                                                textAlign = TextAlign.Start
                                            )
                                        )
                                    }
                                    innerTextField()
                                }
                            }
                        )

                        if (paymentInput.isNotEmpty() && inputAmount > 0) {
                            Text(
                                text = formatAmountWithCommas(inputAmount),
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                            )
                        }
                    }
                }

                // Empty input hint when focused
                AnimatedVisibility(
                    visible = paymentInput.isEmpty() && isAmountFocused,
                    enter = fadeIn() + expandVertically(),
                    exit = fadeOut() + shrinkVertically()
                ) {
                    Text(
                        text = "Enter amount to continue",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                        modifier = Modifier.padding(start = 4.dp, top = 6.dp)
                    )
                }

                // Invalid input hint after shake
                AnimatedVisibility(
                    visible = showInvalidHint && (paymentInput.isEmpty() || inputAmount <= 0),
                    enter = fadeIn() + expandVertically(),
                    exit = fadeOut() + shrinkVertically()
                ) {
                    Text(
                        text = "Please enter a valid amount",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.error,
                        modifier = Modifier.padding(start = 4.dp, top = 6.dp)
                    )
                }

                // Overpayment / cap warning (PART 4)
                AnimatedVisibility(
                    visible = exceedsCap,
                    enter = fadeIn() + expandVertically(),
                    exit = fadeOut() + shrinkVertically()
                ) {
                    Text(
                        text = if (paymentMode == PaymentMode.PAY_THIS_JOB)
                            "Only ${formatAmountWithCommas(jobRemaining)} will be applied to this job"
                        else
                            "Only ${formatAmountWithCommas(totalDue)} due • Extra won't be applied",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.error.copy(alpha = 0.8f),
                        modifier = Modifier.padding(start = 4.dp, top = 6.dp)
                    )
                }

                // PART 3: Always-on compact preview
                if (inputAmount > 0 && jobRemaining > 0) {
                    Spacer(Modifier.height(6.dp))
                    val previewThisJob = minOf(inputAmount, jobRemaining)
                    val previewOther = if (paymentMode == PaymentMode.PAY_THIS_JOB) 0.0
                    else minOf((inputAmount - previewThisJob).coerceAtLeast(0.0), otherJobsDue)
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "This job ${formatAmountWithCommas(previewThisJob)}",
                            style = MaterialTheme.typography.labelSmall,
                            fontWeight = FontWeight.Medium,
                            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f)
                        )
                        Text("|", style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.3f))
                        Text(
                            text = "Other dues ${formatAmountWithCommas(previewOther)}",
                            style = MaterialTheme.typography.labelSmall,
                            fontWeight = FontWeight.Medium,
                            color = if (previewOther > 0) MaterialTheme.colorScheme.tertiary.copy(alpha = 0.7f)
                            else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f)
                        )
                    }
                }

                Spacer(Modifier.height(12.dp))

                // Quick amount chips — mode-aware
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp, Alignment.CenterHorizontally)
                ) {
                    // "Full" chip — caps at effective amount for mode
                    // PART AF — Double-tap "Full" chip auto-submits (speed mode)
                    val fullAmount = effectiveCap
                    val isFullSelected = paymentInput == fullAmount.toLong().toString()
                    QuickAmountChip(
                        label = "Full ${formatAmountWithCommas(fullAmount)}",
                        isSelected = isFullSelected,
                        enabled = !isSaving && fullAmount > 0,
                        scale = if (lastSelectedChip == "full") chipScale else 1f,
                        onClick = {
                            lastSelectedChip = "full"
                            if (isFullSelected) {
                                // PART AF — Already selected, confirm immediately
                                onConfirm()
                            } else {
                                onPaymentInputChange(fullAmount.toLong().toString())
                            }
                        }
                    )

                    if (effectiveCap >= 500) {
                        QuickAmountChip(
                            label = "₹500",
                            isSelected = paymentInput == "500",
                            enabled = !isSaving,
                            scale = if (lastSelectedChip == "500") chipScale else 1f,
                            onClick = {
                                lastSelectedChip = "500"
                                onPaymentInputChange("500")
                            }
                        )
                    }

                    if (effectiveCap >= 1000) {
                        QuickAmountChip(
                            label = "₹1,000",
                            isSelected = paymentInput == "1000",
                            enabled = !isSaving,
                            scale = if (lastSelectedChip == "1000") chipScale else 1f,
                            onClick = {
                                lastSelectedChip = "1000"
                                onPaymentInputChange("1000")
                            }
                        )
                    }

                    if (effectiveCap >= 2000) {
                        QuickAmountChip(
                            label = "₹2,000",
                            isSelected = paymentInput == "2000",
                            enabled = !isSaving,
                            scale = if (lastSelectedChip == "2000") chipScale else 1f,
                            onClick = {
                                lastSelectedChip = "2000"
                                onPaymentInputChange("2000")
                            }
                        )
                    }
                }
            }

            Spacer(Modifier.height(4.dp))

            // ====== PAYMENT METHOD SECTION ======
            Column(modifier = Modifier.fillMaxWidth()) {
                Text(
                    text = "Payment Method",
                    style = MaterialTheme.typography.labelLarge,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
                Spacer(Modifier.height(8.dp))

                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        PaymentMethod.entries.take(2).forEach { method ->
                            PaymentMethodChip(
                                method = method,
                                isSelected = method == selectedMethod,
                                enabled = !isSaving,
                                onClick = { onMethodChange(method) },
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        PaymentMethod.entries.drop(2).forEach { method ->
                            PaymentMethodChip(
                                method = method,
                                isSelected = method == selectedMethod,
                                enabled = !isSaving,
                                onClick = { onMethodChange(method) },
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                }
            }

            Spacer(Modifier.height(4.dp))

            // ====== NOTE FIELD ======
            AnimatedVisibility(
                visible = isNoteExpanded,
                enter = fadeIn(animationSpec = tween(200)) + expandVertically(animationSpec = tween(200)),
                exit = fadeOut(animationSpec = tween(150)) + shrinkVertically(animationSpec = tween(150))
            ) {
                OutlinedTextField(
                    value = note,
                    onValueChange = onNoteChange,
                    modifier = Modifier.fillMaxWidth(),
                    placeholder = { Text(stringResource(R.string.payment_add_note_hint)) },
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp),
                    enabled = !isSaving,
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                    keyboardActions = KeyboardActions(
                        onDone = {
                            keyboardController?.hide()
                            if (isValid) onConfirm()
                        }
                    ),
                    trailingIcon = {
                        if (note.isEmpty()) {
                            IconButton(onClick = { isNoteExpanded = false }) {
                                Icon(
                                    Icons.AutoMirrored.Filled.ArrowBack,
                                    contentDescription = "Hide note",
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }
                    }
                )
            }

            AnimatedVisibility(
                visible = !isNoteExpanded,
                enter = fadeIn(animationSpec = tween(200)) + expandVertically(animationSpec = tween(200)),
                exit = fadeOut(animationSpec = tween(150)) + shrinkVertically(animationSpec = tween(150))
            ) {
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable(enabled = !isSaving) { isNoteExpanded = true },
                    shape = RoundedCornerShape(12.dp),
                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 16.dp, vertical = 14.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            Icons.Filled.Add,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            tint = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Spacer(Modifier.width(8.dp))
                        Text(
                            text = "Add note",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }

            Spacer(Modifier.height(12.dp))

            // ====== ACTION BUTTONS ======
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                TextButton(
                    onClick = handleCancelClick,
                    enabled = !isSaving,
                    modifier = Modifier.weight(1f)
                ) {
                    Text(stringResource(R.string.action_cancel))
                }

                Button(
                    onClick = onConfirm,
                    enabled = isValid,
                    modifier = Modifier
                        .weight(2f)
                        .height(48.dp)
                        .graphicsLayer {
                            scaleX = ctaScale
                            scaleY = ctaScale
                        },
                    shape = RoundedCornerShape(12.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = MaterialTheme.colorScheme.primary
                    ),
                    interactionSource = ctaInteractionSource
                ) {
                    Box(
                        modifier = Modifier.fillMaxWidth(),
                        contentAlignment = Alignment.Center
                    ) {
                        if (isSaving) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.Center
                            ) {
                                CircularProgressIndicator(
                                    modifier = Modifier.size(18.dp),
                                    strokeWidth = 2.dp,
                                    color = MaterialTheme.colorScheme.onPrimary
                                )
                                Spacer(Modifier.width(8.dp))
                                Text("Adding…", fontWeight = FontWeight.Bold)
                            }
                        } else {
                            Text(
                                text = if (inputAmount > 0) {
                                    if (paymentMode == PaymentMode.PAY_THIS_JOB)
                                        "Pay ${formatAmountWithCommas(willApply)} for this job"
                                    else
                                        "Pay ${formatAmountWithCommas(willApply)} across dues"
                                } else {
                                    "Add Payment"
                                },
                                fontWeight = FontWeight.Bold,
                                maxLines = 1
                            )
                        }
                    }
                }
            }

            // Trust footer
            Spacer(Modifier.height(8.dp))
            Text(
                text = " Payments are securely recorded",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.5f),
                textAlign = TextAlign.Center,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

// ================== Helper Composables ==================

/**
 * Formats amount with ₹ symbol and thousand separators (Indian locale).
 */
fun formatAmountWithCommas(amount: Double): String {
    val longAmount = amount.toLong()
    val formatted = java.text.NumberFormat.getNumberInstance(java.util.Locale("en", "IN"))
        .format(longAmount)
    return "₹$formatted"
}

@Composable
private fun QuickAmountChip(
    label: String,
    isSelected: Boolean,
    enabled: Boolean,
    scale: Float,
    onClick: () -> Unit
) {
    val backgroundColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.primaryContainer
        else MaterialTheme.colorScheme.surfaceVariant,
        animationSpec = tween(200),
        label = "chipBg"
    )
    val contentColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer
        else MaterialTheme.colorScheme.onSurfaceVariant,
        animationSpec = tween(200),
        label = "chipContent"
    )

    Surface(
        modifier = Modifier
            .scale(scale)
            .clickable(enabled = enabled, onClick = onClick),
        shape = RoundedCornerShape(20.dp),
        color = backgroundColor,
        tonalElevation = if (isSelected) 4.dp else 0.dp
    ) {
        Text(
            text = label,
            modifier = Modifier.padding(horizontal = 14.dp, vertical = 8.dp),
            style = MaterialTheme.typography.labelMedium,
            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
            color = contentColor,
            maxLines = 1
        )
    }
}

@Composable
private fun PaymentMethodChip(
    method: PaymentMethod,
    isSelected: Boolean,
    enabled: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val backgroundColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.primaryContainer
        else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f),
        animationSpec = tween(200),
        label = "methodBg"
    )
    val borderColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.primary
        else MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
        animationSpec = tween(200),
        label = "methodBorder"
    )
    val chipScale by animateFloatAsState(
        targetValue = if (isSelected) 1.03f else 1f,
        animationSpec = tween(150),
        label = "methodScale"
    )

    Surface(
        modifier = modifier
            .scale(chipScale)
            .clickable(enabled = enabled, onClick = onClick)
            .border(
                width = if (isSelected) 2.dp else 1.dp,
                color = borderColor,
                shape = RoundedCornerShape(12.dp)
            ),
        shape = RoundedCornerShape(12.dp),
        color = backgroundColor,
        tonalElevation = if (isSelected) 6.dp else 0.dp
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 12.dp),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(text = method.emoji, style = MaterialTheme.typography.titleMedium)
            Spacer(Modifier.width(6.dp))
            Text(
                text = method.displayName,
                style = MaterialTheme.typography.labelLarge,
                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer
                else MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}


@Composable
private fun PaymentModeChip(
    label: String,
    subtitle: String,
    isSelected: Boolean,
    enabled: Boolean,
    onClick: () -> Unit
) {
    val backgroundColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.primaryContainer
        else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f),
        animationSpec = tween(200),
        label = "modeBg"
    )
    val borderColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.primary
        else MaterialTheme.colorScheme.outline.copy(alpha = 0.3f),
        animationSpec = tween(200),
        label = "modeBorder"
    )

    Surface(
        modifier = Modifier
            .clickable(enabled = enabled, onClick = onClick)
            .border(
                width = if (isSelected) 2.dp else 1.dp,
                color = borderColor,
                shape = RoundedCornerShape(12.dp)
            ),
        shape = RoundedCornerShape(12.dp),
        color = backgroundColor,
        tonalElevation = if (isSelected) 4.dp else 0.dp
    ) {
        Column(
            modifier = Modifier.padding(horizontal = 20.dp, vertical = 10.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = label,
                style = MaterialTheme.typography.labelLarge,
                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer
                else MaterialTheme.colorScheme.onSurfaceVariant
            )
            Text(
                text = subtitle,
                style = MaterialTheme.typography.labelSmall,
                color = if (isSelected) MaterialTheme.colorScheme.primary
                else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
            )
        }
    }
}

package com.example.fieldtrack.ui.theme
/** * PART 10 — Ultra Quiet Mode styling utilities. * * As session extends, UI progressively calms down: * - Level 0 (0-2h): Fresh — full UI * - Level 1 (2-4h): Working — helper text slightly faded * - Level 2 (4-8h): Deep Session — helper text strongly muted * - Level 3 (8-12h): Quiet Mode — non-essential labels hidden * - Level 4 (12h+): Ultra Quiet — almost all labels hidden, timer dominates * * Ultra Quiet Mode (12h+) hides: * - Section subtitles * - Helper labels * - Non-essential chips * - Decorative icons * * Ultra Quiet Mode keeps ONLY: * - Operational identity * - Timer/quantity * - Primary actions * - Recovery-critical information * * Goal: Reduce eye strain on long rural work days. * Operational controls remain full contrast always. */ object FatigueStyling {
/** * Get text alpha for helper/secondary text at this fatigue level. */ fun helperTextAlpha(fatigueLevel: Int): Float = when (fatigueLevel) { 0 -> 0.7f // Normal 1 -> 0.5f // Slightly faded 2 -> 0.35f // Strongly muted 3 -> 0.2f // Barely visible else -> 0.1f // Almost hidden }
/** * Get text alpha for section titles at this fatigue level. */ fun sectionTitleAlpha(fatigueLevel: Int): Float = when (fatigueLevel) { 0 -> 0.9f 1 -> 0.7f 2 -> 0.5f 3 -> 0.3f else -> 0.15f }
/** * Get text alpha for operational controls (always visible). */ fun operationalControlAlpha(fatigueLevel: Int): Float = when (fatigueLevel) { in 0..1 -> 1.0f 2 -> 0.95f 3 -> 0.9f else -> 0.85f // Still high contrast for controls }
/** * Get vertical spacing reduction at this fatigue level. * UI gradually compresses to reduce scrolling. */ fun spacingMultiplier(fatigueLevel: Int): Float = when (fatigueLevel) { 0 -> 1.0f 1 -> 0.9f 2 -> 0.8f 3 -> 0.7f else -> 0.6f }
/** * Whether to show helper hints at this fatigue level. */ fun showHelperHints(fatigueLevel: Int): Boolean = fatigueLevel <= 2
/** * Whether to show section headers at this fatigue level. */ fun showSectionHeaders(fatigueLevel: Int): Boolean = fatigueLevel <= 3
/** * Whether to show emoji decorations at this fatigue level. */ fun showDecorations(fatigueLevel: Int): Boolean = fatigueLevel <= 1
/** * PART 10: Whether to show section subtitles. * Hidden in Ultra Quiet Mode (12h+). */ fun showSectionSubtitles(fatigueLevel: Int): Boolean = fatigueLevel <= 3
/** * PART 10: Whether to show non-essential chips. * Hidden in Ultra Quiet Mode (12h+). */ fun showNonEssentialChips(fatigueLevel: Int): Boolean = fatigueLevel <= 3
/** * PART 10: Whether to show decorative icons (non-operational). * Hidden in Quiet Mode and beyond. */ fun showDecorativeIcons(fatigueLevel: Int): Boolean = fatigueLevel <= 2
/** * PART 10: Whether to show helper labels (explanatory text). * Hidden in Ultra Quiet Mode (12h+). */ fun showHelperLabels(fatigueLevel: Int): Boolean = fatigueLevel <= 3
/** * PART 9: Whether to show non-essential cards at this fatigue level. * After 8+ hours (level 3), collapse non-essential cards. * Critical actions (Finish, Resume, Payment, Undo) remain full contrast. */ fun showNonEssentialCards(fatigueLevel: Int): Boolean = fatigueLevel <= 2 }

package com.example.fieldtrack.ui.theme
/** * Fatigue-adapted alpha values for text styling. * * As session extends, UI progressively calms down: * - Level 0 (0-2h): Fresh — full UI * - Level 1 (2-4h): Working — helper text slightly faded * - Level 2 (4-8h): Deep Session — helper text strongly muted * - Level 3 (8-12h): Quiet Mode — non-essential labels hidden * - Level 4 (12h+): Ultra Quiet — almost all labels hidden * * NOTE: Visibility decisions now live in OperationalVisibilityModel. * This object provides raw alpha lookups only. */ object FatigueStyling {
/** Text alpha for helper/secondary text at this fatigue level. */ fun helperTextAlpha(fatigueLevel: Int): Float = when (fatigueLevel) { 0 -> 0.7f 1 -> 0.5f 2 -> 0.35f 3 -> 0.2f else -> 0.1f }
/** Text alpha for section titles at this fatigue level. */ fun sectionTitleAlpha(fatigueLevel: Int): Float = when (fatigueLevel) { 0 -> 0.9f 1 -> 0.7f 2 -> 0.5f 3 -> 0.3f else -> 0.15f } }

