/**
 * Home Screen - Main entry point of the app.
 *
 * Design principles:
 * - Glanceable dashboard
 * - Active job visibility first
 * - Quick actions accessible
 * - Financial clarity
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
fun HomeScreen(
    viewModel: HomeViewModel,
    onNewJobClick: () -> Unit,
    onNewJobForCustomer: (String) -> Unit = { _ -> onNewJobClick() },
    onOpenWorkspaceJob: (String) -> Unit = { _ -> onNewJobClick() },
    onRepeatRecentWork: (customerId: String, capability: String, rate: String, machineId: String?) -> Unit = { cid, _, _, _ -> onNewJobForCustomer(cid) },
    onTemplateClick: (String) -> Unit = {},
    onTodaySummaryClick: () -> Unit,
    onNavigateToJobsWithFilter: (DateFilter, PaymentFilter) -> Unit = { _, _ -> onTodaySummaryClick() },
    onNavigateToJobsGrouped: (DateFilter, PaymentFilter) -> Unit = { d, p -> onNavigateToJobsWithFilter(d, p) },
    onAddCustomerClick: () -> Unit,
    onViewCustomersClick: () -> Unit,
    onSettingsClick: () -> Unit = {},
    onDashboardAction: (DashboardAction, DashboardActionType) -> Unit = { _, _ -> },
    onJobClick: (Long) -> Unit = {},
    onCustomerClick: (String) -> Unit = {},
    onAddPaymentClick: (String) -> Unit = {},
    onAddPastWork: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val dashboard by viewModel.uiState.collectAsState()
    val activeJob by viewModel.activeJob.collectAsState()
    val customerName by viewModel.activeJobCustomerName.collectAsState()

    // PART 4/11: Active customer session (multi-job system)
    val activeSession by viewModel.activeCustomerSession.collectAsState()
    // Customer-grouped workspaces for the rail
    val customerWorkspaces by viewModel.customerWorkspaces.collectAsState()

    // PART 5+6: Customer workspace bottom sheet state
    var showWorkspaceSheet by remember { mutableStateOf(false) }
    var selectedWorkspace by remember { mutableStateOf<ActiveCustomerWorkspace?>(null) }

    // ====== Dashboard Action Sheet state (secondary — long press) ======
    var showActionSheet by remember { mutableStateOf(false) }
    var selectedActionType by remember { mutableStateOf<DashboardActionType?>(null) }
    val scope = rememberCoroutineScope()

    // ====== Dashboard Preview Sheet state (primary — tap) ======
    var showPreviewSheet by remember { mutableStateOf(false) }
    var previewType by remember { mutableStateOf<DashboardActionType?>(null) }
    val previewLoading by viewModel.previewLoading.collectAsState()
    val customerDuePreviews by viewModel.customerDuePreviews.collectAsState()
    val customerAmountPreviews by viewModel.customerAmountPreviews.collectAsState()

    // Multi-workspace: always allow new job creation without blocking dialog.
    // Existing active jobs remain untouched and accessible via workspace rail.
    val guardedNewJobClick: () -> Unit = {
        onNewJobClick()
    }

    val pendingSyncCount by viewModel.pendingSyncCount.collectAsState()
    val escalatedFailureCount by viewModel.escalatedFailureCount.collectAsState()

    // PART 1: Daily closure sheet
    val context = LocalContext.current
    val closurePrefs = remember { DailyClosurePreferences(context) }
    val showDailyClosure by viewModel.showDailyClosure.collectAsState()

    // PART 2: Needs attention
    val attentionItems by viewModel.attentionItems.collectAsState()

    // PART 7: Morning continuity banner
    val yesterdayActiveCount by viewModel.yesterdayActiveCount.collectAsState()
    val yesterdayWorkspaces by viewModel.yesterdayWorkspaces.collectAsState()

    // INLINE FINISH FLOW: Job being finished inline (null = no inline finish)
    val inlineFinishJob by viewModel.inlineFinishJob.collectAsState()

    // Check closure trigger after dashboard loads
    LaunchedEffect(dashboard.isLoading, dashboard.todayJobs) {
        if (!dashboard.isLoading) {
            viewModel.checkDailyClosure(closurePrefs.isDismissedToday())
        }
    }

    // Detect if user is brand new (no jobs ever)
    val isNewUser = !dashboard.isLoading &&
            dashboard.todayJobs == 0 &&
            dashboard.allTimeEarnings == 0.0 &&
            customerWorkspaces.isEmpty()

    // ====== Dashboard Action Sheet (long press — secondary) ======
    if (showActionSheet && selectedActionType != null) {
        val summaryData = remember(dashboard) {
            DashboardSummaryData(
                totalEarnings = dashboard.allTimeEarnings,
                totalCollected = dashboard.allTimeCollected,
                totalPending = dashboard.allTimePending,
                totalJobs = dashboard.todayJobs,
                todayEarnings = dashboard.todayEarnings,
                todayJobs = dashboard.todayJobs
            )
        }
        DashboardActionSheet(
            type = selectedActionType!!,
            summaryData = summaryData,
            onDismiss = {
                showActionSheet = false
                selectedActionType = null
            },
            onActionSelected = { action ->
                val type = selectedActionType!!
                showActionSheet = false
                selectedActionType = null
                scope.launch {
                    delay(100)
                    onDashboardAction(action, type)
                }
            }
        )
    }

    // ====== Dashboard Preview Sheet (tap — primary) ======
    if (showPreviewSheet && previewType != null) {
        DashboardPreviewSheet(
            type = previewType!!,
            customerDuePreviews = customerDuePreviews,
            customerAmountPreviews = customerAmountPreviews,
            isLoading = previewLoading,
            onDismiss = {
                showPreviewSheet = false
                previewType = null
            },
            onViewAll = {
                val type = previewType!!
                showPreviewSheet = false
                previewType = null
                scope.launch {
                    delay(100)
                    val paymentFilter = when (type) {
                        DashboardActionType.PENDING -> PaymentFilter.UNPAID
                        DashboardActionType.COLLECTED -> PaymentFilter.PAID
                        DashboardActionType.TOTAL -> PaymentFilter.ALL
                    }
                    // Navigate to jobs screen with customer-grouped mode
                    onNavigateToJobsGrouped(DateFilter.ALL_TIME, paymentFilter)
                }
            },
            onCustomerClick = { customerId ->
                showPreviewSheet = false
                previewType = null
                scope.launch {
                    delay(100)
                    onCustomerClick(customerId)
                }
            }
        )
    }

    // ====== OPERATIONAL ACTION CONSOLE: Work Switcher Sheet ======
    if (showWorkspaceSheet) {
        OperationalSwitcherSheet(
            workspaces = customerWorkspaces,
            onJobClick = { jobId ->
                showWorkspaceSheet = false
                selectedWorkspace = null
                viewModel.dismissRecoveryDialog()
                onOpenWorkspaceJob(jobId)
            },
            onAddWork = { customerId ->
                showWorkspaceSheet = false
                selectedWorkspace = null
                if (customerId.isNotBlank()) {
                    onNewJobForCustomer(customerId)
                } else {
                    onNewJobClick()
                }
            },
            onStartNewWork = {
                showWorkspaceSheet = false
                selectedWorkspace = null
                onNewJobClick()
            },
            // PART 3: Inline action execution — no navigation needed
            onQuickPause = { jobId -> viewModel.quickPauseJob(jobId) },
            onQuickResume = { jobId -> viewModel.quickResumeJob(jobId) },
            onQuickAddLoad = { jobId -> viewModel.quickAddLoad(jobId) },
            onQuickFinish = { jobId ->
                // INLINE FINISH: Check eligibility — show sheet or navigate
                viewModel.beginInlineFinish(jobId) {
                    // Not eligible for inline finish → open full workspace
                    showWorkspaceSheet = false
                    selectedWorkspace = null
                    onOpenWorkspaceJob(jobId)
                }
                // Close switcher sheet — InlineFinishSheet will open if eligible
                showWorkspaceSheet = false
                selectedWorkspace = null
            },
            onQuickStart = { jobId ->
                // Start requires full workspace for timer initialization
                showWorkspaceSheet = false
                selectedWorkspace = null
                onOpenWorkspaceJob(jobId)
            },
            onDismiss = {
                showWorkspaceSheet = false
                selectedWorkspace = null
            }
        )
    }

    // ====== INLINE FINISH SHEET — One-Tap Completion ======
    if (inlineFinishJob != null) {
        InlineFinishSheet(
            job = inlineFinishJob!!,
            onConfirmFinish = { paymentAmount, notes ->
                viewModel.completeInlineFinish(
                    jobId = inlineFinishJob!!.jobId,
                    paymentAmount = paymentAmount,
                    notes = notes
                )
                // Sheet will dismiss when inlineFinishJob becomes null
                showWorkspaceSheet = false
                selectedWorkspace = null
            },
            onDismiss = {
                viewModel.dismissInlineFinish()
            },
            onOpenWorkspace = {
                val jobId = inlineFinishJob!!.jobId
                viewModel.dismissInlineFinish()
                showWorkspaceSheet = false
                selectedWorkspace = null
                onOpenWorkspaceJob(jobId)
            }
        )
    }

    // ====== PART 1: Daily Closure Sheet ======
    if (showDailyClosure) {
        DailyClosureSheet(
            todayWorkValue = dashboard.todayEarnings,
            todayCollected = dashboard.todayCollected,
            todayPending = dashboard.todayPending,
            completedJobs = dashboard.todayJobs,
            activeJobsCount = customerWorkspaces.size,
            onDismiss = {
                closurePrefs.dismissToday()
                viewModel.dismissDailyClosure()
            },
            onShare = {
                closurePrefs.dismissToday()
                viewModel.dismissDailyClosure()
            }
        )
    }

    // ====== Main Content ======
    Box(
        modifier = modifier.fillMaxSize()
    ) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp)
            .verticalScroll(rememberScrollState()),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Spacer(Modifier.height(16.dp))

        // ============ Top Bar: Greeting + Sync ============
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = "FieldFlow",
                style = if (customerWorkspaces.isNotEmpty())
                    MaterialTheme.typography.headlineMedium
                else
                    MaterialTheme.typography.headlineLarge,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )
            // Sync status indicator — tappable for retry on failure
            Surface(
                shape = RoundedCornerShape(20.dp),
                color = when {
                    escalatedFailureCount > 0 -> MaterialTheme.colorScheme.errorContainer
                    pendingSyncCount > 0 -> MaterialTheme.colorScheme.tertiaryContainer
                    else -> MaterialTheme.colorScheme.primaryContainer
                },
                modifier = Modifier
                    .clip(RoundedCornerShape(20.dp))
                    .clickable {
                        when {
                            escalatedFailureCount > 0 -> viewModel.retrySyncNow()
                            pendingSyncCount > 0 -> viewModel.retrySyncNow()
                            // no-op when synced
                        }
                    }
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    val syncIcon = when {
                        escalatedFailureCount > 0 -> "⚠️"
                        pendingSyncCount > 0 -> ""
                        else -> ""
                    }
                    Text(syncIcon, style = MaterialTheme.typography.labelMedium)
                    Text(
                        text = when {
                            escalatedFailureCount > 0 -> "Tap to retry"
                            pendingSyncCount > 0 -> "Syncing"
                            else -> "Synced"
                        },
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = FontWeight.Medium
                    )
                }
            }
        }

        // ============ Morning Readiness (6 AM - 11 AM) ============
        // PART 3: Morning Quick Repeat — one tap restores yesterday's full pattern
        val currentHour = remember {
            java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
        }
        val isMorning = currentHour in 6..10
        val workPatternPrefs = remember { WorkPatternPreferences(context) }
        val lastPattern = remember { workPatternPrefs.getLastPattern() }

        if (isMorning && !dashboard.isLoading && customerWorkspaces.isEmpty()) {
            // No active work + morning = show quick repeat section
            Spacer(Modifier.height(12.dp))
            MorningReadinessSection(
                lastPattern = lastPattern,
                onRepeatLastPattern = { pattern ->
                    // Navigate to NewJob with pre-filled pattern
                    // Operator must still tap Start — never auto-start
                    onNewJobClick()
                }
            )
            Spacer(Modifier.height(4.dp))
        } else if (isMorning && !dashboard.isLoading && customerWorkspaces.isNotEmpty()) {
            Spacer(Modifier.height(12.dp))
            Text(
                text = "Good morning",
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.Medium,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
            )
            Spacer(Modifier.height(4.dp))
        }

        // ============ Layer 1: Current Work (running/paused/prepared) ============
        AnimatedVisibility(
            visible = customerWorkspaces.isNotEmpty(),
            enter = fadeIn() + expandVertically(),
            exit = fadeOut() + shrinkVertically()
        ) {
            Column {
                Spacer(Modifier.height(16.dp))
                // Explicit operational category header
                Text(
                    text = "Current Work",
                    style = MaterialTheme.typography.titleSmall,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurface
                )
                Spacer(Modifier.height(8.dp))

                if (customerWorkspaces.size == 1) {
                    // Single workspace — inline card (fast resume, no sheet needed)
                    ActiveWorkCenter(
                        workspaces = customerWorkspaces,
                        onOpenJob = { jobId ->
                            viewModel.dismissRecoveryDialog()
                            onOpenWorkspaceJob(jobId)
                        },
                        onResumeWorkspace = { workspace ->
                            viewModel.dismissRecoveryDialog()
                            onOpenWorkspaceJob(workspace.primaryJobId)
                        }
                    )
                } else {
                    // OPERATIONAL CONTROL CENTER: Multi-workspace → compact summary row
                    // Tapping opens the Operational Switcher Sheet — NOT a vertical list
                    val runningCount = customerWorkspaces.sumOf { it.runningCount }
                    val pausedCount = customerWorkspaces.sumOf { it.pausedCount }
                    val totalJobs = customerWorkspaces.sumOf { it.jobCount }

                    Surface(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(14.dp))
                            .clickable {
                                // Open operational switcher with ALL workspaces
                                selectedWorkspace = customerWorkspaces.first()
                                showWorkspaceSheet = true
                            },
                        shape = RoundedCornerShape(14.dp),
                        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.5f)
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 16.dp, vertical = 14.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            // Compact operational summary
                            Column {
                                Text(
                                    text = "$totalJobs active work${if (totalJobs != 1) "s" else ""}",
                                    style = MaterialTheme.typography.titleSmall,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onPrimaryContainer
                                )
                                val statusParts = buildList {
                                    if (runningCount > 0) add("$runningCount running")
                                    if (pausedCount > 0) add("$pausedCount paused")
                                    val readyCount = totalJobs - runningCount - pausedCount
                                    if (readyCount > 0) add("$readyCount ready")
                                }
                                Text(
                                    text = statusParts.joinToString(" • "),
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.7f)
                                )
                                // Customer names (compact chips)
                                Text(
                                    text = customerWorkspaces.joinToString(" • ") { it.customerName },
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.5f),
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                            }
                            // Trailing action hint
                            Text(
                                text = "Manage →",
                                style = MaterialTheme.typography.labelMedium,
                                fontWeight = FontWeight.Medium,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                    }
                }
            }
        }


        Spacer(Modifier.height(16.dp))

        // ============ PART 2: Operational Snapshot Row ============
        // One-second operational understanding — flat inline, no cards
        if (!dashboard.isLoading && customerWorkspaces.isNotEmpty()) {
            val runningCount = customerWorkspaces.sumOf { it.runningCount }
            val pausedCount = customerWorkspaces.sumOf { it.pausedCount }
            OperationalSnapshotRow(
                runningCount = runningCount,
                pausedCount = pausedCount,
                pendingAmount = dashboard.todayPending,
                collectedAmount = dashboard.todayCollected
            )
        }

        // ============ PART 10: Daily Closure Readiness ============
        // Compact readiness state — only shown when meaningful
        if (!dashboard.isLoading && dashboard.todayJobs > 0 && customerWorkspaces.isEmpty()) {
            DailyClosureReadiness(
                runningCount = dashboard.runningJobsCount,
                pausedCount = 0,
                pendingAmount = dashboard.todayPending
            )
        }

        // ============ Loading State ============
        if (dashboard.isLoading) {
            // Skeleton placeholders while data loads
            DashboardSkeleton()
        } else if (isNewUser) {
            // ============ Empty State for New Users ============
            EmptyDashboardState(
                onAddCustomerClick = onAddCustomerClick,
                onViewCustomersClick = onViewCustomersClick
            )
        } else {
            // ============ Today Summary Card ============
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { onNavigateToJobsWithFilter(DateFilter.TODAY, PaymentFilter.ALL) },
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(
                    containerColor = if (customerWorkspaces.isNotEmpty())
                        MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.6f)
                    else MaterialTheme.colorScheme.primaryContainer
                ),
                elevation = CardDefaults.cardElevation(
                    defaultElevation = if (customerWorkspaces.isNotEmpty()) 0.dp else 2.dp
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(3.dp)
                ) {
                    Text(
                        "Today",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.6f)
                    )
                    Text(
                        text = CalculationUtils.formatCurrency(dashboard.todayEarnings),
                        style = MaterialTheme.typography.displaySmall.copy(fontFeatureSettings = "tnum"),
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onPrimaryContainer
                    )
                    Text(
                        text = "${dashboard.todayJobs} work${if (dashboard.todayJobs != 1) "s" else ""}",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.7f)
                    )
                    if (dashboard.todayPending > 0) {
                        Surface(
                            shape = RoundedCornerShape(8.dp),
                            color = MaterialTheme.colorScheme.error.copy(alpha = 0.1f),
                            modifier = Modifier.clickable {
                                onNavigateToJobsWithFilter(DateFilter.TODAY, PaymentFilter.UNPAID)
                            }
                        ) {
                            Text(
                                text = "${CalculationUtils.formatCurrencyShort(dashboard.todayPending)} pending",
                                style = MaterialTheme.typography.labelMedium,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.error,
                                modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                            )
                        }
                    }
                    if (dashboard.todayCollected > 0) {
                        Surface(
                            shape = RoundedCornerShape(8.dp),
                            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.08f),
                            modifier = Modifier.clickable {
                                onNavigateToJobsWithFilter(DateFilter.TODAY, PaymentFilter.PAID)
                            }
                        ) {
                            Text(
                                text = "✅ ${CalculationUtils.formatCurrencyShort(dashboard.todayCollected)} collected",
                                style = MaterialTheme.typography.labelMedium,
                                fontWeight = FontWeight.Medium,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                            )
                        }
                    }
                }
            }

            Spacer(Modifier.height(8.dp))

            // ============ Stats Row ============
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                // Total Work
                StatCard(
                    label = "Total Work",
                    value = CalculationUtils.formatCurrencyShort(dashboard.allTimeEarnings),
                    containerColor = MaterialTheme.colorScheme.surface,
                    valueColor = MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier
                        .weight(1f)
                        .combinedClickable(
                            onClick = {
                                previewType = DashboardActionType.TOTAL
                                viewModel.loadPreviewJobs(DashboardActionType.TOTAL)
                                showPreviewSheet = true
                            },
                            onLongClick = {
                                selectedActionType = DashboardActionType.TOTAL
                                showActionSheet = true
                            }
                        )
                )
                // Collected
                StatCard(
                    label = "Collected",
                    value = CalculationUtils.formatCurrencyShort(dashboard.allTimeCollected),
                    containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.5f),
                    valueColor = MaterialTheme.colorScheme.primary,
                    modifier = Modifier
                        .weight(1f)
                        .combinedClickable(
                            onClick = {
                                previewType = DashboardActionType.COLLECTED
                                viewModel.loadPreviewJobs(DashboardActionType.COLLECTED)
                                showPreviewSheet = true
                            },
                            onLongClick = {
                                selectedActionType = DashboardActionType.COLLECTED
                                showActionSheet = true
                            }
                        )
                )
                // Pending
                StatCard(
                    label = "Pending",
                    value = CalculationUtils.formatCurrencyShort(dashboard.allTimePending),
                    containerColor = if (dashboard.allTimePending > 0)
                        MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.4f)
                    else MaterialTheme.colorScheme.surface,
                    valueColor = if (dashboard.allTimePending > 0)
                        MaterialTheme.colorScheme.error
                    else MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier
                        .weight(1f)
                        .combinedClickable(
                            onClick = {
                                previewType = DashboardActionType.PENDING
                                viewModel.loadPreviewJobs(DashboardActionType.PENDING)
                                showPreviewSheet = true
                            },
                            onLongClick = {
                                selectedActionType = DashboardActionType.PENDING
                                showActionSheet = true
                            }
                        )
                )
            }
        }

        // ============ End-of-day confidence ============
        if (!dashboard.isLoading && !isNewUser && dashboard.todayJobs > 0) {
            val activeCount = customerWorkspaces.size
            val noActiveWork = activeCount == 0
            val noPendingToday = dashboard.todayPending == 0.0

            // PART 10: Daily trust lock — quiet confidence when everything reconciles
            if (noActiveWork && noPendingToday && dashboard.isReconciled) {
                Spacer(Modifier.height(4.dp))
                Text(
                    text = "Everything matches ✓",
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.tertiary,
                    fontWeight = FontWeight.Medium,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Center
                )
            } else if (noActiveWork && !noPendingToday) {
                // Work done but pending remains — no extra label needed
            } else if (activeCount > 0) {
                // Active work still in progress — gentle reminder
                Spacer(Modifier.height(4.dp))
                Text(
                    text = "$activeCount active work${if (activeCount != 1) "s" else ""} still open",
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Center
                )
            }

            // PART 2: Calm reconciliation — show when numbers don't align
            if (!dashboard.isReconciled) {
                Spacer(Modifier.height(4.dp))
                Text(
                    text = "Totals updating…",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f),
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.Center
                )
            }

            // PART 4: End-of-day inline summary — quiet evening recap
            val currentHour = remember { java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY) }
            if (noActiveWork && currentHour >= 18 && !closurePrefs.isDismissedToday()) {
                Spacer(Modifier.height(12.dp))
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
                    ),
                    elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text(
                            text = "Today's work complete ✓",
                            style = MaterialTheme.typography.titleSmall,
                            fontWeight = FontWeight.Medium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Text(
                            text = "${dashboard.todayJobs} work${if (dashboard.todayJobs != 1) "s" else ""} finished",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                        )
                        Text(
                            text = "${CalculationUtils.formatCurrencyShort(dashboard.todayEarnings)} total",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                        )
                        if (dashboard.todayCollected > 0) {
                            Text(
                                text = if (dashboard.todayPending == 0.0)
                                    "${CalculationUtils.formatCurrencyShort(dashboard.todayCollected)} collected ✓"
                                else
                                    "${CalculationUtils.formatCurrencyShort(dashboard.todayCollected)} collected",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.tertiary.copy(alpha = 0.8f)
                            )
                        }
                        if (dashboard.todayPending > 0) {
                            Text(
                                text = "${CalculationUtils.formatCurrencyShort(dashboard.todayPending)} pending",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.error.copy(alpha = 0.7f)
                            )
                        }
                        Spacer(Modifier.height(4.dp))
                        Surface(
                            modifier = Modifier
                                .clip(RoundedCornerShape(8.dp))
                                .clickable {
                                    onNavigateToJobsWithFilter(DateFilter.TODAY, PaymentFilter.ALL)
                                },
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.0f)
                        ) {
                            Text(
                                text = "View Today's Work →",
                                style = MaterialTheme.typography.labelMedium,
                                fontWeight = FontWeight.Medium,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(vertical = 4.dp)
                            )
                        }
                    }
                }
            }
        }

        // ============ Sync Failure Warning ============
        AnimatedVisibility(
            visible = escalatedFailureCount > 0,
            enter = fadeIn() + expandVertically(),
            exit = fadeOut() + shrinkVertically()
        ) {
            Spacer(Modifier.height(12.dp))
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { viewModel.retrySyncNow() },
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.4f)
                )
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text("⚠️", style = MaterialTheme.typography.titleMedium)
                    Text(
                        text = "Some items couldn't sync. Tap to retry.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onErrorContainer
                    )
                }
            }
        }

        Spacer(Modifier.height(16.dp))

        // ============ PART 7: Morning Continuity Banner ============
        if (yesterdayActiveCount > 0) {
            ContinuityBanner(
                yesterdayActiveCount = yesterdayActiveCount,
                yesterdayWorkspaces = yesterdayWorkspaces,
                onTap = {
                    // Scroll to workspace rail — already visible above
                },
                onWorkspaceTap = { workspace ->
                    viewModel.dismissRecoveryDialog()
                    onOpenWorkspaceJob(workspace.primaryJobId)
                }
            )
            Spacer(Modifier.height(12.dp))
        }

        // ============ PART 2: Needs Attention ============
        if (attentionItems.isNotEmpty() && !isNewUser) {
            NeedsAttentionSection(
                items = attentionItems,
                onCustomerClick = onCustomerClick
            )
            Spacer(Modifier.height(16.dp))
        }

        // ============ Layer 3: Memory Shortcuts ("Usual Work") ============
        // Lightweight chips — ONLY prefill new setup, never restore/resume.
        val recentWorks by viewModel.recentWorks.collectAsState()
        if (recentWorks.isNotEmpty() && !isNewUser) {
            RecentWorkStrip(
                recentWorks = recentWorks,
                onWorkTap = { work ->
                    // Open new job pre-filled with same customer, capability, rate, and machine
                    if (work.customerId.isNotBlank()) {
                        onRepeatRecentWork(
                            work.customerId,
                            work.capability.name,
                            work.rate.toString(),
                            work.machineId
                        )
                    } else {
                        onTemplateClick(work.capability.name)
                    }
                }
            )
            Spacer(Modifier.height(16.dp))
        }

        // ============ Quick Start — Work Types ============
        Text(
            text = "Quick Start",
            style = MaterialTheme.typography.titleSmall,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.fillMaxWidth()
        )
        Spacer(Modifier.height(6.dp))

        val workTypes = JobCapability.entries
        workTypes.chunked(2).forEach { rowItems ->
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                rowItems.forEach { capability ->
                    val interactionSource = remember { MutableInteractionSource() }
                    val isPressed by interactionSource.collectIsPressedAsState()
                    val scale by animateFloatAsState(
                        targetValue = if (isPressed) 0.96f else 1f,
                        animationSpec = tween(100),
                        label = "capScale"
                    )

                    Card(
                        onClick = {
                            // Multi-workspace: always allow starting new work
                            onTemplateClick(capability.name)
                        },
                        modifier = Modifier
                            .weight(1f)
                            .graphicsLayer {
                                scaleX = scale
                                scaleY = scale
                            },
                        shape = RoundedCornerShape(12.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = MaterialTheme.colorScheme.surface
                        ),
                        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
                        interactionSource = interactionSource
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(10.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = capability.emoji,
                                style = MaterialTheme.typography.titleMedium
                            )
                            Spacer(Modifier.width(8.dp))
                            Text(
                                text = capability.displayName,
                                style = MaterialTheme.typography.bodyMedium,
                                fontWeight = FontWeight.Medium,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }
                }
                // Fill space if odd count
                if (rowItems.size == 1) {
                    Spacer(modifier = Modifier.weight(1f))
                }
            }
            Spacer(Modifier.height(6.dp))
        }

        Spacer(Modifier.height(10.dp))

        // ============ Secondary Action Buttons ============
        LargeSecondaryButton(text = "View Work", onClick = onTodaySummaryClick)
        Spacer(Modifier.height(8.dp))
        LargeSecondaryButton(text = "Farmers", onClick = onViewCustomersClick)
        Spacer(Modifier.height(8.dp))
        // PART 3 — Day-end recovery: calm entry for missed/past work
        LargeSecondaryButton(text = "  Add Past Work", onClick = onAddPastWork)

        Spacer(Modifier.height(80.dp)) // Reserve space for floating CTA dock
    }

    // ============ Floating CTA — extended FAB style ============
    FilledTonalButton(
        onClick = guardedNewJobClick,
        modifier = Modifier
            .align(Alignment.BottomCenter)
            .padding(bottom = 20.dp)
            .height(48.dp),
        shape = RoundedCornerShape(24.dp)
    ) {
        Text(
            text = "➕  Start Work",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.SemiBold
        )
    }
    } // end Box
}

// ============ Loading Skeleton ============

@Composable
private fun DashboardSkeleton() {
    val skeletonColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)

    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        // Today card skeleton
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .height(130.dp),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = skeletonColor),
            elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
        ) { }

        // Stats row skeleton
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            repeat(3) {
                Card(
                    modifier = Modifier
                        .weight(1f)
                        .height(64.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = skeletonColor),
                    elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
                ) { }
            }
        }
    }
}

// ============ Empty State for New Users ============

@Composable
private fun EmptyDashboardState(
    onAddCustomerClick: () -> Unit,
    onViewCustomersClick: () -> Unit
) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                text = "",
                style = MaterialTheme.typography.displayMedium
            )
            Text(
                text = "Ready when you are",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )
            Text(
                text = "Add a farmer to get started.",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center
            )
            Spacer(Modifier.height(8.dp))
            LargeSecondaryButton(
                text = "➕ Add Your First Farmer",
                onClick = onAddCustomerClick
            )
        }
    }
}

// ============ Helper Components ============

@Composable
private fun StatCard(
    label: String,
    value: String,
    containerColor: androidx.compose.ui.graphics.Color,
    valueColor: androidx.compose.ui.graphics.Color,
    modifier: Modifier = Modifier
) {
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = containerColor),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(10.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(2.dp)
        ) {
            Text(
                label,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            Text(
                text = value,
                style = MaterialTheme.typography.titleMedium.copy(fontFeatureSettings = "tnum"),
                fontWeight = FontWeight.Bold,
                color = valueColor,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

