data class DashboardUiState(
    val todayEarnings: Double = 0.0,
    val todayJobs: Int = 0,
    val todayPending: Double = 0.0,
    val todayCollected: Double = 0.0,
    val allTimeEarnings: Double = 0.0,
    val allTimeCollected: Double = 0.0,
    val allTimePending: Double = 0.0,
    val isLoading: Boolean = true,
    // PART 6: Daily work closure summary
    val runningJobsCount: Int = 0
) {
    /**
     * PART 6: Generate end-of-day summary string.
     * Example: "5 works today • ₹24,500 total"
     */
    val dailySummary: String?
        get() {
            if (todayJobs == 0) return null
            val jobWord = if (todayJobs == 1) "work" else "works"
            return "$todayJobs $jobWord today • ${CalculationUtils.formatCurrencyShort(todayEarnings)} total"
        }

    /**
     * PART 6: Generate payment summary string.
     * Example: "₹18,000 collected • ₹6,500 pending"
     */
    val paymentSummary: String?
        get() {
            if (todayCollected <= 0 && todayPending <= 0) return null
            val parts = mutableListOf<String>()
            if (todayCollected > 0) {
                parts.add("${CalculationUtils.formatCurrencyShort(todayCollected)} collected")
            }
            if (todayPending > 0) {
                parts.add("${CalculationUtils.formatCurrencyShort(todayPending)} pending")
            }
            return parts.joinToString(" • ")
        }

    /**
     * PART 6: Running jobs label.
     * Example: "2 works still running"
     */
    val runningJobsLabel: String?
        get() = if (runningJobsCount > 0) {
            val jobWord = if (runningJobsCount == 1) "work" else "works"
            "$runningJobsCount $jobWord still running"
        } else null

    /**
     * CALM FINANCIAL TRUST — Reconciliation invariant.
     * allTimeCollected + allTimePending should equal allTimeEarnings.
     * Small rounding differences (< ₹1) are normal and ignored.
     *
     * INVARIANT: This tolerance exists because paidAmount is computed from
     * individual payments (FIFO allocation), and floating point arithmetic
     * across many small payments can produce sub-rupee drift. A ₹1 tolerance
     * avoids false negatives without masking real discrepancies.
     */
    val isReconciled: Boolean
        get() {
            val delta = kotlin.math.abs(allTimeEarnings - (allTimeCollected + allTimePending))
            return delta < 1.0
        }
}

/**
 * Customer-level due summary for the pending preview sheet.
 */
data class CustomerDuePreview(
    val customerId: String,
    val customerName: String,
    val totalDue: Double,
    val jobCount: Int,
    val oldestUnpaidJobDate: Long,
    val hasOverdue: Boolean // any job > 7 days unpaid
)

/**
 * Customer-level amount preview for COLLECTED/TOTAL sheets.
 */
data class CustomerAmountPreview(
    val customerId: String?,
    val customerName: String,
    val totalAmount: Double,
    val jobCount: Int,
    val lastActivityAt: Long,
    val hasOverdue: Boolean = false
)

enum class ActiveWorkFeedbackState { IDLE, PROCESSING, SUCCESS, ERROR }

data class ActiveWorkFeedback(
    val jobId: String? = null,
    val state: ActiveWorkFeedbackState = ActiveWorkFeedbackState.IDLE,
    val message: String = "",
    val updatedAt: Long = 0L
)

/**
 * ViewModel for the Home Screen dashboard.
 * Loads all-time and today stats using SQL aggregation (fast).
 */
class HomeViewModel(
    private val jobRepository: JobRepository,
    private val activeJobRepository: ActiveJobRepository,
    private val customerRepository: CustomerRepository,
    private val syncManager: SyncManager? = null,
    private val activeJobsRepository: ActiveJobsRepository? = null,
    private val mutationExecutor: OperationalMutationExecutor? = null,
    // R6.3 PART 1 — Optional MachineRepository so the home dashboard can
    // observe machine count for the "Start your first work" next-step card.
    // Nullable for safety: home keeps working if this isn't wired yet.
    private val machineRepository: MachineRepository? = null
) : ViewModel() {

    private val _uiState = MutableStateFlow(DashboardUiState())
    val uiState: StateFlow<DashboardUiState> = _uiState.asStateFlow()

    /** Observe active job — shows resume banner on Home Screen */
    val activeJob: StateFlow<ActiveJobEntity?> = activeJobRepository.getActiveJob()
        .catch { emit(null) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), null)

    /** PART 4/11: Active customer session from multi-job table (live updates) */
    val activeCustomerSession: StateFlow<ActiveCustomerSession?> = if (activeJobsRepository != null) {
        activeJobsRepository.getAllActiveJobs()
            .map { jobs ->
                // Active jobs table is source of truth — no filtering.
                // Phantom cleanup happens only in NewJobViewModel on workspace open.
                ActiveCustomerSession.fromActiveJobs(jobs)
            }
            .catch { emit(null) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), null)
    } else {
        MutableStateFlow(null)
    }

    /** FINAL: Individual active job summaries for workspace rail pills */
    val workspacePills: StateFlow<List<ActiveJobSummary>> = if (activeJobsRepository != null) {
        activeJobsRepository.getAllActiveJobs()
            .map { jobs -> jobs.map { it.toWorkspacePill() } }
            .catch { emit(emptyList()) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())
    } else {
        MutableStateFlow(emptyList())
    }

    /** Customer-grouped workspaces for the home screen rail (CUSTOMER-FIRST) */
    val customerWorkspaces: StateFlow<List<ActiveCustomerWorkspace>> = if (activeJobsRepository != null) {
        activeJobsRepository.getAllActiveJobs()
            .map { jobs ->
                // No hasWork filtering — active_jobs table is the authoritative source.
                // If a row exists, it must appear in the workspace rail.
                ActiveCustomerWorkspace.fromActiveJobs(jobs)
            }
            .catch { emit(emptyList()) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())
    } else {
        MutableStateFlow(emptyList())
    }

    /** Customer name for the active job banner */
    private val _activeJobCustomerName = MutableStateFlow<String?>(null)
    val activeJobCustomerName: StateFlow<String?> = _activeJobCustomerName.asStateFlow()

    /** Recovery dialog — shown once per app launch when active job found */
    private val _showRecoveryDialog = MutableStateFlow(false)
    val showRecoveryDialog: StateFlow<Boolean> = _showRecoveryDialog.asStateFlow()
    private var hasCheckedRecovery = false

    // Inline save confidence for ActiveWorkCommandCenter actions.
    private val _activeWorkFeedback = MutableStateFlow(ActiveWorkFeedback())
    val activeWorkFeedback: StateFlow<ActiveWorkFeedback> = _activeWorkFeedback.asStateFlow()
    private val inFlightActionKeys = mutableSetOf<String>()
    private val queuedLoadAdds = mutableMapOf<String, Int>()

    /** Global sync status: total pending items across jobs + customers */
    val pendingSyncCount: StateFlow<Int> = combine(
        jobRepository.getPendingSyncCount(),
        customerRepository.getPendingSyncCount()
    ) { jobPending, customerPending -> jobPending + customerPending }
        .catch { emit(0) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)

    /** Count of items that failed sync 3+ times — shown as subtle warning */
    val escalatedFailureCount: StateFlow<Int> = combine(
        jobRepository.getEscalatedFailureCount(),
        customerRepository.getEscalatedFailureCount()
    ) { jobFailed, customerFailed -> jobFailed + customerFailed }
        .catch { emit(0) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)

    /**
     * R6 PART 1 — Number of non-archived customers/farmers.
     * Used by HomeScreen to gate the brand-new "Add farmer" empty state:
     * once at least one farmer exists, the dashboard should advance to the
     * "start work" surface. Source: existing [CustomerRepository.getCustomerCount].
     */
    val customerCount: StateFlow<Int> = customerRepository.getCustomerCount()
        .catch { emit(0) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)

    /**
     * R6.3 PART 1 — Number of machines registered on this device.
     * Used by HomeScreen to render a calm inline "Start your first work"
     * next-step card when the user has farmers but no machines yet.
     * Defaults to 0 (assumes "has machines = false") when the repository is
     * not injected, which silently hides the card — safe degraded behavior.
     */
    val machineCount: StateFlow<Int> = (machineRepository?.getAllMachines()
        ?.map { it.size }
        ?: kotlinx.coroutines.flow.flowOf(0))
        .catch { emit(0) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)

    init {
        loadDashboard()
        checkActiveJobOnLaunch()
        loadNeedsAttention()
        loadRecentWorks()
        observeRunningJobsCount()
        loadDailyRhythm()
        loadOwnerMemories()
    }

    // ══════ FIELD OPERATION MEMORY — Daily Rhythm + Time-Aware Ordering ══════

    /** PART 1: Daily operational rhythm detected from recent history */
    private val _dailyRhythm = MutableStateFlow(com.example.fieldtrack.domain.intelligence.DailyOperationalRhythm.EMPTY)
    val dailyRhythm: StateFlow<com.example.fieldtrack.domain.intelligence.DailyOperationalRhythm> = _dailyRhythm.asStateFlow()

    /** PART 2: Time-aware Quick Start ordering — gently reordered, never hidden */
    private val _timeAwareCapabilities = MutableStateFlow(com.example.fieldtrack.domain.job.JobCapability.entries.toList())
    val timeAwareCapabilities: StateFlow<List<com.example.fieldtrack.domain.job.JobCapability>> = _timeAwareCapabilities.asStateFlow()

    // ══════ PHASE E3 — Owner Memory + Weekly Memory + Recovery Memory ══════
    //
    // Derived only. Replay-safe. Never stored. Loaded once on init and
    // re-loaded on dashboard refresh. Operates from jobs + active jobs +
    // mutation journal — financial events default to empty list because the
    // home view-model is not yet wired to FinancialEventDao; both memory
    // models degrade gracefully when financial inputs are absent (chip stays
    // silent, presence stays SILENT, integrity verifier remains green).

    private val _ownerMemorySnapshot = MutableStateFlow<OwnerOperationalSnapshot?>(null)
    val ownerMemorySnapshot: StateFlow<OwnerOperationalSnapshot?> = _ownerMemorySnapshot.asStateFlow()

    private val _weeklyMemory = MutableStateFlow<WeeklyOperationalMemory>(WeeklyOperationalMemory.EMPTY)
    val weeklyMemory: StateFlow<WeeklyOperationalMemory> = _weeklyMemory.asStateFlow()

    private val _recoveryMemory = MutableStateFlow<RecoveryMemory?>(null)
    val recoveryMemory: StateFlow<RecoveryMemory?> = _recoveryMemory.asStateFlow()

    /**
     * Load owner / weekly / recovery memories from current data sources.
     * Safe to call repeatedly — pure derivation, no caching, no writes.
     */
    private fun loadOwnerMemories() {
        viewModelScope.launch {
            try {
                val recentJobs = jobRepository.getRecentCompletedJobs(limit = 200)
                val active = try {
                    activeJobsRepository?.getAllActiveJobsOnce() ?: emptyList()
                } catch (_: Throwable) {
                    emptyList()
                }
                val now = System.currentTimeMillis()
                val (startOfDay, endOfDay) = todayWindow(now)

                val ownerSnap = OwnerOperationalSnapshot.buildFromSources(
                    startOfDay = startOfDay,
                    endOfDay = endOfDay,
                    completedJobs = recentJobs,
                    activeJobs = active,
                    allFinancialEvents = emptyList()
                )
                _ownerMemorySnapshot.value = ownerSnap

                _weeklyMemory.value = WeeklyOperationalMemory.build(
                    endOfWeek = now,
                    completedJobs = recentJobs,
                    activeJobs = active,
                    financialEvents = emptyList()
                )

                _recoveryMemory.value = OperationalRecoveryMemory.summarize(now = now)
            } catch (_: Throwable) {
                // Degrade gracefully — owner memory simply stays silent.
                _ownerMemorySnapshot.value = null
                _weeklyMemory.value = WeeklyOperationalMemory.EMPTY
                _recoveryMemory.value = null
            }
        }
    }

    private fun todayWindow(now: Long): Pair<Long, Long> {
        val cal = Calendar.getInstance().apply {
            timeInMillis = now
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }
        val start = cal.timeInMillis
        return start to (start + 24L * 60 * 60 * 1000)
    }

    /**
     * Load daily rhythm from completed jobs and derive time-aware ordering.
     * PART 6: Calm prediction — never overrides, never auto-starts.
     */
    private fun loadDailyRhythm() {
        viewModelScope.launch {
            try {
                val recentJobs = jobRepository.getRecentCompletedJobs(limit = 100)
                val rhythm = com.example.fieldtrack.domain.intelligence.DailyOperationalRhythm.analyze(recentJobs)
                _dailyRhythm.value = rhythm

                // Apply time-aware ordering
                val currentHour = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
                _timeAwareCapabilities.value = rhythm.getTimeAwareOrdering(currentHour)
            } catch (_: Exception) {
                _dailyRhythm.value = com.example.fieldtrack.domain.intelligence.DailyOperationalRhythm.EMPTY
            }
        }
    }

    // PART 6: Keep running jobs count updated
    private fun observeRunningJobsCount() {
        if (activeJobsRepository == null) return
        viewModelScope.launch {
            activeJobsRepository.getAllActiveJobs()
                .catch { emit(emptyList()) }
                .collect { jobs ->
                    val runningCount = jobs.count { it.isTimerRunning && !it.isPaused && !it.isStopped }
                    _uiState.value = _uiState.value.copy(runningJobsCount = runningCount)
                }
        }
    }

    // ================== PART 1 (LT): Recent Work Muscle Memory ==================

    /** Recent completed works for quick repeat — max 3, stable ordering */
    private val _recentWorks = MutableStateFlow<List<RecentWorkEntry>>(emptyList())
    val recentWorks: StateFlow<List<RecentWorkEntry>> = _recentWorks.asStateFlow()

    /**
     * Load recent completed works for the RecentWorkStrip.
     * 
     * Rules:
     * - Maximum 3 recent works
     * - Stable ordering (by completion time DESC)
     * - Shows last 3 unique customer+machineType combinations
     */
    private fun loadRecentWorks() {
        viewModelScope.launch {
            try {
                // Get recent completed jobs (last 7 days, max 10 for deduplication)
                val recentJobs = jobRepository.getRecentCompletedJobs(limit = 10)
                val customerIds = recentJobs.mapNotNull { it.customerId }.distinct()
                val customerNames = customerRepository.getCustomerNameMap(customerIds)

                // Derive capability from machineType
                fun deriveCapability(machineType: MachineType): JobCapability {
                    return when (machineType) {
                        MachineType.TRACTOR -> JobCapability.LAND_PREPARATION
                        MachineType.HARVESTER -> JobCapability.HARVESTING
                        MachineType.TROLLEY -> JobCapability.TRANSPORT
                    }
                }

                // Deduplicate by customer+machineType combination, keep most recent
                val seen = mutableSetOf<Pair<String?, MachineType>>()
                val entries = recentJobs
                    .mapNotNull { job ->
                        val key = job.customerId to job.machineType
                        if (key in seen) return@mapNotNull null
                        seen.add(key)

                        val capability = deriveCapability(job.machineType)

                        RecentWorkEntry(
                            customerId = job.customerId ?: "",
                            customerName = job.customerId?.let { customerNames[it] } ?: "Unassigned",
                            capability = capability,
                            machineId = job.machineId,
                            machineName = job.machineName,
                            billingMode = BillingModeRegistry.toBillingMode(job.pricingMode),
                            rate = job.rate,
                            completedAt = job.endTime ?: job.createdAt,
                            totalAmount = job.totalAmount,
                            sourceJobId = job.id
                        )
                    }
                    .take(RecentWorkEntry.MAX_RECENT_WORKS)

                _recentWorks.value = entries
            } catch (_: Exception) {
                _recentWorks.value = emptyList()
            }
        }
    }

    // ================== PART 1: Daily Closure ==================

    /** Whether to show the daily closure sheet */
    private val _showDailyClosure = MutableStateFlow(false)
    val showDailyClosure: StateFlow<Boolean> = _showDailyClosure.asStateFlow()

    /** Check if closure sheet should show (after 6 PM, work done, not dismissed) */
    fun checkDailyClosure(isDismissedToday: Boolean) {
        val hour = Calendar.getInstance().get(Calendar.HOUR_OF_DAY)
        val hasWork = _uiState.value.todayJobs > 0
        _showDailyClosure.value = hour >= 18 && hasWork && !isDismissedToday && !_uiState.value.isLoading
    }

    fun dismissDailyClosure() {
        _showDailyClosure.value = false
    }

    // ================== PART 2: Needs Attention ==================

    private val _attentionItems = MutableStateFlow<List<AttentionItem>>(emptyList())
    val attentionItems: StateFlow<List<AttentionItem>> = _attentionItems.asStateFlow()

    /**
     * Load operational attention items from existing Room data.
     *
     * INVARIANT: Sort order is primary=amount DESC, secondary=oldest unpaid ASC.
     * This ensures the most financially significant items appear first,
     * with ties broken by age (oldest gets priority).
     *
     * NOTE: This is a snapshot-based computation (not live Flow).
     * Items refresh on each init/app launch. Real-time updates would require
     * combining with jobRepository flows — marked as future improvement.
     */
    private fun loadNeedsAttention() {
        viewModelScope.launch {
            try {
                val items = mutableListOf<AttentionItem>()

                // 1. Top pending customers
                val unpaidJobs = jobRepository.getRecentUnpaidJobs()
                val customerIds = unpaidJobs.mapNotNull { it.customerId }.distinct()
                val nameMap = customerRepository.getCustomerNameMap(customerIds)

                unpaidJobs
                    .filter { it.customerId != null }
                    .groupBy { it.customerId!! }
                    .map { (custId, jobs) ->
                        Triple(
                            custId,
                            nameMap[custId] ?: "Farmer",
                            jobs
                        )
                    }
                    // Sort: primary = amount DESC, secondary = oldest unpaid ASC
                    .sortedWith(
                        compareByDescending<Triple<String, String, List<JobEntity>>> { (_, _, jobs) ->
                            jobs.sumOf { it.remainingAmount }
                        }.thenBy { (_, _, jobs) ->
                            jobs.minOf { it.createdAt }
                        }
                    )
                    .take(3)
                    .forEach { (custId, name, jobs) ->
                        val amount = jobs.sumOf { it.remainingAmount }
                        val workCount = jobs.size
                        val text = "${CalculationUtils.formatCurrencyShort(amount)} pending from $name" +
                            if (workCount > 1) " · $workCount works" else ""
                        items.add(AttentionItem(
                            emoji = "",
                            text = text,
                            targetCustomerId = custId
                        ))
                    }

                // 2. Stale active works (from workspace data — already computed)
                // Will be enriched when customerWorkspaces emits

                _attentionItems.value = items.take(5)
            } catch (_: Exception) {
                _attentionItems.value = emptyList()
            }
        }
    }

    /** PART 7: Count of active jobs from before today (stale/yesterday) */
    val yesterdayActiveCount: StateFlow<Int> = if (activeJobsRepository != null) {
        val todayStart = DateTimeUtils.getTodayStartMillis()
        activeJobsRepository.getAllActiveJobs()
            .map { jobs ->
                jobs.count { it.createdAt < todayStart && !it.isStopped }
            }
            .catch { emit(0) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)
    } else {
        MutableStateFlow(0)
    }

    /** PART 1: Yesterday's workspaces for rich continuation banner */
    val yesterdayWorkspaces: StateFlow<List<ActiveCustomerWorkspace>> = if (activeJobsRepository != null) {
        val todayStart = DateTimeUtils.getTodayStartMillis()
        activeJobsRepository.getAllActiveJobs()
            .map { jobs ->
                val yesterdayJobs = jobs.filter { it.createdAt < todayStart && !it.isStopped }
                ActiveCustomerWorkspace.fromActiveJobs(yesterdayJobs)
            }
            .catch { emit(emptyList()) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())
    } else {
        MutableStateFlow(emptyList())
    }

    private fun checkActiveJobOnLaunch() {
        viewModelScope.launch {
            activeJob.collect { job ->
                if (job != null) {
                    hasCheckedRecovery = true
                    // Don't auto-show recovery dialog — the active job banner on HomeScreen
                    // is already the resume affordance. The dialog only creates confusion
                    // (shows then auto-dismisses when banner is tapped).
                    // Resolve customer name
                    if (job.customerId.isNotBlank()) {
                        val customer = customerRepository.getCustomerById(job.customerId)
                        _activeJobCustomerName.value = customer?.name
                    } else {
                        _activeJobCustomerName.value = null
                    }
                } else {
                    _activeJobCustomerName.value = null
                    _showRecoveryDialog.value = false
                }
                return@collect // Only check once
            }
        }
    }

    fun dismissRecoveryDialog() {
        _showRecoveryDialog.value = false
    }

    private fun beginAction(actionKey: String): Boolean = synchronized(inFlightActionKeys) {
        if (inFlightActionKeys.contains(actionKey)) return false
        inFlightActionKeys.add(actionKey)
        true
    }

    private fun endAction(actionKey: String) {
        synchronized(inFlightActionKeys) {
            inFlightActionKeys.remove(actionKey)
        }
    }

    private fun publishActionFeedback(jobId: String, state: ActiveWorkFeedbackState, message: String) {
        _activeWorkFeedback.value = ActiveWorkFeedback(
            jobId = jobId,
            state = state,
            message = message,
            updatedAt = System.currentTimeMillis()
        )
    }

    private fun queueLoadAdd(jobId: String): Int = synchronized(queuedLoadAdds) {
        val next = (queuedLoadAdds[jobId] ?: 0) + 1
        queuedLoadAdds[jobId] = next
        next
    }

    private fun popQueuedLoadAdd(jobId: String): Int = synchronized(queuedLoadAdds) {
        val current = queuedLoadAdds[jobId] ?: 0
        if (current <= 1) {
            queuedLoadAdds.remove(jobId)
            0
        } else {
            val remaining = current - 1
            queuedLoadAdds[jobId] = remaining
            remaining
        }
    }

    private fun clearQueuedLoadAdds(jobId: String) {
        synchronized(queuedLoadAdds) {
            queuedLoadAdds.remove(jobId)
        }
    }

    // ══════ OPERATIONAL ACTION CONSOLE — Inline Quick Actions ══════

    /**
     * Pause a running timer directly from the switcher sheet.
     * Routes through canonical mutation executor for versioned, journaled persistence.
     */
    fun quickPauseJob(jobId: String) {
        val actionKey = "pause:$jobId"
        if (!beginAction(actionKey)) {
            publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Saving pause...")
            return
        }
        publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Saving...")
        viewModelScope.launch {
            try {
                val success = if (mutationExecutor != null) {
                    mutationExecutor.quickPauseJob(jobId) != null
                } else {
                    // Fallback: direct repository write (legacy path)
                    val repo = activeJobsRepository
                    val job = repo?.getJobById(jobId)
                    if (repo == null || job == null || !job.isTimerRunning) {
                        false
                    } else {
                        val now = System.currentTimeMillis()
                        repo.saveJob(job.copy(
                            isPaused = true,
                            pauseStartTime = now,
                            lastUpdatedAt = now
                        ))
                        true
                    }
                }
                if (success) {
                    publishActionFeedback(jobId, ActiveWorkFeedbackState.SUCCESS, "Work paused")
                } else {
                    publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not pause work")
                }
            } catch (_: Exception) {
                publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not pause work")
            } finally {
                endAction(actionKey)
            }
        }
    }

    /**
     * Resume a paused timer directly from the switcher sheet.
     * Routes through canonical mutation executor for versioned, journaled persistence.
     */
    fun quickResumeJob(jobId: String) {
        val actionKey = "resume:$jobId"
        if (!beginAction(actionKey)) {
            publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Saving resume...")
            return
        }
        publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Saving...")
        viewModelScope.launch {
            try {
                val success = if (mutationExecutor != null) {
                    mutationExecutor.quickResumeJob(jobId) != null
                } else {
                    // Fallback: direct repository write (legacy path)
                    val repo = activeJobsRepository
                    val job = repo?.getJobById(jobId)
                    if (repo == null || job == null || !job.isPaused) {
                        false
                    } else {
                        val now = System.currentTimeMillis()
                        val additionalPaused = if (job.pauseStartTime != null) now - job.pauseStartTime else 0L
                        repo.saveJob(job.copy(
                            isPaused = false,
                            pauseStartTime = null,
                            totalPausedDuration = job.totalPausedDuration + additionalPaused,
                            lastUpdatedAt = now
                        ))
                        true
                    }
                }
                if (success) {
                    publishActionFeedback(jobId, ActiveWorkFeedbackState.SUCCESS, "Work resumed")
                } else {
                    publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not resume work")
                }
            } catch (_: Exception) {
                publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not resume work")
            } finally {
                endAction(actionKey)
            }
        }
    }

    /**
     * Add a load/packet directly from the switcher sheet.
     * Routes through canonical mutation executor for versioned, journaled persistence.
     */
    fun quickAddLoad(jobId: String) {
        val actionKey = "addLoad:$jobId"
        if (!beginAction(actionKey)) {
            val queued = queueLoadAdd(jobId)
            val msg = if (queued > 1) {
                "Adding next loads ($queued queued)"
            } else {
                "Adding next load..."
            }
            publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, msg)
            return
        }
        publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Adding load...")
        viewModelScope.launch {
            try {
                var keepProcessing = true
                while (keepProcessing) {
                    val success = if (mutationExecutor != null) {
                        mutationExecutor.quickAddLoad(jobId) != null
                    } else {
                        // Fallback: direct repository write (legacy path)
                        val repo = activeJobsRepository
                        val job = repo?.getJobById(jobId)
                        if (repo == null || job == null) {
                            false
                        } else {
                            val now = System.currentTimeMillis()
                            repo.saveJob(job.copy(
                                trips = job.trips + 1,
                                lastUpdatedAt = now
                            ))
                            true
                        }
                    }

                    if (success) {
                        publishActionFeedback(jobId, ActiveWorkFeedbackState.SUCCESS, "Load added")
                        val queued = popQueuedLoadAdd(jobId)
                        if (queued > 0) {
                            val msg = if (queued > 1) {
                                "Adding next loads ($queued queued)"
                            } else {
                                "Adding next load..."
                            }
                            publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, msg)
                        } else {
                            keepProcessing = false
                        }
                    } else {
                        clearQueuedLoadAdds(jobId)
                        publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not add load")
                        keepProcessing = false
                    }
                }
            } catch (_: Exception) {
                clearQueuedLoadAdds(jobId)
                publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not add load")
            } finally {
                endAction(actionKey)
            }
        }
    }

    /**
     * PART 3: Add multiple loads at once (e.g., +5 for rapid transport).
     * Safe: increments trip count atomically.
     */
    fun quickAddMultipleLoads(jobId: String, count: Int) {
        if (count <= 0) return
        viewModelScope.launch {
            val repo = activeJobsRepository ?: return@launch
            val job = repo.getJobById(jobId) ?: return@launch
            val now = System.currentTimeMillis()
            repo.saveJob(job.copy(
                trips = job.trips + count,
                lastUpdatedAt = now
            ))
        }
    }

    /**
     * PART 3: Decrement load with protection — never goes below 0.
     */
    fun quickDecrementLoad(jobId: String) {
        viewModelScope.launch {
            val repo = activeJobsRepository ?: return@launch
            val job = repo.getJobById(jobId) ?: return@launch
            if (job.trips <= 0) return@launch
            val now = System.currentTimeMillis()
            repo.saveJob(job.copy(
                trips = job.trips - 1,
                lastUpdatedAt = now
            ))
        }
    }

    // ══════ LIVE OPERATIONS — HUD + Dominant Workspace ══════

    /**
     * PART 4+5: The single most operationally important job.
     * Used by ActiveWorkHud and smart return context.
     * Priority: running timer > recently paused > recent prepared.
     */
    val dominantJob: StateFlow<ActiveJobsEntity?> = if (activeJobsRepository != null) {
        activeJobsRepository.getAllActiveJobs()
            .map { jobs ->
                com.example.fieldtrack.domain.convergence.WorkspacePresence.findDominant(jobs)
            }
            .catch { emit(null) }
            .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), null)
    } else {
        MutableStateFlow(null)
    }

    /**
     * PART 8: Session fatigue profile — UI progressively compresses during long sessions.
     * Derives session start from the earliest active job created today.
     */
    val sessionFatigueProfile: StateFlow<com.example.fieldtrack.domain.convergence.SessionFatigueProfile> =
        if (activeJobsRepository != null) {
            activeJobsRepository.getAllActiveJobs()
                .map { jobs ->
                    val todayStart = com.example.fieldtrack.util.DateTimeUtils.getTodayStartMillis()
                    val sessionStart = jobs
                        .filter { it.createdAt >= todayStart }
                        .minOfOrNull { it.createdAt }
                    if (sessionStart != null) {
                        com.example.fieldtrack.domain.convergence.SessionFatigueProfile.fromSessionDuration(sessionStart)
                    } else {
                        com.example.fieldtrack.domain.convergence.SessionFatigueProfile.DEFAULT
                    }
                }
                .catch { emit(com.example.fieldtrack.domain.convergence.SessionFatigueProfile.DEFAULT) }
                .stateIn(
                    viewModelScope,
                    SharingStarted.WhileSubscribed(5000),
                    com.example.fieldtrack.domain.convergence.SessionFatigueProfile.DEFAULT
                )
        } else {
            MutableStateFlow(com.example.fieldtrack.domain.convergence.SessionFatigueProfile.DEFAULT)
        }

    // ══════ INLINE FINISH FLOW — One-Tap Completion ══════

    /** Job currently being finished inline (null = no inline finish in progress) */
    private val _inlineFinishJob = MutableStateFlow<ActiveJobsEntity?>(null)
    val inlineFinishJob: StateFlow<ActiveJobsEntity?> = _inlineFinishJob.asStateFlow()

    /**
     * Begin inline finish flow for a job.
     * Shows InlineFinishSheet if eligible, otherwise invokes onNotEligible callback.
     * If the job has a running/paused timer, auto-stops it first.
     */
    fun beginInlineFinish(jobId: String, onNotEligible: () -> Unit = {}) {
        val actionKey = "beginFinish:$jobId"
        if (!beginAction(actionKey)) return
        viewModelScope.launch {
            try {
                val repo = activeJobsRepository ?: return@launch
                var job = repo.getJobById(jobId) ?: return@launch
                val eligibility = com.example.fieldtrack.domain.convergence.InlineFinishEligibility.check(job)
                if (eligibility.eligible) {
                    // Auto-stop timer if needed (running or paused → stopped)
                    if (eligibility.needsTimerStop) {
                        if (mutationExecutor != null) {
                            val stopped = mutationExecutor.stopTimerForInlineFinish(jobId)
                            if (stopped != null) job = stopped
                        } else {
                            val now = System.currentTimeMillis()
                            val additionalPaused = if (job.isPaused && job.pauseStartTime != null) {
                                now - job.pauseStartTime
                            } else 0L
                            val stoppedJob = job.copy(
                                isPaused = false,
                                pauseStartTime = null,
                                isStopped = true,
                                endTime = now,
                                totalPausedDuration = job.totalPausedDuration + additionalPaused,
                                lastUpdatedAt = now
                            )
                            repo.saveJob(stoppedJob)
                            job = stoppedJob
                        }
                    }
                    _inlineFinishJob.value = job
                } else {
                    onNotEligible()
                }
            } finally {
                endAction(actionKey)
            }
        }
    }

    /** Dismiss inline finish sheet */
    fun dismissInlineFinish() {
        _inlineFinishJob.value = null
    }

    /**
     * Complete inline finish: save to jobs table, remove from active jobs.
     * Reuses existing save pipeline logic — no duplicate finish code.
     *
     * Safety: preserves identity verification, atomic persistence,
     * and workspace cleanup ordering.
     */
    fun completeInlineFinish(
        jobId: String,
        paymentAmount: Double? = null,
        notes: String? = null
    ) {
        val actionKey = "finish:$jobId"
        if (!beginAction(actionKey)) {
            publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Finishing work...")
            return
        }
        publishActionFeedback(jobId, ActiveWorkFeedbackState.PROCESSING, "Saving...")
        viewModelScope.launch {
            try {
                val repo = activeJobsRepository
                if (repo == null) {
                    publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not finish work")
                    return@launch
                }
                val job = repo.getJobById(jobId)
                if (job == null) {
                    publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not finish work")
                    return@launch
                }
                // Update notes if provided
                val finalJob = if (notes != null && notes != job.notes) {
                    job.copy(notes = notes, lastUpdatedAt = System.currentTimeMillis())
                } else job

                // Calculate total amount
                val totalAmount = when (finalJob.pricingMode) {
                    PricingMode.TRIP -> finalJob.trips * finalJob.rate
                    PricingMode.TRIP_AND_DISTANCE -> finalJob.trips * finalJob.distance * finalJob.rate
                    PricingMode.PACKET -> finalJob.trips * finalJob.rate
                    PricingMode.PACKET_DISTANCE -> finalJob.trips * finalJob.rate
                    PricingMode.FIXED_AMOUNT -> finalJob.rate
                    PricingMode.PER_ACRE -> finalJob.distance * finalJob.rate
                    PricingMode.TIME -> {
                        val endT = finalJob.endTime ?: System.currentTimeMillis()
                        val elapsed = ((endT - finalJob.startTime) - finalJob.totalPausedDuration)
                            .coerceAtLeast(0L) / 60000L
                        elapsed * finalJob.rate
                    }
                    PricingMode.DISTANCE -> finalJob.distance * finalJob.rate
                }

                // Build JobEntity — same structure as saveJobInternal in NewJobViewModel
                val completedByUserId = OperatorIdentityManager.currentOperatorId()
                val jobEntity = com.example.fieldtrack.data.local.entity.JobEntity(
                    machineType = finalJob.machineType,
                    machineId = finalJob.machineId,
                    machineName = finalJob.machineName,
                    pricingMode = finalJob.pricingMode,
                    rate = finalJob.rate,
                    startTime = finalJob.startTime,
                    endTime = finalJob.endTime ?: System.currentTimeMillis(),
                    durationMinutes = if (finalJob.pricingMode == PricingMode.TIME) {
                        val endT = finalJob.endTime ?: System.currentTimeMillis()
                        ((endT - finalJob.startTime - finalJob.totalPausedDuration) / 60000)
                            .coerceAtLeast(0).toInt()
                    } else null,
                    tripCount = when (finalJob.pricingMode) {
                        PricingMode.TRIP, PricingMode.TRIP_AND_DISTANCE,
                        PricingMode.PACKET, PricingMode.PACKET_DISTANCE -> finalJob.trips
                        else -> null
                    },
                    distanceKm = when (finalJob.pricingMode) {
                        PricingMode.DISTANCE, PricingMode.TRIP_AND_DISTANCE,
                        PricingMode.PACKET_DISTANCE -> finalJob.distance
                        PricingMode.PER_ACRE -> finalJob.distance
                        else -> null
                    },
                    totalAmount = totalAmount,
                    customerId = finalJob.customerId.takeIf { it.isNotBlank() },
                    loadType = finalJob.loadType,
                    fieldName = finalJob.fieldName,
                    routeLabel = finalJob.routeLabel,
                    notes = finalJob.notes,
                    paidAmount = paymentAmount ?: 0.0,
                    paymentStatus = if (paymentAmount != null && paymentAmount >= totalAmount) {
                        com.example.fieldtrack.data.local.entity.PaymentStatus.PAID
                    } else if (paymentAmount != null && paymentAmount > 0) {
                        com.example.fieldtrack.data.local.entity.PaymentStatus.PARTIAL
                    } else {
                        com.example.fieldtrack.data.local.entity.PaymentStatus.UNPAID
                    },
                    paymentDate = if (paymentAmount != null && paymentAmount > 0) {
                        System.currentTimeMillis()
                    } else null
                    organizationId = finalJob.organizationId,
                    createdByUserId = finalJob.createdByUserId,
                    assignedOperatorId = finalJob.assignedOperatorId,
                    completedByUserId = completedByUserId
                )

                // 1. Save to final jobs table
                jobRepository.saveJob(jobEntity)

                // 2. Remove from active jobs (atomic cleanup)
                repo.removeJob(jobId)

                // 3. Clear inline finish state
                _inlineFinishJob.value = null

                // 4. Refresh dashboard
                loadDashboard()
                publishActionFeedback(jobId, ActiveWorkFeedbackState.SUCCESS, "Work finished")

            } catch (e: Exception) {
                android.util.Log.e("HomeVM", "Inline finish failed for $jobId", e)
                // Don't clear job — allow retry
                publishActionFeedback(jobId, ActiveWorkFeedbackState.ERROR, "Could not finish work")
            } finally {
                endAction(actionKey)
            }
        }
    }

    fun discardActiveJob() {
        viewModelScope.launch {
            activeJobRepository.clearJob()
            _showRecoveryDialog.value = false
        }
    }

    /**
     * Finish the current draft (stopped) active job into the jobs table,
     * then clear it so the user can start a new job.
     */
    fun finalizeActiveJob(onComplete: () -> Unit = {}) {
        viewModelScope.launch {
            val job = activeJob.value ?: return@launch
            if (!job.isStopped) return@launch // Only finalize stopped (draft) jobs

            val endT = job.endTime ?: System.currentTimeMillis()
            val elapsed = ((endT - job.startTime) - job.totalPausedDuration).coerceAtLeast(0)
            val durationMinutes = (elapsed / 60_000).toInt()

            val rate = job.rate
            val mode = job.pricingMode
            val totalAmount = when (mode) {
                PricingMode.TIME -> durationMinutes * rate
                PricingMode.TRIP -> job.trips * rate
                PricingMode.DISTANCE -> job.distance * rate
                PricingMode.TRIP_AND_DISTANCE -> job.trips * job.distance * rate
                PricingMode.PACKET -> job.trips * rate
                PricingMode.PACKET_DISTANCE -> job.trips * rate // Hybrid: packets + distance (distance rate not stored in legacy job)
                PricingMode.PER_ACRE -> job.distance * rate
                PricingMode.FIXED_AMOUNT -> rate // For fixed amount, rate IS the final amount
            }

            val entity = JobEntity(
                machineType = job.machineType,
                machineId = job.machineId,
                machineName = job.machineName,
                pricingMode = mode, // stored for backward compat
                rate = rate,
                startTime = job.startTime,
                endTime = endT,
                durationMinutes = if (mode == PricingMode.TIME) durationMinutes else null,
                tripCount = if (mode == PricingMode.TRIP || mode == PricingMode.TRIP_AND_DISTANCE || mode == PricingMode.PACKET) job.trips else null,
                distanceKm = if (mode == PricingMode.DISTANCE || mode == PricingMode.TRIP_AND_DISTANCE) job.distance else null,
                totalAmount = totalAmount,
                customerId = job.customerId.takeIf { it.isNotBlank() },
                loadType = job.loadType,
                fieldName = job.fieldName,
                routeLabel = job.routeLabel,
                notes = job.notes,
                organizationId = job.organizationId,
                createdByUserId = job.createdByUserId,
                assignedOperatorId = job.assignedOperatorId,
                completedByUserId = OperatorIdentityManager.currentOperatorId()
            )

            jobRepository.saveJob(entity)
            activeJobRepository.clearJob()
            _showRecoveryDialog.value = false
            loadDashboard() // Refresh stats
            onComplete()
        }
    }

    private fun loadDashboard() {
        val todayRange = DateTimeUtils.getTodayRange()
        viewModelScope.launch {
            combine(
                jobRepository.getTotalEarningsInRange(todayRange),
                jobRepository.getJobCountInRange(todayRange),
                jobRepository.getTotalPendingInRange(todayRange),
                jobRepository.getAllTimeTotalEarnings(),
                jobRepository.getAllTimeTotalCollected(),
                jobRepository.getAllTimeTotalPending(),
                jobRepository.getTotalCollectedByPaymentDate(todayRange)
            ) { values ->
                DashboardUiState(
                    todayEarnings = values[0] as Double,
                    todayJobs = values[1] as Int,
                    todayPending = values[2] as Double,
                    allTimeEarnings = values[3] as Double,
                    allTimeCollected = values[4] as Double,
                    allTimePending = values[5] as Double,
                    todayCollected = values[6] as Double,
                    isLoading = false
                )
            }
            .catch { _uiState.value = DashboardUiState(isLoading = false) }
            .collect { _uiState.value = it }
        }
    }

    fun retrySyncNow() {
        syncManager?.scheduleOneTimeSync()
    }

    // ================== Dashboard Preview Sheet ==================

    /** Preview jobs for COLLECTED/TOTAL sheets (flat list, max 5). */
    private val _previewJobs = MutableStateFlow<List<JobEntity>>(emptyList())
    val previewJobs: StateFlow<List<JobEntity>> = _previewJobs.asStateFlow()

    /** Customer name map for flat preview jobs. */
    private val _previewCustomerNames = MutableStateFlow<Map<String, String>>(emptyMap())
    val previewCustomerNames: StateFlow<Map<String, String>> = _previewCustomerNames.asStateFlow()

    /** Customer-grouped due previews for PENDING sheet (max 5 customers). */
    private val _customerDuePreviews = MutableStateFlow<List<CustomerDuePreview>>(emptyList())
    val customerDuePreviews: StateFlow<List<CustomerDuePreview>> = _customerDuePreviews.asStateFlow()

    /** Customer-grouped amount previews for COLLECTED/TOTAL sheets. */
    private val _customerAmountPreviews = MutableStateFlow<List<CustomerAmountPreview>>(emptyList())
    val customerAmountPreviews: StateFlow<List<CustomerAmountPreview>> = _customerAmountPreviews.asStateFlow()

    private val _previewLoading = MutableStateFlow(false)
    val previewLoading: StateFlow<Boolean> = _previewLoading.asStateFlow()

    /**
     * Load preview data for a given dashboard action type.
     * PENDING: customer-grouped dues (max 5 customers, sorted by totalDue DESC).
     * COLLECTED/TOTAL: flat job list (max 5 jobs).
     */
    fun loadPreviewJobs(type: DashboardActionType) {
        viewModelScope.launch {
            _previewLoading.value = true
            try {
                when (type) {
                    DashboardActionType.PENDING -> loadPendingGrouped()
                    else -> loadFlatPreview(type)
                }
            } catch (_: Exception) {
                _previewJobs.value = emptyList()
                _previewCustomerNames.value = emptyMap()
                _customerDuePreviews.value = emptyList()
            } finally {
                _previewLoading.value = false
            }
        }
    }

    private suspend fun loadPendingGrouped() {
        // Fetch all unpaid jobs (not just 5) to group by customer
        val allUnpaid = jobRepository.getRecentUnpaidJobs()
        val customerIds = allUnpaid.mapNotNull { it.customerId }.distinct()
        val nameMap = customerRepository.getCustomerNameMap(customerIds)

        val now = System.currentTimeMillis()
        val sevenDaysMs = 7L * 24 * 60 * 60 * 1000

        val grouped = allUnpaid
            .filter { it.customerId != null }
            .groupBy { it.customerId!! }
            .map { (customerId, jobs) ->
                CustomerDuePreview(
                    customerId = customerId,
                    customerName = nameMap[customerId] ?: "Unknown",
                    totalDue = jobs.sumOf { it.remainingAmount },
                    jobCount = jobs.size,
                    oldestUnpaidJobDate = jobs.minOf { it.createdAt },
                    hasOverdue = jobs.any { (now - it.createdAt) > sevenDaysMs }
                )
            }
            .sortedByDescending { it.totalDue }
            .take(5)

        // Also include jobs without customer (unassigned)
        val unassigned = allUnpaid.filter { it.customerId == null }
        val finalList = if (unassigned.isNotEmpty()) {
            grouped + CustomerDuePreview(
                customerId = "",
                customerName = "Unassigned Jobs",
                totalDue = unassigned.sumOf { it.remainingAmount },
                jobCount = unassigned.size,
                oldestUnpaidJobDate = unassigned.minOf { it.createdAt },
                hasOverdue = unassigned.any { (now - it.createdAt) > sevenDaysMs }
            )
        } else grouped

        _customerDuePreviews.value = finalList.take(5)
    }

    private suspend fun loadFlatPreview(type: DashboardActionType) {
        val jobs = when (type) {
            DashboardActionType.COLLECTED -> jobRepository.getRecentPaidJobs()
            else -> jobRepository.getRecentJobs()
        }
        _previewJobs.value = jobs

        val customerIds = jobs.mapNotNull { it.customerId }.distinct()
        val nameMap = customerRepository.getCustomerNameMap(customerIds)
        _previewCustomerNames.value = nameMap

        // Build customer-grouped previews
        val grouped = jobs
            .groupBy { it.customerId }
            .map { (custId, custJobs) ->
                CustomerAmountPreview(
                    customerId = custId,
                    customerName = custId?.let { nameMap[it] } ?: "Unassigned",
                    totalAmount = when (type) {
                        DashboardActionType.COLLECTED -> custJobs.sumOf { it.paidAmount }
                        else -> custJobs.sumOf { it.totalAmount }
                    },
                    jobCount = custJobs.size,
                    lastActivityAt = custJobs.maxOf { it.createdAt }
                )
            }
            .sortedByDescending { it.totalAmount }
            .take(5)

        _customerAmountPreviews.value = grouped
    }

    class Factory(
        private val jobRepository: JobRepository,
        private val activeJobRepository: ActiveJobRepository,
        private val customerRepository: CustomerRepository,
        private val syncManager: SyncManager? = null,
        private val activeJobsRepository: ActiveJobsRepository? = null,
        private val mutationExecutor: OperationalMutationExecutor? = null,
        // R6.3 PART 1 — Optional MachineRepository (see machineCount above).
        private val machineRepository: MachineRepository? = null
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            if (modelClass.isAssignableFrom(HomeViewModel::class.java)) {
                return HomeViewModel(jobRepository, activeJobRepository, customerRepository, syncManager, activeJobsRepository, mutationExecutor, machineRepository) as T
            }
            throw IllegalArgumentException("Unknown ViewModel class")
        }
    }

    /** Convert ActiveJobsEntity to a lightweight workspace pill summary */
    private fun ActiveJobsEntity.toWorkspacePill(): ActiveJobSummary {
        val cap = getJobCapability()
        val now = System.currentTimeMillis()
        val isTimeMode = pricingMode == PricingMode.TIME

        val elapsed = when {
            isStopped -> {
                val endT = endTime ?: now
                ((endT - startTime) - totalPausedDuration) / 1000
            }
            isPaused -> {
                val pauseT = pauseStartTime ?: now
                ((pauseT - startTime) - totalPausedDuration) / 1000
            }
            isTimeMode && startTime > 0 -> {
                ((now - startTime) - totalPausedDuration) / 1000
            }
            else -> 0L
        }.coerceAtLeast(0)

        val running = isTimeMode && !isPaused && !isStopped && startTime > 0
        // CANONICAL: Lifecycle mapper + BillingModeRegistry for status
        val lifecycleState = when {
            running -> com.example.fieldtrack.domain.session.WorkspaceLifecycleState.ACTIVE
            isPaused -> com.example.fieldtrack.domain.session.WorkspaceLifecycleState.PAUSED
            isStopped -> com.example.fieldtrack.domain.session.WorkspaceLifecycleState.COMPLETED
            else -> com.example.fieldtrack.domain.session.WorkspaceLifecycleState.CREATED
        }
        val statusText = if (trips > 0 && !running && !isPaused) {
            com.example.fieldtrack.domain.billing.BillingModeRegistry.getDefinition(pricingMode).formatQuantityLabel(trips)
        } else {
            "${OperationalLifecycleMapper.stateEmoji(lifecycleState)} ${OperationalLifecycleMapper.uiLabel(lifecycleState)}"
        }

        return ActiveJobSummary(
            jobId = jobId,
            machineName = machineName,
            customerName = customerName,
            jobCapability = cap,
            elapsedSeconds = elapsed,
            tripCount = trips,
            isRunning = running,
            isPaused = isPaused,
            emoji = cap?.emoji ?: "",
            displayName = if (machineName != null) "${cap?.displayName ?: "Job"} • $machineName" else cap?.displayName ?: "Job",
            statusLabel = statusText
        )
    }
}

package com.example.fieldtrack.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey import androidx.room.TypeConverter import androidx.room.TypeConverters
/** * Room Entity representing a completed/saved Job record. * * This entity stores all job-related data including: * - Machine and pricing mode information * - Time tracking (start/end for TIME mode) * - Trip counting (for TRIP mode) * - Distance tracking (for DISTANCE mode) * - Rate and calculated total * - Customer link (optional) * - Payment tracking * * OPERATIONAL HARDENING — Data Model Safety: * - This table holds IMMUTABLE completed jobs. Once saved, records should never be modified. * - `totalAmount` is computed at save time and snapshotted — NOT derived from live data. * - `segmentsJson` captures the exact work breakdown at completion — immutable audit trail. * - Payment fields (`amountPaid`, `paymentMode`) are post-completion metadata. * * Schema History: * v1 — Initial entity (core fields) * v2 — Added segmentsJson, loadType, fieldName, notes * v3 — Added payment fields (amountPaid, paymentMode, paymentNote) * * Future extensions (add as nullable columns with defaults): * - locationData: GPS capture for field verification * - syncStatus: Offline-first cloud sync flag * - invoiceId: Link to invoice system * - operatorId: Multi-user role system * - schemaVersion: Explicit version for migration safety * * PERFORMANCE NOTE (System Polish PART 12): * When jobs table grows to 1000+ rows, consider adding indices: * @Entity(tableName = "jobs", indices = [Index("customerId"), Index("createdAt")]) * This requires a DB migration (increment version in FieldFlowDatabase). * Current queries that would benefit: getJobsByCustomerId, getJobsInDateRange. */ @Entity(tableName = "jobs") @TypeConverters(JobConverters::class) data class JobEntity( @PrimaryKey(autoGenerate = true) val id: Long = 0,
// Machine information val machineType: MachineType, /** Reference to MachineEntity.machineId. Nullable for legacy/imported jobs. */ val machineId: String? = null, /** Snapshot of machine name at job creation time — survives machine deletion/rename. */ val machineName: String? = null,
// Pricing configuration val pricingMode: PricingMode, val rate: Double, // Rate per unit (per hour, per trip, per km)
// Time-based tracking val startTime: Long? = null, // Epoch millis val endTime: Long? = null, // Epoch millis val durationMinutes: Int? = null, // Calculated duration in minutes
// Trip-based tracking val tripCount: Int? = null,
// Distance-based tracking (prepared for future) val distanceKm: Double? = null,
// Calculated result val totalAmount: Double,
// Customer link (nullable for backward compatibility) val customerId: String? = null,
// Payment tracking val paymentStatus: PaymentStatus = PaymentStatus.UNPAID, val paidAmount: Double = 0.0, // Amount paid so far (for partial payments) val paymentDate: Long? = null, // Epoch millis when last payment was made
// Metadata val createdAt: Long = System.currentTimeMillis(), val notes: String? = null, val loadType: String? = null, // e.g., "Paddy", "Sand" val fieldName: String? = null, // e.g., "North Field" val village: String? = null, // e.g., "Rampur" val season: String? = null, // e.g., "Paddy Season"
// Sync fields val updatedAt: Long = System.currentTimeMillis(), val updatedBy: String = "local", val syncStatus: String = "PENDING", // PENDING, SYNCED, FAILED val retryCount: Int = 0, val lastSyncAttempt: Long? = null,
// Segment-based pricing (JSON serialized list of WorkSegment) val segmentsJson: String? = null,
/** * How this job was created. Subtle audit trail — not exposed as enterprise log. * Values: "tracked" (default, real-time), "manual" (added later), "imported" */ val entrySource: String = "tracked",
/** * Timestamp of last meaningful edit after initial save. * Null = never edited. Enables subtle "Edited later" label in history. */ val editedAt: Long? = null,
/** * Quick operational note from operator (max ~150 chars). * Use cases: "Diesel included", "Will pay tomorrow", "Half-acre remaining" * Optional, never blocking. Distinct from `notes` (which is job-level context). */ val operatorNote: String? = null,
/** * OPERATIONAL HARDENING PART 14: Schema version for future-safe migrations. * Increment when the business data format changes (e.g., new segment types). * Allows migration code to handle old vs new records differently. */ val schemaVersion: Int = 1 ) { /** * Derived pricing mode from machine type — use this instead of stored pricingMode. * Stored pricingMode kept for backward compatibility only.
/** * Calculate remaining amount to be paid. */ val remainingAmount: Double get() = (totalAmount - paidAmount).coerceAtLeast(0.0)
/** * Check if job is fully paid. */ val isFullyPaid: Boolean get() = paidAmount >= totalAmount
/** * Compare business data only (ignore sync metadata). * Used to skip unnecessary Firestore writes. */ fun isSameBusinessData(other: JobEntity): Boolean = machineType == other.machineType && machineId == other.machineId && machineName == other.machineName && pricingMode == other.pricingMode && rate == other.rate && startTime == other.startTime && endTime == other.endTime && durationMinutes == other.durationMinutes && tripCount == other.tripCount && distanceKm == other.distanceKm && totalAmount == other.totalAmount && customerId == other.customerId && paymentStatus == other.paymentStatus && paidAmount == other.paidAmount && paymentDate == other.paymentDate && notes == other.notes && loadType == other.loadType && fieldName == other.fieldName && village == other.village && season == other.season && segmentsJson == other.segmentsJson && entrySource == other.entrySource && operatorNote == other.operatorNote }
/** * Type converters for Room to handle enum types. */ class JobConverters { @TypeConverter fun fromMachineType(value: MachineType): String = value.name
@TypeConverter fun toMachineType(value: String): MachineType = MachineType.valueOf(value)
@TypeConverter fun fromPricingMode(value: PricingMode): String = value.name
@TypeConverter fun toPricingMode(value: String): PricingMode = PricingMode.valueOf(value)
@TypeConverter fun fromPaymentStatus(value: PaymentStatus): String = value.name
@TypeConverter fun toPaymentStatus(value: String): PaymentStatus = PaymentStatus.fromName(value) }

