/**
 * ViewModel for the New Job screen.
 *
 * Handles:
 * - Machine type and pricing mode selection
 * - Customer selection
 * - Timer management for TIME mode
 * - Trip counting for TRIP mode
 * - Rate input validation
 * - Job saving to repository
 *
 * Design notes:
 * - Uses StateFlow for reactive UI updates
 * - Timer runs in coroutine scope
 * - All business logic is in ViewModel or utils, not in UI
 */
class NewJobViewModel(
    private val jobRepository: JobRepository,
    private val customerRepository: CustomerRepository,
    private val ratePreferences: RatePreferences,
    private val customerFieldDao: CustomerFieldDao,
    private val activeJobRepository: ActiveJobRepository,
    private val machineRepository: MachineRepository,
    private val activeJobsRepository: ActiveJobsRepository,
    private val workPatternPreferences: WorkPatternPreferences,
    val isTemplateFlow: Boolean = false,
    private val initialTemplateId: String? = null,
    private val startAsFreshDraft: Boolean = false,
    private val restoreJobId: String? = null
) : ViewModel() {

    private val _uiState = MutableStateFlow(NewJobUiState(isTemplateFlow = isTemplateFlow, isDraftMode = startAsFreshDraft))
    val uiState: StateFlow<NewJobUiState> = _uiState.asStateFlow()

    // ================== Multi-Job System (PARTS 1-14) ==================

    /** PART 1: All active jobs as a live flow */
    val activeJobs: StateFlow<List<ActiveJobsEntity>> = activeJobsRepository.getAllActiveJobs()
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    /** PART 1: Active job summaries for UI display */
    val activeJobSummaries: StateFlow<List<ActiveJobSummary>> = activeJobs
        .map { jobs -> jobs.map { it.toSummary() } }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    /** PART 7: Customer IDs with active jobs today — for smart picker sort */
    val activeCustomerIds: StateFlow<Set<String>> = activeJobs
        .map { jobs -> jobs.mapNotNull { it.customerId }.toSet() }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptySet())

    /** PART 8: Machine IDs currently locked by active jobs (requires actual work, not just config) */
    val inUseMachineIds: StateFlow<Set<String>> = activeJobs
        .map { jobs -> jobs.filter { it.isLockingMachine }.mapNotNull { it.machineId }.toSet() }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptySet())

    /** PART 6: Machine ID → lock label including customer name for clarity.
     *  Shows "Working for Ramesh" instead of just work type — people remember customers faster. */
    val inUseJobLabels: StateFlow<Map<String, String>> = activeJobs
        .map { jobs ->
            jobs.filter { it.machineId != null }.associate { job ->
                val cap = job.getJobCapability()
                val workLabel = cap?.let { "${it.emoji} ${it.displayName}" } ?: "Working"
                val customerLabel = job.customerName?.let { " for $it" } ?: ""
                job.machineId!! to "$workLabel$customerLabel"
            }
        }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyMap())

    /** PART 2: Current job ID tracking */
    var currentJobId: String? by mutableStateOf(null)
        private set

    /** PART 9: Debounce job for auto-save */
    private var autoSaveMultiJob: Job? = null

    /** PART 1: Guard against duplicate save of the same finalized job */
    private var hasSavedCurrentJob = false

    // Timer coroutine job for cancellation
    private var timerJob: Job? = null

    // PART 3: Undo memory window — 8 second timer
    private var undoTimerJob: Job? = null

    // Track if user manually edited the rate (don't override manual input)
    private var userEditedRate = false

    // Track if we should auto-select the next new customer added
    private var pendingAutoSelectCustomer = false

    // PART 3: Race condition protection — prevent double execution of billing switch
    private var isProcessingBillingSwitch = false

    // PART 3: Double-tap protection for machine switch
    private var isProcessingMachineSwitch = false

    // PART 6: Undo support — store previous state before machine switch reset
    private var undoMachineSwitchData: MachineSwitchUndoData? = null

    // ══════ OPERATIONAL HARDENING ══════

    /** PART 3: Mutex to prevent concurrent database writes (save races) */
    private val saveMutex = Mutex()

    /** PART 1: Minimum interval between persist calls to avoid write spam */
    private var lastPersistTime: Long = 0

    /** OPERATIONAL HARDENING: Snapshot version counter — incremented on every persist to detect stale overwrites */
    private var persistVersion: Int = 0

    /**
     * PART 1: Validate and execute a job phase transition.
     * Logs illegal transitions but does NOT crash — field operation > strict enforcement.
     * Returns true if transition was allowed.
     */
    private fun transitionTo(target: JobPhase): Boolean {
        val current = _uiState.value.jobPhase
        if (current == target) return true // No-op, already in target phase
        if (!current.isTransitionAllowed(target)) {
            // CANONICAL: Use lifecycle mapper for descriptive trace
            android.util.Log.w(
                "NewJobVM",
                "⚠️ ${OperationalLifecycleMapper.describeTransition(current, target, "transitionTo")}"
            )
            return false
        }
        _uiState.update { it.copy(jobPhase = target) }
        return true
    }

    /**
     * CANONICAL PART 12: Verify operational invariants for current state.
     * Called during debug sessions and after critical state transitions.
     * Logs violations but never blocks operation — field safety > strict enforcement.
     */
    private fun verifyInvariants() {
        val s = _uiState.value
        val checkState = com.example.fieldtrack.domain.invariant.InvariantCheckState(
            phase = s.jobPhase,
            isTimerTicking = s.isTimerRunning,
            timerStartTimeMs = s.timerStartTime,
            activeTimerCount = if (s.isTimerRunning) 1 else 0,
            isSaveInProgress = s.isSaving,
            hasWorkspace = s.currentJobId != null,
            hasValidJobData = s.selectedMachine != null || s.selectedJobCapability != null,
            machineId = s.selectedMachine?.machineId,
            segmentCount = s.segments.size,
            segmentTotal = if (s.segments.isNotEmpty()) s.segments.sumOf { it.amount } else 0.0,
            calculatedTotal = s.calculatedTotal,
            snapshotVersion = 0
        )
        val violations = com.example.fieldtrack.domain.invariant.OperationalInvariants.validateAll(checkState)
        violations.forEach { v ->
            android.util.Log.w("INVARIANT", "${v.code} [${v.severity}]: ${v.description}")
        }
    }

    init {
        loadCustomers()
        loadRecentCustomers()
        loadMachines()
        loadRecentMachineIds()
        // REMOVED: restoreActiveJob() — multi-workspace system no longer auto-restores
        // from the legacy single-job slot. Jobs are restored explicitly when user
        // taps a workspace pill or job tab (via switchToJob/restoreFromActiveJobsEntity).
        autoFillRate()

        // OPERATIONAL HARDENING: Clean up stale jobs on startup (prevents ghost machine locks)
        cleanupStaleJobs()

        when {
            // FLOW B: Explicit workspace restore — user tapped a specific active job
            restoreJobId != null -> {
                android.util.Log.d("NewJobVM", "WORKSPACE RESTORED: $restoreJobId")
                openWorkspaceJob(restoreJobId)
            }
            // FLOW A: Fresh draft — completely clean slate
            startAsFreshDraft -> {
                android.util.Log.d("NewJobVM", "DRAFT MODE OPENED")
                // No loading of active jobs — blank slate
            }
            // Legacy fallback: load most recent active job (for Screen.NewJob.route)
            else -> {
                loadActiveJobsOnStart()
            }
        }

        // Auto-apply template ONLY in quick-job (template-first) flow.
        // Supports both old template IDs and new JobCapability names.
        if (isTemplateFlow && !initialTemplateId.isNullOrBlank()) {
            // Try as JobCapability name first (new work-type-first flow)
            val capability = JobCapability.fromName(initialTemplateId)
            if (capability != null) {
                // Switch to work-type-first mode (not template mode)
                _uiState.update { it.copy(isTemplateFlow = false) }
                selectJobCapability(capability)
            } else {
                // Fallback: old template ID
                JobTemplates.findById(initialTemplateId)?.let { selectTemplate(it) }
            }
        }
    }

    private fun loadMachines() {
        viewModelScope.launch {
            machineRepository.getAllMachines().collect { machines ->
                _uiState.update { it.copy(machines = machines) }
                // Auto-select single available machine — never override existing selection.
                autoSelectSingleMachineIfPossible()
                // PART 6: Load machine activity labels
                loadMachineActivity(machines.map { it.machineId })
            }
        }
    }

    // PART 6: Machine activity awareness
    private val _machineActivity = MutableStateFlow<Map<String, String>>(emptyMap())
    val machineActivity: StateFlow<Map<String, String>> = _machineActivity.asStateFlow()

    private fun loadMachineActivity(machineIds: List<String>) {
        viewModelScope.launch {
            try {
                _machineActivity.value = jobRepository.getMachineActivityLabels(machineIds)
            } catch (_: Exception) {
                _machineActivity.value = emptyMap()
            }
        }
