    /** Load recently used machine IDs from last 3 jobs (for picker sheet). */
    private fun loadRecentMachineIds() {
        viewModelScope.launch {
            try {
                val recentJobs = jobRepository.getRecentJobs()
                val recentIds = recentJobs
                    .mapNotNull { it.machineId }
                    .distinct()
                    .take(3)
                _uiState.update { it.copy(recentMachineIds = recentIds) }
            } catch (_: Exception) {
                // Non-critical — silently ignore
            }
        }
    }

    /**
     * If only one machine is available (filtered in template-flow, or all in machine-flow),
     * auto-select it to remove an unnecessary tap.
     * Also handles restoring the machine selection for an active job when machines load after restore.
     */
    private fun autoSelectSingleMachineIfPossible() {
        val state = _uiState.value
        if (state.selectedMachine != null) return // user already chose

        // If an active job was restored (timerStartTime set or trips > 0), find the matching machine
        if (state.timerStartTime != null || state.tripCount > 0 || state.segments.isNotEmpty()) {
            val candidates = if (state.isTemplateFlow) state.filteredMachines else state.machines
            val matchingMachine = candidates.firstOrNull {
                try { MachineType.valueOf(it.type) == state.selectedMachineType } catch (_: Exception) { false }
            }
            if (matchingMachine != null) {
                _uiState.update { it.copy(selectedMachine = matchingMachine) }
                return
            }
        }

        val candidates = if (state.isTemplateFlow) state.filteredMachines else state.machines
        if (candidates.size == 1) {
            selectMachine(candidates.first())
        }
    }

    private fun loadCustomers() {
        viewModelScope.launch {
            customerRepository.getAllCustomers().collect { customers ->
                val previousCount = _uiState.value.availableCustomers.size
                _uiState.update { it.copy(availableCustomers = customers) }

                // Auto-select newest customer if we just came back from Add Customer
                if (pendingAutoSelectCustomer && customers.size > previousCount && customers.isNotEmpty()) {
                    pendingAutoSelectCustomer = false
                    // Newest customer = most recently created (last in list sorted by name, or first by createdAt desc)
                    val newest = customers.maxByOrNull { it.createdAt }
                    newest?.let { selectCustomer(it) }
                }

                // PART 7: Auto-select single customer — removes unnecessary tap
                if (_uiState.value.selectedCustomer == null && customers.size == 1) {
                    selectCustomer(customers.first())
                }
            }
        }
    }

    /**
     * Call before navigating to Add Customer screen.
     * When a new customer is saved and we return, it will be auto-selected.
     */
    fun markPendingCustomerAutoSelect() {
        pendingAutoSelectCustomer = true
    }

    private fun loadRecentCustomers() {
        viewModelScope.launch {
            customerRepository.getRecentCustomers().collect { recent ->
                _uiState.update { it.copy(recentCustomers = recent) }
            }
        }
    }

    // ================== Active Job Persistence ==================

    /**
     * Restore an in-progress job from the database (survives app restart).
     * If a timer was running, it resumes automatically using the persisted startTime.
     */

    // ================== Job Lifecycle ==================

    /**
     * Creates a job entry in active_jobs ONLY when real work begins.
     * Selection functions (machine, capability, rate) should NEVER call this.
     * Called from: startTimer(), onAddTrip(), onAddMultipleTrips(), incrementTrip()
     */
    private fun ensureActiveJobCreated() {
        if (currentJobId != null) return

        val jobId = UUID.randomUUID().toString()
        currentJobId = jobId
        hasSavedCurrentJob = false
        _uiState.update { it.copy(currentJobId = jobId, isDraftMode = false) }

        // Initial save to active_jobs table
        viewModelScope.launch {
            // OPERATIONAL HARDENING: Prevent unbounded job creation
            val existingJobs = activeJobsRepository.getAllActiveJobsOnce()
            if (existingJobs.size >= JobConstants.MAX_ACTIVE_JOBS) {
                // Remove oldest job without meaningful work
                val removable = existingJobs
                    .filter { !it.hasWork }
                    .minByOrNull { it.createdAt }
                if (removable != null) {
                    activeJobsRepository.removeJob(removable.jobId)
                } else {
                    android.util.Log.w("NewJobVM", "⚠️ MAX_ACTIVE_JOBS reached (${JobConstants.MAX_ACTIVE_JOBS}) — all have work")
                }
            }

            // PART 9: Remove any existing draft (no work) before creating new one
            existingJobs.filter { !it.hasWork }.forEach {
                activeJobsRepository.removeJob(it.jobId)
            }

            val state = _uiState.value
            val entity = ActiveJobsEntity(
                jobId = jobId,
                customerId = state.selectedCustomer?.customerId ?: "",
                customerName = state.selectedCustomer?.name,
                machineId = state.selectedMachine?.machineId,
                machineName = state.selectedMachine?.name,
                machineType = state.selectedMachineType,
                pricingMode = state.selectedPricingMode,
                rate = state.rateInput.toDoubleOrNull() ?: 0.0,
                jobCapability = state.selectedJobCapability?.name
            )
            activeJobsRepository.saveJob(entity)
        }
    }

    /**
     * Persist current job state to survive app restarts.
     * Guard: only persists if a job has been started (has currentJobId).
     * OPERATIONAL HARDENING: Throttled to prevent write spam on rapid state changes.
     */
    private fun persistActiveJob() {
        if (currentJobId == null) return // PART 6: No job started yet — don't persist

        // OPERATIONAL HARDENING: Don't write after job is saved/saving (prevents stale overwrite race)
        val phase = _uiState.value.jobPhase
        if (phase == JobPhase.SAVED || phase == JobPhase.SAVING) return

        // Throttle: skip if last persist was < MIN_PERSIST_INTERVAL_MS ago
        val now = System.currentTimeMillis()
        if (now - lastPersistTime < JobConstants.MIN_PERSIST_INTERVAL_MS) return
        lastPersistTime = now
        persistVersion++

        val state = _uiState.value
        val customerId = state.selectedCustomer?.customerId ?: ""
        val startTime = state.timerStartTime ?: System.currentTimeMillis()

        viewModelScope.launch {
            activeJobRepository.startJob(
                ActiveJobEntity(
                    customerId = customerId,
                    machineType = state.selectedMachineType,
                    pricingMode = state.selectedPricingMode,
                    rate = state.rateInput.toDoubleOrNull() ?: 0.0,
                    pricingLabel = null,
                    startTime = startTime,
                    trips = state.tripCount,
                    distance = if (state.selectedPricingMode == PricingMode.PER_ACRE)
                        state.acreQuantity.toDoubleOrNull() ?: 0.0
                    else
                        state.distanceKm.toDoubleOrNull() ?: 0.0,
                    fieldName = state.fieldName.takeIf { it.isNotBlank() },
                    loadType = state.loadType.takeIf { it.isNotBlank() },
                    notes = state.notes.takeIf { it.isNotBlank() },
                    isRateEdited = userEditedRate,
                    isPaused = state.isTimerPaused,
                    pauseStartTime = state.pauseStartTime,
                    totalPausedDuration = state.totalPausedDuration,
                    isStopped = state.timerEndTime != null && !state.isTimerRunning && !state.isTimerPaused,
                    endTime = state.timerEndTime,
                    segmentsJson = if (state.segments.isNotEmpty())
                        SegmentSerializer.toJson(state.segments) else null,
                    // PART 2: Persist job capability for recovery
                    jobCapability = state.selectedJobCapability?.name
                )
            )
        }
        // PART 9: Also save to multi-job table (debounced)
        if (currentJobId != null) {
            saveCurrentJobDebounced()
        }
    }

    private fun clearActiveJob() {
        viewModelScope.launch {
            activeJobRepository.clearJob()
        }
    }

    /**
     * Only persist if a job is currently in progress (timer running/paused, or trips > 0).
     * Avoids writing to DB when user is just browsing the form.
     */
    private fun persistActiveJobIfExists() {
        val state = _uiState.value
        val hasActiveWork = state.isTimerRunning || state.isTimerPaused ||
            state.timerStartTime != null || state.tripCount > 0 || state.segments.isNotEmpty() ||
            (state.acreQuantity.toDoubleOrNull() ?: 0.0) > 0
        if (hasActiveWork) {
            persistActiveJob()
        }
    }

    /**
     * Check if there is an active job in progress.
     */
    fun hasActiveJob(): Boolean {
        val state = _uiState.value
        return state.isTimerRunning || state.isTimerPaused ||
            (state.timerStartTime != null && state.timerEndTime == null) ||
            (state.timerStartTime != null && state.timerEndTime != null) || // stopped but not saved
            state.tripCount > 0 || state.segments.isNotEmpty()
    }

    /**
     * Discard the current active job completely.
     */
    fun discardJob() {
        timerJob?.cancel()
        userEditedRate = false
        hasSavedCurrentJob = false
        clearActiveJob()

        // CANONICAL: Emit work discarded event
        currentJobId?.let { jobId ->
            WorkEventBus.emit(WorkEvent.WorkDiscarded(
                jobId = jobId,
                hadMeaningfulWork = _uiState.value.hasMeaningfulWork
            ))
        }

        // Remove from multi-job table if job was started
        currentJobId?.let { jobId ->
            viewModelScope.launch {
                activeJobsRepository.removeJob(jobId)
            }
        }
        currentJobId = null

        val prev = _uiState.value
        _uiState.value = NewJobUiState(
            isTemplateFlow = isTemplateFlow,
            availableCustomers = prev.availableCustomers,
            recentCustomers = prev.recentCustomers,
            machines = prev.machines,
            recentMachineIds = prev.recentMachineIds
        )
    }

    // ================== Customer Selection ==================

    fun showCustomerPicker() {
        _uiState.update { it.copy(showCustomerPicker = true) }
    }

    fun hideCustomerPicker() {
        _uiState.update { it.copy(showCustomerPicker = false) }
    }

    fun selectCustomer(customer: CustomerEntity?) {
        // Customer-first workspaces: Multiple customers can have active work simultaneously.
        // Only machine locking remains as a global restriction.

        _uiState.update {
            it.copy(
                selectedCustomer = customer,
                showCustomerPicker = false,
                fieldSuggestions = emptyList(),
                lastJobSuggestion = null
            )
        }
        // Update lastUsedAt + load field suggestions + fetch last job
        customer?.let {
            loadFieldSuggestions(it.customerId)
            viewModelScope.launch {
                customerRepository.updateLastUsedAt(it.customerId)
                val lastJob = jobRepository.getLastJobByCustomer(it.customerId)
                _uiState.update { s -> s.copy(lastJobSuggestion = lastJob) }
            }
            // PART 9: Check for duplicate active work
            checkForDuplicateWork()
        }
    }

    /** Apply settings from the customer's last job (machine, mode, rate). PART 5: Workflow memory. */
    fun applyLastJobSuggestion() {
        val lastJob = _uiState.value.lastJobSuggestion ?: return
        userEditedRate = false

        // Find the machine entity if it still exists
        val lastMachine = lastJob.machineId?.let { id ->
            _uiState.value.machines.find { it.machineId == id }
        }

        _uiState.update {
            it.copy(
                selectedMachineType = lastJob.machineType,
                selectedPricingMode = lastJob.pricingMode,
                rateInput = lastJob.rate.toString(),
                selectedMachine = lastMachine ?: it.selectedMachine,
                lastJobSuggestion = null // hide suggestion after applying
            )
        }

        // PART 9: Emit repeat flow event
        WorkEventBus.emit(WorkEvent.RepeatFlowStarted(
            jobId = currentJobId,
            sourceJobId = lastJob.id.toString()
        ))
    }

    fun dismissLastJobSuggestion() {
        _uiState.update { it.copy(lastJobSuggestion = null) }
    }

