    }

    fun hideBulkEntrySheet() {
        _uiState.update { it.copy(showBulkEntrySheet = false) }
    }

    /** Toggle expand/collapse of a segment group in the UI. */
    fun toggleGroupExpand(groupKey: String) {
        _uiState.update { state ->
            val expanded = state.expandedGroupKeys.toMutableSet()
            if (expanded.contains(groupKey)) expanded.remove(groupKey) else expanded.add(groupKey)
            state.copy(expandedGroupKeys = expanded)
