    }

    /**
     * Event-based autosave — triggered on segment add/edit/delete.
     * Does NOT autosave while user is typing rate.
     */
    private fun autoSaveDraft() {
        _uiState.update { it.copy(isAutoSaving = true) }
        persistActiveJob()
        saveCurrentJobDebounced() // PART 9: Also save to multi-job table
        _uiState.update { it.copy(isAutoSaving = false, lastSavedAt = System.currentTimeMillis()) }
    }

    // ================== Distance Input (DISTANCE mode) ==================

    fun updateDistance(distance: String) {
        var filtered = distance.filter { it.isDigit() || it == '.' }

        // OPERATIONAL HARDENING: Reject multiple dots
        val dotIndex = filtered.indexOf('.')
        if (dotIndex >= 0) {
            filtered = filtered.substring(0, dotIndex + 1) +
                filtered.substring(dotIndex + 1).filter { it.isDigit() }
        }

        // Cap distance input length (max 8 chars — supports up to 9999.99 km)
        if (filtered.length > JobConstants.MAX_RATE_INPUT_LENGTH) {
            filtered = filtered.substring(0, JobConstants.MAX_RATE_INPUT_LENGTH)
        }

        _uiState.update {
            val hasDistance = filtered.toDoubleOrNull()?.let { d -> d > 0 } ?: false
            val isComplete = when (it.selectedPricingMode) {
                PricingMode.DISTANCE -> hasDistance
                PricingMode.TRIP_AND_DISTANCE -> hasDistance && it.tripCount > 0
                PricingMode.PACKET_DISTANCE -> true // Packets only required, distance optional
                else -> it.isJobComplete
            }
            it.copy(distanceKm = filtered, isJobComplete = isComplete)
        }
        recalculateTotal()
        persistActiveJobIfExists()
    }

    /** Update distance rate (PACKET_DISTANCE mode) — ₹/km rate for hybrid transport billing */
    fun updateDistanceRate(rate: String) {
        var filtered = rate.filter { it.isDigit() || it == '.' }

        // OPERATIONAL HARDENING: Reject multiple dots
        val dotIndex = filtered.indexOf('.')
        if (dotIndex >= 0) {
            filtered = filtered.substring(0, dotIndex + 1) +
                filtered.substring(dotIndex + 1).filter { it.isDigit() }
        }

        // Cap rate input length
        if (filtered.length > JobConstants.MAX_RATE_INPUT_LENGTH) {
            filtered = filtered.substring(0, JobConstants.MAX_RATE_INPUT_LENGTH)
        }

        _uiState.update { it.copy(distanceRate = filtered) }
        recalculateTotal()
        persistActiveJobIfExists()
    }

    fun updateLoadType(loadType: String) {
        _uiState.update { it.copy(loadType = loadType) }
        persistActiveJobIfExists()
    }

    /** Update acre quantity (PER_ACRE mode) — sanitizes input, max 9999 */
    fun updateAcreQuantity(acres: String) {
        _uiState.update { it.copy(acreQuantity = acres) }
        recalculateTotal()
        persistActiveJobIfExists()
    }

    /**
     * PART 2: Change area unit (regional land measurement).
     * Converts existing value to new unit for display continuity.
     */
    fun updateAreaUnit(newUnit: AreaUnit) {
        val currentState = _uiState.value
        val currentUnit = currentState.selectedAreaUnit
        val currentValue = currentState.acreQuantity.toDoubleOrNull()

        // Convert existing value to new unit for display
        val convertedValue = if (currentValue != null && currentValue > 0) {
            val acreValue = currentUnit.toAcres(currentValue)
            newUnit.fromAcres(acreValue)
        } else null

        val convertedStr = convertedValue?.let {
            if (it == it.toLong().toDouble()) it.toLong().toString()
            else String.format("%.2f", it)
        } ?: currentState.acreQuantity

        _uiState.update {
            it.copy(
                selectedAreaUnit = newUnit,
                acreQuantity = convertedStr
            )
        }
        recalculateTotal()
        persistActiveJobIfExists()
    }

    // ================== Job Templates (Step 1 — what work?) ==================

    /**
     * Select a template (job type). This is the FIRST step in new-job creation.
     * - Resets machine selection (machines will be filtered by template)
     * - Auto-applies template's default rate (if user hasn't edited rate)
     * - Auto-selects machine if only one supports this work
     */
    fun selectTemplate(template: JobTemplate) {
        // If clicking already-selected template — no-op
        if (_uiState.value.selectedTemplate?.id == template.id) return

        timerJob?.cancel()
        userEditedRate = false

        _uiState.update {
            it.copy(
                selectedTemplate = template,
                templateError = null,
                machineError = null,
                // Reset machine — must be re-picked from filtered list
                selectedMachine = null,
                selectedMachineType = template.machineType,
                selectedPricingMode = template.machineType.defaultPricingMode(),
                loadType = template.loadType ?: "",
                // Reset work state
                isTimerRunning = false, isTimerPaused = false,
                timerStartTime = null, timerEndTime = null,
                pauseStartTime = null, totalPausedDuration = 0, elapsedSeconds = 0,
                tripCount = 0, distanceKm = "",
                isJobComplete = false, calculatedTotal = 0.0,
                // Apply template's suggested rate
                rateInput = if (template.defaultRate > 0) {
                    if (template.defaultRate == template.defaultRate.toLong().toDouble())
                        template.defaultRate.toLong().toString()
                    else template.defaultRate.toString()
                } else "",
                rateError = null
            )
        }

        // Auto-select machine when there's only one supporting this work
        val filtered = _uiState.value.filteredMachines
        if (filtered.size == 1) {
            selectMachine(filtered.first())
        }

        // Honor saved per-machine+mode default rate if it exists (overrides template default)
        autoFillRate()
    }

    /** Backward-compat: kept so any older callers (e.g. Home FAB sheet) still work. */
    fun applyTemplate(templateId: String) {
        val template = JobTemplates.findById(templateId) ?: return
        selectTemplate(template)
    }

