    /**
     * PART 3: Continue to next active job for the same customer.
     * Instant switch — no navigation, no dialogs. Feels like "next page".
     */
    fun continueToNextSameCustomerJob(customerId: String?) {
        if (customerId.isNullOrBlank()) return
        viewModelScope.launch {
            val remainingJobs = activeJobsRepository.getAllActiveJobsOnce()
                .filter { it.customerId == customerId && it.jobId != currentJobId }
            val nextJob = remainingJobs.firstOrNull() ?: return@launch

            // Reset state for the new job
            hasSavedCurrentJob = false
            timerJob?.cancel()
            timerJob = null
            currentJobId = nextJob.jobId
            _uiState.update { it.copy(currentJobId = nextJob.jobId, isDraftMode = false) }
            restoreFromActiveJobsEntity(nextJob)

            val cap = nextJob.getJobCapability()
            val label = cap?.let { "${it.emoji} ${it.displayName}" } ?: "next job"
            _uiState.update { it.copy(infoMessage = "Switched to $label") }
        }
    }

