    /**
     * PART 2: Repeat exact same work — preserves customer, work type, machine, rate.
     * Only clears timer/trips. Maximum speed for repetitive cycles (transport, harvesting).
     * Single-tap from completion sheet creates a ready-to-start draft.
     */
    fun repeatSameWork() {
        timerJob?.cancel()
        userEditedRate = false
        hasSavedCurrentJob = false
        val prev = _uiState.value
        val lastCapability = prev.selectedJobCapability
        val lastMachine = prev.selectedMachine
        val lastRate = prev.rateInput
        val lastCustomer = prev.selectedCustomer
        val lastBillingMode = prev.selectedBillingMode
        val lastMachineType = prev.selectedMachineType
        val lastPricingMode = prev.selectedPricingMode
        clearActiveJob()
        currentJobId = null

        _uiState.value = NewJobUiState(
            isTemplateFlow = false,
            isDraftMode = true,
            availableCustomers = prev.availableCustomers,
            recentCustomers = prev.recentCustomers,
            machines = prev.machines,
            recentMachineIds = prev.recentMachineIds,
            selectedCustomer = lastCustomer,
            selectedJobCapability = lastCapability,
            selectedMachine = lastMachine,
            selectedMachineType = lastMachineType,
            selectedPricingMode = lastPricingMode,
            selectedBillingMode = lastBillingMode,
            rateInput = lastRate,
            currentJobId = null
        )

        // Apply capability
        if (lastCapability != null) {
            applyJobCapability(lastCapability)
        }

        val machineName = lastMachine?.name ?: ""
        val workName = lastCapability?.displayName ?: "work"
        _uiState.update { it.copy(
            rateInput = lastRate, // re-apply after applyJobCapability may have overridden
            infoMessage = " Ready to repeat $workName${if (machineName.isNotBlank()) " • $machineName" else ""}"
        ) }
    }

    override fun onCleared() {
        super.onCleared()
        timerJob?.cancel()
        autoSaveMultiJob?.cancel()

        // OPERATIONAL HARDENING: Auto-clean empty jobs — if user leaves without
        // doing meaningful work, silently remove the entry from active_jobs.
        // Uses a dedicated coroutine scope to avoid runBlocking deadlock on main thread.
        val jobId = currentJobId
        val state = _uiState.value
        if (jobId != null && !hasSavedCurrentJob) {
            val hasWork = state.segments.isNotEmpty() || state.tripCount > 0 ||
                state.isTimerRunning || state.isTimerPaused || state.timerStartTime != null
            if (!hasWork) {
                // Use a non-blocking approach — fire-and-forget on IO dispatcher
                @Suppress("OPT_IN_USAGE")
                kotlinx.coroutines.GlobalScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                    try { activeJobsRepository.removeJob(jobId) } catch (_: Exception) {}
                }
            }
        }
    }

    // ================== Multi-Job Methods (PARTS 2-14) ==================

    /**
     * PART 2: Load the most recent active job on startup.
     * Called from init after other initialization.
     */
    private fun loadActiveJobsOnStart() {
        viewModelScope.launch {
            val jobs = activeJobsRepository.getAllActiveJobsOnce()
            val now = System.currentTimeMillis()

            // PART 9+10: Enhanced cleanup — remove phantom jobs AND stale orphans
            val validJobs = jobs.filter { it.hasWork }
            val phantomJobs = jobs.filter { !it.hasWork && (now - it.createdAt) > 60_000 }
            phantomJobs.forEach { activeJobsRepository.removeJob(it.jobId) }

            // PART 10: Remove very old orphans — jobs with no machine AND no rate AND no segments,
            // older than 4 hours. These are abandoned setup attempts.
            val fourHoursMs = 4L * 60 * 60 * 1000
            val orphanJobs = jobs.filter { job ->
                job.hasWork &&  // survived phantom check but...
                    job.machineId == null &&
                    job.rate == 0.0 &&
                    job.trips == 0 &&
                    job.segmentsJson.isNullOrBlank() &&
                    !job.isPaused && !job.isStopped &&
                    (now - job.lastUpdatedAt) > fourHoursMs
            }
            orphanJobs.forEach { activeJobsRepository.removeJob(it.jobId) }

            if (validJobs.isNotEmpty()) {
                // Load most recent valid job
                val mostRecent = validJobs.first()
                currentJobId = mostRecent.jobId
                _uiState.update { it.copy(currentJobId = mostRecent.jobId, isDraftMode = false) }
                restoreFromActiveJobsEntity(mostRecent)
            }
        }
    }

    /**
     * Open a specific workspace job by ID.
     * Used when user explicitly taps a workspace pill, job row, or active tab.
     * Does NOT save current state (since this is a fresh VM for workspace route).
     */
    fun openWorkspaceJob(jobId: String) {
        viewModelScope.launch {
            val job = activeJobsRepository.getJobById(jobId)
            if (job != null) {
                currentJobId = jobId
                _uiState.update { it.copy(currentJobId = jobId, isDraftMode = false) }
                restoreFromActiveJobsEntity(job)

                // PART 6: Recovery authority — use RecoveryReplayScenario
                val lastUpdate = job.lastUpdatedAt
                val staleDuration = if (lastUpdate > 0) System.currentTimeMillis() - lastUpdate else 0L
                val isTimeMode = job.pricingMode == PricingMode.TIME
                val wasRunning = isTimeMode && !job.isPaused && !job.isStopped && job.startTime > 0

                val recoveryContext = com.example.fieldtrack.domain.recovery.RecoveryContext(
                    staleDurationMs = staleDuration,
                    hadActiveTimer = wasRunning,
                    wasPaused = job.isPaused,
                    hadPendingSave = false,
                    hasMeaningfulWork = job.trips > 0 || (isTimeMode && job.startTime > 0),
                    saveAlreadyCompleted = job.isStopped,
                    workSummary = job.jobCapability?.let { JobCapability.fromName(it)?.displayName } ?: "Work",
                    lastPhase = when {
                        job.isStopped -> JobPhase.STOPPED
                        job.isPaused -> JobPhase.PAUSED
                        wasRunning -> JobPhase.RUNNING
                        else -> JobPhase.SETUP
                    }
                )
                val recoveryAction = com.example.fieldtrack.domain.recovery.RecoveryReplayScenario.classify(recoveryContext)

                when (recoveryAction) {
                    is com.example.fieldtrack.domain.recovery.RecoveryAction.OfferRecoveryOrDiscard -> {
                        _uiState.update {
                            it.copy(showStaleBanner = true, staleBannerText = recoveryAction.reason)
                        }
                    }
                    is com.example.fieldtrack.domain.recovery.RecoveryAction.OfferResumeWithDriftWarning -> {
                        _uiState.update { it.copy(showRecoveredBanner = true) }
                    }
                    is com.example.fieldtrack.domain.recovery.RecoveryAction.SilentResume -> {
                        // Silent resume — no banner needed
                    }
                    else -> { /* SilentDiscard, RetrySave — handled elsewhere */ }
                }

                // Emit recovery event if timer was active
                if (wasRunning) {
                    WorkEventBus.emit(WorkEvent.RecoveryOccurred(
                        jobId = jobId,
                        recoveryType = com.example.fieldtrack.domain.event.RecoveryType.PROCESS_DEATH_RESTORE,
                        estimatedDataLossMs = staleDuration
                    ))
                    // Auto-dismiss recovery banner
                    launch {
                        delay(4000)
                        _uiState.update { it.copy(showRecoveredBanner = false) }
                    }
                }

                android.util.Log.d("NewJobVM", "WORKSPACE RESTORED: $jobId — ${job.machineName ?: "unknown"}")
            } else {
                // Job not found — fallback to loading most recent
                android.util.Log.w("NewJobVM", "Workspace job not found: $jobId, falling back")
                loadActiveJobsOnStart()
            }
        }
    }

    /**
     * PART 3: Switch to a different active job instantly.
     * Saves current state, loads new job, restores UI. No dialogs.
     */
    fun switchToJob(jobId: String) {
        if (currentJobId == jobId) return
        val fromJobId = currentJobId
        hasSavedCurrentJob = false

        viewModelScope.launch {
            // 1. Save current job silently — no status message needed for instant operation
            saveCurrentJobToMultiTable()

            // 2. Stop current timer
            timerJob?.cancel()
            timerJob = null

            // 3. Load new job
            val newJob = activeJobsRepository.getJobById(jobId) ?: return@launch

            // 4. Restore UI state
            restoreFromActiveJobsEntity(newJob)

            // 5. Set current job ID
            currentJobId = jobId
            _uiState.update { it.copy(currentJobId = jobId, infoMessage = null) }

            // CANONICAL: Emit workspace switched event
            WorkEventBus.emit(WorkEvent.WorkspaceSwitched(
                jobId = jobId,
                fromJobId = fromJobId
            ))

            // PART 11: Verify invariants after workspace switch
            verifyInvariants()
        }
    }

    /** Switch to next job of SAME customer (swipe left) — no cross-farmer swipe */
    fun switchToNextJob() {
        val currentCustomerId = _uiState.value.selectedCustomer?.customerId
        val jobs = activeJobs.value.filter {
            currentCustomerId == null || it.customerId == currentCustomerId
        }
        if (jobs.size <= 1) return
        val currentIndex = jobs.indexOfFirst { it.jobId == currentJobId }
        val nextIndex = if (currentIndex < 0 || currentIndex >= jobs.size - 1) 0 else currentIndex + 1
        switchToJob(jobs[nextIndex].jobId)
    }

    /** Switch to previous job of SAME customer (swipe right) — no cross-farmer swipe */
    fun switchToPreviousJob() {
        val currentCustomerId = _uiState.value.selectedCustomer?.customerId
        val jobs = activeJobs.value.filter {
            currentCustomerId == null || it.customerId == currentCustomerId
        }
        if (jobs.size <= 1) return
        val currentIndex = jobs.indexOfFirst { it.jobId == currentJobId }
        val prevIndex = if (currentIndex <= 0) jobs.size - 1 else currentIndex - 1
        switchToJob(jobs[prevIndex].jobId)
    }

    /**
     * PART 4: Start a new job with a selected capability.
     * Saves current job, resets UI for new work type.
     * Does NOT create DB entry — that happens on first real work (ensureActiveJobCreated).
     */
    fun startNewJob(capability: JobCapability) {
        viewModelScope.launch {
            // 1. Save current job if exists
            if (currentJobId != null) {
                saveCurrentJobToMultiTable()
            }

            // 2. Stop current timer
            timerJob?.cancel()
            timerJob = null

            // 3. Reset UI state (no DB entry yet — lifecycle deferred to work start)
            val prev = _uiState.value
            userEditedRate = false
            currentJobId = null

            _uiState.value = NewJobUiState(
                isTemplateFlow = false,
                isDraftMode = false,
                availableCustomers = prev.availableCustomers,
                recentCustomers = prev.recentCustomers,
                machines = prev.machines,
                selectedCustomer = prev.selectedCustomer, // keep customer
                currentJobId = null
            )

            // 4. Apply capability (just updates UI, no persistence)
            applyJobCapability(capability)
        }
    }

    /**
     * Start another work for the SAME customer.
     * Preserves customer selection, resets everything else to a fresh draft.
     * Does NOT affect existing active jobs.
     */
    fun startAnotherWork() {
        viewModelScope.launch {
            // 1. Save current job if exists
            if (currentJobId != null) {
                saveCurrentJobToMultiTable()
            }

            // 2. Stop current timer
            timerJob?.cancel()
            timerJob = null

            // 3. Reset to fresh draft but keep customer
            val prev = _uiState.value
            val keepCustomer = prev.selectedCustomer
            userEditedRate = false
            currentJobId = null

            _uiState.value = NewJobUiState(
                isTemplateFlow = false,
                isDraftMode = true,
                availableCustomers = prev.availableCustomers,
                recentCustomers = prev.recentCustomers,
                machines = prev.machines,
                recentMachineIds = prev.recentMachineIds,
                selectedCustomer = keepCustomer, // preserve customer context
                currentJobId = null
            )

            val customerLabel = keepCustomer?.name ?: "same farmer"
            _uiState.update { it.copy(infoMessage = " New work for $customerLabel") }
            // Auto-fill rate so Start Work button becomes visible
            autoFillRate()
        }
    }

    /**
     * PART 10: Finish the current job — save to final table, remove from active jobs.
     */
    fun finishCurrentJob() {
        val jobId = currentJobId ?: return
        viewModelScope.launch {
            // 1. Save to final Job table
            val success = saveJobInternal()

            if (success) {
                // 2. Remove from active jobs
                activeJobsRepository.removeJob(jobId)

                // 3. Clear legacy active job
                clearActiveJob()

                // 4. Switch to another job in SAME workspace first, then any remaining job
                val remainingJobs = activeJobsRepository.getAllActiveJobsOnce()
                    .filter { it.hasWork }
                val currentCustomerId = _uiState.value.selectedCustomer?.customerId
                // Prefer same-customer workspace for continuity
                val sameWorkspaceJob = if (!currentCustomerId.isNullOrBlank()) {
                    remainingJobs.firstOrNull { it.customerId == currentCustomerId }
                } else null
                val nextJob = sameWorkspaceJob ?: remainingJobs.firstOrNull()

                if (nextJob != null) {
                    currentJobId = nextJob.jobId
                    _uiState.update { it.copy(currentJobId = nextJob.jobId, isDraftMode = false) }
                    restoreFromActiveJobsEntity(nextJob)
                    val cap = nextJob.getJobCapability()
                    val label = cap?.let { "${it.emoji} ${it.displayName}" } ?: "next job"
                    _uiState.update { it.copy(infoMessage = "✔ Job completed — switched to $label") }
                } else {
                    // Reset to empty draft state
                    currentJobId = null
                    val prev = _uiState.value
                    _uiState.value = NewJobUiState(
                        isTemplateFlow = isTemplateFlow,
                        isDraftMode = true,
                        availableCustomers = prev.availableCustomers,
                        recentCustomers = prev.recentCustomers,
                        machines = prev.machines,
                        currentJobId = null
                    )
                    _uiState.update { it.copy(infoMessage = "Job completed ✓") }
                }
            }
        }
    }

    /**
     * PART 9: Save current job to multi-job table (debounced).
     * Called on segment add, timer tick, trip add, machine selection.
     */
    fun saveCurrentJobDebounced() {
        if (currentJobId == null) return // Guard: no job started yet
        autoSaveMultiJob?.cancel()
        autoSaveMultiJob = viewModelScope.launch {
            delay(400) // debounce 400ms
            saveCurrentJobToMultiTable()
        }
    }

    /**
     * Save current UI state to the multi-job active_jobs table.
     */
    private suspend fun saveCurrentJobToMultiTable() = saveMutex.withLock {
        val jobId = currentJobId ?: return@withLock
        val state = _uiState.value

        // OPERATIONAL HARDENING: Don't persist in terminal states
        if (state.jobPhase == JobPhase.SAVED || state.jobPhase == JobPhase.SAVING) return@withLock

        persistVersion++

        val entity = ActiveJobsEntity(
            jobId = jobId,
            customerId = state.selectedCustomer?.customerId ?: "",
            customerName = state.selectedCustomer?.name,
            machineId = state.selectedMachine?.machineId,
            machineName = state.selectedMachine?.name,
            machineType = state.selectedMachineType,
            pricingMode = state.selectedPricingMode,
            rate = state.rateInput.toDoubleOrNull() ?: 0.0,
            startTime = state.timerStartTime ?: 0L,
            trips = state.tripCount,
            distance = state.distanceKm.toDoubleOrNull() ?: 0.0,
            fieldName = state.fieldName.takeIf { it.isNotBlank() },
            loadType = state.loadType.takeIf { it.isNotBlank() },
            notes = state.notes.takeIf { it.isNotBlank() },
            isRateEdited = userEditedRate,
            isPaused = state.isTimerPaused,
            pauseStartTime = state.pauseStartTime,
            totalPausedDuration = state.totalPausedDuration,
            isStopped = state.timerEndTime != null && !state.isTimerRunning && !state.isTimerPaused,
            endTime = state.timerEndTime,
            segmentsJson = if (state.segments.isNotEmpty())
                SegmentSerializer.toJson(state.segments) else null,
            jobCapability = state.selectedJobCapability?.name,
            lastUpdatedAt = System.currentTimeMillis(),
            snapshotVersion = persistVersion
        )
        activeJobsRepository.saveJob(entity)
    }

    /**
     * PART 11: Restore UI state from an ActiveJobsEntity.
     * Timer isolation: only resumes timer if the loaded job was running.
     */
    private fun restoreFromActiveJobsEntity(job: ActiveJobsEntity) {
        // Stop any current timer first (PART 11: timer isolation)
        timerJob?.cancel()
        timerJob = null

        val now = System.currentTimeMillis()
        val isTimeMode = job.pricingMode == PricingMode.TIME

        val elapsed: Long
        val isRunning: Boolean
        val isPaused: Boolean
        val isComplete: Boolean

        when {
            job.isStopped -> {
                val endT = job.endTime ?: now
                elapsed = ((endT - job.startTime) - job.totalPausedDuration) / 1000
                isRunning = false
                isPaused = false
                isComplete = true
            }
            job.isPaused -> {
                val pauseT = job.pauseStartTime ?: now
                elapsed = ((pauseT - job.startTime) - job.totalPausedDuration) / 1000
                isRunning = false
                isPaused = true
                isComplete = false
            }
            else -> {
                elapsed = if (isTimeMode) {
                    ((now - job.startTime) - job.totalPausedDuration) / 1000
                } else 0
                isRunning = isTimeMode && job.startTime > 0 && !job.isStopped
                isPaused = false
                isComplete = !isTimeMode && job.trips > 0
            }
        }

        val segments = if (!job.segmentsJson.isNullOrBlank())
            SegmentSerializer.fromJson(job.segmentsJson) else emptyList()

        // Derive pricing mode from capability if available (ensures rate label matches billing label)
        val restoredCapability = job.getJobCapability()
        val restoredPricingMode = if (restoredCapability != null) {
            val usageType = BillingModeResolver.inferUsageType(restoredCapability)
            val usageContext = MachineUsageContext(jobCapability = restoredCapability, usageType = usageType)
            val billingMode = BillingModeResolver.resolveBillingMode(usageContext)
            when (billingMode) {
                BillingMode.PER_MINUTE -> PricingMode.TIME
                BillingMode.PER_HOUR -> PricingMode.TIME
                BillingMode.PER_TRIP -> PricingMode.TRIP
                BillingMode.PER_PACKET -> PricingMode.PACKET
                BillingMode.PER_PACKET_DISTANCE -> PricingMode.PACKET_DISTANCE
                BillingMode.PER_ACRE -> PricingMode.PER_ACRE
                BillingMode.FIXED_AMOUNT -> PricingMode.FIXED_AMOUNT
            }
        } else {
            job.pricingMode
        }

        _uiState.update {
            it.copy(
                currentJobId = job.jobId,
                isDraftMode = false,
                selectedMachineType = job.machineType,
                selectedPricingMode = restoredPricingMode,
                rateInput = if (job.rate > 0) {
                    if (job.rate == job.rate.toLong().toDouble())
                        job.rate.toLong().toString()
                    else job.rate.toString()
                } else "",
                timerStartTime = if (isTimeMode) job.startTime else null,
                timerEndTime = if (job.isStopped) job.endTime else null,
                isTimerRunning = isRunning,
                isTimerPaused = isPaused,
                pauseStartTime = job.pauseStartTime,
                totalPausedDuration = job.totalPausedDuration,
                elapsedSeconds = elapsed.coerceAtLeast(0),
                tripCount = job.trips,
                distanceKm = if (restoredPricingMode != PricingMode.PER_ACRE && job.distance > 0) job.distance.toString() else "",
                acreQuantity = if (restoredPricingMode == PricingMode.PER_ACRE && job.distance > 0) {
                    if (job.distance == job.distance.toLong().toDouble()) job.distance.toLong().toString()
                    else job.distance.toString()
                } else "",
                fieldName = job.fieldName ?: "",
                loadType = job.loadType ?: "",
                notes = job.notes ?: "",
                isJobComplete = isComplete,
                segments = segments,
                currentRate = job.rate,
                selectedJobCapability = job.getJobCapability(),
                isBillingOverridden = false,
                selectedBillingMode = null
            )
        }

        // Resume timer if was running (PART 11)
        if (isRunning) {
            userEditedRate = job.isRateEdited
            startTickingCoroutine()
        }

        // Resolve machine entity
        val currentMachines = _uiState.value.machines
        if (job.machineId != null && currentMachines.isNotEmpty()) {
            val matchingMachine = currentMachines.firstOrNull { it.machineId == job.machineId }
            matchingMachine?.let {
                _uiState.update { state -> state.copy(selectedMachine = matchingMachine) }
            }
        } else {
            _uiState.update { it.copy(selectedMachine = null) }
        }

        // Resolve customer
        if (job.customerId.isNotBlank()) {
            viewModelScope.launch {
                val customer = customerRepository.getCustomerById(job.customerId)
                customer?.let { selectCustomer(it) }
            }
        }

        recalculateTotal()

        // PART 11: Verify invariants after restore
        verifyInvariants()
    }

    /**
     * Convert an ActiveJobsEntity to an ActiveJobSummary for UI display.
     */
    private fun ActiveJobsEntity.toSummary(): ActiveJobSummary {
        val cap = getJobCapability()
        val now = System.currentTimeMillis()
        val isTimeMode = pricingMode == PricingMode.TIME

        val elapsed = when {
            isStopped -> {
                val endT = endTime ?: now
                ((endT - startTime) - totalPausedDuration) / 1000
            }
            isPaused -> {
                val pauseT = pauseStartTime ?: now
                ((pauseT - startTime) - totalPausedDuration) / 1000
            }
            isTimeMode && startTime > 0 -> {
                ((now - startTime) - totalPausedDuration) / 1000
            }
            else -> 0L
        }.coerceAtLeast(0)

        val running = isTimeMode && !isPaused && !isStopped && startTime > 0
        // CANONICAL: Unified status vocabulary via lifecycle mapper
        val statusLabel = when {
            running -> "${OperationalLifecycleMapper.stateEmoji(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.ACTIVE)} ${OperationalLifecycleMapper.uiLabel(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.ACTIVE)}"
            isPaused -> "${OperationalLifecycleMapper.stateEmoji(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.PAUSED)} ${OperationalLifecycleMapper.uiLabel(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.PAUSED)}"
            trips > 0 -> "$trips load${if (trips != 1) "s" else ""}"
            isStopped -> "✔ ${OperationalLifecycleMapper.uiLabel(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.COMPLETED)}"
            else -> "Ready"
        }

        return ActiveJobSummary(
            jobId = jobId,
            machineName = machineName,
            customerName = customerName,
            jobCapability = cap,
            elapsedSeconds = elapsed,
            tripCount = trips,
            isRunning = running,
            isPaused = isPaused,
            emoji = cap?.emoji ?: "",
            displayName = buildString {
                append(cap?.displayName ?: "Job")
                // Add machine name for differentiation (PART 8: machine = primary differentiator)
                if (machineName != null) {
                    append(" • ")
                    append(machineName)
                }
            },
            statusLabel = statusLabel
        )
    }

    // ================== Billing Override Sheet ==================

    /** PART 9 STEP 5: Show billing override bottom sheet. */
    fun showBillingOverrideSheet() {
        val state = _uiState.value
        // Block billing mode changes while job is actively running or paused
        if (state.isTimerRunning || state.isTimerPaused) {
            _uiState.update { it.copy(infoMessage = "Stop the timer before changing billing mode") }
            return
        }
        _uiState.update { it.copy(showBillingOverrideSheet = true) }
    }

    /** PART 9: Dismiss billing override sheet. */
    fun dismissBillingOverrideSheet() {
        _uiState.update { it.copy(showBillingOverrideSheet = false) }
    }

    // ================== State Validation ==================

    /**
     * OPERATIONAL HARDENING: Remove stale active jobs on startup.
     * Prevents ghost machine locks from jobs abandoned after process death.
     * Items older than STALE_JOB_THRESHOLD_MS (8h) with no ongoing work = safe to remove.
     */
    private fun cleanupStaleJobs() {
        viewModelScope.launch {
            try {
                val jobs = activeJobsRepository.getAllActiveJobsOnce()
                val now = System.currentTimeMillis()
                val staleJobs = jobs.filter { job ->
                    val age = now - job.lastUpdatedAt
                    age > JobConstants.STALE_JOB_THRESHOLD_MS &&
                        !job.isPaused && !job.isStopped &&  // Don't remove paused/stopped — user may return
                        job.segmentsJson.isNullOrBlank() &&  // No completed segments
                        job.trips == 0  // No trips counted
                }
                staleJobs.forEach { job ->
                    android.util.Log.d("NewJobVM", "STALE CLEANUP: Removing ${job.jobId} (age ${(now - job.lastUpdatedAt) / 3600000}h)")
                    activeJobsRepository.removeJob(job.jobId)
                }
            } catch (_: Exception) {
                // Non-critical — silent failure on cleanup
            }
        }
    }

    /**
     * PART 6: Revalidate machine compatibility after billing mode change.
     * If machine becomes incompatible, remove it and show info message.
     */
    private fun validateMachineAfterBillingChange() {
        val state = _uiState.value
        val machine = state.selectedMachine ?: return
        val capability = state.selectedJobCapability ?: return

        val isCompatible = MachineCapabilityMatcher.isMachineCompatible(machine, capability)
        if (!isCompatible) {
            _uiState.update {
                it.copy(
                    selectedMachine = null,
                    machineCompatibilityWarning = null,
                    infoMessage = "Previous machine not suitable for this work"
                )
            }
        }
    }

    /**
     * PART 10: Defensive state validator.
     * Called after every major state mutation to ensure invariants hold.
     * Self-heals invalid states and logs warnings.
     */
    private fun validateState(state: NewJobUiState) {
        // Invariant 1: Dialog open without pendingBillingMode → auto dismiss
        if (state.showBillingModeChangeDialog && state.pendingBillingMode == null) {
            _uiState.update {
                it.copy(
                    showBillingModeChangeDialog = false,
                    pendingBillingMode = null
                )
            }
            android.util.Log.w("NewJobVM", "Invalid state: billing dialog without pending mode — auto dismissed")
        }

        // Invariant 2: Timer should not be running if timerStartTime is null
        if (state.isTimerRunning && state.timerStartTime == null) {
            timerJob?.cancel()
            _uiState.update {
                it.copy(
                    isTimerRunning = false,
                    isTimerPaused = false,
                    liveCost = 0.0
                )
            }
            android.util.Log.w("NewJobVM", "Invalid state: timer running without startTime — stopped")
        }

        // OPERATIONAL HARDENING — Invariant 3: Running AND paused simultaneously = impossible
        if (state.isTimerRunning && state.isTimerPaused) {
            _uiState.update { it.copy(isTimerPaused = false) }
            android.util.Log.w("NewJobVM", "Invalid state: timer both running and paused — forced to running")
        }

        // Invariant 4: Negative totalPausedDuration = data corruption — clamp to 0
        if (state.totalPausedDuration < 0) {
            _uiState.update { it.copy(totalPausedDuration = 0) }
            android.util.Log.w("NewJobVM", "Invalid state: negative totalPausedDuration — clamped to 0")
        }

        // Invariant 5: totalPausedDuration > elapsed wallclock = corruption
        if (state.timerStartTime != null && state.totalPausedDuration > 0) {
            val wallclock = System.currentTimeMillis() - state.timerStartTime
            if (state.totalPausedDuration > wallclock) {
                _uiState.update { it.copy(totalPausedDuration = 0) }
                android.util.Log.w("NewJobVM", "Invalid state: pausedDuration exceeds wallclock — reset to 0")
            }
        }
    }

    /**
     * Factory for creating NewJobViewModel with dependencies.
     */
    class Factory(
        private val jobRepository: JobRepository,
        private val customerRepository: CustomerRepository,
        private val ratePreferences: RatePreferences,
        private val customerFieldDao: CustomerFieldDao,
        private val activeJobRepository: ActiveJobRepository,
        private val machineRepository: MachineRepository,
        private val activeJobsRepository: ActiveJobsRepository,
        private val workPatternPreferences: WorkPatternPreferences,
        private val isTemplateFlow: Boolean = false,
        private val initialTemplateId: String? = null,
        private val startAsFreshDraft: Boolean = false,
        private val restoreJobId: String? = null
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            if (modelClass.isAssignableFrom(NewJobViewModel::class.java)) {
                return NewJobViewModel(
                    jobRepository, customerRepository, ratePreferences,
                    customerFieldDao, activeJobRepository, machineRepository,
                    activeJobsRepository, workPatternPreferences,
                    isTemplateFlow, initialTemplateId,
                    startAsFreshDraft, restoreJobId
                ) as T
            }
            throw IllegalArgumentException("Unknown ViewModel class")
        }
    }
}

/**
 * Holds data needed to undo a machine switch reset.
 * Timer state is NOT stored — undo only restores segments/trips/machine.
 */
private data class MachineSwitchUndoData(
    val previousMachine: MachineEntity?,
    val segments: List<WorkSegment>,
    val tripCount: Int
)

