    // ================== Selection Events ==================

    // ====== PART 6: Work Type (JobCapability) selection ======

    /**
     * Select a work type (job capability). This determines what kind of work
     * the job IS doing, and enables machine compatibility checks.
     *
     * PART 1: Detects work-type change when segments/timer exist.
     * Shows split dialog to ensure one job = one billing mode.
     */
    fun selectJobCapability(capability: JobCapability) {
        val state = _uiState.value

        // If switching capability while work exists → auto-split (parallel jobs)
        if (state.selectedJobCapability != null && state.selectedJobCapability != capability) {
            val hasWork = state.segments.isNotEmpty() || state.isTimerRunning ||
                state.isTimerPaused || state.timerStartTime != null
            if (hasWork) {
                // Save current job and start fresh — no dialog needed for parallel jobs
                autoSplitAndStartNew(capability)
                return
            }
        }

        applyJobCapability(capability)
    }

    /**
     * Auto-split: saves current running job to active_jobs and starts fresh with new capability.
     * No dialog — jobs run in parallel.
     * UI resets IMMEDIATELY, DB save happens in background.
     */
    private fun autoSplitAndStartNew(newCapability: JobCapability) {
        // Capture what we need for background save BEFORE resetting state
        val oldJobId = currentJobId
        val oldState = _uiState.value
        val oldUserEditedRate = userEditedRate

        // Cancel UI ticker immediately (timer continues accruing via startTime in DB)
        timerJob?.cancel()
        timerJob = null

        // Reset UI state IMMEDIATELY — no dialog, no delay
        userEditedRate = false
        currentJobId = null

        _uiState.value = NewJobUiState(
            isTemplateFlow = false,
            availableCustomers = oldState.availableCustomers,
            recentCustomers = oldState.recentCustomers,
            machines = oldState.machines,
            selectedCustomer = oldState.selectedCustomer,
            selectedMachine = null, // Must re-select machine
            isBillingOverridden = false,
            selectedBillingMode = null,
            currentJobId = null
        )

        applyJobCapability(newCapability)

        _uiState.update { it.copy(infoMessage = "Previous job still running • Select machine to start new work") }

        // Save old job to active_jobs in background (doesn't block UI)
        if (oldJobId != null) {
            viewModelScope.launch {
                val entity = ActiveJobsEntity(
                    jobId = oldJobId,
                    customerId = oldState.selectedCustomer?.customerId ?: "",
                    customerName = oldState.selectedCustomer?.name,
                    machineId = oldState.selectedMachine?.machineId,
                    machineName = oldState.selectedMachine?.name,
                    machineType = oldState.selectedMachineType,
                    pricingMode = oldState.selectedPricingMode,
                    rate = oldState.rateInput.toDoubleOrNull() ?: 0.0,
                    startTime = oldState.timerStartTime ?: System.currentTimeMillis(),
                    trips = oldState.tripCount,
                    distance = oldState.distanceKm.toDoubleOrNull() ?: 0.0,
                    fieldName = oldState.fieldName.takeIf { it.isNotBlank() },
                    loadType = oldState.loadType.takeIf { it.isNotBlank() },
                    notes = oldState.notes.takeIf { it.isNotBlank() },
                    isRateEdited = oldUserEditedRate,
                    isPaused = false, // NOT paused — job keeps running in background
                    pauseStartTime = oldState.pauseStartTime,
                    totalPausedDuration = oldState.totalPausedDuration,
                    isStopped = false,
                    endTime = null,
                    segmentsJson = if (oldState.segments.isNotEmpty())
                        SegmentSerializer.toJson(oldState.segments) else null,
                    jobCapability = oldState.selectedJobCapability?.name
                )
                activeJobsRepository.saveJob(entity)
            }
        }
    }

    /**
     * Internal: Apply job capability change (no split check).
     */
    private fun applyJobCapability(capability: JobCapability) {
        val usageType = BillingModeResolver.inferUsageType(capability)
        val usageContext = MachineUsageContext(jobCapability = capability, usageType = usageType)
        val billingMode = BillingModeResolver.resolveBillingMode(usageContext)

        // Map domain billing mode to data-layer pricing mode for auto-selection
        val derivedPricingMode = when (billingMode) {
            BillingMode.PER_MINUTE -> PricingMode.TIME
            BillingMode.PER_HOUR -> PricingMode.TIME
            BillingMode.PER_TRIP -> PricingMode.TRIP
            BillingMode.PER_PACKET -> PricingMode.PACKET
            BillingMode.PER_PACKET_DISTANCE -> PricingMode.PACKET_DISTANCE
            BillingMode.PER_ACRE -> PricingMode.PER_ACRE
            BillingMode.FIXED_AMOUNT -> PricingMode.FIXED_AMOUNT
        }

        _uiState.update {
            it.copy(
                selectedJobCapability = capability,
                jobCapabilityError = null,
                machineCompatibilityWarning = null,
                selectedPricingMode = derivedPricingMode,
                // PART 9 STEP 2: Update billing mode only if not manually overridden
                selectedBillingMode = if (!it.isBillingOverridden) billingMode else it.selectedBillingMode
            )
        }

        // PART 4: Restore transport memory for hybrid billing modes
        if (derivedPricingMode == PricingMode.PACKET_DISTANCE) {
            val recentDistRate = workPatternPreferences.getRecentDistanceRate()
            val recentLoadType = workPatternPreferences.getRecentLoadType()
            if (recentDistRate != null || recentLoadType != null) {
                _uiState.update {
                    it.copy(
                        distanceRate = if (it.distanceRate.isBlank() && recentDistRate != null)
                            recentDistRate.toString() else it.distanceRate,
                        loadType = if (it.loadType.isBlank() && recentLoadType != null)
                            recentLoadType else it.loadType
                    )
                }
            }
        }

        // PART 3: Auto-select if only one compatible machine
        val visibleMachines = _uiState.value.visibleMachines
        if (visibleMachines.size == 1 && _uiState.value.selectedMachine == null) {
            selectMachine(visibleMachines.first())
        }

        // Re-validate current machine selection against new capability
        val currentMachine = _uiState.value.selectedMachine
        if (currentMachine != null) {
            validateMachineCompatibility(currentMachine, capability)
        }

        // PART 1: Smart auto-suggestion — suggest best machine (not auto-apply)
        if (_uiState.value.selectedMachine == null) {
            computeMachineSuggestion(capability)
        }

        // If job already started (has work), sync capability change to active_jobs
        if (currentJobId != null) {
            saveCurrentJobDebounced()
        }

        // PART 9: Check for duplicate active work after capability change
        checkForDuplicateWork()
    }

    /**
     * PART 1: Compute best machine suggestion for current work type.
     * Priority: 1) last used for same work, 2) compatible, 3) recently used.
     */
    private fun computeMachineSuggestion(capability: JobCapability) {
        val state = _uiState.value
        val compatible = state.visibleMachines
        if (compatible.isEmpty()) {
            _uiState.update { it.copy(suggestedMachine = null) }
            return
        }

        // Priority 1: Last used for this work type (from recent machine IDs)
        val recentCompatible = state.recentMachineIds.firstNotNullOfOrNull { id ->
            compatible.find { it.machineId == id }
        }

        // Priority 2: Any compatible machine (first one)
        val suggestion = recentCompatible ?: compatible.firstOrNull()

        // Don't suggest if it's already the only option (auto-select handles that)
        val shouldSuggest = compatible.size > 1 && suggestion != null
        _uiState.update { it.copy(suggestedMachine = if (shouldSuggest) suggestion else null) }
    }

    /** PART 1: Apply the suggested machine instantly. */
    fun applySuggestedMachine() {
        val suggestion = _uiState.value.suggestedMachine ?: return
        selectMachine(suggestion)
        _uiState.update { it.copy(suggestedMachine = null) }
    }

    /** Dismiss machine suggestion. */
    fun dismissMachineSuggestion() {
        _uiState.update { it.copy(suggestedMachine = null) }
    }

    /** PART 6: Dismiss the split success banner. */
    fun dismissSplitBanner() {
        _uiState.update { it.copy(showSplitBanner = false, splitBannerText = null) }
    }

    /** PART 3: Clear the info message. */
    fun clearInfoMessage() {
        _uiState.update { it.copy(infoMessage = null) }
    }

    /** PART 8: Set info message for UI feedback. */
    fun setInfoMessage(message: String) {
        _uiState.update { it.copy(infoMessage = message) }
    }

    /** PART 9 STEP 3: Manual billing override with guard — uses OperationalSafetyVerifier. */
    fun overrideBillingMode(mode: BillingMode) {
        val state = _uiState.value

        // PART 1: Null safety — if mode matches current, no-op
        if (mode == state.selectedBillingMode && state.isBillingOverridden) return

        // Use centralized safety verifier
        val safetyResult = OperationalSafetyVerifier
            .checkBillingModeChangeSafety(
                currentMode = state.selectedBillingMode,
                newMode = mode,
                hasSegments = state.segments.isNotEmpty(),
                hasTimer = state.timerStartTime != null,
                isTimerRunning = state.isTimerRunning || state.isTimerPaused,
                tripCount = state.tripCount
            )

        when (safetyResult) {
            is OperationalSafetyVerifier.BillingChangeResult.Safe -> {
                applyBillingModeOverride(mode)
            }
            is OperationalSafetyVerifier.BillingChangeResult.Blocked -> {
                _uiState.update { it.copy(infoMessage = safetyResult.reason) }
            }
            is OperationalSafetyVerifier.BillingChangeResult.RequiresConfirmation -> {
                _uiState.update {
                    it.copy(
                        showBillingModeChangeDialog = true,
                        pendingBillingMode = mode
                    )
                }
                validateState(_uiState.value)
            }
        }
    }

    /** Apply billing mode override (internal — no guard check). */
    private fun applyBillingModeOverride(mode: BillingMode?) {
        // PART 1: Null safety — return early if mode is null
        if (mode == null) return

        // Map billing mode to pricing mode for work controls
        val derivedPricingMode = when (mode) {
            BillingMode.PER_MINUTE -> PricingMode.TIME
            BillingMode.PER_HOUR -> PricingMode.TIME
            BillingMode.PER_TRIP -> PricingMode.TRIP
            BillingMode.PER_PACKET -> PricingMode.PACKET
            BillingMode.PER_PACKET_DISTANCE -> PricingMode.PACKET_DISTANCE
            BillingMode.PER_ACRE -> PricingMode.PER_ACRE
            BillingMode.FIXED_AMOUNT -> PricingMode.FIXED_AMOUNT
        }

        _uiState.update {
            it.copy(
                selectedBillingMode = mode,
                isBillingOverridden = true,
                showBillingOverrideSheet = false,
                selectedPricingMode = derivedPricingMode,
                infoMessage = "Billing updated to ${mode.displayName}"
            )
        }

        // PART 6: Revalidate machine compatibility after billing change
        validateMachineAfterBillingChange()
        validateState(_uiState.value)
    }

    /** Confirm billing mode switch — resets all work (no mixed billing allowed). */
    fun confirmBillingModeSwitch() {
        // PART 3: Race condition protection — prevent double execution
        if (isProcessingBillingSwitch) return
        isProcessingBillingSwitch = true

        val mode = _uiState.value.pendingBillingMode
        // PART 1: Null safety — if pendingBillingMode is null, dismiss safely
        if (mode == null) {
            _uiState.update {
                it.copy(
                    showBillingModeChangeDialog = false,
                    pendingBillingMode = null
                )
            }
            isProcessingBillingSwitch = false
            return
        }

        val derivedPricingMode = when (mode) {
            BillingMode.PER_MINUTE -> PricingMode.TIME
            BillingMode.PER_HOUR -> PricingMode.TIME
            BillingMode.PER_TRIP -> PricingMode.TRIP
            BillingMode.PER_PACKET -> PricingMode.PACKET
            BillingMode.PER_PACKET_DISTANCE -> PricingMode.PACKET_DISTANCE
            BillingMode.PER_ACRE -> PricingMode.PER_ACRE
            BillingMode.FIXED_AMOUNT -> PricingMode.FIXED_AMOUNT
        }

        // PART 4: Timer safety — ALWAYS stop timer before any work reset
        timerJob?.cancel()
        timerJob = null

        _uiState.update {
            it.copy(
                // PART 5: Clear ALL work — no partial data remains
                segments = emptyList(),
                tripCount = 0,
                isTimerRunning = false,
                isTimerPaused = false,
                timerStartTime = null,
                timerEndTime = null,
                pauseStartTime = null,
                totalPausedDuration = 0,
                elapsedSeconds = 0,
                liveCost = 0.0,
                isJobComplete = false,
                calculatedTotal = 0.0,
                // Apply new billing
                selectedBillingMode = mode,
                isBillingOverridden = true,
                selectedPricingMode = derivedPricingMode,
                showBillingOverrideSheet = false,
                // Reset dialog
                showBillingModeChangeDialog = false,
                pendingBillingMode = null,
                // PART 8: Feedback — PART 3 safe billing transition memory
                infoMessage = "Previous quantity cleared for new billing method"
            )
        }

        // PART 6: Revalidate machine compatibility after billing change
        validateMachineAfterBillingChange()
        validateState(_uiState.value)

        isProcessingBillingSwitch = false
    }

    /** Cancel billing mode switch — keep current billing. */
    fun dismissBillingModeSwitch() {
        _uiState.update {
            it.copy(
                showBillingModeChangeDialog = false,
                pendingBillingMode = null
            )
        }
        validateState(_uiState.value)
    }

    /**
     * Internal save (does not update UI state for navigation — used by split flow).
     * Returns true on success, false on failure.
     */
    private suspend fun saveJobInternal(): Boolean = saveMutex.withLock {
        val state = _uiState.value
        val rate = state.rateInput.toDoubleOrNull() ?: return@withLock false

        return@withLock try {
            val durationMinutes = when (state.selectedPricingMode) {
                PricingMode.TIME -> {
                    if (state.segments.isNotEmpty()) {
                        state.segments.filter { it.type == PricingMode.TIME }.sumOf { it.quantity }.toInt()
                    } else (state.elapsedSeconds / 60).toInt()
                }
                else -> null
            }
            val tripCount = when {
                state.segments.isNotEmpty() -> state.segments.filter { it.type == PricingMode.TRIP }.sumOf { it.quantity }.toInt()
                state.selectedPricingMode == PricingMode.TRIP || state.selectedPricingMode == PricingMode.TRIP_AND_DISTANCE -> state.tripCount
                else -> null
            }
            val finalRate = if (state.segments.isNotEmpty()) state.segments.last().rate else rate
            val finalTotal = if (state.segments.isNotEmpty()) {
                CalculationUtils.calculateSegmentTotal(state.segments)
            } else state.calculatedTotal

            val job = JobEntity(
                machineType = state.selectedMachineType,
                machineId = state.selectedMachine?.machineId,
                machineName = state.selectedMachine?.name,
                pricingMode = state.selectedPricingMode,
                rate = finalRate,
                startTime = state.timerStartTime,
                endTime = state.timerEndTime,
                durationMinutes = durationMinutes,
                tripCount = tripCount,
                distanceKm = when (state.selectedPricingMode) {
                    PricingMode.DISTANCE, PricingMode.TRIP_AND_DISTANCE -> state.distanceKm.toDoubleOrNull()
                    PricingMode.PER_ACRE -> state.acreQuantity.toDoubleOrNull()
                    else -> null
                },
                totalAmount = finalTotal,
                customerId = state.selectedCustomer?.customerId,
                loadType = state.loadType.takeIf { it.isNotBlank() },
                fieldName = state.fieldName.takeIf { it.isNotBlank() },
                notes = state.notes.takeIf { it.isNotBlank() },
                segmentsJson = if (state.segments.isNotEmpty())
                    SegmentSerializer.toJson(state.segments) else null
            )
            jobRepository.saveJob(job)
            true
        } catch (_: Exception) {
            false
        }
    }

    /**
     * Validate machine ↔ job capability compatibility.
     * Shows inline warning if machine may not be suitable.
     */
    private fun validateMachineCompatibility(machine: MachineEntity, capability: JobCapability) {
        val isCompatible = MachineCapabilityMatcher.isMachineCompatible(machine, capability)
        _uiState.update {
            it.copy(
                machineCompatibilityWarning = if (!isCompatible)
                    "This machine may not be suitable for this work"
                else null
            )
        }
    }

    fun selectMachineType(machineType: MachineType) {
        val derivedMode = machineType.defaultPricingMode()
        val currentMode = _uiState.value.selectedPricingMode
        if (derivedMode != currentMode) {
            // Mode changed — reset mode-specific state
            userEditedRate = false
            _uiState.update {
                it.copy(
                    selectedMachineType = machineType,
                    selectedPricingMode = derivedMode,
                    isTimerRunning = false,
                    isTimerPaused = false,
                    timerStartTime = null,
                    timerEndTime = null,
                    pauseStartTime = null,
                    totalPausedDuration = 0,
                    elapsedSeconds = 0,
                    tripCount = 0,
                    distanceKm = "",
                    loadType = "",
                    isJobComplete = false,
                    calculatedTotal = 0.0
                )
            }
            timerJob?.cancel()
        } else {
            _uiState.update { it.copy(selectedMachineType = machineType) }
        }
        autoFillRate()
    }

    // selectPricingMode removed — pricing mode derived from machine's billingType

    /**
     * Select a specific machine entity — derives pricing mode from machine.pricingMode,
     * auto-fills rate from machine.defaultRate (or RatePreferences fallback).
     * Uses hasMeaningfulWork to decide whether to show confirmation dialog.
     */
    fun selectMachine(machine: MachineEntity) {
        // PART 3: Double-tap protection
        if (isProcessingMachineSwitch) return

        val state = _uiState.value

        // No-op if same machine
        if (state.selectedMachine != null && state.selectedMachine.machineId == machine.machineId) return

        // If meaningful work exists → require confirmation
        if (state.selectedMachine != null && state.hasMeaningfulWork) {
            isProcessingMachineSwitch = true
            // PART 1: Detect small work for softer messaging
            val isSmallWork = state.elapsedSeconds < 30 && state.segments.isEmpty() && state.tripCount == 0
            _uiState.update {
                it.copy(
                    showMachineSwitchConfirm = true,
                    pendingMachineSwitch = machine,
                    machineSwitchIsSmallWork = isSmallWork
                )
            }
            return
        }

        // No meaningful work → switch directly (silently reset any trivial timer <10s)
        if (state.isTimerRunning && state.elapsedSeconds < 10) {
            timerJob?.cancel()
            timerJob = null
            _uiState.update {
                it.copy(
                    isTimerRunning = false,
                    isTimerPaused = false,
                    timerStartTime = null,
                    timerEndTime = null,
                    pauseStartTime = null,
                    totalPausedDuration = 0,
                    elapsedSeconds = 0,
                    liveCost = 0.0
                )
            }
        }

        performMachineSelection(machine)
    }

    /** Confirm machine switch — clears ALL work and applies new machine. */
    fun confirmMachineSwitch() {
        val state = _uiState.value
        val pending = state.pendingMachineSwitch ?: run {
            isProcessingMachineSwitch = false
            return
        }

        // PART 6: Store undo data (segments + trips + previous machine; skip timer)
        val hadMeaningfulWork = state.hasMeaningfulWork
        if (hadMeaningfulWork && (state.segments.isNotEmpty() || state.tripCount > 0)) {
            undoMachineSwitchData = MachineSwitchUndoData(
                previousMachine = state.selectedMachine,
                segments = state.segments,
                tripCount = state.tripCount
            )
        } else {
            undoMachineSwitchData = null
        }

        // Reset ALL work safely — timer, segments, trips, liveCost
        timerJob?.cancel()
        timerJob = null

        // PART 4: Context-aware feedback
        val feedback = if (hadMeaningfulWork) {
            "Machine changed • Work reset"
        } else {
            "Machine selected"
        }

        _uiState.update { it.copy(
            showMachineSwitchConfirm = false,
            pendingMachineSwitch = null,
            machineSwitchIsSmallWork = false,
            segments = emptyList(),
            tripCount = 0,
            isTimerRunning = false,
            isTimerPaused = false,
            timerStartTime = null,
            timerEndTime = null,
            pauseStartTime = null,
            totalPausedDuration = 0,
            elapsedSeconds = 0,
            liveCost = 0.0,
            isJobComplete = false,
            calculatedTotal = 0.0,
            infoMessage = feedback
        )}

        performMachineSelection(pending)
        isProcessingMachineSwitch = false
    }

    /** Cancel machine switch. */
    fun dismissMachineSwitch() {
        _uiState.update {
            it.copy(
                showMachineSwitchConfirm = false,
                pendingMachineSwitch = null,
                machineSwitchIsSmallWork = false
            )
        }
        isProcessingMachineSwitch = false
    }

    /** PART 6: Undo the last machine switch — restore segments and trips (not timer). */
    fun undoMachineSwitch() {
        val undo = undoMachineSwitchData ?: return
        undoMachineSwitchData = null

        // Restore previous machine
        if (undo.previousMachine != null) {
            _uiState.update {
                it.copy(
                    segments = undo.segments,
                    tripCount = undo.tripCount,
                    isJobComplete = undo.segments.isNotEmpty() || undo.tripCount > 0,
                    calculatedTotal = if (undo.segments.isNotEmpty())
                        CalculationUtils.calculateSegmentTotal(undo.segments) else 0.0,
                    infoMessage = "Machine switch undone"
                )
            }
            performMachineSelection(undo.previousMachine)
        }
    }

    /** Check if machine switch undo is available. */
    fun hasMachineSwitchUndo(): Boolean = undoMachineSwitchData != null

    /** Clear undo data (call after snackbar dismissed without undo). */
    fun clearMachineSwitchUndo() {
        undoMachineSwitchData = null
    }

    private fun performMachineSelection(machine: MachineEntity) {
        val derivedMode = if (machine.pricingMode == "PER_TRIP") PricingMode.TRIP else PricingMode.TIME
        val currentMode = _uiState.value.selectedPricingMode
        val machineType = try { MachineType.valueOf(machine.type) } catch (_: Exception) { MachineType.TRACTOR }

        // Contextual selection message (includes work type if selected)
        val workLabel = _uiState.value.selectedJobCapability?.displayName
        val selectionMsg = if (workLabel != null) {
            "✓ ${machine.name} ready for $workLabel"
        } else {
            "✓ ${machine.name} ready"
        }

        if (derivedMode != currentMode) {
            // Mode changed — reset mode-specific state
            userEditedRate = false
            _uiState.update {
                it.copy(
                    selectedMachine = machine,
                    machineError = null,
                    selectedMachineType = machineType,
                    selectedPricingMode = derivedMode,
                    isTimerRunning = false,
                    isTimerPaused = false,
                    timerStartTime = null,
                    timerEndTime = null,
                    pauseStartTime = null,
                    totalPausedDuration = 0,
                    elapsedSeconds = 0,
                    tripCount = 0,
                    distanceKm = "",
                    loadType = "",
                    isJobComplete = false,
                    calculatedTotal = 0.0,
                    machineSelectionMessage = selectionMsg
                )
            }
            timerJob?.cancel()
        } else {
            _uiState.update {
                it.copy(
                    selectedMachine = machine,
                    machineError = null,
                    selectedMachineType = machineType,
                    machineSelectionMessage = selectionMsg
                )
            }
        }

        // Auto-fill rate: prefer machine.defaultRate, fallback to RatePreferences
        if (!userEditedRate) {
            val rate = if (machine.defaultRate > 0) {
                machine.defaultRate
            } else {
                ratePreferences.getDefaultRate(machineType, derivedMode)
            }
            if (rate != null && rate > 0) {
                val rateStr = if (rate == rate.toLong().toDouble()) rate.toLong().toString() else rate.toString()
                _uiState.update { it.copy(rateInput = rateStr, rateError = null) }
                recalculateTotal()
            }
        }

        // PART 6: Validate machine compatibility with selected work type
        val selectedCap = _uiState.value.selectedJobCapability
        if (selectedCap != null) {
            validateMachineCompatibility(machine, selectedCap)
        }

        // PART 9: Emit machine switched event
        currentJobId?.let { jobId ->
            WorkEventBus.emit(WorkEvent.MachineSwitched(
                jobId = jobId,
                fromMachineId = _uiState.value.selectedMachine?.machineId,
                toMachineId = machine.machineId
            ))
        }
    }

    fun updateMachineSearch(query: String) {
        _uiState.update { it.copy(machineSearchQuery = query) }
    }

    // ================== Rate Input ==================

    fun updateRate(rate: String) {
        userEditedRate = true
        // OPERATIONAL HARDENING: Sanitize input
        var filtered = rate.filter { it.isDigit() || it == '.' }

        // Reject multiple dots — keep only up to first dot and digits after
        val dotIndex = filtered.indexOf('.')
        if (dotIndex >= 0) {
            filtered = filtered.substring(0, dotIndex + 1) +
                filtered.substring(dotIndex + 1).filter { it.isDigit() }
        }

        // Cap input length to prevent absurd values
        if (filtered.length > JobConstants.MAX_RATE_INPUT_LENGTH) {
            filtered = filtered.substring(0, JobConstants.MAX_RATE_INPUT_LENGTH)
        }

        val rateError = when {
            filtered.isEmpty() -> null
            filtered.toDoubleOrNull() == null -> "Invalid number"
            filtered.toDouble() <= 0 -> "Rate must be greater than 0"
            filtered.toDouble() > JobConstants.MAX_RATE -> "Rate too high (max ₹${JobConstants.MAX_RATE.toInt()})"
            else -> null
        }
        _uiState.update {
            it.copy(
                rateInput = filtered,
                rateError = rateError
            )
        }
        recalculateTotal()
    }

    // ================== Timer Controls (TIME mode) ==================

    fun startTimer() {
        // OPERATIONAL HARDENING: If paused, redirect to resume (prevents data loss)
        if (_uiState.value.jobPhase == JobPhase.PAUSED) {
            resumeTimer()
            return
        }

        // PART W — Block start if rate is empty; trigger focus instead
        val rate = _uiState.value.rateInput.toDoubleOrNull()
        if (rate == null || rate <= 0) {
            _uiState.update { it.copy(rateFocusTrigger = it.rateFocusTrigger + 1) }
            return
        }

        // Create job in active_jobs on first real work
        ensureActiveJobCreated()

        // OPERATIONAL HARDENING: Validate phase transition
        if (!transitionTo(JobPhase.RUNNING)) return

        val startTime = System.currentTimeMillis()
        _uiState.update {
            it.copy(
                isTimerRunning = true,
                isTimerPaused = false,
                timerStartTime = startTime,
                timerEndTime = null,
                pauseStartTime = null,
                totalPausedDuration = 0,
                elapsedSeconds = 0,
                isJobComplete = false,
                // PART 1: Reset auto-minimize on new timer start
                isAutoMinimized = false,
                autoMinimizeOverridden = false,
                // PART 2: Begin focus transition
                focusPhase = FocusPhase.TRANSITIONING,
                // PART 5: Clear interruption label
                timerInterruptionLabel = null,
                // PART 7: Reset persistence status
                persistenceStatus = PersistenceStatus.IDLE
            )
        }
        startTickingCoroutine()
        persistActiveJob()

        // CANONICAL: Emit work started event
        _uiState.value.currentJobId?.let { jobId ->
            WorkEventBus.emit(WorkEvent.WorkStarted(
                jobId = jobId,
                capability = _uiState.value.selectedJobCapability?.name,
                machineId = _uiState.value.selectedMachine?.machineId,
                customerId = _uiState.value.selectedCustomer?.customerId
            ))
        }

        // CANONICAL PART 12: Invariant check after timer start
        verifyInvariants()
    }

    fun pauseTimer() {
        // OPERATIONAL HARDENING: Guard — only pause if timer is running
        if (_uiState.value.jobPhase != JobPhase.RUNNING && !_uiState.value.isTimerRunning) return
        transitionTo(JobPhase.PAUSED)

        timerJob?.cancel()
        _uiState.update {
            it.copy(
                isTimerRunning = false,
                isTimerPaused = true,
                pauseStartTime = System.currentTimeMillis()
            )
        }
        persistActiveJob()

        // CANONICAL: Emit timer paused event
        _uiState.value.currentJobId?.let { jobId ->
            WorkEventBus.emit(WorkEvent.TimerPaused(
                jobId = jobId,
                elapsedSeconds = _uiState.value.elapsedSeconds
            ))
        }
    }

    fun resumeTimer() {
        // OPERATIONAL HARDENING: Guard — only resume if paused
        if (_uiState.value.jobPhase != JobPhase.PAUSED && !_uiState.value.isTimerPaused) return
        transitionTo(JobPhase.RUNNING)

        val now = System.currentTimeMillis()
        _uiState.update { state ->
            val pausedMs = (now - (state.pauseStartTime ?: now)).coerceAtLeast(0)  // OPERATIONAL HARDENING: Never negative
            // PART 5: Timer interruption label
            val pausedMins = (pausedMs / 60_000).toInt()
            val label = if (pausedMins >= 1) "Paused ${pausedMins}m" else "Paused briefly"
            state.copy(
                isTimerRunning = true,
                isTimerPaused = false,
                pauseStartTime = null,
                totalPausedDuration = state.totalPausedDuration + pausedMs,
                timerInterruptionLabel = label
            )
        }
        // PART 5: Auto-clear interruption label after 30s
        viewModelScope.launch {
            delay(30_000)
            _uiState.update { it.copy(timerInterruptionLabel = null) }
        }
        startTickingCoroutine()
        persistActiveJob()

        // CANONICAL: Emit timer resumed event
        _uiState.value.currentJobId?.let { jobId ->
            val pausedMs = _uiState.value.totalPausedDuration
            WorkEventBus.emit(WorkEvent.TimerResumed(
                jobId = jobId,
                pausedDurationMs = pausedMs
            ))
        }
    }

    /**
     * COMPRESSED LIFECYCLE: Finish timer and directly save.
     * - Short sessions (<10s) silently revert to setup.
     * - Normal sessions: stop timer → auto-create segment → save immediately.
     * - No intermediate STOPPED state — reduces taps.
     * - Shows undo snackbar for 5s to allow "undo finish" (resume timer).
     */
    fun stopTimer() {
        timerJob?.cancel()
        val endTime = System.currentTimeMillis()

        _uiState.update { state ->
            // If paused, account for final paused duration
            val extraPaused = if (state.isTimerPaused && state.pauseStartTime != null) {
                endTime - state.pauseStartTime
            } else 0L
            val totalPaused = state.totalPausedDuration + extraPaused

            val startTime = state.timerStartTime ?: endTime
            val durationSeconds = ((endTime - startTime) - totalPaused) / 1000

            state.copy(
                isTimerRunning = false,
                isTimerPaused = false,
                timerEndTime = endTime,
                pauseStartTime = null,
                totalPausedDuration = totalPaused,
                elapsedSeconds = durationSeconds.coerceAtLeast(0),
                isJobComplete = true,
                focusPhase = FocusPhase.SETUP,
                isAutoMinimized = false,
                timerInterruptionLabel = null
            )
        }

        // Short session guard: silently revert <10s sessions
        val state = _uiState.value
        if (state.elapsedSeconds < JobConstants.MEANINGFUL_WORK_SECONDS) {
            _uiState.update {
                it.copy(
                    tooShortFeedback = "Timer was under ${JobConstants.MEANINGFUL_WORK_SECONDS}s — reset",
                    isTimerRunning = false,
                    isTimerPaused = false,
                    timerStartTime = null,
                    timerEndTime = null,
                    totalPausedDuration = 0,
                    elapsedSeconds = 0,
                    isJobComplete = false,
                    jobPhase = JobPhase.SETUP
                )
            }
            recalculateTotal()
            viewModelScope.launch {
                delay(3000)
                _uiState.update { it.copy(tooShortFeedback = null) }
            }
            return
        }

        // COMPRESSED: Create segment and auto-save immediately
        transitionTo(JobPhase.STOPPED) // brief transitional
        createTimeSegment()
        recalculateTotal()
        persistActiveJob()

        // Direct save — skip STOPPED review step
        saveJob()
    }

    /**
     * Starts the coroutine that ticks elapsed time every second.
     * Also computes live cost for real-time display.
     *
     * PART 6: Timer safety — elapsed is ALWAYS derived from persisted timestamps:
     *   elapsed = (now - startTime - totalPausedDuration) / 1000
     * This survives:
     *   - device sleep (doze mode)
     *   - process death (Room auto-save every 20s)
     *   - overnight timers (no drift)
     * Never relies on in-memory tick counting.
     */
    private fun startTickingCoroutine() {
        timerJob?.cancel()
        timerJob = viewModelScope.launch {
            var tickCount = 0L
            var lastSavedCost = 0.0
            var consecutiveFailures = 0  // PART 9: Track consecutive save failures
            while (true) {
                delay(1000)
                val s = _uiState.value
                if (!s.isTimerRunning) break
                tickCount++

                // PART 6: Always re-derive from timestamps — never accumulate
                val elapsed = (System.currentTimeMillis() - (s.timerStartTime ?: 0) - s.totalPausedDuration) / 1000
                val rate = s.rateInput.toDoubleOrNull() ?: 0.0
                val liveCost = if (rate > 0) (elapsed / 60.0) * rate else 0.0

                // Only update liveCost visually every 5 seconds to reduce flicker
                val displayCost = if (tickCount % 5 == 0L || kotlin.math.abs(liveCost - lastSavedCost) >= 1.0) {
                    lastSavedCost = liveCost
                    liveCost
                } else {
                    s.liveCost // keep previous display value
                }

                // CANONICAL: Fatigue profile from convergence engine (used by UiState.fatigueProfile)
                // No longer setting fatigue booleans — UiState.fatigueProfile is the single authority

                // PART 1: Smart auto-minimize — collapse non-essential cards after 20s
                val shouldAutoMinimize = elapsed >= 20 && !s.autoMinimizeOverridden

                _uiState.update {
                    it.copy(
                        elapsedSeconds = elapsed.coerceAtLeast(0),
                        liveCost = displayCost,
                        isAutoMinimized = if (shouldAutoMinimize) true else it.isAutoMinimized,
                        // PART 2: Focus mode transition — SETUP → ACTIVE after 2s
                        focusPhase = if (elapsed >= 2 && it.focusPhase == FocusPhase.TRANSITIONING) FocusPhase.ACTIVE else it.focusPhase
                    )
                }

                // PART 7: Save confidence — auto-save heartbeat with status tracking
                if (tickCount % 20 == 0L && currentJobId != null) {
                    _uiState.update { it.copy(persistenceStatus = PersistenceStatus.SAVING) }
                    try {
                        saveCurrentJobToMultiTable()
                        consecutiveFailures = 0  // Reset on success
                        _uiState.update {
                            it.copy(
                                persistenceStatus = PersistenceStatus.SAVED,
                                lastSuccessfulSaveAt = System.currentTimeMillis(),
                                showSaveFailureWarning = false  // Clear warning on success
                            )
                        }
                    } catch (_: Exception) {
                        consecutiveFailures++
                        // PART 9: Escalate after >2 minutes (6+ consecutive 20s failures)
                        val showWarning = consecutiveFailures >= 6
                        _uiState.update {
                            it.copy(
                                persistenceStatus = PersistenceStatus.ERROR,
                                showSaveFailureWarning = showWarning
                            )
                        }
                        // Soft failure: continue operation, retry next cycle
                        // Field operation > database purity
                    }
                }

                // PART 7: Detect delayed status (last save > 60s ago)
                val lastSave = _uiState.value.lastSuccessfulSaveAt
                if (lastSave != null && _uiState.value.persistenceStatus == PersistenceStatus.SAVED) {
                    if (System.currentTimeMillis() - lastSave > 60_000) {
                        _uiState.update { it.copy(persistenceStatus = PersistenceStatus.DELAYED) }
                    }
                }

                // Compute last backup label every 5s (internal tracking)
                if (tickCount % 5 == 0L) {
                    val ls = _uiState.value.lastSuccessfulSaveAt
                    val label = if (ls != null && ls > 0) {
                        val secsAgo = ((System.currentTimeMillis() - ls) / 1000).toInt()
                        when {
                            secsAgo < 10 -> "Backed up just now"
                            secsAgo < 60 -> "Backed up ${secsAgo}s ago"
                            else -> "Backed up ${secsAgo / 60}m ago"
                        }
                    } else null
                    _uiState.update { it.copy(lastBackupLabel = label) }
                }
            }
        }
    }

    // ================== Trip Counter (TRIP mode) ==================

    fun incrementTrip() {
        // Create job in active_jobs on first real work
        ensureActiveJobCreated()

        // OPERATIONAL HARDENING: Transition to RUNNING on first trip (if still in SETUP)
        val phase = _uiState.value.jobPhase
        if (phase == JobPhase.SETUP) {
            transitionTo(JobPhase.RUNNING)
        }

        _uiState.update {
            val newCount = it.tripCount + 1
            val isComplete = when (it.selectedPricingMode) {
                PricingMode.TRIP -> true
                PricingMode.TRIP_AND_DISTANCE -> newCount > 0 && (it.distanceKm.toDoubleOrNull() ?: 0.0) > 0
                else -> it.isJobComplete
            }
            it.copy(tripCount = newCount, isJobComplete = isComplete)
        }
        recalculateTotal()
        persistActiveJob()
    }

    fun decrementTrip() {
        _uiState.update { state ->
            val newCount = maxOf(0, state.tripCount - 1)
            val isComplete = when (state.selectedPricingMode) {
                PricingMode.TRIP -> newCount > 0
                PricingMode.TRIP_AND_DISTANCE -> newCount > 0 && (state.distanceKm.toDoubleOrNull() ?: 0.0) > 0
                else -> state.isJobComplete
            }
            state.copy(tripCount = newCount, isJobComplete = isComplete)
        }
        recalculateTotal()
        persistActiveJob()
    }

    // ================== Segment-Based Pricing ==================

    /**
     * Add a single trip segment at the current rate.
     * Uses the rate from rateInput (or last segment rate if available).
     */
    fun onAddTrip() {
        val state = _uiState.value
        if (state.isAddingSegment) return // PART AB — guard rapid taps (debounce)
        val rate = state.rateInput.toDoubleOrNull() ?: return
        if (rate <= 0) return

        // OPERATIONAL HARDENING: Cap trip count
        val currentTripCount = state.segments.count { it.type == PricingMode.TRIP }
        if (currentTripCount >= JobConstants.MAX_TRIP_SEGMENTS) {
            _uiState.update { it.copy(segmentActionMessage = "Maximum loads reached (${JobConstants.MAX_TRIP_SEGMENTS})") }
            return
        }

        // Create job in active_jobs on first real work
        ensureActiveJobCreated()

        // OPERATIONAL HARDENING: Transition to RUNNING on first segment add
        if (_uiState.value.jobPhase == JobPhase.SETUP) {
            transitionTo(JobPhase.RUNNING)
        }

        _uiState.update { it.copy(isAddingSegment = true) }
        // PART AB — Release debounce lock after 400ms
        viewModelScope.launch {
            delay(400)
            _uiState.update { it.copy(isAddingSegment = false) }
        }

        // Detect rate change
        val previousRate = state.segments.lastOrNull()?.rate
        val rateChanged = previousRate != null && previousRate != rate
        val newGroupKey = if (rateChanged) "${PricingMode.TRIP.name}_${rate}" else null

        val segment = WorkSegment.trip(rate)
        _uiState.update {
            val newSegments = it.segments + segment
            // Consolidate messages: if rate changed, include in the action message
            val actionMsg = if (rateChanged) {
                "Load added • ${CalculationUtils.formatCurrencyShort(rate)} [Rate → ${CalculationUtils.formatCurrencyShort(rate)}]"
            } else {
                "Load added • ${CalculationUtils.formatCurrencyShort(rate)}"
            }
            it.copy(
                segments = newSegments,
                tripCount = newSegments.size,
                isJobComplete = true,
                calculatedTotal = CalculationUtils.calculateSegmentTotal(newSegments),
                currentRate = rate,
                rateChangeMessage = null, // consolidated into actionMessage
                lastAddedSegmentIds = listOf(segment.id),
                segmentActionMessage = actionMsg,
                newRateGroupKey = newGroupKey,
                canUndoLastAction = true
            )
        }
        // PART 3: Start 8-second undo window
        undoTimerJob?.cancel()
        undoTimerJob = viewModelScope.launch {
            delay(8000)
            _uiState.update { it.copy(canUndoLastAction = false) }
        }
        autoSaveDraft()
        trackAction()
    }

    /**
     * Add multiple trip segments at a given rate (bulk entry).
     */
    fun onAddMultipleTrips(count: Int, rate: Double) {
        if (count <= 0 || rate <= 0) return
        val state = _uiState.value
        if (state.isAddingSegment) return

        // Create job in active_jobs on first real work
        ensureActiveJobCreated()

        _uiState.update { it.copy(isAddingSegment = true) }
        // PART AB — Release debounce lock after 400ms
        viewModelScope.launch {
            delay(400)
            _uiState.update { it.copy(isAddingSegment = false) }
        }

        val newSegments = (1..count).map { WorkSegment.trip(rate) }
        val addedIds = newSegments.map { it.id }
        _uiState.update {
            val allSegments = it.segments + newSegments
            it.copy(
                segments = allSegments,
                tripCount = allSegments.filter { s -> s.type == PricingMode.TRIP }.size,
                isJobComplete = true,
                calculatedTotal = CalculationUtils.calculateSegmentTotal(allSegments),
                currentRate = rate,
                showBulkEntrySheet = false,
                lastAddedSegmentIds = addedIds,
                segmentActionMessage = "$count loads added"
            )
        }
        autoSaveDraft()
        trackAction()
    }

    /**
     * Create a time segment when timer is stopped.
     * Uses fair rounding: round to nearest minute.
     * PART 6: Skip if < 10 seconds OR if billed amount == 0.
     */
    fun createTimeSegment() {
        val state = _uiState.value
        val rate = state.rateInput.toDoubleOrNull() ?: return
        if (rate <= 0) return

        val actualSeconds = state.elapsedSeconds.toInt()

        // PART Q — Short duration rule: don't create segment for < 10 seconds
        if (actualSeconds < CalculationUtils.MIN_SEGMENT_SECONDS) {
            _uiState.update { it.copy(
                segmentActionMessage = "Not recorded — too short",
                tooShortFeedback = "Not recorded — too short"
            ) }
            clearTooShortFeedbackAfterDelay()
            return
        }

        val segment = WorkSegment.time(actualSeconds, rate)

        // PART Q — Zero-amount rule: if rounds to 0 minutes, don't create
        if (segment.amount <= 0) {
            _uiState.update { it.copy(
                segmentActionMessage = "Not billed — less than 30 sec",
                tooShortFeedback = "Not billed — less than 30 sec"
            ) }
            clearTooShortFeedbackAfterDelay()
            return
        }

        val billedMinutes = segment.quantity.toInt()

        // Format display: "Worked Xm Ys • Billed Nm"
        val wMins = actualSeconds / 60
        val wSecs = actualSeconds % 60
        val workedStr = when {
            wMins > 0 && wSecs > 0 -> "${wMins}m ${wSecs}s"
            wMins > 0 -> "${wMins}m"
            else -> "${wSecs}s"
        }
        val displayMsg = "Worked $workedStr • Billed ${billedMinutes}m"

        _uiState.update {
            val newSegments = it.segments + segment
            it.copy(
                segments = newSegments,
                calculatedTotal = CalculationUtils.calculateSegmentTotal(newSegments),
                currentRate = rate,
                lastAddedSegmentIds = listOf(segment.id),
                segmentActionMessage = displayMsg
            )
        }
        autoSaveDraft()
    }

    /**
     * Undo the last segment action (removes last batch of added segments).
     */
    fun undoLastSegment() {
        val state = _uiState.value
        if (state.lastAddedSegmentIds.isEmpty()) return
        val idsToRemove = state.lastAddedSegmentIds.toSet()
        _uiState.update {
            val updated = it.segments.filter { seg -> seg.id !in idsToRemove }
            it.copy(
                segments = updated,
                tripCount = updated.filter { seg -> seg.type == PricingMode.TRIP }.size,
                isJobComplete = updated.isNotEmpty(),
                calculatedTotal = CalculationUtils.calculateSegmentTotal(updated),
                lastAddedSegmentIds = emptyList(),
                segmentActionMessage = null
            )
        }
        autoSaveDraft()
    }

