    // ================== Rate Edit (Inline) ==================

    /** Open rate edit sheet for a specific group. */
    fun showRateEditSheet(groupKey: String, currentRate: Double) {
        _uiState.update {
            it.copy(
                showRateEditSheet = true,
                rateEditGroupKey = groupKey,
                rateEditCurrentRate = currentRate.toLong().toString()
            )
        }
    }

    fun hideRateEditSheet() {
        _uiState.update { it.copy(showRateEditSheet = false, rateEditGroupKey = null) }
    }

    fun updateRateEditInput(value: String) {
        // OPERATIONAL HARDENING: Same input sanitization as updateRate()
        var filtered = value.filter { c -> c.isDigit() || c == '.' }
        val dotIndex = filtered.indexOf('.')
        if (dotIndex >= 0) {
            filtered = filtered.substring(0, dotIndex + 1) +
                filtered.substring(dotIndex + 1).filter { it.isDigit() }
        }
        if (filtered.length > JobConstants.MAX_RATE_INPUT_LENGTH) {
            filtered = filtered.substring(0, JobConstants.MAX_RATE_INPUT_LENGTH)
        }
        _uiState.update { it.copy(rateEditCurrentRate = filtered) }
    }

    /** Apply new rate to all segments in the group. */
    fun applyRateToGroup() {
        val state = _uiState.value
        val groupKey = state.rateEditGroupKey ?: return
        val newRate = state.rateEditCurrentRate.toDoubleOrNull() ?: return
        if (newRate <= 0) return

        // Parse groupKey: "TYPE_rate"
        val parts = groupKey.split("_", limit = 2)
        if (parts.size < 2) return
        val typeName = parts[0]
        val oldRate = parts[1].toDoubleOrNull() ?: return

        _uiState.update { s ->
            val updated = s.segments.map { seg ->
                if (seg.type.name == typeName && seg.rate == oldRate) {
                    val newAmount = seg.quantity * newRate
                    seg.copy(rate = newRate, amount = newAmount)
                } else seg
            }
            s.copy(
                segments = updated,
                calculatedTotal = CalculationUtils.calculateSegmentTotal(updated),
                showRateEditSheet = false,
                rateEditGroupKey = null
            )
        }
        autoSaveDraft()
    }

    /**
     * Edit an existing segment (update rate or quantity).
     */
    fun editSegment(segmentId: String, newRate: Double, newQuantity: Double) {
        if (newRate <= 0 || newQuantity <= 0) return
        _uiState.update { state ->
            val updated = state.segments.map { seg ->
                if (seg.id == segmentId) {
                    val newAmount = newQuantity * newRate
                    seg.copy(
                        rate = newRate,
                        quantity = newQuantity,
                        amount = newAmount
                    )
                } else seg
            }
            state.copy(
                segments = updated,
                tripCount = updated.filter { it.type == PricingMode.TRIP }.size,
                calculatedTotal = CalculationUtils.calculateSegmentTotal(updated)
            )
        }
        autoSaveDraft()
    }

    /**
     * Delete a segment by ID.
     */
    fun deleteSegment(segmentId: String) {
        _uiState.update { state ->
            val updated = state.segments.filter { it.id != segmentId }
            state.copy(
                segments = updated,
                tripCount = updated.filter { it.type == PricingMode.TRIP }.size,
                isJobComplete = updated.isNotEmpty(),
                calculatedTotal = CalculationUtils.calculateSegmentTotal(updated)
            )
        }
        autoSaveDraft()
        trackAction()
    }

    /**
     * Delete all segments in a group by group key.
     */
    fun deleteGroup(groupKey: String) {
        _uiState.update { state ->
            val updated = state.segments.filter { "${it.type.name}_${it.rate}" != groupKey }
            state.copy(
                segments = updated,
                tripCount = updated.filter { it.type == PricingMode.TRIP }.size,
                isJobComplete = updated.isNotEmpty(),
                calculatedTotal = CalculationUtils.calculateSegmentTotal(updated)
            )
        }
        autoSaveDraft()
        trackAction()
    }

    /**
     * PART 3: Undo the last load add within 8-second window.
     * Removes lastAddedSegmentIds from segments and clears undo state.
     */
    fun undoLastAction() {
        val ids = _uiState.value.lastAddedSegmentIds
        if (ids.isEmpty()) return
        undoTimerJob?.cancel()
        _uiState.update { state ->
            val updated = state.segments.filter { it.id !in ids }
            state.copy(
                segments = updated,
                tripCount = updated.filter { it.type == PricingMode.TRIP }.size,
                isJobComplete = updated.isNotEmpty(),
                calculatedTotal = CalculationUtils.calculateSegmentTotal(updated),
                lastAddedSegmentIds = emptyList(),
                canUndoLastAction = false,
                segmentActionMessage = "Undone"
            )
        }
        autoSaveDraft()
    }

