    // ================== Default Rate Auto-fill ==================

    private fun autoFillRate() {
        if (userEditedRate) return // Don't override manual input
        val state = _uiState.value
        val defaultRate = ratePreferences.getDefaultRate(state.selectedMachineType, state.selectedPricingMode)
        if (defaultRate != null && defaultRate > 0) {
            val rateStr = if (defaultRate == defaultRate.toLong().toDouble()) {
                defaultRate.toLong().toString() // Show "500" not "500.0"
            } else {
                defaultRate.toString()
            }
            _uiState.update { it.copy(rateInput = rateStr, rateError = null) }
            recalculateTotal()
        }
    }

    // ================== Calculation ==================

    private fun recalculateTotal() {
        val state = _uiState.value

        // PACKET_DISTANCE mode: combine segment total + distance charge
        if (state.selectedPricingMode == PricingMode.PACKET_DISTANCE) {
            val packetTotal = if (state.segments.isNotEmpty()) {
                CalculationUtils.calculateSegmentTotal(state.segments)
            } else {
                val rate = state.rateInput.toDoubleOrNull() ?: 0.0
                state.tripCount * rate
            }
            val distance = state.distanceKm.toDoubleOrNull() ?: 0.0
            val distRate = state.distanceRate.toDoubleOrNull() ?: 0.0
            val distanceTotal = distance * distRate
            val total = CalculationUtils.applyMinimumCharge(packetTotal + distanceTotal)
            _uiState.update { it.copy(calculatedTotal = total) }
            return
        }

        // If segments exist, they are the source of truth for total
        if (state.segments.isNotEmpty()) {
            val total = CalculationUtils.calculateSegmentTotal(state.segments)
            _uiState.update { it.copy(calculatedTotal = total) }
            return
        }

        // Fallback: legacy calculation for backward compat
        val rate = state.rateInput.toDoubleOrNull() ?: 0.0

        val total = when (state.selectedPricingMode) {
            PricingMode.TIME -> {
                val minutes = (state.elapsedSeconds / 60).toInt()
                CalculationUtils.calculateTotal(
                    mode = PricingMode.TIME,
                    rate = rate,
                    durationMinutes = minutes
                )
            }
            PricingMode.TRIP -> {
                CalculationUtils.calculateTotal(
                    mode = PricingMode.TRIP,
                    rate = rate,
                    tripCount = state.tripCount
                )
            }
            PricingMode.DISTANCE -> {
                val distance = state.distanceKm.toDoubleOrNull() ?: 0.0
                CalculationUtils.calculateTotal(
                    mode = PricingMode.DISTANCE,
                    rate = rate,
                    distanceKm = distance
                )
            }
            PricingMode.TRIP_AND_DISTANCE -> {
                val distance = state.distanceKm.toDoubleOrNull() ?: 0.0
                CalculationUtils.calculateTotal(
                    mode = PricingMode.TRIP_AND_DISTANCE,
                    rate = rate,
                    tripCount = state.tripCount,
                    distanceKm = distance
                )
            }
            PricingMode.PACKET -> {
                CalculationUtils.calculateTotal(
                    mode = PricingMode.PACKET,
                    rate = rate,
                    packetCount = state.tripCount
                )
            }
            PricingMode.FIXED_AMOUNT -> {
                // Fixed amount: no auto-calculation. Use manually entered amount.
                0.0
            }
            PricingMode.PER_ACRE -> {
                // Convert user-entered value from selected unit to acres for billing
                val enteredValue = state.acreQuantity.toDoubleOrNull() ?: 0.0
                val acresForBilling = state.selectedAreaUnit.toAcres(enteredValue)
                CalculationUtils.calculateTotal(
                    mode = PricingMode.PER_ACRE,
                    rate = rate,
                    acreQuantity = acresForBilling
                )
            }
            PricingMode.PACKET_DISTANCE -> {
                // Handled early in function — should not reach here
                0.0
            }
        }

        _uiState.update { it.copy(calculatedTotal = total) }
    }

    // ================== Save Job ==================

    fun saveJob() {
        val state = _uiState.value

        // PART 10: Prevent rapid double taps
        if (state.isSaving) return

        // Prevent duplicate save of already-finalized job — silent ignore
        if (hasSavedCurrentJob) return

        // OPERATIONAL HARDENING: Phase guard — only save from valid phases
        if (state.jobPhase == JobPhase.SAVING || state.jobPhase == JobPhase.SAVED) {
            android.util.Log.w("NewJobVM", "⚠️ saveJob() called in phase ${state.jobPhase} — blocked")
            return
        }

        // Validate
        if (!state.canSave) {
            _uiState.update {
                it.copy(
                    templateError = if (state.isTemplateFlow && state.selectedTemplate == null) "Select a job type" else null,
                    machineError = if (state.machines.isNotEmpty() && state.selectedMachine == null) "Select a machine" else null,
                    rateError = state.rateError ?: run {
                        val r = state.rateInput.toDoubleOrNull()
                        if (r == null || r <= 0) "Enter valid rate" else null
                    },
                    errorMessage = "Please complete required fields"
                )
            }
            return
        }

        val rate = state.rateInput.toDoubleOrNull() ?: return

        _uiState.update { it.copy(isSaving = true, errorMessage = null, saveAnimationState = SaveAnimationState.LOADING, jobPhase = JobPhase.SAVING) }

        // STEP 7 — Recalculate total from raw values for billing accuracy
        // OPERATIONAL HARDENING: Snapshot displayed total BEFORE recalc for consistency check
        val displayedTotal = _uiState.value.segmentTotal
        recalculateTotal()
        val finalState = _uiState.value
        val recalcTotal = finalState.segmentTotal
        if (kotlin.math.abs(displayedTotal - recalcTotal) > 1.0) {
            android.util.Log.w("NewJobVM", "⚠️ Save total drift: displayed=$displayedTotal recalc=$recalcTotal")
        }

        viewModelScope.launch {
            try {
                val durationMinutes = when (finalState.selectedPricingMode) {
                    PricingMode.TIME -> {
                        // Use segment-based duration if available
                        if (finalState.segments.isNotEmpty()) {
                            finalState.segments
                                .filter { it.type == PricingMode.TIME }
                                .sumOf { it.quantity }.toInt()
                        } else {
                            (finalState.elapsedSeconds / 60).toInt()
                        }
                    }
                    else -> null
                }

                // Backward compat: tripCount = sum of trip segment quantities
                val tripCount = when {
                    finalState.segments.isNotEmpty() ->
                        finalState.segments
                            .filter { it.type == PricingMode.TRIP }
                            .sumOf { it.quantity }.toInt()
                    finalState.selectedPricingMode == PricingMode.TRIP ||
                        finalState.selectedPricingMode == PricingMode.TRIP_AND_DISTANCE -> finalState.tripCount
                    else -> null
                }

                // Backward compat: rate = last segment rate (or input rate)
                val finalRate = if (finalState.segments.isNotEmpty()) {
                    finalState.segments.last().rate
                } else rate

                // Total from segments if available, otherwise calculated
                val finalTotal = if (finalState.segments.isNotEmpty()) {
                    CalculationUtils.calculateSegmentTotal(finalState.segments)
                } else {
                    finalState.calculatedTotal
                }

                val job = JobEntity(
                    machineType = finalState.selectedMachineType,
                    machineId = finalState.selectedMachine?.machineId,
                    machineName = finalState.selectedMachine?.name,
                    pricingMode = finalState.selectedPricingMode,
                    rate = finalRate,
                    startTime = finalState.timerStartTime,
                    endTime = finalState.timerEndTime,
                    durationMinutes = durationMinutes,
                    tripCount = tripCount,
                    distanceKm = if (finalState.selectedPricingMode == PricingMode.DISTANCE ||
                        finalState.selectedPricingMode == PricingMode.TRIP_AND_DISTANCE)
                        finalState.distanceKm.toDoubleOrNull() else null,
                    totalAmount = finalTotal,
                    customerId = finalState.selectedCustomer?.customerId,
                    loadType = finalState.loadType.takeIf { it.isNotBlank() },
                    fieldName = finalState.fieldName.takeIf { it.isNotBlank() },
                    notes = finalState.notes.takeIf { it.isNotBlank() },
                    segmentsJson = if (finalState.segments.isNotEmpty())
                        SegmentSerializer.toJson(finalState.segments) else null
                )

                jobRepository.saveJob(job)

                // PART 1: Mark as saved to prevent duplicate saves
                hasSavedCurrentJob = true

                // Save field name for future suggestions (avoid duplicates)
                val cId = finalState.selectedCustomer?.customerId
                val fName = finalState.fieldName.trim()
                if (cId != null && fName.isNotBlank()) {
                    if (customerFieldDao.fieldExists(cId, fName) == 0) {
                        customerFieldDao.insert(CustomerFieldEntity(customerId = cId, fieldName = fName))
                    }
                }

                // Save rate as default for this machine+mode combo
                ratePreferences.saveDefaultRate(finalState.selectedMachineType, finalState.selectedPricingMode, rate)

                // PART 8: Save work pattern for passive system intelligence
                finalState.selectedJobCapability?.let { cap ->
                    workPatternPreferences.saveLastPattern(
                        capability = cap.name,
                        capabilityDisplayName = cap.displayName,
                        capabilityEmoji = cap.emoji,
                        machineId = finalState.selectedMachine?.machineId,
                        machineName = finalState.selectedMachine?.name,
                        rate = rate,
                        billingMode = finalState.effectiveBillingMode.name
                    )
                    workPatternPreferences.incrementCapabilityUsage(cap.name)

                    // PART 5: Track billing mode usage per capability for recommendations
                    workPatternPreferences.trackBillingModeForCapability(
                        capability = cap.name,
                        billingMode = finalState.effectiveBillingMode.name
                    )
                }

                // PART 4: Save area unit preference if used
                if (finalState.selectedPricingMode == PricingMode.PER_ACRE) {
                    workPatternPreferences.saveLastAreaUnit(finalState.selectedAreaUnit.name)
                    workPatternPreferences.incrementAreaUnitUsage(finalState.selectedAreaUnit.name)
                }

                // PART 4: Save transport memory for hybrid billing modes
                if (finalState.selectedPricingMode == PricingMode.PACKET_DISTANCE) {
                    val distRate = finalState.distanceRate.toDoubleOrNull() ?: 0.0
                    val dist = finalState.distanceKm.toDoubleOrNull() ?: 0.0
                    if (distRate > 0 || dist > 0 || finalState.loadType.isNotBlank()) {
                        workPatternPreferences.saveTransportMemory(
                            distanceRate = distRate,
                            lastDistance = dist,
                            loadType = finalState.loadType.takeIf { it.isNotBlank() }
                        )
                    }
                }

                // Update lastUsedAt on save (most accurate — job was actually completed)
                finalState.selectedCustomer?.let {
                    customerRepository.updateLastUsedAt(it.customerId)
                }

                clearActiveJob()

                // PART 1: Remove from active_jobs table and transition
                val savedJobId = currentJobId
                if (savedJobId != null) {
                    activeJobsRepository.removeJob(savedJobId)
                }

                // PART 6: Compute continuity context for completion sheet
                val custPendingAmount = finalState.selectedCustomer?.let { cust ->
                    try { jobRepository.getCustomerUnpaidAmountOnce(cust.customerId) } catch (_: Exception) { 0.0 }
                } ?: 0.0
                val machineActiveLabel = finalState.selectedMachine?.let { machine ->
                    try {
                        val remaining = activeJobsRepository.getAllActiveJobsOnce()
                            .filter { it.machineId == machine.machineId && it.jobId != savedJobId }
                        if (remaining.isNotEmpty()) "${machine.name} still active in another work" else null
                    } catch (_: Exception) { null }
                }

                _uiState.update {
                    it.copy(
                        isSaving = false,
                        saveSuccess = true,
                        saveAnimationState = SaveAnimationState.SUCCESS,
                        jobPhase = JobPhase.SAVED,
                        completionSummary = WorkCompletionSummary(
                            customerName = finalState.selectedCustomer?.name,
                            customerId = finalState.selectedCustomer?.customerId,
                            workType = finalState.selectedJobCapability?.displayName ?: "Work",
                            workEmoji = finalState.selectedJobCapability?.emoji ?: "",
                            machineName = finalState.selectedMachine?.name,
                            billingMode = finalState.selectedPricingMode.displayName,
                            elapsedFormatted = finalState.elapsedTimeFormatted,
                            tripCount = finalState.tripCount,
                            rate = finalState.rateInput.toDoubleOrNull() ?: 0.0,
                            total = finalTotal,
                            completedAt = System.currentTimeMillis(),
                            jobIds = listOfNotNull(currentJobId),
                            customerPendingAmount = custPendingAmount,
                            machineOtherActiveLabel = machineActiveLabel
                        )
                    )
                }
                // Hold success state briefly for visual closure
                delay(800)
                _uiState.update { it.copy(saveAnimationState = SaveAnimationState.IDLE) }

                // PART 1: NO auto-navigation — completion sheet is the final state.
                // User explicitly decides: Done / Continue / Start Another.
                // Just mark saved and stop timer.
                hasSavedCurrentJob = true
                timerJob?.cancel()
                timerJob = null

                // CANONICAL: Emit work completed event
                currentJobId?.let { jobId ->
                    WorkEventBus.emit(WorkEvent.WorkCompleted(
                        jobId = jobId,
                        totalAmount = finalTotal,
                        durationSeconds = finalState.elapsedSeconds.takeIf { it > 0 },
                        tripCount = finalState.tripCount.takeIf { it > 0 },
                        customerId = finalState.selectedCustomer?.customerId
                    ))
                }

                // CANONICAL PART 12: Invariant check after save
                verifyInvariants()
            } catch (e: Exception) {
                // PART 8: Save failure recovery — NEVER discard work
                // Keep all state intact, allow retry. Timer continues if was running.
                _uiState.update {
                    it.copy(
                        isSaving = false,
                        errorMessage = "Couldn't finish just now — tap Finish to try again. Your work is safe.",
                        saveAnimationState = SaveAnimationState.IDLE,
                        jobPhase = JobPhase.STOPPED  // Return to reviewable state
                    )
                }
                // Do NOT set hasSavedCurrentJob — allow retry
            }
        }
    }

    fun clearError() {
        _uiState.update { it.copy(errorMessage = null) }
    }

