    // ══════ PART 9: Collision Prevention ══════
    /** Check for duplicate active work (same customer + machine + capability) */
    private fun checkForDuplicateWork() {
        val state = _uiState.value
        val customerId = state.selectedCustomer?.customerId ?: return
        val machineId = state.selectedMachine?.machineId
        val capability = state.selectedJobCapability?.name

        val activeList = activeJobs.value
        val duplicate = activeList.any { job ->
            job.jobId != currentJobId &&
                job.customerId == customerId &&
                (machineId == null || job.machineId == machineId) &&
                (capability == null || job.jobCapability == capability)
        }
        _uiState.update {
            it.copy(
                duplicateWorkWarning = if (duplicate)
                    "Similar work already active for this customer"
                else null
            )
        }
    }

    fun dismissDuplicateWarning() {
        _uiState.update { it.copy(duplicateWorkWarning = null, showDuplicateConfirmDialog = false) }
    }

    fun confirmDuplicateWork() {
        _uiState.update { it.copy(showDuplicateConfirmDialog = false, duplicateWorkWarning = null) }
    }

    fun showDiscardDialog() { _uiState.update { it.copy(showDiscardDialog = true) } }
    fun hideDiscardDialog() { _uiState.update { it.copy(showDiscardDialog = false) } }
    fun dismissLongRunningWarning() { _uiState.update { it.copy(showLongRunningWarning = false) } }

    /**
     * ZERO-FRICTION PART 3: Repeat Last Setup — instantly restore previous work config.
     * Restores: customer, work type, machine, billing, rate.
     * Skips all selectors. Useful for transport loops and repeated harvesting rounds.
     */
    fun repeatLastSetup() {
        // Delegate to existing repeatSameWork which already does this
        repeatSameWork()
    }

    /**
     * ZERO-FRICTION PART 4: Quick Machine Swap — change machine without full draft recreation.
     * If no meaningful work exists, swap instantly. Otherwise show existing confirmation.
     */
    fun quickMachineSwap(machine: MachineEntity) {
        if (_uiState.value.hasMeaningfulWork) {
            // Existing reset confirmation flow
            selectMachine(machine)
        } else {
            // No meaningful work — instant swap, no dialog
            isProcessingMachineSwitch = true
            _uiState.update {
                it.copy(
                    selectedMachine = machine,
                    selectedMachineType = runCatching { MachineType.valueOf(machine.type) }.getOrDefault(MachineType.TRACTOR),
                    machineError = null,
                    machineCompatibilityWarning = null,
                    infoMessage = " Switched to ${machine.name}"
                )
            }
            // Update active job if exists
            if (currentJobId != null) {
                saveCurrentJobDebounced()
            }
            isProcessingMachineSwitch = false
        }
    }

