    /**
     * PART 8: Fast repeat — preserve customer AND last work type.
     * Auto-opens machine picker state so user can start immediately.
     * Minimum taps during repetitive workdays.
     */
    fun startAnotherWorkFast() {
        timerJob?.cancel()
        userEditedRate = false
        hasSavedCurrentJob = false
        val prev = _uiState.value
        val lastCapability = prev.selectedJobCapability
        clearActiveJob()
        currentJobId = null

        _uiState.value = NewJobUiState(
            isTemplateFlow = false,
            isDraftMode = true,
            availableCustomers = prev.availableCustomers,
            recentCustomers = prev.recentCustomers,
            machines = prev.machines,
            recentMachineIds = prev.recentMachineIds,
            selectedCustomer = prev.selectedCustomer, // preserve customer
            selectedJobCapability = lastCapability, // preserve last work type
