    }

    /**
     * PART 2: Repeat exact same work — preserves customer, work type, machine, rate.
     * Only clears timer/trips. Maximum speed for repetitive cycles (transport, harvesting).
     * Single-tap from completion sheet creates a ready-to-start draft.
     */
    fun repeatSameWork() {
        timerJob?.cancel()
        userEditedRate = false
        hasSavedCurrentJob = false
        val prev = _uiState.value
        val lastCapability = prev.selectedJobCapability
        val lastMachine = prev.selectedMachine
        val lastRate = prev.rateInput
        val lastCustomer = prev.selectedCustomer
        val lastBillingMode = prev.selectedBillingMode
        val lastMachineType = prev.selectedMachineType
        val lastPricingMode = prev.selectedPricingMode
        clearActiveJob()
        currentJobId = null

        _uiState.value = NewJobUiState(
            isTemplateFlow = false,
            isDraftMode = true,
            availableCustomers = prev.availableCustomers,
            recentCustomers = prev.recentCustomers,
            machines = prev.machines,
            recentMachineIds = prev.recentMachineIds,
            selectedCustomer = lastCustomer,
            selectedJobCapability = lastCapability,
            selectedMachine = lastMachine,
            selectedMachineType = lastMachineType,
            selectedPricingMode = lastPricingMode,
            selectedBillingMode = lastBillingMode,
            rateInput = lastRate,
            currentJobId = null
        )

        // Apply capability
        if (lastCapability != null) {
            applyJobCapability(lastCapability)
        }

        val machineName = lastMachine?.name ?: ""
        val workName = lastCapability?.displayName ?: "work"
        _uiState.update { it.copy(
            rateInput = lastRate, // re-apply after applyJobCapability may have overridden
            infoMessage = " Ready to repeat $workName${if (machineName.isNotBlank()) " • $machineName" else ""}"
        ) }
    }

    override fun onCleared() {
        super.onCleared()
        timerJob?.cancel()
        autoSaveMultiJob?.cancel()

        // OPERATIONAL HARDENING: Auto-clean empty jobs — if user leaves without
        // doing meaningful work, silently remove the entry from active_jobs.
        // Uses a dedicated coroutine scope to avoid runBlocking deadlock on main thread.
        val jobId = currentJobId
        val state = _uiState.value
        if (jobId != null && !hasSavedCurrentJob) {
            val hasWork = state.segments.isNotEmpty() || state.tripCount > 0 ||
                state.isTimerRunning || state.isTimerPaused || state.timerStartTime != null
            if (!hasWork) {
                // Use a non-blocking approach — fire-and-forget on IO dispatcher
                @Suppress("OPT_IN_USAGE")
                kotlinx.coroutines.GlobalScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                    try { activeJobsRepository.removeJob(jobId) } catch (_: Exception) {}
                }
            }
        }
    }

    // ================== Multi-Job Methods (PARTS 2-14) ==================

    /**
     * PART 2: Load the most recent active job on startup.
     * Called from init after other initialization.
     */
    private fun loadActiveJobsOnStart() {
        viewModelScope.launch {
            val jobs = activeJobsRepository.getAllActiveJobsOnce()
            val now = System.currentTimeMillis()

            // PART 9+10: Enhanced cleanup — remove phantom jobs AND stale orphans
            val validJobs = jobs.filter { it.hasWork }
            val phantomJobs = jobs.filter { !it.hasWork && (now - it.createdAt) > 60_000 }
            phantomJobs.forEach { activeJobsRepository.removeJob(it.jobId) }

            // PART 10: Remove very old orphans — jobs with no machine AND no rate AND no segments,
            // older than 4 hours. These are abandoned setup attempts.
            val fourHoursMs = 4L * 60 * 60 * 1000
            val orphanJobs = jobs.filter { job ->
                job.hasWork &&  // survived phantom check but...
                    job.machineId == null &&
                    job.rate == 0.0 &&
                    job.trips == 0 &&
                    job.segmentsJson.isNullOrBlank() &&
                    !job.isPaused && !job.isStopped &&
                    (now - job.lastUpdatedAt) > fourHoursMs
            }
            orphanJobs.forEach { activeJobsRepository.removeJob(it.jobId) }

            if (validJobs.isNotEmpty()) {
                // Load most recent valid job
                val mostRecent = validJobs.first()
                currentJobId = mostRecent.jobId
                _uiState.update { it.copy(currentJobId = mostRecent.jobId, isDraftMode = false) }
                restoreFromActiveJobsEntity(mostRecent)
            }
        }
    }

    /**
     * Open a specific workspace job by ID.
     * Used when user explicitly taps a workspace pill, job row, or active tab.
     * Does NOT save current state (since this is a fresh VM for workspace route).
     */
    fun openWorkspaceJob(jobId: String) {
        viewModelScope.launch {
            val job = activeJobsRepository.getJobById(jobId)
            if (job != null) {
                currentJobId = jobId
                _uiState.update { it.copy(currentJobId = jobId, isDraftMode = false) }
                restoreFromActiveJobsEntity(job)

                // PART 6: Recovery authority — use RecoveryReplayScenario
                val lastUpdate = job.lastUpdatedAt
                val staleDuration = if (lastUpdate > 0) System.currentTimeMillis() - lastUpdate else 0L
                val isTimeMode = job.pricingMode == PricingMode.TIME
                val wasRunning = isTimeMode && !job.isPaused && !job.isStopped && job.startTime > 0

                val recoveryContext = com.example.fieldtrack.domain.recovery.RecoveryContext(
                    staleDurationMs = staleDuration,
                    hadActiveTimer = wasRunning,
                    wasPaused = job.isPaused,
                    hadPendingSave = false,
                    hasMeaningfulWork = job.trips > 0 || (isTimeMode && job.startTime > 0),
                    saveAlreadyCompleted = job.isStopped,
                    workSummary = job.jobCapability?.let { JobCapability.fromName(it)?.displayName } ?: "Work",
                    lastPhase = when {
                        job.isStopped -> JobPhase.STOPPED
                        job.isPaused -> JobPhase.PAUSED
                        wasRunning -> JobPhase.RUNNING
                        else -> JobPhase.SETUP
                    }
                )
                val recoveryAction = com.example.fieldtrack.domain.recovery.RecoveryReplayScenario.classify(recoveryContext)

                when (recoveryAction) {
                    is com.example.fieldtrack.domain.recovery.RecoveryAction.OfferRecoveryOrDiscard -> {
                        _uiState.update {
                            it.copy(showStaleBanner = true, staleBannerText = recoveryAction.reason)
                        }
                    }
                    is com.example.fieldtrack.domain.recovery.RecoveryAction.OfferResumeWithDriftWarning -> {
                        _uiState.update { it.copy(showRecoveredBanner = true) }
                    }
                    is com.example.fieldtrack.domain.recovery.RecoveryAction.SilentResume -> {
                        // Silent resume — no banner needed
                    }
                    else -> { /* SilentDiscard, RetrySave — handled elsewhere */ }
                }

                // Emit recovery event if timer was active
                if (wasRunning) {
                    WorkEventBus.emit(WorkEvent.RecoveryOccurred(
                        jobId = jobId,
                        recoveryType = com.example.fieldtrack.domain.event.RecoveryType.PROCESS_DEATH_RESTORE,
                        estimatedDataLossMs = staleDuration
                    ))
                    // Auto-dismiss recovery banner
                    launch {
                        delay(4000)
                        _uiState.update { it.copy(showRecoveredBanner = false) }
                    }
                }

                android.util.Log.d("NewJobVM", "WORKSPACE RESTORED: $jobId — ${job.machineName ?: "unknown"}")
            } else {
                // Job not found — fallback to loading most recent
                android.util.Log.w("NewJobVM", "Workspace job not found: $jobId, falling back")
                loadActiveJobsOnStart()
            }
        }
    }

    /**
     * PART 3: Switch to a different active job instantly.
     * Saves current state, loads new job, restores UI. No dialogs.
     */
    fun switchToJob(jobId: String) {
        if (currentJobId == jobId) return
        val fromJobId = currentJobId
        hasSavedCurrentJob = false

        viewModelScope.launch {
            // 1. Save current job silently — no status message needed for instant operation
            saveCurrentJobToMultiTable()

            // 2. Stop current timer
            timerJob?.cancel()
            timerJob = null

            // 3. Load new job
            val newJob = activeJobsRepository.getJobById(jobId) ?: return@launch

            // 4. Restore UI state
            restoreFromActiveJobsEntity(newJob)

            // 5. Set current job ID
            currentJobId = jobId
            _uiState.update { it.copy(currentJobId = jobId, infoMessage = null) }

            // CANONICAL: Emit workspace switched event
            WorkEventBus.emit(WorkEvent.WorkspaceSwitched(
                jobId = jobId,
                fromJobId = fromJobId
            ))

            // PART 11: Verify invariants after workspace switch
            verifyInvariants()
        }
    }

    /** Switch to next job of SAME customer (swipe left) — no cross-farmer swipe */
    fun switchToNextJob() {
        val currentCustomerId = _uiState.value.selectedCustomer?.customerId
        val jobs = activeJobs.value.filter {
            currentCustomerId == null || it.customerId == currentCustomerId
        }
        if (jobs.size <= 1) return
        val currentIndex = jobs.indexOfFirst { it.jobId == currentJobId }
        val nextIndex = if (currentIndex < 0 || currentIndex >= jobs.size - 1) 0 else currentIndex + 1
        switchToJob(jobs[nextIndex].jobId)
    }

    /** Switch to previous job of SAME customer (swipe right) — no cross-farmer swipe */
    fun switchToPreviousJob() {
        val currentCustomerId = _uiState.value.selectedCustomer?.customerId
        val jobs = activeJobs.value.filter {
            currentCustomerId == null || it.customerId == currentCustomerId
        }
        if (jobs.size <= 1) return
        val currentIndex = jobs.indexOfFirst { it.jobId == currentJobId }
        val prevIndex = if (currentIndex <= 0) jobs.size - 1 else currentIndex - 1
        switchToJob(jobs[prevIndex].jobId)
    }

    /**
     * PART 4: Start a new job with a selected capability.
     * Saves current job, resets UI for new work type.
     * Does NOT create DB entry — that happens on first real work (ensureActiveJobCreated).
     */
    fun startNewJob(capability: JobCapability) {
        viewModelScope.launch {
            // 1. Save current job if exists
            if (currentJobId != null) {
                saveCurrentJobToMultiTable()
            }

            // 2. Stop current timer
            timerJob?.cancel()
            timerJob = null

            // 3. Reset UI state (no DB entry yet — lifecycle deferred to work start)
            val prev = _uiState.value
            userEditedRate = false
            currentJobId = null

            _uiState.value = NewJobUiState(
                isTemplateFlow = false,
                isDraftMode = false,
                availableCustomers = prev.availableCustomers,
                recentCustomers = prev.recentCustomers,
                machines = prev.machines,
                selectedCustomer = prev.selectedCustomer, // keep customer
                currentJobId = null
            )

            // 4. Apply capability (just updates UI, no persistence)
            applyJobCapability(capability)
        }
    }

    /**
     * Start another work for the SAME customer.
     * Preserves customer selection, resets everything else to a fresh draft.
     * Does NOT affect existing active jobs.
     */
    fun startAnotherWork() {
        viewModelScope.launch {
            // 1. Save current job if exists
            if (currentJobId != null) {
                saveCurrentJobToMultiTable()
            }

            // 2. Stop current timer
            timerJob?.cancel()
            timerJob = null

            // 3. Reset to fresh draft but keep customer
            val prev = _uiState.value
            val keepCustomer = prev.selectedCustomer
            userEditedRate = false
            currentJobId = null

            _uiState.value = NewJobUiState(
                isTemplateFlow = false,
                isDraftMode = true,
                availableCustomers = prev.availableCustomers,
                recentCustomers = prev.recentCustomers,
                machines = prev.machines,
                recentMachineIds = prev.recentMachineIds,
                selectedCustomer = keepCustomer, // preserve customer context
                currentJobId = null
            )

            val customerLabel = keepCustomer?.name ?: "same farmer"
            _uiState.update { it.copy(infoMessage = " New work for $customerLabel") }
            // Auto-fill rate so Start Work button becomes visible
            autoFillRate()
        }
    }

    /**
     * PART 10: Finish the current job — save to final table, remove from active jobs.
     */
    fun finishCurrentJob() {
        val jobId = currentJobId ?: return
        viewModelScope.launch {
            // 1. Save to final Job table
            val success = saveJobInternal()

            if (success) {
                // 2. Remove from active jobs
                activeJobsRepository.removeJob(jobId)

                // 3. Clear legacy active job
                clearActiveJob()

                // 4. Switch to another job in SAME workspace first, then any remaining job
                val remainingJobs = activeJobsRepository.getAllActiveJobsOnce()
                    .filter { it.hasWork }
                val currentCustomerId = _uiState.value.selectedCustomer?.customerId
                // Prefer same-customer workspace for continuity
                val sameWorkspaceJob = if (!currentCustomerId.isNullOrBlank()) {
                    remainingJobs.firstOrNull { it.customerId == currentCustomerId }
                } else null
                val nextJob = sameWorkspaceJob ?: remainingJobs.firstOrNull()

                if (nextJob != null) {
                    currentJobId = nextJob.jobId
                    _uiState.update { it.copy(currentJobId = nextJob.jobId, isDraftMode = false) }
                    restoreFromActiveJobsEntity(nextJob)
                    val cap = nextJob.getJobCapability()
                    val label = cap?.let { "${it.emoji} ${it.displayName}" } ?: "next job"
                    _uiState.update { it.copy(infoMessage = "✔ Job completed — switched to $label") }
                } else {
                    // Reset to empty draft state
                    currentJobId = null
                    val prev = _uiState.value
                    _uiState.value = NewJobUiState(
                        isTemplateFlow = isTemplateFlow,
                        isDraftMode = true,
                        availableCustomers = prev.availableCustomers,
                        recentCustomers = prev.recentCustomers,
                        machines = prev.machines,
                        currentJobId = null
                    )
                    _uiState.update { it.copy(infoMessage = "Job completed ✓") }
                }
            }
        }
    }

    /**
     * PART 9: Save current job to multi-job table (debounced).
     * Called on segment add, timer tick, trip add, machine selection.
     */
    fun saveCurrentJobDebounced() {
        if (currentJobId == null) return // Guard: no job started yet
        autoSaveMultiJob?.cancel()
        autoSaveMultiJob = viewModelScope.launch {
            delay(400) // debounce 400ms
            saveCurrentJobToMultiTable()
        }
    }

    /**
     * Save current UI state to the multi-job active_jobs table.
     */
    private suspend fun saveCurrentJobToMultiTable() = saveMutex.withLock {
        val jobId = currentJobId ?: return@withLock
        val state = _uiState.value

        // OPERATIONAL HARDENING: Don't persist in terminal states
        if (state.jobPhase == JobPhase.SAVED || state.jobPhase == JobPhase.SAVING) return@withLock

        persistVersion++

        val entity = ActiveJobsEntity(
            jobId = jobId,
            customerId = state.selectedCustomer?.customerId ?: "",
            customerName = state.selectedCustomer?.name,
            machineId = state.selectedMachine?.machineId,
            machineName = state.selectedMachine?.name,
            machineType = state.selectedMachineType,
            pricingMode = state.selectedPricingMode,
            rate = state.rateInput.toDoubleOrNull() ?: 0.0,
            startTime = state.timerStartTime ?: 0L,
            trips = state.tripCount,
            distance = state.distanceKm.toDoubleOrNull() ?: 0.0,
            fieldName = state.fieldName.takeIf { it.isNotBlank() },
            loadType = state.loadType.takeIf { it.isNotBlank() },
            notes = state.notes.takeIf { it.isNotBlank() },
            isRateEdited = userEditedRate,
            isPaused = state.isTimerPaused,
            pauseStartTime = state.pauseStartTime,
            totalPausedDuration = state.totalPausedDuration,
            isStopped = state.timerEndTime != null && !state.isTimerRunning && !state.isTimerPaused,
            endTime = state.timerEndTime,
            segmentsJson = if (state.segments.isNotEmpty())
                SegmentSerializer.toJson(state.segments) else null,
            jobCapability = state.selectedJobCapability?.name,
            lastUpdatedAt = System.currentTimeMillis(),
            snapshotVersion = persistVersion
        )
        activeJobsRepository.saveJob(entity)
    }

    /**
     * PART 11: Restore UI state from an ActiveJobsEntity.
     * Timer isolation: only resumes timer if the loaded job was running.
     */
    private fun restoreFromActiveJobsEntity(job: ActiveJobsEntity) {
        // Stop any current timer first (PART 11: timer isolation)
        timerJob?.cancel()
        timerJob = null

        val now = System.currentTimeMillis()
        val isTimeMode = job.pricingMode == PricingMode.TIME

        val elapsed: Long
        val isRunning: Boolean
        val isPaused: Boolean
        val isComplete: Boolean

        when {
            job.isStopped -> {
                val endT = job.endTime ?: now
                elapsed = ((endT - job.startTime) - job.totalPausedDuration) / 1000
                isRunning = false
                isPaused = false
                isComplete = true
            }
            job.isPaused -> {
                val pauseT = job.pauseStartTime ?: now
                elapsed = ((pauseT - job.startTime) - job.totalPausedDuration) / 1000
                isRunning = false
                isPaused = true
                isComplete = false
            }
            else -> {
                elapsed = if (isTimeMode) {
                    ((now - job.startTime) - job.totalPausedDuration) / 1000
                } else 0
                isRunning = isTimeMode && job.startTime > 0 && !job.isStopped
                isPaused = false
                isComplete = !isTimeMode && job.trips > 0
            }
        }

        val segments = if (!job.segmentsJson.isNullOrBlank())
            SegmentSerializer.fromJson(job.segmentsJson) else emptyList()

        // Derive pricing mode from capability if available (ensures rate label matches billing label)
        val restoredCapability = job.getJobCapability()
        val restoredPricingMode = if (restoredCapability != null) {
            val usageType = BillingModeResolver.inferUsageType(restoredCapability)
            val usageContext = MachineUsageContext(jobCapability = restoredCapability, usageType = usageType)
            val billingMode = BillingModeResolver.resolveBillingMode(usageContext)
            when (billingMode) {
                BillingMode.PER_MINUTE -> PricingMode.TIME
                BillingMode.PER_HOUR -> PricingMode.TIME
                BillingMode.PER_TRIP -> PricingMode.TRIP
                BillingMode.PER_PACKET -> PricingMode.PACKET
                BillingMode.PER_PACKET_DISTANCE -> PricingMode.PACKET_DISTANCE
                BillingMode.PER_ACRE -> PricingMode.PER_ACRE
                BillingMode.FIXED_AMOUNT -> PricingMode.FIXED_AMOUNT
            }
        } else {
            job.pricingMode
        }

        _uiState.update {
            it.copy(
                currentJobId = job.jobId,
                isDraftMode = false,
                selectedMachineType = job.machineType,
                selectedPricingMode = restoredPricingMode,
                rateInput = if (job.rate > 0) {
                    if (job.rate == job.rate.toLong().toDouble())
                        job.rate.toLong().toString()
                    else job.rate.toString()
                } else "",
                timerStartTime = if (isTimeMode) job.startTime else null,
                timerEndTime = if (job.isStopped) job.endTime else null,
                isTimerRunning = isRunning,
                isTimerPaused = isPaused,
                pauseStartTime = job.pauseStartTime,
                totalPausedDuration = job.totalPausedDuration,
                elapsedSeconds = elapsed.coerceAtLeast(0),
                tripCount = job.trips,
                distanceKm = if (restoredPricingMode != PricingMode.PER_ACRE && job.distance > 0) job.distance.toString() else "",
                acreQuantity = if (restoredPricingMode == PricingMode.PER_ACRE && job.distance > 0) {
                    if (job.distance == job.distance.toLong().toDouble()) job.distance.toLong().toString()
                    else job.distance.toString()
                } else "",
                fieldName = job.fieldName ?: "",
                loadType = job.loadType ?: "",
                notes = job.notes ?: "",
                isJobComplete = isComplete,
                segments = segments,
                currentRate = job.rate,
                selectedJobCapability = job.getJobCapability(),
                isBillingOverridden = false,
                selectedBillingMode = null
            )
        }

        // Resume timer if was running (PART 11)
        if (isRunning) {
            userEditedRate = job.isRateEdited
            startTickingCoroutine()
        }

        // Resolve machine entity
        val currentMachines = _uiState.value.machines
        if (job.machineId != null && currentMachines.isNotEmpty()) {
            val matchingMachine = currentMachines.firstOrNull { it.machineId == job.machineId }
            matchingMachine?.let {
                _uiState.update { state -> state.copy(selectedMachine = matchingMachine) }
            }
        } else {
            _uiState.update { it.copy(selectedMachine = null) }
        }

        // Resolve customer
        if (job.customerId.isNotBlank()) {
            viewModelScope.launch {
                val customer = customerRepository.getCustomerById(job.customerId)
                customer?.let { selectCustomer(it) }
            }
        }

        recalculateTotal()

        // PART 11: Verify invariants after restore
        verifyInvariants()
    }

    /**
     * Convert an ActiveJobsEntity to an ActiveJobSummary for UI display.
     */
    private fun ActiveJobsEntity.toSummary(): ActiveJobSummary {
        val cap = getJobCapability()
        val now = System.currentTimeMillis()
        val isTimeMode = pricingMode == PricingMode.TIME

        val elapsed = when {
            isStopped -> {
                val endT = endTime ?: now
                ((endT - startTime) - totalPausedDuration) / 1000
            }
            isPaused -> {
                val pauseT = pauseStartTime ?: now
                ((pauseT - startTime) - totalPausedDuration) / 1000
            }
            isTimeMode && startTime > 0 -> {
                ((now - startTime) - totalPausedDuration) / 1000
            }
            else -> 0L
        }.coerceAtLeast(0)

        val running = isTimeMode && !isPaused && !isStopped && startTime > 0
        // CANONICAL: Unified status vocabulary via lifecycle mapper
        val statusLabel = when {
            running -> "${OperationalLifecycleMapper.stateEmoji(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.ACTIVE)} ${OperationalLifecycleMapper.uiLabel(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.ACTIVE)}"
            isPaused -> "${OperationalLifecycleMapper.stateEmoji(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.PAUSED)} ${OperationalLifecycleMapper.uiLabel(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.PAUSED)}"
            trips > 0 -> "$trips load${if (trips != 1) "s" else ""}"
            isStopped -> "✔ ${OperationalLifecycleMapper.uiLabel(com.example.fieldtrack.domain.session.WorkspaceLifecycleState.COMPLETED)}"
            else -> "Ready"
        }

        return ActiveJobSummary(
            jobId = jobId,
            machineName = machineName,
            customerName = customerName,
            jobCapability = cap,
            elapsedSeconds = elapsed,
            tripCount = trips,
            isRunning = running,
            isPaused = isPaused,
            emoji = cap?.emoji ?: "",
            displayName = buildString {
                append(cap?.displayName ?: "Job")
                // Add machine name for differentiation (PART 8: machine = primary differentiator)
                if (machineName != null) {
                    append(" • ")
                    append(machineName)
                }
            },
            statusLabel = statusLabel
        )
    }

    // ================== Billing Override Sheet ==================

    /** PART 9 STEP 5: Show billing override bottom sheet. */
    fun showBillingOverrideSheet() {
        val state = _uiState.value
        // Block billing mode changes while job is actively running or paused
        if (state.isTimerRunning || state.isTimerPaused) {
            _uiState.update { it.copy(infoMessage = "Stop the timer before changing billing mode") }
            return
        }
        _uiState.update { it.copy(showBillingOverrideSheet = true) }
    }

    /** PART 9: Dismiss billing override sheet. */
    fun dismissBillingOverrideSheet() {
        _uiState.update { it.copy(showBillingOverrideSheet = false) }
    }

    // ================== State Validation ==================

    /**
     * OPERATIONAL HARDENING: Remove stale active jobs on startup.
     * Prevents ghost machine locks from jobs abandoned after process death.
     * Items older than STALE_JOB_THRESHOLD_MS (8h) with no ongoing work = safe to remove.
     */
    private fun cleanupStaleJobs() {
        viewModelScope.launch {
            try {
                val jobs = activeJobsRepository.getAllActiveJobsOnce()
                val now = System.currentTimeMillis()
                val staleJobs = jobs.filter { job ->
                    val age = now - job.lastUpdatedAt
                    age > JobConstants.STALE_JOB_THRESHOLD_MS &&
                        !job.isPaused && !job.isStopped &&  // Don't remove paused/stopped — user may return
                        job.segmentsJson.isNullOrBlank() &&  // No completed segments
                        job.trips == 0  // No trips counted
                }
                staleJobs.forEach { job ->
                    android.util.Log.d("NewJobVM", "STALE CLEANUP: Removing ${job.jobId} (age ${(now - job.lastUpdatedAt) / 3600000}h)")
                    activeJobsRepository.removeJob(job.jobId)
                }
            } catch (_: Exception) {
                // Non-critical — silent failure on cleanup
            }
        }
    }

    /**
     * PART 6: Revalidate machine compatibility after billing mode change.
     * If machine becomes incompatible, remove it and show info message.
     */
    private fun validateMachineAfterBillingChange() {
        val state = _uiState.value
        val machine = state.selectedMachine ?: return
        val capability = state.selectedJobCapability ?: return

        val isCompatible = MachineCapabilityMatcher.isMachineCompatible(machine, capability)
        if (!isCompatible) {
            _uiState.update {
                it.copy(
                    selectedMachine = null,
                    machineCompatibilityWarning = null,
                    infoMessage = "Previous machine not suitable for this work"
                )
            }
        }
    }

    /**
     * PART 10: Defensive state validator.
     * Called after every major state mutation to ensure invariants hold.
     * Self-heals invalid states and logs warnings.
     */
    private fun validateState(state: NewJobUiState) {
        // Invariant 1: Dialog open without pendingBillingMode → auto dismiss
        if (state.showBillingModeChangeDialog && state.pendingBillingMode == null) {
            _uiState.update {
                it.copy(
                    showBillingModeChangeDialog = false,
                    pendingBillingMode = null
                )
            }
            android.util.Log.w("NewJobVM", "Invalid state: billing dialog without pending mode — auto dismissed")
        }

        // Invariant 2: Timer should not be running if timerStartTime is null
        if (state.isTimerRunning && state.timerStartTime == null) {
            timerJob?.cancel()
            _uiState.update {
                it.copy(
                    isTimerRunning = false,
                    isTimerPaused = false,
                    liveCost = 0.0
                )
            }
            android.util.Log.w("NewJobVM", "Invalid state: timer running without startTime — stopped")
        }

        // OPERATIONAL HARDENING — Invariant 3: Running AND paused simultaneously = impossible
        if (state.isTimerRunning && state.isTimerPaused) {
            _uiState.update { it.copy(isTimerPaused = false) }
            android.util.Log.w("NewJobVM", "Invalid state: timer both running and paused — forced to running")
        }

        // Invariant 4: Negative totalPausedDuration = data corruption — clamp to 0
        if (state.totalPausedDuration < 0) {
            _uiState.update { it.copy(totalPausedDuration = 0) }
            android.util.Log.w("NewJobVM", "Invalid state: negative totalPausedDuration — clamped to 0")
        }

        // Invariant 5: totalPausedDuration > elapsed wallclock = corruption
        if (state.timerStartTime != null && state.totalPausedDuration > 0) {
            val wallclock = System.currentTimeMillis() - state.timerStartTime
            if (state.totalPausedDuration > wallclock) {
                _uiState.update { it.copy(totalPausedDuration = 0) }
                android.util.Log.w("NewJobVM", "Invalid state: pausedDuration exceeds wallclock — reset to 0")
            }
        }
    }

    /**
     * Factory for creating NewJobViewModel with dependencies.
     */
    class Factory(
        private val jobRepository: JobRepository,
        private val customerRepository: CustomerRepository,
        private val ratePreferences: RatePreferences,
        private val customerFieldDao: CustomerFieldDao,
        private val activeJobRepository: ActiveJobRepository,
        private val machineRepository: MachineRepository,
        private val activeJobsRepository: ActiveJobsRepository,
        private val workPatternPreferences: WorkPatternPreferences,
        private val isTemplateFlow: Boolean = false,
        private val initialTemplateId: String? = null,
        private val startAsFreshDraft: Boolean = false,
        private val restoreJobId: String? = null
    ) : ViewModelProvider.Factory {
        @Suppress("UNCHECKED_CAST")
        override fun <T : ViewModel> create(modelClass: Class<T>): T {
            if (modelClass.isAssignableFrom(NewJobViewModel::class.java)) {
                return NewJobViewModel(
                    jobRepository, customerRepository, ratePreferences,
                    customerFieldDao, activeJobRepository, machineRepository,
                    activeJobsRepository, workPatternPreferences,
                    isTemplateFlow, initialTemplateId,
                    startAsFreshDraft, restoreJobId
                ) as T
            }
            throw IllegalArgumentException("Unknown ViewModel class")
        }
    }
}

/**
 * Holds data needed to undo a machine switch reset.
 * Timer state is NOT stored — undo only restores segments/trips/machine.
 */
private data class MachineSwitchUndoData(
    val previousMachine: MachineEntity?,
    val segments: List<WorkSegment>,
    val tripCount: Int
)

package com.example.fieldtrack.debug

import com.example.fieldtrack.core.config.AppEnvironment
import com.example.fieldtrack.core.identity.OperatorIdentityManager
import com.example.fieldtrack.core.logging.OperationalEventHistory
import com.example.fieldtrack.core.logging.OperationalReplayRecorder
import com.example.fieldtrack.core.persistence.MutationCoalescer
import com.example.fieldtrack.core.persistence.OperationalMutationExecutor
import com.example.fieldtrack.core.persistence.OperationalMutationJournal
import com.example.fieldtrack.core.recovery.OperationalQuarantine
import com.example.fieldtrack.core.session.OperationalSessionManager
import com.example.fieldtrack.core.sync.OperationalConnectivity
import com.example.fieldtrack.core.sync.OperationalSyncHealth
import com.example.fieldtrack.core.sync.OperationalSyncQueue
import com.example.fieldtrack.core.sync.RemoteEntityStateCache
import com.example.fieldtrack.core.sync.SyncPresenceState
import com.example.fieldtrack.core.sync.SyncQueueHealth
import com.example.fieldtrack.core.verification.InvariantSeverity
import com.example.fieldtrack.core.verification.MutationIntegrityVerifier
import com.example.fieldtrack.core.verification.OperationalInvariantReporter

/**
 * PART 9 — Debug Operation Center.
 *
 * Provides read-only debug panels for DEV/STAGING environments.
 *
 * Panels:
 * - Recent mutations
 * - Replay frames
 * - Active transactions
 * - Quarantined entries
 * - Integrity warnings
 * - Recovery actions
 * - Version conflicts
 * - Mutation throughput
 *
 * Read-only visualization only. No editing UI.
 */
object OperationalDebugCenter {

    /**
     * Complete debug snapshot — all operational state in one call.
     * Returns null in PROD.
     */
    fun snapshot(executor: OperationalMutationExecutor? = null): DebugSnapshot? {
        if (!AppEnvironment.current().isDebugLike) return null

        return DebugSnapshot(
            recentMutations = recentMutations(),
            recentReplayFrames = recentReplayFrames(),
            activeTransactions = activeTransactions(executor),
            completedTransactions = completedTransactions(executor),
            quarantinedEntries = quarantinedEntries(),
            integrityWarnings = integrityWarnings(),
            recentInvariants = recentInvariants(),
            journalStats = journalStats(),
            replayStats = replayStats(),
            activeOperator = activeOperator(),
            activeSession = activeSession(),
            recentOwnershipMutations = recentOwnershipMutations(),
            ownershipConflicts = ownershipConflicts(),
            sessionRecoveryEvents = sessionRecoveryEvents()
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Individual panels
    // ════════════════════════════════════════════════════════════════

    /** Recent mutation journal entries (coalesced for readability). */
    fun recentMutations(count: Int = 30): List<MutationDebugEntry> {
        val entries = OperationalMutationJournal.recent(count)
        val coalesced = MutationCoalescer.coalesce(entries)
        return coalesced.map { group ->
            MutationDebugEntry(
                summary = group.summary,
                operationalId = group.operationalId.take(8),
                entityType = group.entityType,
                count = group.count,
                timestamp = group.endTimestamp,
                pattern = group.pattern.name
            )
        }
    }

    /** Recent replay frames. */
    fun recentReplayFrames(count: Int = 30): List<ReplayFrameDebugEntry> {
        return OperationalReplayRecorder.recent(count).map { frame ->
            ReplayFrameDebugEntry(
                summary = frame.summary,
                operationalId = frame.operationalId.take(8),
                entityVersion = frame.entityVersion,
                mutationSource = frame.mutationSource.label,
                classification = frame.mutationClassification.name,
                eventType = frame.eventType.name,
                transactionId = frame.transactionId?.take(8),
                timestamp = frame.timestamp,
                sequenceNumber = frame.sequenceNumber
            )
        }
    }

    /** Active transactions. */
    fun activeTransactions(executor: OperationalMutationExecutor? = null): List<TransactionDebugEntry> {
        return (executor?.activeTransactions ?: emptyList()).map { tx ->
            TransactionDebugEntry(
                transactionId = tx.transactionId.take(8),
                startedAt = tx.startedAt,
                mutationCount = tx.mutationCount,
                affectedIds = tx.affectedOperationalIds.map { it.take(8) },
                isActive = true
            )
        }
    }

    /** Completed transactions (recent). */
    fun completedTransactions(executor: OperationalMutationExecutor? = null): List<TransactionDebugEntry> {
        return (executor?.completedTransactions ?: emptyList()).takeLast(20).map { tx ->
            TransactionDebugEntry(
                transactionId = tx.transactionId.take(8),
                startedAt = tx.startedAt,
                completedAt = tx.completedAt,
                mutationCount = tx.mutationCount,
                affectedIds = tx.affectedOperationalIds.map { it.take(8) },
                isActive = false
            )
        }
    }

    /** Quarantined entries. */
    fun quarantinedEntries(): List<QuarantineDebugEntry> {
        return OperationalQuarantine.entries().map { entry ->
            QuarantineDebugEntry(
                jobId = entry.jobId.take(8),
                reason = entry.reason,
                type = entry.quarantineType.name,
                detectedAt = entry.detectedAt,
                isReviewed = entry.isReviewed
            )
        }
    }

    /** Integrity warnings from latest verification run. */
    fun integrityWarnings(): IntegrityDebugSummary {
        val issues = MutationIntegrityVerifier.verify()
        return IntegrityDebugSummary(
            totalIssues = issues,
            duplicateMutations = MutationIntegrityVerifier.checkDuplicateMutationIds(),
            versionViolations = MutationIntegrityVerifier.checkVersionMonotonicity(),
            timestampInversions = MutationIntegrityVerifier.checkTimestampOrdering(),
            missingDeviceIds = MutationIntegrityVerifier.checkDeviceIds(),
            replayHealthy = OperationalReplayRecorder.isSequenceHealthy()
        )
    }

    /** Recent invariant reports. */
    fun recentInvariants(): List<InvariantDebugEntry> {
        return OperationalInvariantReporter.recentInvariants().takeLast(30).map { inv ->
            InvariantDebugEntry(
                id = inv.id,
                title = inv.title,
                severity = inv.severity.name,
                message = inv.message.take(200),
                source = inv.source,
                timestamp = inv.timestamp
            )
        }
    }

    /** Journal statistics. */
    fun journalStats(): JournalDebugStats {
        return JournalDebugStats(
            entryCount = OperationalMutationJournal.entryCount,
            currentSequence = OperationalMutationJournal.currentSequence,
            pendingSyncCount = OperationalMutationJournal.pendingSyncCount(),
            lastSummary = OperationalMutationJournal.lastSummary()
        )
    }

    /** Replay statistics. */
    fun replayStats(): ReplayDebugStats {
        return ReplayDebugStats(
            frameCount = OperationalReplayRecorder.frameCount,
            lastSequence = OperationalReplayRecorder.lastSequence,
            isHealthy = OperationalReplayRecorder.isSequenceHealthy()
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase B: Operator / Session panels
    // ════════════════════════════════════════════════════════════════

    /** Active operator info. Returns null in PROD. */
    fun activeOperator(): OperatorDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val op = OperatorIdentityManager.current()
        return OperatorDebugEntry(
            operatorId = op.operatorId.take(8),
            displayName = op.displayName,
            initials = op.initials,
            isGuest = op.isGuest,
            createdAt = op.createdAt
        )
    }

    /** Active session info. Returns null in PROD. */
    fun activeSession(): SessionDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val session = OperationalSessionManager.current() ?: return null
        return SessionDebugEntry(
            sessionId = session.sessionId.take(8),
            operatorId = session.operatorId.take(8),
            startedAt = session.startedAt,
            lastActiveAt = session.lastActiveAt,
            environment = session.environment,
            isExpired = session.isExpired,
            durationMs = session.durationMs
        )
    }

    /** Recent mutations showing operator attribution. */
    fun recentOwnershipMutations(count: Int = 20): List<OwnershipMutationDebugEntry> {
        return OperationalMutationJournal.recent(count).map { entry ->
            OwnershipMutationDebugEntry(
                summary = entry.summary,
                operationalId = entry.operationalId.take(8),
                operatorId = entry.operatorId.take(8).ifBlank { "none" },
                sessionId = entry.sessionId.take(8).ifBlank { "none" },
                timestamp = entry.timestamp
            )
        }
    }

    /** Ownership conflicts from invariant reporter. */
    fun ownershipConflicts(): List<InvariantDebugEntry> {
        return OperationalInvariantReporter.recentInvariants()
            .filter { it.id.startsWith("OWNERSHIP-") }
            .takeLast(20)
            .map { inv ->
                InvariantDebugEntry(
                    id = inv.id,
                    title = inv.title,
                    severity = inv.severity.name,
                    message = inv.message.take(200),
                    source = inv.source,
                    timestamp = inv.timestamp
                )
            }
    }

    /** Session recovery events from event history. */
    fun sessionRecoveryEvents(): List<String> {
        return OperationalEventHistory.entries()
            .filter { it.message.contains("session", ignoreCase = true) || it.message.contains("Session", ignoreCase = true) }
            .takeLast(10)
            .map { "${it.message} (${it.timestamp})" }
    }

    // ════════════════════════════════════════════════════════════════
    // Phase C1: Sync Queue panels
    // ════════════════════════════════════════════════════════════════

    /** Sync queue health. Returns null in PROD or if no queue provided. */
    suspend fun syncQueueHealth(syncQueue: OperationalSyncQueue?): SyncQueueDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val queue = syncQueue ?: return null
        val health = queue.health()
        return SyncQueueDebugEntry(
            pending = health.pending,
            inFlight = health.inFlight,
            retrying = health.retrying,
            failed = health.failed,
            conflicted = health.conflicted,
            acknowledged = health.acknowledged,
            oldestPendingAgeMs = health.oldestPendingAgeMs,
            isHealthy = health.isHealthy,
            isCritical = health.isCritical
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase C2: Consistency & ACK panels
    // ════════════════════════════════════════════════════════════════

    /** Sync health state. */
    fun syncHealthState(): SyncHealthDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        return SyncHealthDebugEntry(
            state = OperationalSyncHealth.currentState.name,
            isHealthy = OperationalSyncHealth.isHealthy,
            isCritical = OperationalSyncHealth.isCritical,
            lastEvaluatedAt = OperationalSyncHealth.lastEvaluatedAt
        )
    }

    /** Remote entity state cache info. */
    fun remoteStateInfo(cache: RemoteEntityStateCache?): RemoteStateDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val c = cache ?: return null
        val snapshot = c.snapshot()
        return RemoteStateDebugEntry(
            trackedEntities = snapshot.size,
            newestRemoteVersion = snapshot.maxByOrNull { it.lastRemoteVersion }?.lastRemoteVersion ?: 0,
            oldestRefresh = snapshot.minByOrNull { it.localRefreshAt }?.localRefreshAt ?: 0
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase C3: Transport & Presence panels
    // ════════════════════════════════════════════════════════════════

    /** Transport reliability and latency. */
    fun transportReliability(): TransportDebugInfo? {
        if (!AppEnvironment.current().isDebugLike) return null
        return TransportDebugInfo(
            connectivityState = OperationalConnectivity.state.name,
            reliabilityScore = OperationalConnectivity.reliabilityScore,
            averageLatencyMs = OperationalConnectivity.averageLatencyMs,
            syncPresence = SyncPresenceState.current.name,
            ackLastSequence = com.example.fieldtrack.core.sync.AcknowledgementPersistence.lastAckedSequence,
            ackTotalCount = com.example.fieldtrack.core.sync.AcknowledgementPersistence.totalAcknowledged,
            ackGaps = com.example.fieldtrack.core.sync.AcknowledgementPersistence.continuityGaps
        )
    }

    /** Device presence summary. */
    fun devicePresenceSummary(): DevicePresenceDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val devices = com.example.fieldtrack.core.presence.DevicePresenceRegistry.all()
        return DevicePresenceDebugEntry(
            knownDevices = devices.size,
            recentlyActive = devices.count { it.isRecentlyActive },
            staleDevices = devices.count { it.isStale }
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase D1: Financial debug panels
    // ════════════════════════════════════════════════════════════════

    /** Financial event summary. */
    suspend fun financialSummary(dao: com.example.fieldtrack.data.local.dao.FinancialEventDao?): FinancialDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val d = dao ?: return null
        val count = d.count()
        val recent = d.getRecentEvents(10)
        return FinancialDebugEntry(
            totalEvents = count,
            recentEventCount = recent.size,
            lastEventType = recent.firstOrNull()?.eventType,
            lastEventAmount = recent.firstOrNull()?.amount
        )
    }

    /**
     * PHASE D2 PART 14 — Collection observability.
     *
     * Pending summary, duplicate detection, replay health, stale pending detection.
     */
    suspend fun collectionObservability(
        dao: com.example.fieldtrack.data.local.dao.FinancialEventDao?
    ): CollectionObservabilityEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val d = dao ?: return null

        val recent = d.getRecentEvents(200)
        val integrity = com.example.fieldtrack.core.verification.CollectionIntegrityVerifier.verify(recent, 200)
        val summary = d.getSettlementSummary()
        val totalPending = summary.filter { it.total > 0 }.sumOf { it.total }
        val customersPending = summary.count { it.total > 0 }
        val now = System.currentTimeMillis()
        val stalePending = recent
            .filter { it.eventType == com.example.fieldtrack.core.finance.FinancialEventType.JOB_CHARGE.name }
            .count { (now - it.timestamp) > 60L * 24 * 60 * 60 * 1000 }

        return CollectionObservabilityEntry(
            totalPending = totalPending,
            customersPending = customersPending,
            duplicateCollections = integrity.duplicateCollections,
            correctionLoops = integrity.correctionLoops,
            invalidSettlements = integrity.invalidSettlements,
            multiDeviceSettlements = integrity.multiDeviceSettlements,
            stalePendingCount = stalePending,
            financialPresence = com.example.fieldtrack.core.finance.FinancialPresence.current.name
        )
    }

    /**
     * PHASE D3 PART 15 — Settlement observability.
     */
    suspend fun settlementObservability(
        dao: com.example.fieldtrack.data.local.dao.FinancialEventDao?
    ): SettlementObservabilityEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val d = dao ?: return null

        val recent = d.getRecentEvents(200)
        val integrity = com.example.fieldtrack.core.verification.SettlementIntegrityVerifier.verify(recent, 200)

        val settlementCount = recent.count {
            it.eventType == com.example.fieldtrack.core.finance.FinancialEventType.SETTLEMENT.name
        }
        val carryForwardCount = recent.count {
            it.eventType == com.example.fieldtrack.core.finance.FinancialEventType.BALANCE_CARRY_FORWARD.name
        }
        val operatorsActive = recent
            .filter { it.eventType == com.example.fieldtrack.core.finance.FinancialEventType.SETTLEMENT.name }
            .map { it.operatorId }
            .distinct().size

        return SettlementObservabilityEntry(
            settlementCount = settlementCount,
            carryForwardCount = carryForwardCount,
            operatorsActive = operatorsActive,
            duplicateSettlements = integrity.duplicateSettlements,
            overSettlements = integrity.overSettlements,
            carryForwardLoops = integrity.carryForwardLoops,
            multiDeviceSettlements = integrity.multiDeviceSettlements,
            replayGaps = integrity.replayGaps,
            correctionLoops = integrity.correctionLoops,
            operatorMismatches = integrity.operatorMismatches
        )
    }

    // ════════════════════════════════════════════════════════════════
    // PHASE E1 PART 11 — Reporting observability
    // ════════════════════════════════════════════════════════════════

    /**
     * Reporting observability — derived daily snapshot quick-look.
     * Returns null in PROD or if DAOs are missing.
     */
    suspend fun reportingObservability(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?,
        activeJobsDao: com.example.fieldtrack.data.local.dao.ActiveJobsDao? = null
    ): ReportingObservabilityEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null
        val jdao = jobDao ?: return null

        val (start, end) = todayWindow()
        val events = fdao.getRecentEvents(500)
        val recentJobs = jdao.getRecentCompletedJobs(200)
        val active = try {
            activeJobsDao?.getAllActiveJobsOnce() ?: emptyList()
        } catch (_: Throwable) {
            emptyList()
        }

        val snapshot = com.example.fieldtrack.core.reporting.DailyOperationSnapshot.build(
            startOfDay = start,
            endOfDay = end,
            completedJobs = recentJobs,
            activeJobs = active,
            allFinancialEvents = events
        )
        val presence = com.example.fieldtrack.core.reporting.ReportingPresence.classify(snapshot)

        return ReportingObservabilityEntry(
            totalWorks = snapshot.totalWorks,
            totalActive = snapshot.totalActive,
            totalCompleted = snapshot.totalCompleted,
            totalRevenue = snapshot.totalRevenue,
            totalCollected = snapshot.totalCollected,
            totalPending = snapshot.totalPending,
            operatorCount = snapshot.operatorCount,
            customerCount = snapshot.customerCount,
            machineCount = snapshot.machineCount,
            presence = presence.name
        )
    }

    /** Timeline stats — counts of timeline entries by category for today. */
    suspend fun timelineStats(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?
    ): TimelineStatsEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null

        val (start, end) = todayWindow()
        val events = fdao.getRecentEvents(500)
        val timeline = com.example.fieldtrack.core.reporting.OperationalTimeline.buildForWindow(
            startOfDay = start,
            endOfDay = end,
            financialEvents = events
        )
        val byCategory = timeline.groupingBy { it.category.name }.eachCount()
        return TimelineStatsEntry(
            totalEntries = timeline.size,
            workEntries = byCategory["WORK"] ?: 0,
            collectionEntries = byCategory["COLLECTION"] ?: 0,
            settlementEntries = byCategory["SETTLEMENT"] ?: 0,
            systemEntries = byCategory["SYSTEM"] ?: 0
        )
    }

    /** Export foundation health — verifies all export models can be constructed. */
    suspend fun exportHealth(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?
    ): ExportHealthEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null
        val jdao = jobDao ?: return null

        val (start, end) = todayWindow()
        val events = fdao.getRecentEvents(500)
        val recentJobs = jdao.getRecentCompletedJobs(200)
        val snapshot = com.example.fieldtrack.core.reporting.DailyOperationSnapshot.build(
            startOfDay = start,
            endOfDay = end,
            completedJobs = recentJobs,
            activeJobs = emptyList(),
            allFinancialEvents = events
        )
        val timeline = com.example.fieldtrack.core.reporting.OperationalTimeline.buildForWindow(
            startOfDay = start,
            endOfDay = end,
            financialEvents = events
        )
        val replayFrames = com.example.fieldtrack.core.logging.OperationalReplayRecorder.frames()
        val payload = com.example.fieldtrack.core.reporting.OperationalExport.buildJsonExport(
            snapshot, timeline, events, replayFrames
        )
        return ExportHealthEntry(
            jsonExportable = true,
            timelineEntries = payload.timeline.size,
            financialEventCount = payload.financialEvents.size,
            replayFrameCount = payload.replayFrames.size
        )
    }

    /** Owner memory summary — observational digest. */
    suspend fun ownerMemorySummary(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?
    ): OwnerMemoryDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null
        val jdao = jobDao ?: return null

        val events = fdao.getRecentEvents(500)
        val jobs = jdao.getRecentCompletedJobs(200)
        val insights = com.example.fieldtrack.core.reporting.OwnerOperationalMemory.observe(
            jobs = jobs,
            events = events
        )
        return OwnerMemoryDebugEntry(
            insightCount = insights.size,
            firstInsight = insights.firstOrNull()?.summary,
            kinds = insights.map { it.kind.name }
        )
    }

    private fun todayWindow(): Pair<Long, Long> {
        val cal = java.util.Calendar.getInstance().apply {
            set(java.util.Calendar.HOUR_OF_DAY, 0)
            set(java.util.Calendar.MINUTE, 0)
            set(java.util.Calendar.SECOND, 0)
            set(java.util.Calendar.MILLISECOND, 0)
        }
        val start = cal.timeInMillis
        return start to (start + 24L * 60 * 60 * 1000)
    }

    // ════════════════════════════════════════════════════════════════
    // Debug data models (compact, display-safe)
    // ════════════════════════════════════════════════════════════════

    data class DebugSnapshot(
        val recentMutations: List<MutationDebugEntry>,
        val recentReplayFrames: List<ReplayFrameDebugEntry>,
        val activeTransactions: List<TransactionDebugEntry>,
        val completedTransactions: List<TransactionDebugEntry>,
        val quarantinedEntries: List<QuarantineDebugEntry>,
        val integrityWarnings: IntegrityDebugSummary,
        val recentInvariants: List<InvariantDebugEntry>,
        val journalStats: JournalDebugStats,
        val replayStats: ReplayDebugStats,
        val activeOperator: OperatorDebugEntry?,
        val activeSession: SessionDebugEntry?,
        val recentOwnershipMutations: List<OwnershipMutationDebugEntry>,
        val ownershipConflicts: List<InvariantDebugEntry>,
        val sessionRecoveryEvents: List<String>
    )

    data class MutationDebugEntry(
        val summary: String,
        val operationalId: String,
        val entityType: String,
        val count: Int,
        val timestamp: Long,
        val pattern: String
    )

    data class ReplayFrameDebugEntry(
        val summary: String,
        val operationalId: String,
        val entityVersion: Long,
        val mutationSource: String,
        val classification: String,
        val eventType: String,
        val transactionId: String?,
        val timestamp: Long,
        val sequenceNumber: Long
    )

    data class TransactionDebugEntry(
        val transactionId: String,
        val startedAt: Long,
        val completedAt: Long? = null,
        val mutationCount: Int,
        val affectedIds: List<String>,
        val isActive: Boolean
    )

    data class QuarantineDebugEntry(
        val jobId: String,
        val reason: String,
        val type: String,
        val detectedAt: Long,
        val isReviewed: Boolean
    )

    data class IntegrityDebugSummary(
        val totalIssues: Int,
        val duplicateMutations: Int,
        val versionViolations: Int,
        val timestampInversions: Int,
        val missingDeviceIds: Int,
        val replayHealthy: Boolean
    )

    data class InvariantDebugEntry(
        val id: String,
        val title: String,
        val severity: String,
        val message: String,
        val source: String,
        val timestamp: Long
    )

    data class JournalDebugStats(
        val entryCount: Int,
        val currentSequence: Long,
        val pendingSyncCount: Int,
        val lastSummary: String?
    )

    data class ReplayDebugStats(
        val frameCount: Int,
        val lastSequence: Long,
        val isHealthy: Boolean
    )

    data class OperatorDebugEntry(
        val operatorId: String,
        val displayName: String,
        val initials: String,
        val isGuest: Boolean,
        val createdAt: Long
    )

    data class SessionDebugEntry(
        val sessionId: String,
        val operatorId: String,
        val startedAt: Long,
        val lastActiveAt: Long,
        val environment: String,
        val isExpired: Boolean,
        val durationMs: Long
    )

    data class OwnershipMutationDebugEntry(
        val summary: String,
        val operationalId: String,
        val operatorId: String,
        val sessionId: String,
        val timestamp: Long
    )

    data class SyncQueueDebugEntry(
        val pending: Int,
        val inFlight: Int,
        val retrying: Int,
        val failed: Int,
        val conflicted: Int,
        val acknowledged: Int,
        val oldestPendingAgeMs: Long,
        val isHealthy: Boolean,
        val isCritical: Boolean
    )

    data class SyncHealthDebugEntry(
        val state: String,
        val isHealthy: Boolean,
        val isCritical: Boolean,
        val lastEvaluatedAt: Long
    )

    data class RemoteStateDebugEntry(
        val trackedEntities: Int,
        val newestRemoteVersion: Long,
        val oldestRefresh: Long
    )

    data class TransportDebugInfo(
        val connectivityState: String,
        val reliabilityScore: Float,
        val averageLatencyMs: Long,
        val syncPresence: String,
        val ackLastSequence: Long,
        val ackTotalCount: Long,
        val ackGaps: Int
    )

    data class DevicePresenceDebugEntry(
        val knownDevices: Int,
        val recentlyActive: Int,
        val staleDevices: Int
    )

    data class FinancialDebugEntry(
        val totalEvents: Int,
        val recentEventCount: Int,
        val lastEventType: String?,
        val lastEventAmount: Double?
    )

    data class CollectionObservabilityEntry(
        val totalPending: Double,
        val customersPending: Int,
        val duplicateCollections: Int,
        val correctionLoops: Int,
        val invalidSettlements: Int,
        val multiDeviceSettlements: Int,
        val stalePendingCount: Int,
        val financialPresence: String
    )

    data class SettlementObservabilityEntry(
        val settlementCount: Int,
        val carryForwardCount: Int,
        val operatorsActive: Int,
        val duplicateSettlements: Int,
        val overSettlements: Int,
        val carryForwardLoops: Int,
        val multiDeviceSettlements: Int,
        val replayGaps: Int,
        val correctionLoops: Int,
        val operatorMismatches: Int
    )

    // PHASE E1 PART 11 — Reporting debug entries

    data class ReportingObservabilityEntry(
        val totalWorks: Int,
        val totalActive: Int,
        val totalCompleted: Int,
        val totalRevenue: Double,
        val totalCollected: Double,
        val totalPending: Double,
        val operatorCount: Int,
        val customerCount: Int,
        val machineCount: Int,
        val presence: String
    )

    data class TimelineStatsEntry(
        val totalEntries: Int,
        val workEntries: Int,
        val collectionEntries: Int,
        val settlementEntries: Int,
        val systemEntries: Int
    )

    data class ExportHealthEntry(
        val jsonExportable: Boolean,
        val timelineEntries: Int,
        val financialEventCount: Int,
        val replayFrameCount: Int
    )

    data class OwnerMemoryDebugEntry(
        val insightCount: Int,
        val firstInsight: String?,
        val kinds: List<String>
    )
}

package com.example.fieldtrack.debug

import com.example.fieldtrack.core.config.AppEnvironment
import com.example.fieldtrack.core.identity.OperatorIdentityManager
import com.example.fieldtrack.core.logging.OperationalEventHistory
import com.example.fieldtrack.core.logging.OperationalReplayRecorder
import com.example.fieldtrack.core.persistence.MutationCoalescer
import com.example.fieldtrack.core.persistence.OperationalMutationExecutor
import com.example.fieldtrack.core.persistence.OperationalMutationJournal
import com.example.fieldtrack.core.recovery.OperationalQuarantine
import com.example.fieldtrack.core.session.OperationalSessionManager
import com.example.fieldtrack.core.sync.OperationalConnectivity
import com.example.fieldtrack.core.sync.OperationalSyncHealth
import com.example.fieldtrack.core.sync.OperationalSyncQueue
import com.example.fieldtrack.core.sync.RemoteEntityStateCache
import com.example.fieldtrack.core.sync.SyncPresenceState
import com.example.fieldtrack.core.sync.SyncQueueHealth
import com.example.fieldtrack.core.verification.InvariantSeverity
import com.example.fieldtrack.core.verification.MutationIntegrityVerifier
import com.example.fieldtrack.core.verification.OperationalInvariantReporter

/**
 * PART 9 — Debug Operation Center.
 *
 * Provides read-only debug panels for DEV/STAGING environments.
 *
 * Panels:
 * - Recent mutations
 * - Replay frames
 * - Active transactions
 * - Quarantined entries
 * - Integrity warnings
 * - Recovery actions
 * - Version conflicts
 * - Mutation throughput
 *
 * Read-only visualization only. No editing UI.
 */
object OperationalDebugCenter {

    /**
     * Complete debug snapshot — all operational state in one call.
     * Returns null in PROD.
     */
    fun snapshot(executor: OperationalMutationExecutor? = null): DebugSnapshot? {
        if (!AppEnvironment.current().isDebugLike) return null

        return DebugSnapshot(
            recentMutations = recentMutations(),
            recentReplayFrames = recentReplayFrames(),
            activeTransactions = activeTransactions(executor),
            completedTransactions = completedTransactions(executor),
            quarantinedEntries = quarantinedEntries(),
            integrityWarnings = integrityWarnings(),
            recentInvariants = recentInvariants(),
            journalStats = journalStats(),
            replayStats = replayStats(),
            activeOperator = activeOperator(),
            activeSession = activeSession(),
            recentOwnershipMutations = recentOwnershipMutations(),
            ownershipConflicts = ownershipConflicts(),
            sessionRecoveryEvents = sessionRecoveryEvents()
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Individual panels
    // ════════════════════════════════════════════════════════════════

    /** Recent mutation journal entries (coalesced for readability). */
    fun recentMutations(count: Int = 30): List<MutationDebugEntry> {
        val entries = OperationalMutationJournal.recent(count)
        val coalesced = MutationCoalescer.coalesce(entries)
        return coalesced.map { group ->
            MutationDebugEntry(
                summary = group.summary,
                operationalId = group.operationalId.take(8),
                entityType = group.entityType,
                count = group.count,
                timestamp = group.endTimestamp,
                pattern = group.pattern.name
            )
        }
    }

    /** Recent replay frames. */
    fun recentReplayFrames(count: Int = 30): List<ReplayFrameDebugEntry> {
        return OperationalReplayRecorder.recent(count).map { frame ->
            ReplayFrameDebugEntry(
                summary = frame.summary,
                operationalId = frame.operationalId.take(8),
                entityVersion = frame.entityVersion,
                mutationSource = frame.mutationSource.label,
                classification = frame.mutationClassification.name,
                eventType = frame.eventType.name,
                transactionId = frame.transactionId?.take(8),
                timestamp = frame.timestamp,
                sequenceNumber = frame.sequenceNumber
            )
        }
    }

    /** Active transactions. */
    fun activeTransactions(executor: OperationalMutationExecutor? = null): List<TransactionDebugEntry> {
        return (executor?.activeTransactions ?: emptyList()).map { tx ->
            TransactionDebugEntry(
                transactionId = tx.transactionId.take(8),
                startedAt = tx.startedAt,
                mutationCount = tx.mutationCount,
                affectedIds = tx.affectedOperationalIds.map { it.take(8) },
                isActive = true
            )
        }
    }

    /** Completed transactions (recent). */
    fun completedTransactions(executor: OperationalMutationExecutor? = null): List<TransactionDebugEntry> {
        return (executor?.completedTransactions ?: emptyList()).takeLast(20).map { tx ->
            TransactionDebugEntry(
                transactionId = tx.transactionId.take(8),
                startedAt = tx.startedAt,
                completedAt = tx.completedAt,
                mutationCount = tx.mutationCount,
                affectedIds = tx.affectedOperationalIds.map { it.take(8) },
                isActive = false
            )
        }
    }

    /** Quarantined entries. */
    fun quarantinedEntries(): List<QuarantineDebugEntry> {
        return OperationalQuarantine.entries().map { entry ->
            QuarantineDebugEntry(
                jobId = entry.jobId.take(8),
                reason = entry.reason,
                type = entry.quarantineType.name,
                detectedAt = entry.detectedAt,
                isReviewed = entry.isReviewed
            )
        }
    }

    /** Integrity warnings from latest verification run. */
    fun integrityWarnings(): IntegrityDebugSummary {
        val issues = MutationIntegrityVerifier.verify()
        return IntegrityDebugSummary(
            totalIssues = issues,
            duplicateMutations = MutationIntegrityVerifier.checkDuplicateMutationIds(),
            versionViolations = MutationIntegrityVerifier.checkVersionMonotonicity(),
            timestampInversions = MutationIntegrityVerifier.checkTimestampOrdering(),
            missingDeviceIds = MutationIntegrityVerifier.checkDeviceIds(),
            replayHealthy = OperationalReplayRecorder.isSequenceHealthy()
        )
    }

    /** Recent invariant reports. */
    fun recentInvariants(): List<InvariantDebugEntry> {
        return OperationalInvariantReporter.recentInvariants().takeLast(30).map { inv ->
            InvariantDebugEntry(
                id = inv.id,
                title = inv.title,
                severity = inv.severity.name,
                message = inv.message.take(200),
                source = inv.source,
                timestamp = inv.timestamp
            )
        }
    }

    /** Journal statistics. */
    fun journalStats(): JournalDebugStats {
        return JournalDebugStats(
            entryCount = OperationalMutationJournal.entryCount,
            currentSequence = OperationalMutationJournal.currentSequence,
            pendingSyncCount = OperationalMutationJournal.pendingSyncCount(),
            lastSummary = OperationalMutationJournal.lastSummary()
        )
    }

    /** Replay statistics. */
    fun replayStats(): ReplayDebugStats {
        return ReplayDebugStats(
            frameCount = OperationalReplayRecorder.frameCount,
            lastSequence = OperationalReplayRecorder.lastSequence,
            isHealthy = OperationalReplayRecorder.isSequenceHealthy()
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase B: Operator / Session panels
    // ════════════════════════════════════════════════════════════════

    /** Active operator info. Returns null in PROD. */
    fun activeOperator(): OperatorDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val op = OperatorIdentityManager.current()
        return OperatorDebugEntry(
            operatorId = op.operatorId.take(8),
            displayName = op.displayName,
            initials = op.initials,
            isGuest = op.isGuest,
            createdAt = op.createdAt
        )
    }

    /** Active session info. Returns null in PROD. */
    fun activeSession(): SessionDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val session = OperationalSessionManager.current() ?: return null
        return SessionDebugEntry(
            sessionId = session.sessionId.take(8),
            operatorId = session.operatorId.take(8),
            startedAt = session.startedAt,
            lastActiveAt = session.lastActiveAt,
            environment = session.environment,
            isExpired = session.isExpired,
            durationMs = session.durationMs
        )
    }

    /** Recent mutations showing operator attribution. */
    fun recentOwnershipMutations(count: Int = 20): List<OwnershipMutationDebugEntry> {
        return OperationalMutationJournal.recent(count).map { entry ->
            OwnershipMutationDebugEntry(
                summary = entry.summary,
                operationalId = entry.operationalId.take(8),
                operatorId = entry.operatorId.take(8).ifBlank { "none" },
                sessionId = entry.sessionId.take(8).ifBlank { "none" },
                timestamp = entry.timestamp
            )
        }
    }

    /** Ownership conflicts from invariant reporter. */
    fun ownershipConflicts(): List<InvariantDebugEntry> {
        return OperationalInvariantReporter.recentInvariants()
            .filter { it.id.startsWith("OWNERSHIP-") }
            .takeLast(20)
            .map { inv ->
                InvariantDebugEntry(
                    id = inv.id,
                    title = inv.title,
                    severity = inv.severity.name,
                    message = inv.message.take(200),
                    source = inv.source,
                    timestamp = inv.timestamp
                )
            }
    }

    /** Session recovery events from event history. */
    fun sessionRecoveryEvents(): List<String> {
        return OperationalEventHistory.entries()
            .filter { it.message.contains("session", ignoreCase = true) || it.message.contains("Session", ignoreCase = true) }
            .takeLast(10)
            .map { "${it.message} (${it.timestamp})" }
    }

    // ════════════════════════════════════════════════════════════════
    // Phase C1: Sync Queue panels
    // ════════════════════════════════════════════════════════════════

    /** Sync queue health. Returns null in PROD or if no queue provided. */
    suspend fun syncQueueHealth(syncQueue: OperationalSyncQueue?): SyncQueueDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val queue = syncQueue ?: return null
        val health = queue.health()
        return SyncQueueDebugEntry(
            pending = health.pending,
            inFlight = health.inFlight,
            retrying = health.retrying,
            failed = health.failed,
            conflicted = health.conflicted,
            acknowledged = health.acknowledged,
            oldestPendingAgeMs = health.oldestPendingAgeMs,
            isHealthy = health.isHealthy,
            isCritical = health.isCritical
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase C2: Consistency & ACK panels
    // ════════════════════════════════════════════════════════════════

    /** Sync health state. */
    fun syncHealthState(): SyncHealthDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        return SyncHealthDebugEntry(
            state = OperationalSyncHealth.currentState.name,
            isHealthy = OperationalSyncHealth.isHealthy,
            isCritical = OperationalSyncHealth.isCritical,
            lastEvaluatedAt = OperationalSyncHealth.lastEvaluatedAt
        )
    }

    /** Remote entity state cache info. */
    fun remoteStateInfo(cache: RemoteEntityStateCache?): RemoteStateDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val c = cache ?: return null
        val snapshot = c.snapshot()
        return RemoteStateDebugEntry(
            trackedEntities = snapshot.size,
            newestRemoteVersion = snapshot.maxByOrNull { it.lastRemoteVersion }?.lastRemoteVersion ?: 0,
            oldestRefresh = snapshot.minByOrNull { it.localRefreshAt }?.localRefreshAt ?: 0
        )
    }

    // ════════════════════════════════════════════════════════════════
    // Phase C3: Transport & Presence panels
    // ════════════════════════════════════════════════════════════════

    /** Transport reliability and latency. */
    fun transportReliability(): TransportDebugInfo? {
        if (!AppEnvironment.current().isDebugLike) return null
        return TransportDebugInfo(
            connectivityState = OperationalConnectivity.state.name,
            reliabilityScore = OperationalConnectivity.reliabilityScore,
            averageLatencyMs = OperationalConnectivity.averageLatencyMs,
            syncPresence = SyncPresenceState.current.name,
            ackLastSequence = com.example.fieldtrack.core.sync.AcknowledgementPersistence.lastAckedSequence,
            ackTotalCount = com.example.fieldtrack.core.sync.AcknowledgementPersistence.totalAcknowledged,
            ackGaps = com.example.fieldtrack.core.sync.AcknowledgementPersistence.continuityGaps
        )
    }

    /** Device presence summary. */
    fun devicePresenceSummary(): DevicePresenceDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val devices = com.example.fieldtrack.core.presence.DevicePresenceRegistry.all()
        return DevicePresenceDebugEntry(
            knownDevices = devices.size,
            recentlyActive = devices.count { it.isRecentlyActive },
            staleDevices = devices.count { it.isStale }
        )
    }

    // ════════════════════════════════════════════════════════════════
