    /**
     * Preview the operational timeline (most recent N entries today).
     * Renders calm one-line summaries — no replay IDs, no mutation jargon.
     */
    suspend fun operationalTimelinePreview(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        limit: Int = 20
    ): TimelinePreviewEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null

        val (start, end) = todayWindow()
        val events = fdao.getRecentEvents(500)
        val timeline = com.example.fieldtrack.core.reporting.OperationalTimeline.buildForWindow(
            startOfDay = start,
            endOfDay = end,
            financialEvents = events
        )
        val recent = timeline.takeLast(limit).reversed()
        return TimelinePreviewEntry(
            total = timeline.size,
            entries = recent.map { e ->
                TimelinePreviewLine(
                    timestamp = e.timestamp,
                    category = e.category.name,
                    importance = e.importance.name,
                    summary = e.summary
                )
            }
        )
    }

    /**
     * Calm utilization view per machine — observational only.
     * Limited to top-N most-used machines for legibility.
     */
    suspend fun machineUtilizationSummary(
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?,
        activeJobsDao: com.example.fieldtrack.data.local.dao.ActiveJobsDao? = null,
        limit: Int = 5
    ): MachineUtilizationDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val jdao = jobDao ?: return null

        val jobs = jdao.getRecentCompletedJobs(500)
        val active = try {
            activeJobsDao?.getAllActiveJobsOnce() ?: emptyList()
        } catch (_: Throwable) {
            emptyList()
        }

        // Distinct machineIds across completed + active
        val machineIds = (jobs.mapNotNull { it.machineId } + active.mapNotNull { it.machineId })
            .distinct()
        val nameLookup = (jobs.mapNotNull { mIdAndName(it.machineId, it.machineName) } +
            active.mapNotNull { mIdAndName(it.machineId, it.machineName) })
            .toMap()

        val profiles = machineIds.map { id ->
            com.example.fieldtrack.core.reporting.MachineUtilizationMemory.profileFor(
                machineId = id,
                machineName = nameLookup[id],
                jobs = jobs,
                active = active
            )
        }.sortedByDescending { it.totalJobCount }
            .take(limit)

        return MachineUtilizationDebugEntry(
            machineCount = machineIds.size,
            entries = profiles.map { p ->
                MachineUtilizationLine(
                    machineId = p.machineId.take(8),
                    machineName = p.machineName,
                    activeDays = p.activeDays,
                    idleDays = p.idleDurationDays,
                    continuityStreak = p.continuityStreakDays,
                    transportHeavy = p.transportHeavy,
                    currentlyActive = p.currentlyActiveJobCount
                )
            }
        )
    }

    /**
     * Calm operator continuity view — never ranked, never scored.
     */
    suspend fun operatorContinuitySummary(
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?,
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        activeJobsDao: com.example.fieldtrack.data.local.dao.ActiveJobsDao? = null,
        limit: Int = 5
    ): OperatorContinuityDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val jdao = jobDao ?: return null
        val fdao = financialDao ?: return null

        val jobs = jdao.getRecentCompletedJobs(500)
        val events = fdao.getRecentEvents(500)
        val active = try {
            activeJobsDao?.getAllActiveJobsOnce() ?: emptyList()
        } catch (_: Throwable) {
            emptyList()
        }

        val operatorIds = buildSet {
            jobs.forEach { it.updatedBy.takeIf(String::isNotBlank)?.let(::add) }
            active.forEach { it.operatorId?.takeIf(String::isNotBlank)?.let(::add) }
            events.forEach { it.operatorId.takeIf(String::isNotBlank)?.let(::add) }
        }

        val profiles = operatorIds.map { id ->
            com.example.fieldtrack.core.reporting.OperatorActivityMemory.profileFor(
                operatorId = id,
                jobs = jobs,
                active = active,
                events = events
            )
        }.sortedByDescending { it.continuityActiveDays }
            .take(limit)

        return OperatorContinuityDebugEntry(
            operatorCount = operatorIds.size,
            entries = profiles.map { p ->
                OperatorContinuityLine(
                    operatorId = p.operatorId.take(8),
                    activeDaysLast14 = p.continuityActiveDays,
                    commonWorkType = p.commonWorkTypes.firstOrNull(),
                    preferredMachine = p.preferredMachines.firstOrNull(),
                    completedJobs = p.completedJobCount,
                    activeJobs = p.activeJobCount
                )
            }
        )
    }

    /**
     * Reporting integrity state — compact green/issue summary for the debug surface.
     * Behaves per ReportingIntegrityVerifier's environment rules (DEV throws upstream).
     */
    suspend fun reportingIntegrityState(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?,
        activeJobsDao: com.example.fieldtrack.data.local.dao.ActiveJobsDao? = null
    ): ReportingIntegrityDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null
        val jdao = jobDao ?: return null

        val (start, end) = todayWindow()
        val events = fdao.getRecentEvents(500)
        val jobs = jdao.getRecentCompletedJobs(200)
        val active = try {
            activeJobsDao?.getAllActiveJobsOnce() ?: emptyList()
        } catch (_: Throwable) {
            emptyList()
        }

        val daily = com.example.fieldtrack.core.reporting.DailyOperationSnapshot.build(
            startOfDay = start,
            endOfDay = end,
            completedJobs = jobs,
            activeJobs = active,
            allFinancialEvents = events
        )
        val timeline = com.example.fieldtrack.core.reporting.OperationalTimeline.buildForWindow(
            startOfDay = start,
            endOfDay = end,
            financialEvents = events
        )
        val result = try {
            com.example.fieldtrack.core.verification.ReportingIntegrityVerifier.verify(daily, timeline)
        } catch (t: Throwable) {
            // DEV throws — capture as unhealthy entry rather than crashing the debug panel.
            return ReportingIntegrityDebugEntry(
                isHealthy = false,
                totalIssues = -1,
                negativeTotals = 0,
                orphanReferences = 0,
                replayDiscontinuities = 0,
                duplicateTimelineEntries = 0,
                settlementReportMismatch = 0,
                collectionInconsistency = 0,
                impossibleContinuity = 0,
                threwInDev = true,
                threwMessage = t.message?.take(200)
            )
        }
        return ReportingIntegrityDebugEntry(
            isHealthy = result.isHealthy,
            totalIssues = result.totalIssues,
            negativeTotals = result.negativeTotals,
            orphanReferences = result.orphanReferences,
            replayDiscontinuities = result.replayDiscontinuities,
            duplicateTimelineEntries = result.duplicateTimelineEntries,
            settlementReportMismatch = result.settlementReportMismatch,
            collectionInconsistency = result.collectionInconsistency,
            impossibleContinuity = result.impossibleContinuity,
            threwInDev = false,
            threwMessage = null
        )
    }

    private fun mIdAndName(id: String?, name: String?): Pair<String, String>? {
        if (id.isNullOrBlank() || name.isNullOrBlank()) return null
        return id to name
    }

    /** Owner memory summary — observational digest. */
    suspend fun ownerMemorySummary(
        financialDao: com.example.fieldtrack.data.local.dao.FinancialEventDao?,
        jobDao: com.example.fieldtrack.data.local.dao.JobDao?
    ): OwnerMemoryDebugEntry? {
        if (!AppEnvironment.current().isDebugLike) return null
        val fdao = financialDao ?: return null
        val jdao = jobDao ?: return null

        val events = fdao.getRecentEvents(500)
        val jobs = jdao.getRecentCompletedJobs(200)
        val insights = com.example.fieldtrack.core.reporting.OwnerOperationalMemory.observe(
            jobs = jobs,
            events = events
        )
        return OwnerMemoryDebugEntry(
            insightCount = insights.size,
            firstInsight = insights.firstOrNull()?.summary,
            kinds = insights.map { it.kind.name }
        )
    }

    private fun todayWindow(): Pair<Long, Long> {
        val cal = java.util.Calendar.getInstance().apply {
            set(java.util.Calendar.HOUR_OF_DAY, 0)
            set(java.util.Calendar.MINUTE, 0)
            set(java.util.Calendar.SECOND, 0)
            set(java.util.Calendar.MILLISECOND, 0)
        }
        val start = cal.timeInMillis
        return start to (start + 24L * 60 * 60 * 1000)
    }

    // ════════════════════════════════════════════════════════════════
    // Debug data models (compact, display-safe)
    // ════════════════════════════════════════════════════════════════

    data class DebugSnapshot(
        val recentMutations: List<MutationDebugEntry>,
        val recentReplayFrames: List<ReplayFrameDebugEntry>,
        val activeTransactions: List<TransactionDebugEntry>,
        val completedTransactions: List<TransactionDebugEntry>,
        val quarantinedEntries: List<QuarantineDebugEntry>,
        val integrityWarnings: IntegrityDebugSummary,
        val recentInvariants: List<InvariantDebugEntry>,
        val journalStats: JournalDebugStats,
        val replayStats: ReplayDebugStats,
        val activeOperator: OperatorDebugEntry?,
        val activeSession: SessionDebugEntry?,
        val recentOwnershipMutations: List<OwnershipMutationDebugEntry>,
        val ownershipConflicts: List<InvariantDebugEntry>,
        val sessionRecoveryEvents: List<String>
    )

    data class MutationDebugEntry(
        val summary: String,
        val operationalId: String,
        val entityType: String,
        val count: Int,
        val timestamp: Long,
        val pattern: String
