/**
 * SINGLE AUTHORITY for meaningful operational writes.
 *
 * All operational mutations (pause, resume, +load, finish, recovery,
 * route update, machine reassignment, prepared workspace, quantity changes, etc.)
 * MUST route through this executor.
 *
 * Responsibilities:
 * 1. Version increment (EntityMutation)
 * 2. Mutation metadata generation (OperationalMutation)
 * 3. Conflict pre-check (ConflictDetectionEngine)
 * 4. Invariant verification
 * 5. Journal append (OperationalMutationJournal)
 * 6. Replay frame generation (OperationalReplayRecorder)
 * 7. Repository save execution
 * 8. Event history logging
 * 9. Transaction grouping (OperationalTransaction)
 * 10. Sync-ready metadata stamping
 *
 * Architectural rule:
 * - Repositories store entities (pure persistence)
 * - This executor owns operational mutation logic
 * - Repositories should NOT increment versions or generate mutation metadata
 */
class OperationalMutationExecutor(
    private val activeJobsRepository: ActiveJobsRepository
) {
    private val source = "MutationExecutor"

    // ════════════════════════════════════════════════════════════════
    // PART 3: Active transaction tracking
    // ════════════════════════════════════════════════════════════════
    private val _activeTransactions = mutableListOf<OperationalTransaction>()

    /** Active transactions (read-only view). */
    val activeTransactions: List<OperationalTransaction>
        get() = synchronized(_activeTransactions) { _activeTransactions.toList() }

    /** Completed transactions history (capped). */
    private val _completedTransactions = ArrayDeque<OperationalTransaction>(200)
    val completedTransactions: List<OperationalTransaction>
        get() = synchronized(_completedTransactions) { _completedTransactions.toList() }

    // ════════════════════════════════════════════════════════════════
    // CORE EXECUTE — Canonical mutation pipeline
    // ════════════════════════════════════════════════════════════════

    /**
     * Execute a canonical operational mutation on an active job.
     *
     * @param jobId The active job to mutate
     * @param mutationSource What triggered this mutation
     * @param classification Sync priority classification
     * @param summary Human-readable description
     * @param isRecovery Whether this is a recovery mutation
     * @param transactionId Optional transaction grouping ID
     * @param mutate Lambda that transforms the entity (receives current, returns mutated)
     * @return The saved entity, or null if the job was not found
     */
    suspend fun execute(
        jobId: String,
        mutationSource: MutationSource = MutationSource.LOCAL_OPERATOR,
        classification: MutationClassification = MutationClassification.OPERATIONAL,
        summary: String,
        isRecovery: Boolean = false,
        transactionId: String? = null,
        mutate: (ActiveJobsEntity) -> ActiveJobsEntity
    ): ActiveJobsEntity? {
        // 1. Load current entity
        val currentJob = activeJobsRepository.getJobById(jobId)
        if (currentJob == null) {
            OperationalInvariantReporter.report(OperationalInvariant(
                id = "MUTATION-MISSING-ENTITY",
                title = "Mutation target not found",
                severity = InvariantSeverity.WARNING,
                message = "Cannot execute mutation: job '$jobId' not found. Summary: $summary",
                source = source
            ))
            return null
        }

        // 2. Conflict pre-check
        val operationalId = currentJob.operationalId ?: currentJob.jobId
        ConflictDetectionEngine.checkVersionConflict(
            entityId = operationalId,
            entityType = "ActiveJobs",
            currentVersion = currentJob.entityVersion,
            incomingVersion = currentJob.entityVersion + 1,
            currentDevice = currentJob.updatedOnDevice,
            incomingDevice = DeviceIdentity.installationId
        )

        // 3. Apply mutation
        val now = System.currentTimeMillis()
        val newVersion = currentJob.entityVersion + 1

        // PART 10: Pipeline assertions
        SavePipelineAssertions.assertVersionMonotonicity(operationalId, currentJob.entityVersion, newVersion)
        SavePipelineAssertions.assertMutationSourcePresence(mutationSource.label, "$operationalId-v$newVersion")

        val mutatedJob = mutate(currentJob).copy(
            entityVersion = newVersion,
            lastMutationSource = mutationSource.label,
            updatedOnDevice = DeviceIdentity.installationId,
            lastUpdatedAt = now,
            operatorId = OperatorIdentityManager.currentOperatorId()
        )

        // Touch session to keep it alive
        OperationalSessionManager.touchSession()

        // 4. Generate mutation metadata
        val mutation = if (isRecovery) {
            OperationalMutation.recovery(
                operationalId = operationalId,
                entityType = "ActiveJobs",
                entityVersion = newVersion,
                summary = summary
            )
        } else {
            OperationalMutation.create(
                operationalId = operationalId,
                entityType = "ActiveJobs",
                entityVersion = newVersion,
                source = mutationSource,
                classification = classification,
                summary = summary
            )
        }

        // 5. Journal append
        val seq = OperationalMutationJournal.append(mutation)

        // 5b. Session assertions (Part 11)
        SessionAssertions.assertOperatorPresent(mutation.operatorId, "${operationalId}-v$newVersion")
        SessionAssertions.assertSessionPresent(mutation.sessionId, "${operationalId}-v$newVersion")

        // 6. Replay frame generation (with transactionId + classification)
        OperationalReplayRecorder.record(mutation, seq, transactionId)

        // 7. Repository save (pure persistence)
        activeJobsRepository.saveJob(mutatedJob)

        // 8. Event history logging
        OperationalEventHistory.record(
            type = OperationalEventType.SAVE,
            message = summary,
            operationalId = operationalId,
            deviceId = DeviceIdentity.installationId,
            mutationSource = mutationSource.label,
            entityVersion = newVersion,
            operatorId = OperatorIdentityManager.currentOperatorId()
        )

        OperationalLog.d(
            OperationalEventType.SAVE,
            "Mutation executed: $summary",
            mapOf(
                "jobId" to jobId,
                "version" to newVersion.toString(),
                "seq" to seq.toString(),
                "txId" to (transactionId ?: "none")
            )
        )

        return mutatedJob
    }

    // ════════════════════════════════════════════════════════════════
    // PART 3: Transaction-aware execution
    // ════════════════════════════════════════════════════════════════

    /**
     * Execute a mutation within an explicit transaction.
     * Records the mutation against the transaction for batching/rollback readiness.
     */
    suspend fun executeInTransaction(
        transaction: OperationalTransaction,
        jobId: String,
        mutationSource: MutationSource = MutationSource.LOCAL_OPERATOR,
        classification: MutationClassification = MutationClassification.OPERATIONAL,
        summary: String,
        mutate: (ActiveJobsEntity) -> ActiveJobsEntity
    ): Pair<ActiveJobsEntity?, OperationalTransaction> {
        val result = execute(
            jobId = jobId,
            mutationSource = mutationSource,
            classification = classification,
            summary = summary,
            transactionId = transaction.transactionId,
            mutate = mutate
        )

        val operationalId = result?.operationalId ?: result?.jobId ?: jobId
        val updatedTransaction = transaction.recordMutation(operationalId)

        return result to updatedTransaction
    }

    /**
     * Begin a new transaction.
     */
    fun beginTransaction(): OperationalTransaction {
        val tx = OperationalTransaction.begin()
        synchronized(_activeTransactions) {
            _activeTransactions.add(tx)
        }
        OperationalLog.d(
            OperationalEventType.SAVE,
            "Transaction started: ${tx.transactionId}"
        )
        return tx
    }

    /**
     * Complete a transaction.
     */
    fun completeTransaction(transaction: OperationalTransaction): OperationalTransaction {
        val completed = transaction.complete()

        // PART 10: Transaction consistency assertion
        SavePipelineAssertions.assertTransactionConsistency(
            completed.transactionId, completed.startedAt, completed.completedAt
        )

        synchronized(_activeTransactions) {
            _activeTransactions.removeAll { it.transactionId == transaction.transactionId }
        }
        synchronized(_completedTransactions) {
            if (_completedTransactions.size >= 200) _completedTransactions.removeFirst()
            _completedTransactions.addLast(completed)
        }
        OperationalLog.d(
            OperationalEventType.SAVE,
            "Transaction completed: ${completed.transactionId} (${completed.mutationCount} mutations, ${completed.durationMs}ms)"
        )
        return completed
    }

    // ════════════════════════════════════════════════════════════════
    // PART 2: Complete operational flow adoption
    // ════════════════════════════════════════════════════════════════

    /**
     * Start work — canonical operational mutation.
     */
    suspend fun startWork(jobId: String, startTime: Long = System.currentTimeMillis()): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Started work"
        ) { job ->
            job.copy(
                startTime = startTime,
                isPaused = false,
                isStopped = false,
                endTime = null
            )
        }
    }

    /**
     * Quick pause — canonical operational mutation.
     */
    suspend fun quickPauseJob(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "Paused timer"
        ) { job ->
            if (!job.isTimerRunning) return@execute job
            val now = System.currentTimeMillis()
            job.copy(
                isPaused = true,
                pauseStartTime = now
            )
        }
    }

    /**
     * Quick resume — canonical operational mutation.
     */
    suspend fun quickResumeJob(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "Resumed timer"
        ) { job ->
            if (!job.isPaused) return@execute job
            val now = System.currentTimeMillis()
            val additionalPaused = if (job.pauseStartTime != null) now - job.pauseStartTime else 0L
            job.copy(
                isPaused = false,
                pauseStartTime = null,
                totalPausedDuration = job.totalPausedDuration + additionalPaused
            )
        }
    }

    /**
     * Quick add load — canonical operational mutation.
     */
    suspend fun quickAddLoad(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "+1 load"
        ) { job ->
            job.copy(trips = job.trips + 1)
        }
    }

    /**
     * Bulk add loads — canonical operational mutation.
     */
    suspend fun bulkAddLoads(jobId: String, count: Int): ActiveJobsEntity? {
        if (count <= 0) return null
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "+$count loads"
        ) { job ->
            job.copy(trips = job.trips + count)
        }
    }

    /**
     * Inline finish: stop timer and prepare for completion.
     */
    suspend fun stopTimerForInlineFinish(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.STRUCTURAL,
            summary = "Inline finish — timer stopped"
        ) { job ->
            val now = System.currentTimeMillis()
            val additionalPaused = if (job.isPaused && job.pauseStartTime != null) {
                now - job.pauseStartTime
            } else 0L
            job.copy(
                isPaused = false,
                pauseStartTime = null,
                isStopped = true,
                endTime = now,
                totalPausedDuration = job.totalPausedDuration + additionalPaused
            )
        }
    }

    /**
     * Workspace restore — canonical recovery mutation.
     */
    suspend fun restoreWorkspace(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.WORKSPACE_RESTORE,
            classification = MutationClassification.RECOVERY,
            summary = "Workspace restored",
            isRecovery = false
        ) { job -> job } // Identity mutation — marks restore without changing data
    }

    /**
     * Interruption recovery — canonical recovery mutation.
     */
    suspend fun recoverFromInterruption(
        jobId: String,
        summary: String = "Recovered interrupted workspace"
    ): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INTERRUPTION_RECOVERY,
            classification = MutationClassification.RECOVERY,
            summary = summary,
            isRecovery = true
        ) { job -> job } // Identity mutation — marks recovery without changing data
    }

    /**
     * Route update — canonical operational mutation.
     */
    suspend fun updateRoute(jobId: String, newRoute: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Route changed to $newRoute"
        ) { job ->
            job.copy(routeLabel = newRoute)
        }
    }

    /**
     * Machine reassignment — canonical structural mutation.
     */
    suspend fun reassignMachine(
        jobId: String,
        newMachineId: String?,
        newMachineName: String?
    ): ActiveJobsEntity? {
        val label = newMachineName ?: "unknown"
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Machine reassigned to $label"
        ) { job ->
            job.copy(machineId = newMachineId, machineName = newMachineName)
        }
    }

    /**
     * Prepared workspace creation — canonical structural mutation.
     */
    suspend fun createPreparedWorkspace(entity: ActiveJobsEntity): ActiveJobsEntity? {
        // Stamp ownership on creation
        val ownedEntity = entity.copy(
            ownerOperatorId = OperatorIdentityManager.currentOperatorId(),
            ownerSessionId = OperationalSessionManager.currentSessionId(),
            operatorId = OperatorIdentityManager.currentOperatorId()
        )
        // For new entity creation, we save directly then execute an identity mutation
        activeJobsRepository.saveJob(ownedEntity)
        return execute(
            jobId = entity.jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Prepared transport setup"
        ) { job -> job.copy(
            ownerOperatorId = job.ownerOperatorId ?: OperatorIdentityManager.currentOperatorId(),
            ownerSessionId = job.ownerSessionId ?: OperationalSessionManager.currentSessionId()
        ) }
    }

    /**
     * Transport quantity change — canonical operational mutation.
     */
    suspend fun updateTransportQuantity(jobId: String, newTrips: Int): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Transport quantity → $newTrips"
        ) { job ->
            job.copy(trips = newTrips)
        }
    }

    /**
     * Packet count change — canonical operational mutation.
     */
    suspend fun updatePacketCount(jobId: String, newCount: Int): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Packet count → $newCount"
        ) { job ->
            job.copy(trips = newCount)
        }
    }

    /**
     * PER_ACRE quantity update — canonical operational mutation.
     */
    suspend fun updateAcreQuantity(jobId: String, newAcres: Double): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Area quantity → $newAcres acres"
        ) { job ->
            job.copy(distance = newAcres)
        }
    }

    /**
     * Generic entity save — canonical operational mutation.
     * Used for background persistence (timer tick saves, draft saves).
     */
    suspend fun persistWorkspaceState(
        jobId: String,
        summary: String = "Workspace state persisted",
        mutate: (ActiveJobsEntity) -> ActiveJobsEntity
    ): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = summary,
            mutate = mutate
        )
    }

    /**
     * Discard workspace — canonical structural mutation.
     */
    suspend fun discardWorkspace(jobId: String) {
        // Record the discard mutation before removal
        val currentJob = activeJobsRepository.getJobById(jobId)
        if (currentJob != null) {
            val operationalId = currentJob.operationalId ?: currentJob.jobId
            val mutation = OperationalMutation.create(
                operationalId = operationalId,
                entityType = "ActiveJobs",
                entityVersion = currentJob.entityVersion + 1,
                source = MutationSource.LOCAL_OPERATOR,
                classification = MutationClassification.STRUCTURAL,
                summary = "Workspace discarded"
            )
            val seq = OperationalMutationJournal.append(mutation)
            OperationalReplayRecorder.record(mutation, seq)
            OperationalEventHistory.record(
                type = OperationalEventType.SAVE,
                message = "Workspace discarded",
                operationalId = operationalId,
                deviceId = DeviceIdentity.installationId,
                mutationSource = MutationSource.LOCAL_OPERATOR.label,
                entityVersion = currentJob.entityVersion + 1,
                operatorId = OperatorIdentityManager.currentOperatorId()
            )
        }
        activeJobsRepository.removeJob(jobId)
    }

    // ════════════════════════════════════════════════════════════════
    // PART 3: Grouped transaction flows
    // ════════════════════════════════════════════════════════════════

    /**
     * Finish current job — transactional: stop timer + prepare for save.
     */
    suspend fun finishCurrentJob(jobId: String): Pair<ActiveJobsEntity?, OperationalTransaction> {
        var tx = beginTransaction()
        val result: ActiveJobsEntity?
        val (stopped, tx2) = executeInTransaction(
            transaction = tx,
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Finished harvesting"
        ) { job ->
            val now = System.currentTimeMillis()
            val additionalPaused = if (job.isPaused && job.pauseStartTime != null) {
                now - job.pauseStartTime
            } else 0L
            job.copy(
                isPaused = false,
                pauseStartTime = null,
                isStopped = true,
                endTime = now,
                totalPausedDuration = job.totalPausedDuration + additionalPaused
            )
        }
        tx = tx2
        result = stopped
        tx = completeTransaction(tx)
        return result to tx
    }

    /**
     * Auto-split and start new — transactional: save old job + create new workspace.
     */
    suspend fun autoSplitAndStartNew(
        oldJobId: String,
        oldJobMutate: (ActiveJobsEntity) -> ActiveJobsEntity,
        newEntity: ActiveJobsEntity
    ): OperationalTransaction {
        var tx = beginTransaction()

        // Save old job state
        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = oldJobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Auto-split — previous job preserved"
        ) { job -> oldJobMutate(job) }
        tx = tx2

        // Create new workspace
        activeJobsRepository.saveJob(newEntity)

        tx = completeTransaction(tx)
        return tx
    }

    /**
     * Continue to next same-customer job — transactional switch.
     */
    suspend fun continueToNextSameCustomerJob(
        currentJobId: String,
        nextJobId: String
    ): OperationalTransaction {
        var tx = beginTransaction()

        // Mark current as transition point
        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = currentJobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Transitioning to next customer job"
        ) { it }
        tx = tx2

        // Mark next job as restored
        val (_, tx3) = executeInTransaction(
            transaction = tx,
            jobId = nextJobId,
            mutationSource = MutationSource.WORKSPACE_RESTORE,
            classification = MutationClassification.RECOVERY,
            summary = "Continued from previous customer job"
        ) { it }
        tx = tx3

        tx = completeTransaction(tx)
        return tx
    }

    /**
     * Interruption recovery restore — transactional.
     */
    suspend fun interruptionRecoveryRestore(
        jobId: String,
        recoveryDescription: String = "Recovered interrupted workspace"
    ): OperationalTransaction {
        var tx = beginTransaction()

        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = jobId,
            mutationSource = MutationSource.INTERRUPTION_RECOVERY,
            classification = MutationClassification.RECOVERY,
            summary = recoveryDescription
        ) { it }
        tx = tx2

        tx = completeTransaction(tx)
        return tx
    }

    /**
     * Prepared workspace conversion — transactional: convert prepared → active.
     */
    suspend fun convertPreparedToActive(
        jobId: String,
        startTime: Long = System.currentTimeMillis()
    ): OperationalTransaction {
        var tx = beginTransaction()

        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Prepared workspace → active work"
        ) { job ->
            job.copy(
                startTime = startTime,
                isPaused = false,
                isStopped = false,
                endTime = null
            )
        }
        tx = tx2

        tx = completeTransaction(tx)
        return tx
    }
}

package com.example.fieldtrack.core.persistence

import com.example.fieldtrack.core.identity.DeviceIdentity
import com.example.fieldtrack.core.identity.OperatorIdentityManager
import com.example.fieldtrack.core.logging.OperationalEventHistory
import com.example.fieldtrack.core.logging.OperationalEventType
import com.example.fieldtrack.core.logging.OperationalLog
import com.example.fieldtrack.core.logging.OperationalReplayRecorder
import com.example.fieldtrack.core.session.OperationalSessionManager
import com.example.fieldtrack.core.sync.OperationalSyncQueue
import com.example.fieldtrack.core.verification.InvariantSeverity
import com.example.fieldtrack.core.verification.OperationalInvariant
import com.example.fieldtrack.core.verification.OperationalInvariantReporter
import com.example.fieldtrack.core.verification.SavePipelineAssertions
import com.example.fieldtrack.core.verification.SessionAssertions
import com.example.fieldtrack.data.local.entity.ActiveJobsEntity
import com.example.fieldtrack.data.repository.ActiveJobsRepository

/**
 * SINGLE AUTHORITY for meaningful operational writes.
 *
 * All operational mutations (pause, resume, +load, finish, recovery,
 * route update, machine reassignment, prepared workspace, quantity changes, etc.)
 * MUST route through this executor.
 *
 * Responsibilities:
 * 1. Version increment (EntityMutation)
 * 2. Mutation metadata generation (OperationalMutation)
 * 3. Conflict pre-check (ConflictDetectionEngine)
 * 4. Invariant verification
 * 5. Journal append (OperationalMutationJournal)
 * 6. Replay frame generation (OperationalReplayRecorder)
 * 7. Repository save execution
 * 8. Event history logging
 * 9. Transaction grouping (OperationalTransaction)
 * 10. Sync-ready metadata stamping
 *
 * Architectural rule:
 * - Repositories store entities (pure persistence)
 * - This executor owns operational mutation logic
 * - Repositories should NOT increment versions or generate mutation metadata
 */
class OperationalMutationExecutor(
    private val activeJobsRepository: ActiveJobsRepository,
    private val syncQueue: OperationalSyncQueue? = null
) {
    private val source = "MutationExecutor"

    // ════════════════════════════════════════════════════════════════
    // PART 3: Active transaction tracking
    // ════════════════════════════════════════════════════════════════
    private val _activeTransactions = mutableListOf<OperationalTransaction>()

    /** Active transactions (read-only view). */
    val activeTransactions: List<OperationalTransaction>
        get() = synchronized(_activeTransactions) { _activeTransactions.toList() }

    /** Completed transactions history (capped). */
    private val _completedTransactions = ArrayDeque<OperationalTransaction>(200)
    val completedTransactions: List<OperationalTransaction>
        get() = synchronized(_completedTransactions) { _completedTransactions.toList() }

    // ════════════════════════════════════════════════════════════════
    // CORE EXECUTE — Canonical mutation pipeline
    // ════════════════════════════════════════════════════════════════

    /**
     * Execute a canonical operational mutation on an active job.
     *
     * @param jobId The active job to mutate
     * @param mutationSource What triggered this mutation
     * @param classification Sync priority classification
     * @param summary Human-readable description
     * @param isRecovery Whether this is a recovery mutation
     * @param transactionId Optional transaction grouping ID
     * @param mutate Lambda that transforms the entity (receives current, returns mutated)
     * @return The saved entity, or null if the job was not found
     */
    suspend fun execute(
        jobId: String,
        mutationSource: MutationSource = MutationSource.LOCAL_OPERATOR,
        classification: MutationClassification = MutationClassification.OPERATIONAL,
        summary: String,
        isRecovery: Boolean = false,
        transactionId: String? = null,
        mutate: (ActiveJobsEntity) -> ActiveJobsEntity
    ): ActiveJobsEntity? {
        // 1. Load current entity
        val currentJob = activeJobsRepository.getJobById(jobId)
        if (currentJob == null) {
            OperationalInvariantReporter.report(OperationalInvariant(
                id = "MUTATION-MISSING-ENTITY",
                title = "Mutation target not found",
                severity = InvariantSeverity.WARNING,
                message = "Cannot execute mutation: job '$jobId' not found. Summary: $summary",
                source = source
            ))
            return null
        }

        // 2. Conflict pre-check
        val operationalId = currentJob.operationalId ?: currentJob.jobId
        ConflictDetectionEngine.checkVersionConflict(
            entityId = operationalId,
            entityType = "ActiveJobs",
            currentVersion = currentJob.entityVersion,
            incomingVersion = currentJob.entityVersion + 1,
            currentDevice = currentJob.updatedOnDevice,
            incomingDevice = DeviceIdentity.installationId
        )

        // 3. Apply mutation
        val now = System.currentTimeMillis()
        val newVersion = currentJob.entityVersion + 1

        // PART 10: Pipeline assertions
        SavePipelineAssertions.assertVersionMonotonicity(operationalId, currentJob.entityVersion, newVersion)
        SavePipelineAssertions.assertMutationSourcePresence(mutationSource.label, "$operationalId-v$newVersion")

        val mutatedJob = mutate(currentJob).copy(
            entityVersion = newVersion,
            lastMutationSource = mutationSource.label,
            updatedOnDevice = DeviceIdentity.installationId,
            lastUpdatedAt = now,
            operatorId = OperatorIdentityManager.currentOperatorId()
        )

        // Touch session to keep it alive
        OperationalSessionManager.touchSession()

        // 4. Generate mutation metadata
        val mutation = if (isRecovery) {
            OperationalMutation.recovery(
                operationalId = operationalId,
                entityType = "ActiveJobs",
                entityVersion = newVersion,
                summary = summary
            )
        } else {
            OperationalMutation.create(
                operationalId = operationalId,
                entityType = "ActiveJobs",
                entityVersion = newVersion,
                source = mutationSource,
                classification = classification,
                summary = summary
            )
        }

        // 5. Journal append
        val seq = OperationalMutationJournal.append(mutation)

        // 5b. Session assertions (Part 11)
        SessionAssertions.assertOperatorPresent(mutation.operatorId, "${operationalId}-v$newVersion")
        SessionAssertions.assertSessionPresent(mutation.sessionId, "${operationalId}-v$newVersion")

        // 6. Replay frame generation (with transactionId + classification)
        OperationalReplayRecorder.record(mutation, seq, transactionId)

        // 7. Repository save (pure persistence)
        activeJobsRepository.saveJob(mutatedJob)

        // 8. Event history logging
        OperationalEventHistory.record(
            type = OperationalEventType.SAVE,
            message = summary,
            operationalId = operationalId,
            deviceId = DeviceIdentity.installationId,
            mutationSource = mutationSource.label,
            entityVersion = newVersion,
            operatorId = OperatorIdentityManager.currentOperatorId()
        )

        OperationalLog.d(
            OperationalEventType.SAVE,
            "Mutation executed: $summary",
            mapOf(
                "jobId" to jobId,
                "version" to newVersion.toString(),
                "seq" to seq.toString(),
                "txId" to (transactionId ?: "none")
            )
        )

        return mutatedJob
    }

    // ════════════════════════════════════════════════════════════════
    // PART 3: Transaction-aware execution
    // ════════════════════════════════════════════════════════════════

    /**
     * Execute a mutation within an explicit transaction.
     * Records the mutation against the transaction for batching/rollback readiness.
     */
    suspend fun executeInTransaction(
        transaction: OperationalTransaction,
        jobId: String,
        mutationSource: MutationSource = MutationSource.LOCAL_OPERATOR,
        classification: MutationClassification = MutationClassification.OPERATIONAL,
        summary: String,
        mutate: (ActiveJobsEntity) -> ActiveJobsEntity
    ): Pair<ActiveJobsEntity?, OperationalTransaction> {
        val result = execute(
            jobId = jobId,
            mutationSource = mutationSource,
            classification = classification,
            summary = summary,
            transactionId = transaction.transactionId,
            mutate = mutate
        )

        val operationalId = result?.operationalId ?: result?.jobId ?: jobId
        val updatedTransaction = transaction.recordMutation(operationalId)

        return result to updatedTransaction
    }

    /**
     * Begin a new transaction.
     */
    fun beginTransaction(): OperationalTransaction {
        val tx = OperationalTransaction.begin()
        synchronized(_activeTransactions) {
            _activeTransactions.add(tx)
        }
        OperationalLog.d(
            OperationalEventType.SAVE,
            "Transaction started: ${tx.transactionId}"
        )
        return tx
    }

    /**
     * Complete a transaction.
     */
    fun completeTransaction(transaction: OperationalTransaction): OperationalTransaction {
        val completed = transaction.complete()

        // PART 10: Transaction consistency assertion
        SavePipelineAssertions.assertTransactionConsistency(
            completed.transactionId, completed.startedAt, completed.completedAt
        )

        synchronized(_activeTransactions) {
            _activeTransactions.removeAll { it.transactionId == transaction.transactionId }
        }
        synchronized(_completedTransactions) {
            if (_completedTransactions.size >= 200) _completedTransactions.removeFirst()
            _completedTransactions.addLast(completed)
        }
        OperationalLog.d(
            OperationalEventType.SAVE,
            "Transaction completed: ${completed.transactionId} (${completed.mutationCount} mutations, ${completed.durationMs}ms)"
        )
        return completed
    }

    // ════════════════════════════════════════════════════════════════
    // PART 2: Complete operational flow adoption
    // ════════════════════════════════════════════════════════════════

    /**
     * Start work — canonical operational mutation.
     */
    suspend fun startWork(jobId: String, startTime: Long = System.currentTimeMillis()): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Started work"
        ) { job ->
            job.copy(
                startTime = startTime,
                isPaused = false,
                isStopped = false,
                endTime = null
            )
        }
    }

    /**
     * Quick pause — canonical operational mutation.
     */
    suspend fun quickPauseJob(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "Paused timer"
        ) { job ->
            if (!job.isTimerRunning) return@execute job
            val now = System.currentTimeMillis()
            job.copy(
                isPaused = true,
                pauseStartTime = now
            )
        }
    }

    /**
     * Quick resume — canonical operational mutation.
     */
    suspend fun quickResumeJob(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "Resumed timer"
        ) { job ->
            if (!job.isPaused) return@execute job
            val now = System.currentTimeMillis()
            val additionalPaused = if (job.pauseStartTime != null) now - job.pauseStartTime else 0L
            job.copy(
                isPaused = false,
                pauseStartTime = null,
                totalPausedDuration = job.totalPausedDuration + additionalPaused
            )
        }
    }

    /**
     * Quick add load — canonical operational mutation.
     */
    suspend fun quickAddLoad(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "+1 load"
        ) { job ->
            job.copy(trips = job.trips + 1)
        }
    }

    /**
     * Bulk add loads — canonical operational mutation.
     */
    suspend fun bulkAddLoads(jobId: String, count: Int): ActiveJobsEntity? {
        if (count <= 0) return null
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.OPERATIONAL,
            summary = "+$count loads"
        ) { job ->
            job.copy(trips = job.trips + count)
        }
    }

    /**
     * Inline finish: stop timer and prepare for completion.
     */
    suspend fun stopTimerForInlineFinish(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INLINE_ACTION,
            classification = MutationClassification.STRUCTURAL,
            summary = "Inline finish — timer stopped"
        ) { job ->
            val now = System.currentTimeMillis()
            val additionalPaused = if (job.isPaused && job.pauseStartTime != null) {
                now - job.pauseStartTime
            } else 0L
            job.copy(
                isPaused = false,
                pauseStartTime = null,
                isStopped = true,
                endTime = now,
                totalPausedDuration = job.totalPausedDuration + additionalPaused
            )
        }
    }

    /**
     * Workspace restore — canonical recovery mutation.
     */
    suspend fun restoreWorkspace(jobId: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.WORKSPACE_RESTORE,
            classification = MutationClassification.RECOVERY,
            summary = "Workspace restored",
            isRecovery = false
        ) { job -> job } // Identity mutation — marks restore without changing data
    }

    /**
     * Interruption recovery — canonical recovery mutation.
     */
    suspend fun recoverFromInterruption(
        jobId: String,
        summary: String = "Recovered interrupted workspace"
    ): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.INTERRUPTION_RECOVERY,
            classification = MutationClassification.RECOVERY,
            summary = summary,
            isRecovery = true
        ) { job -> job } // Identity mutation — marks recovery without changing data
    }

    /**
     * Route update — canonical operational mutation.
     */
    suspend fun updateRoute(jobId: String, newRoute: String): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Route changed to $newRoute"
        ) { job ->
            job.copy(routeLabel = newRoute)
        }
    }

    /**
     * Machine reassignment — canonical structural mutation.
     */
    suspend fun reassignMachine(
        jobId: String,
        newMachineId: String?,
        newMachineName: String?
    ): ActiveJobsEntity? {
        val label = newMachineName ?: "unknown"
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Machine reassigned to $label"
        ) { job ->
            job.copy(machineId = newMachineId, machineName = newMachineName)
        }
    }

    /**
     * Prepared workspace creation — canonical structural mutation.
     */
    suspend fun createPreparedWorkspace(entity: ActiveJobsEntity): ActiveJobsEntity? {
        // Stamp ownership on creation
        val ownedEntity = entity.copy(
            ownerOperatorId = OperatorIdentityManager.currentOperatorId(),
            ownerSessionId = OperationalSessionManager.currentSessionId(),
            operatorId = OperatorIdentityManager.currentOperatorId()
        )
        // For new entity creation, we save directly then execute an identity mutation
        activeJobsRepository.saveJob(ownedEntity)
        return execute(
            jobId = entity.jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Prepared transport setup"
        ) { job -> job.copy(
            ownerOperatorId = job.ownerOperatorId ?: OperatorIdentityManager.currentOperatorId(),
            ownerSessionId = job.ownerSessionId ?: OperationalSessionManager.currentSessionId()
        ) }
    }

    /**
     * Transport quantity change — canonical operational mutation.
     */
    suspend fun updateTransportQuantity(jobId: String, newTrips: Int): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Transport quantity → $newTrips"
        ) { job ->
            job.copy(trips = newTrips)
        }
    }

    /**
     * Packet count change — canonical operational mutation.
     */
    suspend fun updatePacketCount(jobId: String, newCount: Int): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Packet count → $newCount"
        ) { job ->
            job.copy(trips = newCount)
        }
    }

    /**
     * PER_ACRE quantity update — canonical operational mutation.
     */
    suspend fun updateAcreQuantity(jobId: String, newAcres: Double): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Area quantity → $newAcres acres"
        ) { job ->
            job.copy(distance = newAcres)
        }
    }

    /**
     * Generic entity save — canonical operational mutation.
     * Used for background persistence (timer tick saves, draft saves).
     */
    suspend fun persistWorkspaceState(
        jobId: String,
        summary: String = "Workspace state persisted",
        mutate: (ActiveJobsEntity) -> ActiveJobsEntity
    ): ActiveJobsEntity? {
        return execute(
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = summary,
            mutate = mutate
        )
    }

    /**
     * Discard workspace — canonical structural mutation.
     */
    suspend fun discardWorkspace(jobId: String) {
        // Record the discard mutation before removal
        val currentJob = activeJobsRepository.getJobById(jobId)
        if (currentJob != null) {
            val operationalId = currentJob.operationalId ?: currentJob.jobId
            val mutation = OperationalMutation.create(
                operationalId = operationalId,
                entityType = "ActiveJobs",
                entityVersion = currentJob.entityVersion + 1,
                source = MutationSource.LOCAL_OPERATOR,
                classification = MutationClassification.STRUCTURAL,
                summary = "Workspace discarded"
            )
            val seq = OperationalMutationJournal.append(mutation)
            OperationalReplayRecorder.record(mutation, seq)
            OperationalEventHistory.record(
                type = OperationalEventType.SAVE,
                message = "Workspace discarded",
                operationalId = operationalId,
                deviceId = DeviceIdentity.installationId,
                mutationSource = MutationSource.LOCAL_OPERATOR.label,
                entityVersion = currentJob.entityVersion + 1,
                operatorId = OperatorIdentityManager.currentOperatorId()
            )
        }
        activeJobsRepository.removeJob(jobId)
    }

    // ════════════════════════════════════════════════════════════════
    // PART 3: Grouped transaction flows
    // ════════════════════════════════════════════════════════════════

    /**
     * Finish current job — transactional: stop timer + prepare for save.
     */
    suspend fun finishCurrentJob(jobId: String): Pair<ActiveJobsEntity?, OperationalTransaction> {
        var tx = beginTransaction()
        val result: ActiveJobsEntity?
        val (stopped, tx2) = executeInTransaction(
            transaction = tx,
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Finished harvesting"
        ) { job ->
            val now = System.currentTimeMillis()
            val additionalPaused = if (job.isPaused && job.pauseStartTime != null) {
                now - job.pauseStartTime
            } else 0L
            job.copy(
                isPaused = false,
                pauseStartTime = null,
                isStopped = true,
                endTime = now,
                totalPausedDuration = job.totalPausedDuration + additionalPaused
            )
        }
        tx = tx2
        result = stopped
        tx = completeTransaction(tx)
        return result to tx
    }

    /**
     * Auto-split and start new — transactional: save old job + create new workspace.
     */
    suspend fun autoSplitAndStartNew(
        oldJobId: String,
        oldJobMutate: (ActiveJobsEntity) -> ActiveJobsEntity,
        newEntity: ActiveJobsEntity
    ): OperationalTransaction {
        var tx = beginTransaction()

        // Save old job state
        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = oldJobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Auto-split — previous job preserved"
        ) { job -> oldJobMutate(job) }
        tx = tx2

        // Create new workspace
        activeJobsRepository.saveJob(newEntity)

        tx = completeTransaction(tx)
        return tx
    }

    /**
     * Continue to next same-customer job — transactional switch.
     */
    suspend fun continueToNextSameCustomerJob(
        currentJobId: String,
        nextJobId: String
    ): OperationalTransaction {
        var tx = beginTransaction()

        // Mark current as transition point
        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = currentJobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.OPERATIONAL,
            summary = "Transitioning to next customer job"
        ) { it }
        tx = tx2

        // Mark next job as restored
        val (_, tx3) = executeInTransaction(
            transaction = tx,
            jobId = nextJobId,
            mutationSource = MutationSource.WORKSPACE_RESTORE,
            classification = MutationClassification.RECOVERY,
            summary = "Continued from previous customer job"
        ) { it }
        tx = tx3

        tx = completeTransaction(tx)
        return tx
    }

    /**
     * Interruption recovery restore — transactional.
     */
    suspend fun interruptionRecoveryRestore(
        jobId: String,
        recoveryDescription: String = "Recovered interrupted workspace"
    ): OperationalTransaction {
        var tx = beginTransaction()

        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = jobId,
            mutationSource = MutationSource.INTERRUPTION_RECOVERY,
            classification = MutationClassification.RECOVERY,
            summary = recoveryDescription
        ) { it }
        tx = tx2

        tx = completeTransaction(tx)
        return tx
    }

    /**
     * Prepared workspace conversion — transactional: convert prepared → active.
     */
    suspend fun convertPreparedToActive(
        jobId: String,
        startTime: Long = System.currentTimeMillis()
    ): OperationalTransaction {
        var tx = beginTransaction()

        val (_, tx2) = executeInTransaction(
            transaction = tx,
            jobId = jobId,
            mutationSource = MutationSource.LOCAL_OPERATOR,
            classification = MutationClassification.STRUCTURAL,
            summary = "Prepared workspace → active work"
        ) { job ->
            job.copy(
                startTime = startTime,
                isPaused = false,
                isStopped = false,
                endTime = null
            )
        }
        tx = tx2

        tx = completeTransaction(tx)
        return tx
    }
}

package com.example.fieldtrack.debug

import com.example.fieldtrack.core.config.FeatureFlags
import com.example.fieldtrack.core.identity.OperationalIdentity
import com.example.fieldtrack.core.identity.OperatorIdentityManager
import com.example.fieldtrack.core.logging.OperationalEventType
import com.example.fieldtrack.core.logging.OperationalLog
import com.example.fieldtrack.core.persistence.MutationClassification
import com.example.fieldtrack.core.persistence.MutationSource
import com.example.fieldtrack.core.persistence.OperationalMutation
import com.example.fieldtrack.core.session.OperationalSessionManager
import com.example.fieldtrack.core.session.OperatorSwitcher
import com.example.fieldtrack.core.sync.OperationalSyncQueue
import com.example.fieldtrack.data.local.entity.ActiveJobsEntity
import com.example.fieldtrack.data.local.entity.PricingMode
import com.example.fieldtrack.data.repository.ActiveJobsRepository
import com.example.fieldtrack.domain.job.JobCapability
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Executes operational simulation scenarios by injecting state
 * through canonical repository paths.
 *
 * DEV/STAGING only — gated by [FeatureFlags.enableOperationalSimulator].
 * Uses real persistence paths (no fake bypass mutations).
 */
class OperationalScenarioRunner(
    private val activeJobsRepository: ActiveJobsRepository,
    private val syncQueue: OperationalSyncQueue? = null
) {

    private fun guard(scenario: String): Boolean {
        if (!FeatureFlags.enableOperationalSimulator) {
            OperationalLog.w(
                OperationalEventType.INVARIANT,
                "Scenario '$scenario' blocked — simulator disabled in this environment"
            )
            return false
        }
        return true
    }

    /**
     * Simulate a long transport day: 3 active transport workspaces with varying loads.
     */
    suspend fun simulateLongTransportDay() {
        if (!guard("LONG_TRANSPORT_DAY")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Long Transport Day scenario")

            val baseTime = System.currentTimeMillis() - 6 * 3600_000 // Started 6 hours ago

            val jobs = listOf(
                createTransportJob("sim_transport_1", "Salem Route", baseTime, trips = 8),
                createTransportJob("sim_transport_2", "Market Route", baseTime + 3600_000, trips = 5),
                createTransportJob("sim_transport_3", "Mill Route", baseTime + 5400_000, trips = 3)
            )

            jobs.forEach { activeJobsRepository.saveJob(it) }
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injected ${jobs.size} transport workspaces")
        }
    }

    /**
     * Simulate an interrupted timer: workspace with running timer that appears
     * to have been interrupted (simulates app kill scenario).
     */
    suspend fun simulateInterruptedTimer() {
        if (!guard("INTERRUPTED_TIMER")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.TIMER, "Injecting: Interrupted Timer scenario")

            val job = ActiveJobsEntity(
                jobId = "sim_interrupted_1",
                customerId = "",
                customerName = "Simulation Customer",
                machineId = null,
                machineName = "Sim Tractor",
                jobCapability = JobCapability.LAND_PREPARATION.name,
                pricingMode = PricingMode.TIME,
                rate = 200.0,
                startTime = System.currentTimeMillis() - 45 * 60_000, // Started 45 min ago
                isPaused = false,
                isStopped = false,
                totalPausedDuration = 0L,
                trips = 0,
                distance = 0.0
            )

            activeJobsRepository.saveJob(job)
            OperationalLog.d(OperationalEventType.TIMER, "Injected interrupted timer workspace")
        }
    }

    /**
     * Simulate prepared work recovery: workspace set up but never started.
     */
    suspend fun simulatePreparedWorkRecovery() {
        if (!guard("STALE_PREPARED_WORK")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Prepared Work Recovery scenario")

            val job = ActiveJobsEntity(
                jobId = "sim_prepared_1",
                customerId = "",
                customerName = "Recovery Customer",
                machineId = null,
                machineName = "Sim Harvester",
                jobCapability = JobCapability.HARVESTING.name,
                pricingMode = PricingMode.PER_ACRE,
                rate = 1500.0,
                startTime = System.currentTimeMillis() - 3 * 24 * 3600_000, // 3 days ago
                isPaused = false,
                isStopped = true, // Stopped = no timer running
                totalPausedDuration = 0L,
                trips = 0,
                distance = 0.0
            )

            activeJobsRepository.saveJob(job)
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injected stale prepared workspace")
        }
    }

    private fun createTransportJob(
        id: String,
        customerName: String,
        startTime: Long,
        trips: Int
    ) = ActiveJobsEntity(
        jobId = id,
        customerId = "",
        customerName = customerName,
        machineId = null,
        machineName = "Sim Trolley",
        jobCapability = JobCapability.TRANSPORT.name,
        pricingMode = PricingMode.TRIP,
        rate = 500.0,
        startTime = startTime,
        isPaused = false,
        isStopped = false,
        totalPausedDuration = 0L,
        trips = trips,
        distance = 0.0,
        ownerOperatorId = OperatorIdentityManager.currentOperatorId(),
        ownerSessionId = OperationalSessionManager.currentSessionId()
    )

    // ══════ Phase B: Operator/Session Simulation Scenarios ══════

    /**
     * Simulate multi-operator day: switch between 3 operators creating workspaces.
     */
    suspend fun simulateMultiOperatorDay() {
        if (!guard("MULTI_OPERATOR_DAY")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Multi-Operator Day scenario")

            // Operator 1: Owner
            OperatorSwitcher.switchTo("Ravi Kumar")
            val job1 = createTransportJob("sim_op1_job", "Owner Route", System.currentTimeMillis() - 4 * 3600_000, trips = 6)
            activeJobsRepository.saveJob(job1)

            // Operator 2: Helper
            OperatorSwitcher.switchTo("Suresh")
            val job2 = createTransportJob("sim_op2_job", "Helper Route", System.currentTimeMillis() - 2 * 3600_000, trips = 3)
            activeJobsRepository.saveJob(job2)

            // Operator 3: Field Worker
            OperatorSwitcher.switchTo("Anand")
            val job3 = createTransportJob("sim_op3_job", "Field Route", System.currentTimeMillis() - 1 * 3600_000, trips = 2)
            activeJobsRepository.saveJob(job3)

            // Switch back to first operator
            OperatorSwitcher.switchTo("Ravi Kumar")
            OperationalLog.d(OperationalEventType.WORKSPACE, "Multi-operator day: 3 operators, 3 workspaces injected")
        }
    }

    /**
     * Simulate shift handoff: operator switch with active workspaces.
     */
    suspend fun simulateShiftHandoff() {
        if (!guard("SHIFT_HANDOFF")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Shift Handoff scenario")

            // Day shift creates active work
            OperatorSwitcher.switchTo("Day Shift Operator")
            val job = createTransportJob("sim_shift_job", "Shift Route", System.currentTimeMillis() - 8 * 3600_000, trips = 12)
            activeJobsRepository.saveJob(job)

            // Night shift takes over
            OperatorSwitcher.switchTo("Night Shift Operator")
            OperationalLog.d(OperationalEventType.WORKSPACE, "Shift handoff simulated — active work visible to new operator")
        }
    }

    /**
     * Simulate device recovery session: stale session after restart.
     */
    suspend fun simulateDeviceRecoverySession() {
        if (!guard("DEVICE_RECOVERY_SESSION")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Device Recovery Session scenario")

            // Create a workspace then simulate session expiry by clearing session
            val job = createTransportJob("sim_recovery_session_job", "Recovery Route", System.currentTimeMillis() - 7 * 3600_000, trips = 4)
            activeJobsRepository.saveJob(job)

            // Simulate expired session
            OperationalSessionManager.clearSession()
            OperationalLog.d(OperationalEventType.WORKSPACE, "Device recovery session: session cleared, work preserved")
        }
    }

    /**
     * Simulate owner override restore: different operator restores workspace.
     */
    suspend fun simulateOwnerOverrideRestore() {
        if (!guard("OWNER_OVERRIDE_RESTORE")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Owner Override Restore scenario")

            // Operator A creates workspace
            OperatorSwitcher.switchTo("Original Owner")
            val job = createTransportJob("sim_owner_override_job", "Override Route", System.currentTimeMillis() - 3 * 3600_000, trips = 5)
            activeJobsRepository.saveJob(job)

            // Operator B is now current (simulates someone else restoring)
            OperatorSwitcher.switchTo("Restoring Operator")
            OperationalLog.d(OperationalEventType.WORKSPACE, "Owner override: workspace owned by Original Owner, current operator is Restoring Operator")
        }
    }

    // ══════ Phase C1: Sync Queue Simulation Scenarios ══════

    /**
     * Simulate offline 3 days: inject many mutations into the sync queue.
     */
    suspend fun simulateOffline3Days() {
        if (!guard("OFFLINE_3_DAYS")) return
        val queue = syncQueue ?: return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.SYNC, "Injecting: Offline 3 Days scenario — 100 mutations")

            val mutations = (1..100).map { i ->
                OperationalMutation.create(
                    operationalId = OperationalIdentity.newId(),
                    entityType = "ActiveJobs",
                    entityVersion = i.toLong(),
                    source = MutationSource.LOCAL_OPERATOR,
                    classification = MutationClassification.OPERATIONAL,
                    summary = "Simulated offline mutation #$i"
                )
            }
            queue.enqueueBatch(mutations)
            OperationalLog.d(OperationalEventType.SYNC, "Offline 3 Days: 100 mutations queued")
        }
    }

    /**
     * Simulate massive pending queue: 500+ mutations.
     */
    suspend fun simulateMassivePendingQueue() {
        if (!guard("MASSIVE_PENDING_QUEUE")) return
        val queue = syncQueue ?: return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.SYNC, "Injecting: Massive Pending Queue — 500 mutations")

            val mutations = (1..500).map { i ->
                OperationalMutation.create(
                    operationalId = OperationalIdentity.newId(),
                    entityType = "ActiveJobs",
                    entityVersion = i.toLong(),
                    source = MutationSource.LOCAL_OPERATOR,
                    classification = MutationClassification.OPERATIONAL,
                    summary = "Stress test mutation #$i"
                )
            }
            queue.enqueueBatch(mutations)
            OperationalLog.d(OperationalEventType.SYNC, "Massive queue: 500 mutations injected")
        }
    }
}

package com.example.fieldtrack.debug

import com.example.fieldtrack.core.config.FeatureFlags
import com.example.fieldtrack.core.identity.OperationalIdentity
import com.example.fieldtrack.core.identity.OperatorIdentityManager
import com.example.fieldtrack.core.logging.OperationalEventType
import com.example.fieldtrack.core.logging.OperationalLog
import com.example.fieldtrack.core.persistence.MutationClassification
import com.example.fieldtrack.core.persistence.MutationSource
import com.example.fieldtrack.core.persistence.OperationalMutation
import com.example.fieldtrack.core.session.OperationalSessionManager
import com.example.fieldtrack.core.session.OperatorSwitcher
import com.example.fieldtrack.core.sync.OperationalSyncQueue
import com.example.fieldtrack.core.finance.FinancialEvent
import com.example.fieldtrack.core.finance.FinancialEventType
import com.example.fieldtrack.core.finance.PaymentMode
import com.example.fieldtrack.data.local.dao.FinancialEventDao
import com.example.fieldtrack.data.local.dao.JobDao
import com.example.fieldtrack.data.local.entity.ActiveJobsEntity
import com.example.fieldtrack.data.local.entity.FinancialEventEntity
import com.example.fieldtrack.data.local.entity.JobEntity
import com.example.fieldtrack.data.local.entity.MachineType
import com.example.fieldtrack.data.local.entity.PaymentStatus
import com.example.fieldtrack.data.local.entity.PricingMode
import com.example.fieldtrack.data.repository.ActiveJobsRepository
import com.example.fieldtrack.domain.job.JobCapability
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Executes operational simulation scenarios by injecting state
 * through canonical repository paths.
 *
 * DEV/STAGING only — gated by [FeatureFlags.enableOperationalSimulator].
 * Uses real persistence paths (no fake bypass mutations).
 */
class OperationalScenarioRunner(
    private val activeJobsRepository: ActiveJobsRepository,
    private val syncQueue: OperationalSyncQueue? = null
) {

    private fun guard(scenario: String): Boolean {
        if (!FeatureFlags.enableOperationalSimulator) {
            OperationalLog.w(
                OperationalEventType.INVARIANT,
                "Scenario '$scenario' blocked — simulator disabled in this environment"
            )
            return false
        }
        return true
    }

    /**
     * Simulate a long transport day: 3 active transport workspaces with varying loads.
     */
    suspend fun simulateLongTransportDay() {
        if (!guard("LONG_TRANSPORT_DAY")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Long Transport Day scenario")

            val baseTime = System.currentTimeMillis() - 6 * 3600_000 // Started 6 hours ago

            val jobs = listOf(
                createTransportJob("sim_transport_1", "Salem Route", baseTime, trips = 8),
                createTransportJob("sim_transport_2", "Market Route", baseTime + 3600_000, trips = 5),
                createTransportJob("sim_transport_3", "Mill Route", baseTime + 5400_000, trips = 3)
            )

            jobs.forEach { activeJobsRepository.saveJob(it) }
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injected ${jobs.size} transport workspaces")
        }
    }

    /**
     * Simulate an interrupted timer: workspace with running timer that appears
     * to have been interrupted (simulates app kill scenario).
     */
    suspend fun simulateInterruptedTimer() {
        if (!guard("INTERRUPTED_TIMER")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.TIMER, "Injecting: Interrupted Timer scenario")

            val job = ActiveJobsEntity(
                jobId = "sim_interrupted_1",
                customerId = "",
                customerName = "Simulation Customer",
                machineId = null,
                machineName = "Sim Tractor",
                jobCapability = JobCapability.LAND_PREPARATION.name,
                pricingMode = PricingMode.TIME,
                rate = 200.0,
                startTime = System.currentTimeMillis() - 45 * 60_000, // Started 45 min ago
                isPaused = false,
                isStopped = false,
                totalPausedDuration = 0L,
                trips = 0,
                distance = 0.0
            )

            activeJobsRepository.saveJob(job)
            OperationalLog.d(OperationalEventType.TIMER, "Injected interrupted timer workspace")
        }
    }

    /**
     * Simulate prepared work recovery: workspace set up but never started.
     */
    suspend fun simulatePreparedWorkRecovery() {
        if (!guard("STALE_PREPARED_WORK")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Prepared Work Recovery scenario")

            val job = ActiveJobsEntity(
                jobId = "sim_prepared_1",
                customerId = "",
                customerName = "Recovery Customer",
                machineId = null,
                machineName = "Sim Harvester",
                jobCapability = JobCapability.HARVESTING.name,
                pricingMode = PricingMode.PER_ACRE,
                rate = 1500.0,
                startTime = System.currentTimeMillis() - 3 * 24 * 3600_000, // 3 days ago
                isPaused = false,
                isStopped = true, // Stopped = no timer running
                totalPausedDuration = 0L,
                trips = 0,
                distance = 0.0
            )

            activeJobsRepository.saveJob(job)
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injected stale prepared workspace")
        }
    }

    private fun createTransportJob(
        id: String,
        customerName: String,
        startTime: Long,
        trips: Int
    ) = ActiveJobsEntity(
        jobId = id,
        customerId = "",
        customerName = customerName,
        machineId = null,
        machineName = "Sim Trolley",
        jobCapability = JobCapability.TRANSPORT.name,
        pricingMode = PricingMode.TRIP,
        rate = 500.0,
        startTime = startTime,
        isPaused = false,
        isStopped = false,
        totalPausedDuration = 0L,
        trips = trips,
        distance = 0.0,
        ownerOperatorId = OperatorIdentityManager.currentOperatorId(),
        ownerSessionId = OperationalSessionManager.currentSessionId()
    )

    // ══════ Phase B: Operator/Session Simulation Scenarios ══════

    /**
     * Simulate multi-operator day: switch between 3 operators creating workspaces.
     */
    suspend fun simulateMultiOperatorDay() {
        if (!guard("MULTI_OPERATOR_DAY")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Multi-Operator Day scenario")

            // Operator 1: Owner
            OperatorSwitcher.switchTo("Ravi Kumar")
            val job1 = createTransportJob("sim_op1_job", "Owner Route", System.currentTimeMillis() - 4 * 3600_000, trips = 6)
            activeJobsRepository.saveJob(job1)

            // Operator 2: Helper
            OperatorSwitcher.switchTo("Suresh")
            val job2 = createTransportJob("sim_op2_job", "Helper Route", System.currentTimeMillis() - 2 * 3600_000, trips = 3)
            activeJobsRepository.saveJob(job2)

            // Operator 3: Field Worker
            OperatorSwitcher.switchTo("Anand")
            val job3 = createTransportJob("sim_op3_job", "Field Route", System.currentTimeMillis() - 1 * 3600_000, trips = 2)
            activeJobsRepository.saveJob(job3)

            // Switch back to first operator
            OperatorSwitcher.switchTo("Ravi Kumar")
            OperationalLog.d(OperationalEventType.WORKSPACE, "Multi-operator day: 3 operators, 3 workspaces injected")
        }
    }

    /**
     * Simulate shift handoff: operator switch with active workspaces.
     */
    suspend fun simulateShiftHandoff() {
        if (!guard("SHIFT_HANDOFF")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Shift Handoff scenario")

            // Day shift creates active work
            OperatorSwitcher.switchTo("Day Shift Operator")
            val job = createTransportJob("sim_shift_job", "Shift Route", System.currentTimeMillis() - 8 * 3600_000, trips = 12)
            activeJobsRepository.saveJob(job)

            // Night shift takes over
            OperatorSwitcher.switchTo("Night Shift Operator")
            OperationalLog.d(OperationalEventType.WORKSPACE, "Shift handoff simulated — active work visible to new operator")
        }
    }

    /**
     * Simulate device recovery session: stale session after restart.
     */
    suspend fun simulateDeviceRecoverySession() {
        if (!guard("DEVICE_RECOVERY_SESSION")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Device Recovery Session scenario")

            // Create a workspace then simulate session expiry by clearing session
            val job = createTransportJob("sim_recovery_session_job", "Recovery Route", System.currentTimeMillis() - 7 * 3600_000, trips = 4)
            activeJobsRepository.saveJob(job)

            // Simulate expired session
            OperationalSessionManager.clearSession()
            OperationalLog.d(OperationalEventType.WORKSPACE, "Device recovery session: session cleared, work preserved")
        }
    }

    /**
     * Simulate owner override restore: different operator restores workspace.
     */
    suspend fun simulateOwnerOverrideRestore() {
        if (!guard("OWNER_OVERRIDE_RESTORE")) return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.WORKSPACE, "Injecting: Owner Override Restore scenario")

            // Operator A creates workspace
            OperatorSwitcher.switchTo("Original Owner")
            val job = createTransportJob("sim_owner_override_job", "Override Route", System.currentTimeMillis() - 3 * 3600_000, trips = 5)
            activeJobsRepository.saveJob(job)

            // Operator B is now current (simulates someone else restoring)
            OperatorSwitcher.switchTo("Restoring Operator")
            OperationalLog.d(OperationalEventType.WORKSPACE, "Owner override: workspace owned by Original Owner, current operator is Restoring Operator")
        }
    }

    // ══════ Phase C1: Sync Queue Simulation Scenarios ══════

    /**
     * Simulate offline 3 days: inject many mutations into the sync queue.
     */
    suspend fun simulateOffline3Days() {
        if (!guard("OFFLINE_3_DAYS")) return
        val queue = syncQueue ?: return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.SYNC, "Injecting: Offline 3 Days scenario — 100 mutations")

            val mutations = (1..100).map { i ->
                OperationalMutation.create(
                    operationalId = OperationalIdentity.newId(),
                    entityType = "ActiveJobs",
                    entityVersion = i.toLong(),
                    source = MutationSource.LOCAL_OPERATOR,
                    classification = MutationClassification.OPERATIONAL,
                    summary = "Simulated offline mutation #$i"
                )
            }
            queue.enqueueBatch(mutations)
            OperationalLog.d(OperationalEventType.SYNC, "Offline 3 Days: 100 mutations queued")
        }
    }

    /**
     * Simulate massive pending queue: 500+ mutations.
     */
    suspend fun simulateMassivePendingQueue() {
        if (!guard("MASSIVE_PENDING_QUEUE")) return
        val queue = syncQueue ?: return

        withContext(Dispatchers.IO) {
            OperationalLog.d(OperationalEventType.SYNC, "Injecting: Massive Pending Queue — 500 mutations")

            val mutations = (1..500).map { i ->
                OperationalMutation.create(
                    operationalId = OperationalIdentity.newId(),
                    entityType = "ActiveJobs",
                    entityVersion = i.toLong(),
                    source = MutationSource.LOCAL_OPERATOR,
                    classification = MutationClassification.OPERATIONAL,
                    summary = "Stress test mutation #$i"
                )
            }
            queue.enqueueBatch(mutations)
            OperationalLog.d(OperationalEventType.SYNC, "Massive queue: 500 mutations injected")
        }
    }
}

package com.example.fieldtrack.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import com.example.fieldtrack.data.local.entity.PaymentEntity
import kotlinx.coroutines.flow.Flow

@Dao
interface PaymentDao {

    /** Newest payment first — what the UI lists. */
    @Query("SELECT * FROM payments WHERE jobId = :jobId AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId) ORDER BY paidAt DESC, createdAt DESC")
    fun getPaymentsForJob(jobId: Long, organizationId: String?): Flow<List<PaymentEntity>>

    /** Snapshot list (non-Flow) for use in repository merge operations. */
    @Query("SELECT * FROM payments WHERE jobId = :jobId AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId) ORDER BY paidAt DESC, createdAt DESC")
    suspend fun getPaymentsForJobOnce(jobId: Long, organizationId: String?): List<PaymentEntity>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(payment: PaymentEntity)

    /** Get a single payment by ID (for merge checks). */
    @Query("SELECT * FROM payments WHERE paymentId = :paymentId")
    suspend fun getPaymentById(paymentId: String): PaymentEntity?

    /** Get all local payment IDs (for orphan cleanup). */
    @Query("SELECT paymentId FROM payments WHERE ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId)")
    suspend fun getAllPaymentIds(organizationId: String?): List<String>

    /** Returns SUM(amount) for a job, or null if no payments yet. */
    @Query("SELECT SUM(amount) FROM payments WHERE jobId = :jobId AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId)")
    suspend fun getTotalPaid(jobId: Long, organizationId: String?): Double?

    @Query("DELETE FROM payments WHERE paymentId = :paymentId")
    suspend fun delete(paymentId: String)

    @Query("DELETE FROM payments WHERE jobId = :jobId")
    suspend fun deleteAllForJob(jobId: Long)

    /** Get all payments belonging to a group (customer-level payment). */
    @Query("SELECT * FROM payments WHERE paymentGroupId = :groupId AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId) ORDER BY paidAt DESC")
    suspend fun getPaymentsByGroupId(groupId: String, organizationId: String?): List<PaymentEntity>

    /** Delete all payments belonging to a group. */
    @Query("DELETE FROM payments WHERE paymentGroupId = :groupId")
    suspend fun deleteByGroupId(groupId: String)

    /** Get distinct job IDs for payments in a group. */
    @Query("SELECT DISTINCT jobId FROM payments WHERE paymentGroupId = :groupId AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId)")
    suspend fun getJobIdsByGroupId(groupId: String, organizationId: String?): List<Long>

    /**
     * Get customer-level payments (the "parent" entries with customerId set).
     * These are the real-world transactions shown in UI.
     */
    @Query("SELECT * FROM payments WHERE customerId = :customerId AND customerId IS NOT NULL AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId) ORDER BY paidAt DESC")
    fun getCustomerPayments(customerId: String, organizationId: String?): Flow<List<PaymentEntity>>

    /**
     * Get recent payments for jobs belonging to a customer (legacy + new format).
     * Used for displaying recent payment history in customer details.
     */
    @Query("""
        SELECT p.* FROM payments p
        INNER JOIN jobs j ON p.jobId = j.id
        WHERE j.customerId = :customerId
        AND ((:organizationId IS NULL AND j.organizationId IS NULL) OR j.organizationId = :organizationId)
        AND ((:organizationId IS NULL AND p.organizationId IS NULL) OR p.organizationId = :organizationId)
        ORDER BY p.paidAt DESC
        LIMIT :limit
    """)
    fun getRecentPaymentsForCustomer(customerId: String, limit: Int = 10, organizationId: String?): Flow<List<PaymentEntity>>

    /** Get all customer-level payment entries (non-allocation rows). */
    @Query("SELECT * FROM payments WHERE customerId = :customerId AND ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId) ORDER BY paidAt DESC")
    suspend fun getCustomerPaymentsOnce(customerId: String, organizationId: String?): List<PaymentEntity>

    /** One-shot list of all payments (for backup). */
    @Query("SELECT * FROM payments WHERE ((:organizationId IS NULL AND organizationId IS NULL) OR organizationId = :organizationId) ORDER BY paidAt DESC")
    suspend fun getAllPaymentsList(organizationId: String?): List<PaymentEntity>

    /** Delete all payments (used during restore). */
    @Query("DELETE FROM payments")
    suspend fun deleteAllPayments()
}

