package com.example.fieldtrack.util

import android.content.ContentValues
import android.content.Context
import android.content.Intent
import android.graphics.Color
import android.graphics.Paint
import android.graphics.pdf.PdfDocument
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import androidx.core.content.FileProvider
import com.example.fieldtrack.data.local.entity.CustomerEntity
import com.example.fieldtrack.data.local.entity.JobEntity
import com.example.fieldtrack.data.local.entity.PaymentEntity
import com.example.fieldtrack.data.local.entity.PricingMode
import com.example.fieldtrack.data.model.WorkSegment
import com.example.fieldtrack.ui.screens.customer.BillPeriod
import com.example.fieldtrack.ui.screens.customer.ShareReportType
import java.io.File
import java.io.FileOutputStream
import com.example.fieldtrack.domain.billing.WorkQuantitySummary
import com.example.fieldtrack.domain.billing.AreaUnit

/**
 * Generates clean, structured PDF bills aligned with the customer-level payment model.
 *
 * Three document types:
 * 1. STANDARD BILL — work table (date-grouped) + totals + simple payment list
 * 2. FULL STATEMENT — work table (date-grouped) + totals + structured payment history table
 * 3. PENDING ONLY — only unpaid jobs + due amount (no payment history)
 *
 * Work rows are grouped by date — if same date has multiple jobs/segments,
 * date is shown once, subsequent rows leave date column blank.
 */
object PdfGenerator {

    // Page dimensions (A4 at 72 DPI)
    private const val PAGE_WIDTH = 595
    private const val PAGE_HEIGHT = 842
    private const val MARGIN = 40f
    private const val CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN
    private const val RIGHT_EDGE = PAGE_WIDTH - MARGIN

    // Work table column widths
    private val COL_DATE = CONTENT_WIDTH * 0.16f
    private val COL_WORK = CONTENT_WIDTH * 0.22f
    private val COL_QTY = CONTENT_WIDTH * 0.20f

    // Payment table column widths (full statement)
    private val PAY_COL_DATE = CONTENT_WIDTH * 0.30f
    private val PAY_COL_METHOD = CONTENT_WIDTH * 0.18f
    private val PAY_COL_AMOUNT = CONTENT_WIDTH * 0.22f
    private val PAY_COL_NOTE = CONTENT_WIDTH * 0.30f

    /**
     * A single work row for the PDF table.
     * Pre-built from segments or legacy job fields, then sorted/grouped by date.
     */
    private data class WorkRow(
        val date: String,      // formatted date string
        val sortKey: Long,     // createdAt for sorting
        val work: String,      // machine type
        val quantity: String,  // "3 Loads", "2h 30m"
        val rate: String,      // "₹500", "₹200/min"
        val amount: Double,    // numeric for totalling
        val amountStr: String, // formatted "₹1,500"
        val meta: String? = null // "Load: Sand • Field: North"
    )

    fun generateCustomerPdf(
        context: Context,
        customer: CustomerEntity,
        jobs: List<JobEntity>,
        reportType: ShareReportType = ShareReportType.STANDARD_BILL,
        customerPayments: List<PaymentEntity> = emptyList(),
        segmentsByJob: Map<Long, List<WorkSegment>> = emptyMap(),
        period: BillPeriod? = null,
        areaUnit: AreaUnit = AreaUnit.ACRE
    ): File {
        // Date-range filter
        val rangeStart = period?.startMillis ?: 0L
        val rangeEnd = period?.endMillis ?: Long.MAX_VALUE
        val dateFilteredJobs = jobs.filter { it.createdAt in rangeStart..rangeEnd }
        val dateFilteredPayments = customerPayments.filter { it.paidAt in rangeStart..rangeEnd }

        // Report-type filter (PENDING_ONLY)
        val filteredJobs = if (reportType == ShareReportType.PENDING_ONLY) {
            dateFilteredJobs.filter { it.paidAmount < it.totalAmount }
        } else {
            dateFilteredJobs
        }

        val document = PdfDocument()
        var pageNumber = 1
        var pageInfo = PdfDocument.PageInfo.Builder(PAGE_WIDTH, PAGE_HEIGHT, pageNumber).create()
        var page = document.startPage(pageInfo)
        var canvas = page.canvas
        var y = MARGIN

        // ============ PAINTS ============
        val titlePaint = Paint().apply {
            color = Color.BLACK; textSize = 20f; isFakeBoldText = true; isAntiAlias = true
        }
        val subtitlePaint = Paint().apply {
            color = Color.DKGRAY; textSize = 11f; isAntiAlias = true
        }
        val sectionPaint = Paint().apply {
            color = Color.BLACK; textSize = 13f; isFakeBoldText = true; isAntiAlias = true
        }
        val bodyPaint = Paint().apply {
            color = Color.BLACK; textSize = 11f; isAntiAlias = true
        }
        val bodySmallPaint = Paint().apply {
            color = Color.DKGRAY; textSize = 10f; isAntiAlias = true
        }
        val boldPaint = Paint().apply {
            color = Color.BLACK; textSize = 11f; isFakeBoldText = true; isAntiAlias = true
        }
        val datePaint = Paint().apply {
            color = Color.rgb(80, 80, 80); textSize = 10f; isFakeBoldText = true; isAntiAlias = true
        }
        val amountPaint = Paint().apply {
            color = Color.BLACK; textSize = 11f; isFakeBoldText = true; isAntiAlias = true
        }
        val totalLabelPaint = Paint().apply {
            color = Color.BLACK; textSize = 13f; isFakeBoldText = true; isAntiAlias = true
        }
        val dueLabelPaint = Paint().apply {
            color = Color.rgb(180, 0, 0); textSize = 14f; isFakeBoldText = true; isAntiAlias = true
        }
        val paidLabelPaint = Paint().apply {
            color = Color.rgb(0, 130, 0); textSize = 12f; isAntiAlias = true
        }
        val linePaint = Paint().apply {
            color = Color.LTGRAY; strokeWidth = 1f
        }
        val thickLinePaint = Paint().apply {
            color = Color.DKGRAY; strokeWidth = 1.5f
        }
        val tableHeaderBgPaint = Paint().apply {
            color = Color.rgb(235, 235, 240); style = Paint.Style.FILL
        }
        val dateGroupBgPaint = Paint().apply {
            color = Color.rgb(248, 248, 252); style = Paint.Style.FILL
        }
        val emptyPaint = Paint().apply {
            color = Color.GRAY; textSize = 11f; isAntiAlias = true
        }

        // ============ HELPERS ============
        fun ensureSpace(needed: Float) {
            if (y + needed > PAGE_HEIGHT - MARGIN - 30) {
                document.finishPage(page)
                pageNumber++
                pageInfo = PdfDocument.PageInfo.Builder(PAGE_WIDTH, PAGE_HEIGHT, pageNumber).create()
                page = document.startPage(pageInfo)
                canvas = page.canvas
                y = MARGIN
            }
        }

        fun drawRight(text: String, rightX: Float, yPos: Float, paint: Paint) {
            val w = paint.measureText(text)
            canvas.drawText(text, rightX - w, yPos, paint)
        }

        // ====== HEADER ======
        canvas.drawText("FieldFlow", MARGIN, y + 20f, titlePaint)
        y += 26f

        val billDate = "Bill Date: ${DateTimeUtils.formatDate(System.currentTimeMillis())}"
        drawRight(billDate, RIGHT_EDGE, y - 6f, bodySmallPaint)

        val typeLabel = when (reportType) {
            ShareReportType.FULL_STATEMENT -> "Full Statement"
            ShareReportType.PENDING_ONLY -> "Pending Dues"
            else -> "Work Bill"
        }
        canvas.drawText(typeLabel, MARGIN, y + 11f, subtitlePaint)
        y += 20f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, thickLinePaint)
        y += 14f

        // Customer info
        canvas.drawText(customer.name, MARGIN, y + 12f, sectionPaint)
        y += 18f
        val contactParts = listOfNotNull(
            customer.phoneNumber.ifBlank { null },
            customer.village.ifBlank { null }
        ).joinToString(" • ")
        if (contactParts.isNotEmpty()) {
            canvas.drawText(contactParts, MARGIN, y + 10f, bodyPaint)
            y += 14f
        }
        // Bill period
        if (period != null) {
            y += 4f
            canvas.drawText("Bill Period: ${period.label}", MARGIN, y + 10f, boldPaint)
            y += 14f
        }
        y += 8f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
        y += 12f

        // ====== BUILD WORK ROWS (date-grouped) ======
        val workRows = mutableListOf<WorkRow>()
        for (job in filteredJobs) {
            val segments = segmentsByJob[job.id].orEmpty()
            val date = DateTimeUtils.formatDate(job.createdAt)
            val work = job.machineType.displayName
            val meta = listOfNotNull(
                job.loadType,
                job.fieldName,
                job.routeLabel
            ).joinToString(" • ").ifBlank { null }

            if (segments.isNotEmpty()) {
                val grouped = segments.groupBy { Pair(it.type, it.rate) }
                var isFirstRow = true
                for ((key, group) in grouped) {
                    val (type, rate) = key
                    val totalQty = group.sumOf { it.quantity }
                    val totalAmt = group.sumOf { it.amount }
                    workRows.add(WorkRow(
                        date = date,
                        sortKey = job.createdAt,
                        work = work,
                        quantity = formatQuantity(type, totalQty, areaUnit),
                        rate = formatRate(type, rate, areaUnit),
                        amount = totalAmt,
                        amountStr = CalculationUtils.formatCurrencyShort(totalAmt),
                        meta = if (isFirstRow) meta else null
                    ))
                    isFirstRow = false
                }
            } else {
                workRows.add(WorkRow(
                    date = date,
                    sortKey = job.createdAt,
                    work = work,
                    quantity = formatLegacyQuantity(job, areaUnit),
                    rate = formatLegacyRate(job, areaUnit),
                    amount = job.totalAmount,
                    amountStr = CalculationUtils.formatCurrencyShort(job.totalAmount),
                    meta = meta
                ))
            }
        }
        // Sort by date (oldest first)
        workRows.sortBy { it.sortKey }

        // ====== WORK TABLE ======
        if (workRows.isNotEmpty()) {
            canvas.drawText("Work Summary", MARGIN, y + 12f, sectionPaint)
            y += 20f

            // Table header
            canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + 20f, tableHeaderBgPaint)
            var hx = MARGIN + 4f
            canvas.drawText("Date", hx, y + 14f, boldPaint)
            hx += COL_DATE
            canvas.drawText("Work", hx, y + 14f, boldPaint)
            hx += COL_WORK
            canvas.drawText("Qty", hx, y + 14f, boldPaint)
            hx += COL_QTY
            canvas.drawText("Rate", hx, y + 14f, boldPaint)
            drawRight("Total", RIGHT_EDGE - 4f, y + 14f, boldPaint)
            y += 24f
            canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
            y += 2f

            // Render rows grouped by date
            var lastDate = ""
            var rowIndex = 0
            val zebraPaint = Paint().apply {
                color = Color.rgb(248, 248, 252); style = Paint.Style.FILL
            }
            for (row in workRows) {
                val rowHeight = 18f + if (row.meta != null) 13f else 0f
                ensureSpace(rowHeight)

                // Date group header — show date only once per unique date
                val showDate = row.date != lastDate
                if (showDate && lastDate.isNotEmpty()) {
                    canvas.drawLine(MARGIN + 6f, y, RIGHT_EDGE - 6f, y, linePaint)
                    y += 3f
                    rowIndex = 0
                }

                // Zebra striping
                if (rowIndex % 2 == 1) {
                    canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + rowHeight, zebraPaint)
                }

                var rx = MARGIN + 4f
                if (showDate) {
                    canvas.drawText(truncateText(row.date, COL_DATE - 6f, datePaint), rx, y + 12f, datePaint)
                    lastDate = row.date
                }
                rx += COL_DATE
                canvas.drawText(truncateText(row.work, COL_WORK - 6f, bodyPaint), rx, y + 12f, bodyPaint)
                rx += COL_WORK
                canvas.drawText(row.quantity, rx, y + 12f, bodyPaint)
                rx += COL_QTY
                canvas.drawText(row.rate, rx, y + 12f, bodyPaint)
                drawRight(row.amountStr, RIGHT_EDGE - 4f, y + 12f, amountPaint)
                y += 18f

                // Metadata (load/field)
                if (row.meta != null) {
                    canvas.drawText(row.meta, MARGIN + COL_DATE + 4f, y + 9f, bodySmallPaint)
                    y += 13f
                }
                rowIndex++
            }

            // End of table line
            y += 2f
        } else {
            val msg = if (reportType == ShareReportType.PENDING_ONLY)
                "No pending work for this customer in selected period."
            else
                "No work found for selected period."
            canvas.drawText(msg, MARGIN, y + 12f, emptyPaint)
            y += 24f
        }

        // ====== TOTALS ======
        ensureSpace(90f)
        y += 6f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, thickLinePaint)
        y += 2f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, thickLinePaint)
        y += 16f

        val totalWorkAmount = filteredJobs.sumOf { it.totalAmount }
        val labelX = MARGIN + 8f
        val valueX = RIGHT_EDGE - 8f

        when (reportType) {
            ShareReportType.STANDARD_BILL -> {
                // STANDARD BILL: Only total work amount — clean invoice
                canvas.drawText("Total Work Amount", labelX, y + 13f, totalLabelPaint)
                drawRight(CalculationUtils.formatCurrency(totalWorkAmount), valueX, y + 13f, totalLabelPaint)
                y += 24f
            }

            ShareReportType.FULL_STATEMENT -> {
                // FULL STATEMENT: All-time summary first, then period subtotal
                val allTimeTotalWork = jobs.sumOf { it.totalAmount }
                val allTimePaid = jobs.sumOf { it.paidAmount }
                val allTimeDue = (allTimeTotalWork - allTimePaid).coerceAtLeast(0.0)

                // Section 1: All-Time Financial Summary
                canvas.drawText("All-Time Summary", labelX, y + 13f, sectionPaint)
                y += 22f

                canvas.drawText("Total Work", labelX, y + 12f, totalLabelPaint)
                drawRight(CalculationUtils.formatCurrency(allTimeTotalWork), valueX, y + 12f, totalLabelPaint)
                y += 20f

                canvas.drawText("Total Paid", labelX, y + 12f, paidLabelPaint)
                drawRight(CalculationUtils.formatCurrency(allTimePaid), valueX, y + 12f, paidLabelPaint)
                y += 18f

                canvas.drawLine(MARGIN + 8f, y, RIGHT_EDGE - 8f, y, linePaint)
                y += 14f

                if (allTimeDue > 0) {
                    canvas.drawText("Remaining Due", labelX, y + 14f, dueLabelPaint)
                    drawRight(CalculationUtils.formatCurrency(allTimeDue), valueX, y + 14f, dueLabelPaint)
                } else {
                    val clearedPaint = Paint().apply {
                        color = Color.rgb(0, 130, 0); textSize = 14f; isFakeBoldText = true; isAntiAlias = true
                    }
                    canvas.drawText("Remaining Due", labelX, y + 14f, clearedPaint)
                    drawRight("₹0.00 ✓", valueX, y + 14f, clearedPaint)
                }
                y += 24f

                // Section 2: This Period
                if (period != null) {
                    canvas.drawLine(MARGIN + 8f, y, RIGHT_EDGE - 8f, y, linePaint)
                    y += 14f
                    canvas.drawText("This Period", labelX, y + 12f, bodySmallPaint)
                    y += 16f
                    canvas.drawText("Work Done", labelX, y + 12f, boldPaint)
                    drawRight(CalculationUtils.formatCurrency(totalWorkAmount), valueX, y + 12f, boldPaint)
                    y += 22f
                }
            }

            ShareReportType.PENDING_ONLY -> {
                // PENDING ONLY: Collection-focused
                val pendingDue = filteredJobs.sumOf { (it.totalAmount - it.paidAmount).coerceAtLeast(0.0) }

                canvas.drawText("Total Pending Work", labelX, y + 13f, totalLabelPaint)
                drawRight(CalculationUtils.formatCurrency(totalWorkAmount), valueX, y + 13f, totalLabelPaint)
                y += 22f

                canvas.drawLine(MARGIN + 8f, y, RIGHT_EDGE - 8f, y, linePaint)
                y += 14f

                canvas.drawText("Amount Due", labelX, y + 14f, dueLabelPaint)
                drawRight(CalculationUtils.formatCurrency(pendingDue), valueX, y + 14f, dueLabelPaint)
                y += 24f
            }
        }

        // ====== PAYMENTS ======
        val hintPaint = Paint().apply {
            color = Color.GRAY; textSize = 8.5f; isAntiAlias = true; letterSpacing = 0.02f
        }

        if (reportType == ShareReportType.STANDARD_BILL && dateFilteredPayments.isNotEmpty()) {
            // Standard Bill: optional reference-only payment list
            ensureSpace(50f)
            y += 8f
            canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
            y += 14f

            canvas.drawText("Payments (Recent)", MARGIN, y + 12f, sectionPaint)
            y += 18f
            canvas.drawText("For reference only — not included in bill total", MARGIN + 2f, y + 9f, hintPaint)
            y += 16f

            for (payment in dateFilteredPayments) {
                ensureSpace(16f)
                val pDate = "${DateTimeUtils.formatDate(payment.paidAt)}, ${DateTimeUtils.formatTime(payment.paidAt)}"
                val pAmount = CalculationUtils.formatCurrencyShort(payment.amount)
                canvas.drawText("$pAmount — $pDate (${payment.method.displayName})", MARGIN + 8f, y + 11f, bodyPaint)
                y += 16f
            }

        } else if (reportType == ShareReportType.FULL_STATEMENT) {
            // Full Statement: structured payment table
            ensureSpace(50f)
            y += 8f
            canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
            y += 14f

            canvas.drawText("Payment History", MARGIN, y + 12f, sectionPaint)
            y += 20f

            if (dateFilteredPayments.isNotEmpty()) {
                canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + 20f, tableHeaderBgPaint)
                var phx = MARGIN + 4f
                canvas.drawText("Date & Time", phx, y + 14f, boldPaint)
                phx += PAY_COL_DATE
                canvas.drawText("Method", phx, y + 14f, boldPaint)
                phx += PAY_COL_METHOD
                canvas.drawText("Amount", phx, y + 14f, boldPaint)
                phx += PAY_COL_AMOUNT
                canvas.drawText("Note", phx, y + 14f, boldPaint)
                y += 24f
                canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
                y += 2f

                var payRowIdx = 0
                val payZebraPaint = Paint().apply {
                    color = Color.rgb(248, 248, 252); style = Paint.Style.FILL
                }
                for (payment in dateFilteredPayments) {
                    ensureSpace(18f)
                    if (payRowIdx % 2 == 1) {
                        canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + 18f, payZebraPaint)
                    }
                    val pDate = "${DateTimeUtils.formatDate(payment.paidAt)}, ${DateTimeUtils.formatTime(payment.paidAt)}"
                    var px = MARGIN + 4f
                    canvas.drawText(truncateText(pDate, PAY_COL_DATE - 6f, bodySmallPaint), px, y + 12f, bodySmallPaint)
                    px += PAY_COL_DATE
                    canvas.drawText(payment.method.displayName, px, y + 12f, bodyPaint)
                    px += PAY_COL_METHOD
                    canvas.drawText(CalculationUtils.formatCurrencyShort(payment.amount), px, y + 12f, boldPaint)
                    px += PAY_COL_AMOUNT
                    canvas.drawText(truncateText(payment.note ?: "—", PAY_COL_NOTE - 6f, bodySmallPaint), px, y + 12f, bodySmallPaint)
                    y += 18f
                    payRowIdx++
                }

                // Payment subtotal
                y += 4f
                canvas.drawLine(MARGIN + 10f, y, RIGHT_EDGE - 10f, y, linePaint)
                y += 12f
                val payTotal = dateFilteredPayments.sumOf { it.amount }
                canvas.drawText("Total Payments: ${dateFilteredPayments.size}", labelX, y + 11f, bodySmallPaint)
                drawRight(CalculationUtils.formatCurrency(payTotal), valueX, y + 11f, boldPaint)
                y += 16f
            } else {
                canvas.drawText("No payments recorded in this period", MARGIN + 8f, y + 11f, emptyPaint)
                y += 16f
            }
        }
        // PENDING_ONLY: no payment section

        // ====== FOOTER ======
        ensureSpace(40f)
        y += 12f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
        y += 14f
        val generatedDate = "Generated on: ${DateTimeUtils.formatDate(System.currentTimeMillis())} ${DateTimeUtils.formatTime(System.currentTimeMillis())}"
        canvas.drawText(generatedDate, MARGIN, y + 10f, bodySmallPaint)
        y += 14f
        canvas.drawText("Generated by FieldFlow", MARGIN, y + 10f, bodySmallPaint)

        // Finish last page
        document.finishPage(page)

        // Write to file
        val safeName = customer.name
            .replace(Regex("[^A-Za-z0-9 ]"), "")
            .trim()
            .replace(Regex("\\s+"), "_")
            .ifBlank { "Customer" }
        val dateStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault())
            .format(java.util.Date())
        val docType = when (reportType) {
            ShareReportType.FULL_STATEMENT -> "Statement"
            ShareReportType.PENDING_ONLY -> "Pending"
            else -> "Bill"
        }
        val fileName = "FieldFlow_${docType}_${safeName}_${dateStr}.pdf"
        val file = File(context.cacheDir, fileName)
        FileOutputStream(file).use { document.writeTo(it) }
        document.close()

        return file
    }

    // ============ FORMAT HELPERS ============

    private fun formatQuantity(type: PricingMode, qty: Double, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return CalculationUtils.formatQuantityLabel(type, qty, areaUnit)
    }

    private fun formatRate(type: PricingMode, rate: Double, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return if (type == PricingMode.TIME) CalculationUtils.formatDualRate(rate)
        else CalculationUtils.formatRateCompact(rate, type, areaUnit)
    }

    private fun formatLegacyQuantity(job: JobEntity, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return WorkQuantitySummary.fromJobEntity(job, areaUnit).compact
    }

    private fun formatLegacyRate(job: JobEntity, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return CalculationUtils.formatRateCompact(job.rate, job.pricingMode, areaUnit)
    }

    private fun truncateText(text: String, maxWidth: Float, paint: Paint): String {
        if (paint.measureText(text) <= maxWidth) return text
        var truncated = text
        while (truncated.isNotEmpty() && paint.measureText("$truncated…") > maxWidth) {
            truncated = truncated.dropLast(1)
        }
        return "$truncated…"
    }

    fun createShareIntent(context: Context, file: File): Intent {
        val uri = FileProvider.getUriForFile(
            context,
            "${context.packageName}.fileprovider",
            file
        )
        return Intent(Intent.ACTION_SEND).apply {
            type = "application/pdf"
            putExtra(Intent.EXTRA_STREAM, uri)
            putExtra(Intent.EXTRA_SUBJECT, "FieldFlow Bill - ${file.nameWithoutExtension}")
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
    }

    data class SavedPdf(val uri: Uri?, val displayName: String)

    fun savePdfToDownloads(context: Context, sourceFile: File): SavedPdf {
        val displayName = sourceFile.name
        val resolver = context.contentResolver

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, displayName)
                put(MediaStore.MediaColumns.MIME_TYPE, "application/pdf")
                put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS)
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
            val collection = MediaStore.Files.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val itemUri = resolver.insert(collection, values)
                ?: return SavedPdf(null, displayName)
            try {
                resolver.openOutputStream(itemUri)?.use { out ->
                    sourceFile.inputStream().use { input -> input.copyTo(out) }
                }
                values.clear()
                values.put(MediaStore.MediaColumns.IS_PENDING, 0)
                resolver.update(itemUri, values, null, null)
                return SavedPdf(itemUri, displayName)
            } catch (e: Exception) {
                runCatching { resolver.delete(itemUri, null, null) }
                throw e
            }
        } else {
            val downloads = Environment.getExternalStoragePublicDirectory(
                Environment.DIRECTORY_DOWNLOADS
            )
            if (!downloads.exists()) downloads.mkdirs()
            val target = File(downloads, displayName)
            sourceFile.inputStream().use { input ->
                FileOutputStream(target).use { out -> input.copyTo(out) }
            }
            return SavedPdf(Uri.fromFile(target), displayName)
        }
    }
}

package com.example.fieldtrack.util

import android.content.ContentValues
import android.content.Context
import android.content.Intent
import android.graphics.Color
import android.graphics.Paint
import android.graphics.pdf.PdfDocument
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import androidx.core.content.FileProvider
import com.example.fieldtrack.data.local.entity.CustomerEntity
import com.example.fieldtrack.data.local.entity.JobEntity
import com.example.fieldtrack.data.local.entity.PaymentEntity
import com.example.fieldtrack.data.local.entity.PricingMode
import com.example.fieldtrack.data.model.WorkSegment
import com.example.fieldtrack.ui.screens.customer.BillPeriod
import com.example.fieldtrack.ui.screens.customer.ShareReportType
import java.io.File
import java.io.FileOutputStream
import com.example.fieldtrack.domain.billing.WorkQuantitySummary
import com.example.fieldtrack.domain.billing.AreaUnit

/**
 * Generates clean, structured PDF bills aligned with the customer-level payment model.
 *
 * Three document types:
 * 1. STANDARD BILL — work table (date-grouped) + totals + simple payment list
 * 2. FULL STATEMENT — work table (date-grouped) + totals + structured payment history table
 * 3. PENDING ONLY — only unpaid jobs + due amount (no payment history)
 *
 * Work rows are grouped by date — if same date has multiple jobs/segments,
 * date is shown once, subsequent rows leave date column blank.
 */
object PdfGenerator {

    // Page dimensions (A4 at 72 DPI)
    private const val PAGE_WIDTH = 595
    private const val PAGE_HEIGHT = 842
    private const val MARGIN = 40f
    private const val CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN
    private const val RIGHT_EDGE = PAGE_WIDTH - MARGIN

    // Work table column widths
    private val COL_DATE = CONTENT_WIDTH * 0.16f
    private val COL_WORK = CONTENT_WIDTH * 0.22f
    private val COL_QTY = CONTENT_WIDTH * 0.20f

    // Payment table column widths (full statement)
    private val PAY_COL_DATE = CONTENT_WIDTH * 0.30f
    private val PAY_COL_METHOD = CONTENT_WIDTH * 0.18f
    private val PAY_COL_AMOUNT = CONTENT_WIDTH * 0.22f
    private val PAY_COL_NOTE = CONTENT_WIDTH * 0.30f

    /**
     * A single work row for the PDF table.
     * Pre-built from segments or legacy job fields, then sorted/grouped by date.
     */
    private data class WorkRow(
        val date: String,      // formatted date string
        val sortKey: Long,     // createdAt for sorting
        val work: String,      // machine type
        val quantity: String,  // "3 Loads", "2h 30m"
        val rate: String,      // "₹500", "₹200/min"
        val amount: Double,    // numeric for totalling
        val amountStr: String, // formatted "₹1,500"
        val meta: String? = null // "Load: Sand • Field: North"
    )

    fun generateCustomerPdf(
        context: Context,
        customer: CustomerEntity,
        jobs: List<JobEntity>,
        reportType: ShareReportType = ShareReportType.STANDARD_BILL,
        customerPayments: List<PaymentEntity> = emptyList(),
        segmentsByJob: Map<Long, List<WorkSegment>> = emptyMap(),
        period: BillPeriod? = null,
        areaUnit: AreaUnit = AreaUnit.ACRE
    ): File {
        // Date-range filter
        val rangeStart = period?.startMillis ?: 0L
        val rangeEnd = period?.endMillis ?: Long.MAX_VALUE
        val dateFilteredJobs = jobs.filter { it.createdAt in rangeStart..rangeEnd }
        val dateFilteredPayments = customerPayments.filter { it.paidAt in rangeStart..rangeEnd }

        // Report-type filter (PENDING_ONLY)
        val filteredJobs = if (reportType == ShareReportType.PENDING_ONLY) {
            dateFilteredJobs.filter { it.paidAmount < it.totalAmount }
        } else {
            dateFilteredJobs
        }

        val document = PdfDocument()
        var pageNumber = 1
        var pageInfo = PdfDocument.PageInfo.Builder(PAGE_WIDTH, PAGE_HEIGHT, pageNumber).create()
        var page = document.startPage(pageInfo)
        var canvas = page.canvas
        var y = MARGIN

        // ============ PAINTS ============
        val titlePaint = Paint().apply {
            color = Color.BLACK; textSize = 20f; isFakeBoldText = true; isAntiAlias = true
        }
        val subtitlePaint = Paint().apply {
            color = Color.DKGRAY; textSize = 11f; isAntiAlias = true
        }
        val sectionPaint = Paint().apply {
            color = Color.BLACK; textSize = 13f; isFakeBoldText = true; isAntiAlias = true
        }
        val bodyPaint = Paint().apply {
            color = Color.BLACK; textSize = 11f; isAntiAlias = true
        }
        val bodySmallPaint = Paint().apply {
            color = Color.DKGRAY; textSize = 10f; isAntiAlias = true
        }
        val boldPaint = Paint().apply {
            color = Color.BLACK; textSize = 11f; isFakeBoldText = true; isAntiAlias = true
        }
        val datePaint = Paint().apply {
            color = Color.rgb(80, 80, 80); textSize = 10f; isFakeBoldText = true; isAntiAlias = true
        }
        val amountPaint = Paint().apply {
            color = Color.BLACK; textSize = 11f; isFakeBoldText = true; isAntiAlias = true
        }
        val totalLabelPaint = Paint().apply {
            color = Color.BLACK; textSize = 13f; isFakeBoldText = true; isAntiAlias = true
        }
        val dueLabelPaint = Paint().apply {
            color = Color.rgb(180, 0, 0); textSize = 14f; isFakeBoldText = true; isAntiAlias = true
        }
        val paidLabelPaint = Paint().apply {
            color = Color.rgb(0, 130, 0); textSize = 12f; isAntiAlias = true
        }
        val linePaint = Paint().apply {
            color = Color.LTGRAY; strokeWidth = 1f
        }
        val thickLinePaint = Paint().apply {
            color = Color.DKGRAY; strokeWidth = 1.5f
        }
        val tableHeaderBgPaint = Paint().apply {
            color = Color.rgb(235, 235, 240); style = Paint.Style.FILL
        }
        val emptyPaint = Paint().apply {
            color = Color.GRAY; textSize = 11f; isAntiAlias = true
        }

        // ============ HELPERS ============
        fun ensureSpace(needed: Float) {
            if (y + needed > PAGE_HEIGHT - MARGIN - 30) {
                document.finishPage(page)
                pageNumber++
                pageInfo = PdfDocument.PageInfo.Builder(PAGE_WIDTH, PAGE_HEIGHT, pageNumber).create()
                page = document.startPage(pageInfo)
                canvas = page.canvas
                y = MARGIN
            }
        }

        fun drawRight(text: String, rightX: Float, yPos: Float, paint: Paint) {
            val w = paint.measureText(text)
            canvas.drawText(text, rightX - w, yPos, paint)
        }

        // ====== HEADER ======
        canvas.drawText("FieldFlow", MARGIN, y + 20f, titlePaint)
        y += 26f

        val billDate = "Bill Date: ${DateTimeUtils.formatDate(System.currentTimeMillis())}"
        drawRight(billDate, RIGHT_EDGE, y - 6f, bodySmallPaint)

        val typeLabel = when (reportType) {
            ShareReportType.FULL_STATEMENT -> "Full Statement"
            ShareReportType.PENDING_ONLY -> "Pending Dues"
            else -> "Work Bill"
        }
        canvas.drawText(typeLabel, MARGIN, y + 11f, subtitlePaint)
        y += 20f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, thickLinePaint)
        y += 14f

        // Customer info
        canvas.drawText(customer.name, MARGIN, y + 12f, sectionPaint)
        y += 18f
        val contactParts = listOfNotNull(
            customer.phoneNumber.ifBlank { null },
            customer.village.ifBlank { null }
        ).joinToString(" • ")
        if (contactParts.isNotEmpty()) {
            canvas.drawText(contactParts, MARGIN, y + 10f, bodyPaint)
            y += 14f
        }
        // Bill period
        if (period != null) {
            y += 4f
            canvas.drawText("Bill Period: ${period.label}", MARGIN, y + 10f, boldPaint)
            y += 14f
        }
        y += 8f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
        y += 12f

        // ====== BUILD WORK ROWS (date-grouped) ======
        val workRows = mutableListOf<WorkRow>()
        for (job in filteredJobs) {
            val segments = segmentsByJob[job.id].orEmpty()
            val date = DateTimeUtils.formatDate(job.createdAt)
            val work = job.machineType.displayName
            val meta = listOfNotNull(
                job.loadType,
                job.fieldName,
                job.routeLabel
            ).joinToString(" • ").ifBlank { null }

            if (segments.isNotEmpty()) {
                val grouped = segments.groupBy { Pair(it.type, it.rate) }
                var isFirstRow = true
                for ((key, group) in grouped) {
                    val (type, rate) = key
                    val totalQty = group.sumOf { it.quantity }
                    val totalAmt = group.sumOf { it.amount }
                    workRows.add(WorkRow(
                        date = date,
                        sortKey = job.createdAt,
                        work = work,
                        quantity = formatQuantity(type, totalQty, areaUnit),
                        rate = formatRate(type, rate, areaUnit),
                        amount = totalAmt,
                        amountStr = CalculationUtils.formatCurrencyShort(totalAmt),
                        meta = if (isFirstRow) meta else null
                    ))
                    isFirstRow = false
                }
            } else {
                workRows.add(WorkRow(
                    date = date,
                    sortKey = job.createdAt,
                    work = work,
                    quantity = formatLegacyQuantity(job, areaUnit),
                    rate = formatLegacyRate(job, areaUnit),
                    amount = job.totalAmount,
                    amountStr = CalculationUtils.formatCurrencyShort(job.totalAmount),
                    meta = meta
                ))
            }
        }
        // Sort by date (oldest first)
        workRows.sortBy { it.sortKey }

        // ====== WORK TABLE ======
        if (workRows.isNotEmpty()) {
            canvas.drawText("Work Summary", MARGIN, y + 12f, sectionPaint)
            y += 20f

            // Table header
            canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + 20f, tableHeaderBgPaint)
            var hx = MARGIN + 4f
            canvas.drawText("Date", hx, y + 14f, boldPaint)
            hx += COL_DATE
            canvas.drawText("Work", hx, y + 14f, boldPaint)
            hx += COL_WORK
            canvas.drawText("Qty", hx, y + 14f, boldPaint)
            hx += COL_QTY
            canvas.drawText("Rate", hx, y + 14f, boldPaint)
            drawRight("Total", RIGHT_EDGE - 4f, y + 14f, boldPaint)
            y += 24f
            canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
            y += 2f

            // Render rows grouped by date
            var lastDate = ""
            var rowIndex = 0
            val zebraPaint = Paint().apply {
                color = Color.rgb(248, 248, 252); style = Paint.Style.FILL
            }
            for (row in workRows) {
                val rowHeight = 18f + if (row.meta != null) 13f else 0f
                ensureSpace(rowHeight)

                // Date group header — show date only once per unique date
                val showDate = row.date != lastDate
                if (showDate && lastDate.isNotEmpty()) {
                    canvas.drawLine(MARGIN + 6f, y, RIGHT_EDGE - 6f, y, linePaint)
                    y += 3f
                    rowIndex = 0
                }

                // Zebra striping
                if (rowIndex % 2 == 1) {
                    canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + rowHeight, zebraPaint)
                }

                var rx = MARGIN + 4f
                if (showDate) {
                    canvas.drawText(truncateText(row.date, COL_DATE - 6f, datePaint), rx, y + 12f, datePaint)
                    lastDate = row.date
                }
                rx += COL_DATE
                canvas.drawText(truncateText(row.work, COL_WORK - 6f, bodyPaint), rx, y + 12f, bodyPaint)
                rx += COL_WORK
                canvas.drawText(row.quantity, rx, y + 12f, bodyPaint)
                rx += COL_QTY
                canvas.drawText(row.rate, rx, y + 12f, bodyPaint)
                drawRight(row.amountStr, RIGHT_EDGE - 4f, y + 12f, amountPaint)
                y += 18f

                // Metadata (load/field)
                if (row.meta != null) {
                    canvas.drawText(row.meta, MARGIN + COL_DATE + 4f, y + 9f, bodySmallPaint)
                    y += 13f
                }
                rowIndex++
            }

            // End of table line
            y += 2f
        } else {
            val msg = if (reportType == ShareReportType.PENDING_ONLY)
                "No pending work for this customer in selected period."
            else
                "No work found for selected period."
            canvas.drawText(msg, MARGIN, y + 12f, emptyPaint)
            y += 24f
        }

        // ====== TOTALS ======
        ensureSpace(90f)
        y += 6f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, thickLinePaint)
        y += 2f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, thickLinePaint)
        y += 16f

        val totalWorkAmount = filteredJobs.sumOf { it.totalAmount }
        val labelX = MARGIN + 8f
        val valueX = RIGHT_EDGE - 8f

        when (reportType) {
            ShareReportType.STANDARD_BILL -> {
                // STANDARD BILL: Only total work amount — clean invoice
                canvas.drawText("Total Work Amount", labelX, y + 13f, totalLabelPaint)
                drawRight(CalculationUtils.formatCurrency(totalWorkAmount), valueX, y + 13f, totalLabelPaint)
                y += 24f
            }

            ShareReportType.FULL_STATEMENT -> {
                // FULL STATEMENT: All-time summary first, then period subtotal
                val allTimeTotalWork = jobs.sumOf { it.totalAmount }
                val allTimePaid = jobs.sumOf { it.paidAmount }
                val allTimeDue = (allTimeTotalWork - allTimePaid).coerceAtLeast(0.0)

                // Section 1: All-Time Financial Summary
                canvas.drawText("All-Time Summary", labelX, y + 13f, sectionPaint)
                y += 22f

                canvas.drawText("Total Work", labelX, y + 12f, totalLabelPaint)
                drawRight(CalculationUtils.formatCurrency(allTimeTotalWork), valueX, y + 12f, totalLabelPaint)
                y += 20f

                canvas.drawText("Total Paid", labelX, y + 12f, paidLabelPaint)
                drawRight(CalculationUtils.formatCurrency(allTimePaid), valueX, y + 12f, paidLabelPaint)
                y += 18f

                canvas.drawLine(MARGIN + 8f, y, RIGHT_EDGE - 8f, y, linePaint)
                y += 14f

                if (allTimeDue > 0) {
                    canvas.drawText("Remaining Due", labelX, y + 14f, dueLabelPaint)
                    drawRight(CalculationUtils.formatCurrency(allTimeDue), valueX, y + 14f, dueLabelPaint)
                } else {
                    val clearedPaint = Paint().apply {
                        color = Color.rgb(0, 130, 0); textSize = 14f; isFakeBoldText = true; isAntiAlias = true
                    }
                    canvas.drawText("Remaining Due", labelX, y + 14f, clearedPaint)
                    drawRight("₹0.00 ✓", valueX, y + 14f, clearedPaint)
                }
                y += 24f

                // Section 2: This Period
                if (period != null) {
                    canvas.drawLine(MARGIN + 8f, y, RIGHT_EDGE - 8f, y, linePaint)
                    y += 14f
                    canvas.drawText("This Period", labelX, y + 12f, bodySmallPaint)
                    y += 16f
                    canvas.drawText("Work Done", labelX, y + 12f, boldPaint)
                    drawRight(CalculationUtils.formatCurrency(totalWorkAmount), valueX, y + 12f, boldPaint)
                    y += 22f
                }
            }

            ShareReportType.PENDING_ONLY -> {
                // PENDING ONLY: Collection-focused
                val pendingDue = filteredJobs.sumOf { (it.totalAmount - it.paidAmount).coerceAtLeast(0.0) }

                canvas.drawText("Total Pending Work", labelX, y + 13f, totalLabelPaint)
                drawRight(CalculationUtils.formatCurrency(totalWorkAmount), valueX, y + 13f, totalLabelPaint)
                y += 22f

                canvas.drawLine(MARGIN + 8f, y, RIGHT_EDGE - 8f, y, linePaint)
                y += 14f

                canvas.drawText("Amount Due", labelX, y + 14f, dueLabelPaint)
                drawRight(CalculationUtils.formatCurrency(pendingDue), valueX, y + 14f, dueLabelPaint)
                y += 24f
            }
        }

        // ====== PAYMENTS ======
        val hintPaint = Paint().apply {
            color = Color.GRAY; textSize = 8.5f; isAntiAlias = true; letterSpacing = 0.02f
        }

        if (reportType == ShareReportType.STANDARD_BILL && dateFilteredPayments.isNotEmpty()) {
            // Standard Bill: optional reference-only payment list
            ensureSpace(50f)
            y += 8f
            canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
            y += 14f

            canvas.drawText("Payments (Recent)", MARGIN, y + 12f, sectionPaint)
            y += 18f
            canvas.drawText("For reference only — not included in bill total", MARGIN + 2f, y + 9f, hintPaint)
            y += 16f

            for (payment in dateFilteredPayments) {
                ensureSpace(16f)
                val pDate = "${DateTimeUtils.formatDate(payment.paidAt)}, ${DateTimeUtils.formatTime(payment.paidAt)}"
                val pAmount = CalculationUtils.formatCurrencyShort(payment.amount)
                canvas.drawText("$pAmount — $pDate (${payment.method.displayName})", MARGIN + 8f, y + 11f, bodyPaint)
                y += 16f
            }

        } else if (reportType == ShareReportType.FULL_STATEMENT) {
            // Full Statement: structured payment table
            ensureSpace(50f)
            y += 8f
            canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
            y += 14f

            canvas.drawText("Payment History", MARGIN, y + 12f, sectionPaint)
            y += 20f

            if (dateFilteredPayments.isNotEmpty()) {
                canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + 20f, tableHeaderBgPaint)
                var phx = MARGIN + 4f
                canvas.drawText("Date & Time", phx, y + 14f, boldPaint)
                phx += PAY_COL_DATE
                canvas.drawText("Method", phx, y + 14f, boldPaint)
                phx += PAY_COL_METHOD
                canvas.drawText("Amount", phx, y + 14f, boldPaint)
                phx += PAY_COL_AMOUNT
                canvas.drawText("Note", phx, y + 14f, boldPaint)
                y += 24f
                canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
                y += 2f

                var payRowIdx = 0
                val payZebraPaint = Paint().apply {
                    color = Color.rgb(248, 248, 252); style = Paint.Style.FILL
                }
                for (payment in dateFilteredPayments) {
                    ensureSpace(18f)
                    if (payRowIdx % 2 == 1) {
                        canvas.drawRect(MARGIN, y, RIGHT_EDGE, y + 18f, payZebraPaint)
                    }
                    val pDate = "${DateTimeUtils.formatDate(payment.paidAt)}, ${DateTimeUtils.formatTime(payment.paidAt)}"
                    var px = MARGIN + 4f
                    canvas.drawText(truncateText(pDate, PAY_COL_DATE - 6f, bodySmallPaint), px, y + 12f, bodySmallPaint)
                    px += PAY_COL_DATE
                    canvas.drawText(payment.method.displayName, px, y + 12f, bodyPaint)
                    px += PAY_COL_METHOD
                    canvas.drawText(CalculationUtils.formatCurrencyShort(payment.amount), px, y + 12f, boldPaint)
                    px += PAY_COL_AMOUNT
                    canvas.drawText(truncateText(payment.note ?: "—", PAY_COL_NOTE - 6f, bodySmallPaint), px, y + 12f, bodySmallPaint)
                    y += 18f
                    payRowIdx++
                }

                // Payment subtotal
                y += 4f
                canvas.drawLine(MARGIN + 10f, y, RIGHT_EDGE - 10f, y, linePaint)
                y += 12f
                val payTotal = dateFilteredPayments.sumOf { it.amount }
                canvas.drawText("Total Payments: ${dateFilteredPayments.size}", labelX, y + 11f, bodySmallPaint)
                drawRight(CalculationUtils.formatCurrency(payTotal), valueX, y + 11f, boldPaint)
                y += 16f
            } else {
                canvas.drawText("No payments recorded in this period", MARGIN + 8f, y + 11f, emptyPaint)
                y += 16f
            }
        }
        // PENDING_ONLY: no payment section

        // ====== FOOTER ======
        ensureSpace(40f)
        y += 12f
        canvas.drawLine(MARGIN, y, RIGHT_EDGE, y, linePaint)
        y += 14f
        val generatedDate = "Generated on: ${DateTimeUtils.formatDate(System.currentTimeMillis())} ${DateTimeUtils.formatTime(System.currentTimeMillis())}"
        canvas.drawText(generatedDate, MARGIN, y + 10f, bodySmallPaint)
        y += 14f
        canvas.drawText("Generated by FieldFlow", MARGIN, y + 10f, bodySmallPaint)

        // Finish last page
        document.finishPage(page)

        // Write to file
        val safeName = customer.name
            .replace(Regex("[^A-Za-z0-9 ]"), "")
            .trim()
            .replace(Regex("\\s+"), "_")
            .ifBlank { "Customer" }
        val dateStr = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault())
            .format(java.util.Date())
        val docType = when (reportType) {
            ShareReportType.FULL_STATEMENT -> "Statement"
            ShareReportType.PENDING_ONLY -> "Pending"
            else -> "Bill"
        }
        val fileName = "FieldFlow_${docType}_${safeName}_${dateStr}.pdf"
        val file = File(context.cacheDir, fileName)
        FileOutputStream(file).use { document.writeTo(it) }
        document.close()

        return file
    }

    // ============ FORMAT HELPERS ============

    private fun formatQuantity(type: PricingMode, qty: Double, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return CalculationUtils.formatQuantityLabel(type, qty, areaUnit)
    }

    private fun formatRate(type: PricingMode, rate: Double, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return if (type == PricingMode.TIME) CalculationUtils.formatDualRate(rate)
        else CalculationUtils.formatRateCompact(rate, type, areaUnit)
    }

    private fun formatLegacyQuantity(job: JobEntity, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return WorkQuantitySummary.fromJobEntity(job, areaUnit).compact
    }

    private fun formatLegacyRate(job: JobEntity, areaUnit: AreaUnit = AreaUnit.ACRE): String {
        return CalculationUtils.formatRateCompact(job.rate, job.pricingMode, areaUnit)
    }

    private fun truncateText(text: String, maxWidth: Float, paint: Paint): String {
        if (paint.measureText(text) <= maxWidth) return text
        var truncated = text
        while (truncated.isNotEmpty() && paint.measureText("$truncated…") > maxWidth) {
            truncated = truncated.dropLast(1)
        }
        return "$truncated…"
    }

    fun createShareIntent(context: Context, file: File): Intent {
        val uri = FileProvider.getUriForFile(
            context,
            "${context.packageName}.fileprovider",
            file
        )
        return Intent(Intent.ACTION_SEND).apply {
            type = "application/pdf"
            putExtra(Intent.EXTRA_STREAM, uri)
            putExtra(Intent.EXTRA_SUBJECT, "FieldFlow Bill - ${file.nameWithoutExtension}")
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
    }

    data class SavedPdf(val uri: Uri?, val displayName: String)

    fun savePdfToDownloads(context: Context, sourceFile: File): SavedPdf {
        val displayName = sourceFile.name
        val resolver = context.contentResolver

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            val values = ContentValues().apply {
                put(MediaStore.MediaColumns.DISPLAY_NAME, displayName)
                put(MediaStore.MediaColumns.MIME_TYPE, "application/pdf")
                put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS)
                put(MediaStore.MediaColumns.IS_PENDING, 1)
            }
            val collection = MediaStore.Files.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val itemUri = resolver.insert(collection, values)
                ?: return SavedPdf(null, displayName)
            try {
                resolver.openOutputStream(itemUri)?.use { out ->
                    sourceFile.inputStream().use { input -> input.copyTo(out) }
                }
                values.clear()
                values.put(MediaStore.MediaColumns.IS_PENDING, 0)
                resolver.update(itemUri, values, null, null)
                return SavedPdf(itemUri, displayName)
            } catch (e: Exception) {
                runCatching { resolver.delete(itemUri, null, null) }
                throw e
            }
        } else {
            val downloads = Environment.getExternalStoragePublicDirectory(
                Environment.DIRECTORY_DOWNLOADS
            )
            if (!downloads.exists()) downloads.mkdirs()
            val target = File(downloads, displayName)
            sourceFile.inputStream().use { input ->
                FileOutputStream(target).use { out -> input.copyTo(out) }
            }
            return SavedPdf(Uri.fromFile(target), displayName)
        }
    }
}

package com.example.fieldtrack.ui.screens.newjob

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.text.KeyboardActions
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.focus.FocusRequester
import androidx.compose.ui.focus.focusRequester
import androidx.compose.ui.platform.LocalSoftwareKeyboardController
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import com.example.fieldtrack.data.local.entity.PaymentMethod
import com.example.fieldtrack.data.model.PaymentSnapshot
import com.example.fieldtrack.util.CalculationUtils

/**
 * Quick Payment bottom sheet — shown after tapping " Paid" on completion sheet.
 * Ultra-lightweight: no accounting jargon.
 *
 * Options:
 * - Full Amount (one tap)
 * - Partial Amount (quick input)
 * - Mark Pending (dismiss without payment)
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun QuickPaymentSheet(
    totalAmount: Double,
    onPaymentRecorded: (PaymentSnapshot) -> Unit,
    onDismiss: () -> Unit
) {
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    var showPartialInput by remember { mutableStateOf(false) }
    var partialAmountInput by remember { mutableStateOf("") }
    val focusRequester = remember { FocusRequester() }
    val keyboardController = LocalSoftwareKeyboardController.current

    val totalFormatted = CalculationUtils.formatCurrencyShort(totalAmount)

    ModalBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = sheetState
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header
            Text(
                text = "Payment",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = totalFormatted,
                style = MaterialTheme.typography.headlineSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(24.dp))

            if (!showPartialInput) {
                // Main options
                Button(
                    onClick = {
                        val snapshot = PaymentSnapshot.fullPayment(
                            totalAmount = totalAmount,
                            method = PaymentMethod.CASH
                        )
                        onPaymentRecorded(snapshot)
                    },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text(
                        text = "✔ Full Amount Collected",
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(modifier = Modifier.height(12.dp))

                FilledTonalButton(
                    onClick = { showPartialInput = true },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("◐ Partial Amount")
                }

                Spacer(modifier = Modifier.height(12.dp))

                OutlinedButton(
                    onClick = {
                        val snapshot = PaymentSnapshot.pending(totalAmount = totalAmount)
                        onPaymentRecorded(snapshot)
                    },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("○ Collect Later")
                }
            } else {
                // Partial amount input
                Text(
                    text = "Enter amount received",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )

                Spacer(modifier = Modifier.height(12.dp))

                OutlinedTextField(
                    value = partialAmountInput,
                    onValueChange = { value ->
                        partialAmountInput = value.filter { it.isDigit() || it == '.' }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .focusRequester(focusRequester),
                    label = { Text("Amount (₹)") },
                    prefix = { Text("₹") },
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Number,
                        imeAction = ImeAction.Done
                    ),
                    keyboardActions = KeyboardActions(
                        onDone = {
                            keyboardController?.hide()
                            val amount = partialAmountInput.toDoubleOrNull()
                            if (amount != null && amount > 0 && amount < totalAmount) {
                                val snapshot = PaymentSnapshot.partialPayment(
                                    totalAmount = totalAmount,
                                    paidAmount = amount,
                                    method = PaymentMethod.CASH
                                )
                                onPaymentRecorded(snapshot)
                            }
                        }
                    ),
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(16.dp))

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    OutlinedButton(
                        onClick = { showPartialInput = false },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text("Back")
                    }

                    Button(
                        onClick = {
                            keyboardController?.hide()
                            val amount = partialAmountInput.toDoubleOrNull()
                            if (amount != null && amount > 0 && amount <= totalAmount) {
                                val status = if (amount >= totalAmount) {
                                    PaymentSnapshot.fullPayment(totalAmount, PaymentMethod.CASH)
                                } else {
                                    PaymentSnapshot.partialPayment(totalAmount, amount, PaymentMethod.CASH)
                                }
                                onPaymentRecorded(status)
                            }
                        },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp),
                        enabled = partialAmountInput.toDoubleOrNull()?.let { it > 0 } == true
                    ) {
                        Text("Confirm", fontWeight = FontWeight.Bold)
                    }
                }

                // Auto-focus the input field
                LaunchedEffect(Unit) {
                    focusRequester.requestFocus()
                }
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

package com.example.fieldtrack.ui.screens.newjob

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.text.KeyboardActions
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.focus.FocusRequester
import androidx.compose.ui.focus.focusRequester
import androidx.compose.ui.platform.LocalSoftwareKeyboardController
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import com.example.fieldtrack.R
import com.example.fieldtrack.data.local.entity.PaymentMethod
import com.example.fieldtrack.data.model.PaymentSnapshot
import com.example.fieldtrack.util.CalculationUtils

/**
 * Quick Payment bottom sheet — shown after tapping " Paid" on completion sheet.
 * Ultra-lightweight: no accounting jargon.
 *
 * Options:
 * - Full Amount (one tap)
 * - Partial Amount (quick input)
 * - Mark Pending (dismiss without payment)
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun QuickPaymentSheet(
    totalAmount: Double,
    onPaymentRecorded: (PaymentSnapshot) -> Unit,
    onDismiss: () -> Unit
) {
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)
    var showPartialInput by remember { mutableStateOf(false) }
    var partialAmountInput by remember { mutableStateOf("") }
    val focusRequester = remember { FocusRequester() }
    val keyboardController = LocalSoftwareKeyboardController.current

    val totalFormatted = CalculationUtils.formatCurrencyShort(totalAmount)

    ModalBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = sheetState
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header
            Text(
                text = "Payment",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = totalFormatted,
                style = MaterialTheme.typography.headlineSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(24.dp))

            if (!showPartialInput) {
                // Main options
                Button(
                    onClick = {
                        val snapshot = PaymentSnapshot.fullPayment(
                            totalAmount = totalAmount,
                            method = PaymentMethod.CASH
                        )
                        onPaymentRecorded(snapshot)
                    },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text(
                        text = "✔ Full Amount Collected",
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(modifier = Modifier.height(12.dp))

                FilledTonalButton(
                    onClick = { showPartialInput = true },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("◐ Partial Amount")
                }

                Spacer(modifier = Modifier.height(12.dp))

                OutlinedButton(
                    onClick = {
                        val snapshot = PaymentSnapshot.pending(totalAmount = totalAmount)
                        onPaymentRecorded(snapshot)
                    },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("○ Collect Later")
                }
            } else {
                // Partial amount input
                Text(
                    text = "Enter amount received",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )

                Spacer(modifier = Modifier.height(12.dp))

                OutlinedTextField(
                    value = partialAmountInput,
                    onValueChange = { value ->
                        partialAmountInput = value.filter { it.isDigit() || it == '.' }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .focusRequester(focusRequester),
                    label = { Text("Amount (₹)") },
                    prefix = { Text("₹") },
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Number,
                        imeAction = ImeAction.Done
                    ),
                    keyboardActions = KeyboardActions(
                        onDone = {
                            keyboardController?.hide()
                            val amount = partialAmountInput.toDoubleOrNull()
                            if (amount != null && amount > 0 && amount < totalAmount) {
                                val snapshot = PaymentSnapshot.partialPayment(
                                    totalAmount = totalAmount,
                                    paidAmount = amount,
                                    method = PaymentMethod.CASH
                                )
                                onPaymentRecorded(snapshot)
                            }
                        }
                    ),
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(16.dp))

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    OutlinedButton(
                        onClick = { showPartialInput = false },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text("Back")
                    }

                    Button(
                        onClick = {
                            keyboardController?.hide()
                            val amount = partialAmountInput.toDoubleOrNull()
                            if (amount != null && amount > 0 && amount <= totalAmount) {
                                val status = if (amount >= totalAmount) {
                                    PaymentSnapshot.fullPayment(totalAmount, PaymentMethod.CASH)
                                } else {
                                    PaymentSnapshot.partialPayment(totalAmount, amount, PaymentMethod.CASH)
                                }
                                onPaymentRecorded(status)
                            }
                        },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp),
                        enabled = partialAmountInput.toDoubleOrNull()?.let { it > 0 } == true
                    ) {
                        Text("Confirm", fontWeight = FontWeight.Bold)
                    }
                }

                // Auto-focus the input field
                LaunchedEffect(Unit) {
                    focusRequester.requestFocus()
                }
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

package com.example.fieldtrack.domain.recovery

import com.example.fieldtrack.domain.job.JobPhase

/**
 * BEHAVIORAL DETERMINISM — PART 4: Recovery Reproducibility.
 *
 * Defines deterministic recovery scenarios for simulation and testing.
 * Recovery behavior becomes replay-safe — same inputs always produce
 * same recovery outcomes.
 *
 * Pure logic, zero Android dependencies, fully testable.
 */
object RecoveryReplayScenario {

    /**
     * Classify an interruption scenario based on observable state.
     * Returns the deterministic recovery action to take.
     */
    fun classify(context: RecoveryContext): RecoveryAction {
        return when {
            // Scenario 1: Overnight interruption (>8 hours stale)
            context.staleDurationMs > 8 * 60 * 60 * 1000L ->
                RecoveryAction.OfferRecoveryOrDiscard(
                    reason = "Work was interrupted overnight",
                    staleDurationMs = context.staleDurationMs,
                    preservedWorkSummary = context.workSummary
                )

            // Scenario 2: Brief app kill/reopen (<2 minutes)
            context.staleDurationMs < 2 * 60 * 1000L && context.hadActiveTimer ->
                RecoveryAction.SilentResume(
                    adjustedElapsedMs = context.staleDurationMs,
                    reason = "Brief interruption — resuming seamlessly"
                )

            // Scenario 3: Medium stale (2 min – 8 hours) with active timer
            context.hadActiveTimer ->
                RecoveryAction.OfferResumeWithDriftWarning(
                    driftMs = context.staleDurationMs,
                    reason = "Timer was interrupted for ${formatDuration(context.staleDurationMs)}"
                )

            // Scenario 4: Stale paused work (paused before interruption, >4 hours)
            context.wasPaused && context.staleDurationMs > 4 * 60 * 60 * 1000L ->
                RecoveryAction.OfferRecoveryOrDiscard(
                    reason = "Paused work found from ${formatDuration(context.staleDurationMs)} ago",
                    staleDurationMs = context.staleDurationMs,
                    preservedWorkSummary = context.workSummary
                )

            // Scenario 5: Paused work, not too stale
            context.wasPaused ->
                RecoveryAction.SilentResume(
                    adjustedElapsedMs = 0,
                    reason = "Resuming paused work"
                )

            // Scenario 6: Unfinished save
            context.hadPendingSave ->
                RecoveryAction.RetrySave(
                    reason = "Previous save was interrupted"
                )

            // Scenario 7: No meaningful work to recover
            !context.hasMeaningfulWork ->
                RecoveryAction.SilentDiscard(
                    reason = "No meaningful work to recover"
                )

            // Scenario 8: Work already saved (repeated finish taps)
            context.saveAlreadyCompleted ->
                RecoveryAction.SilentDiscard(
                    reason = "Work already saved"
                )

            // Default: offer recovery
            else ->
                RecoveryAction.OfferRecoveryOrDiscard(
                    reason = "Interrupted work found",
                    staleDurationMs = context.staleDurationMs,
                    preservedWorkSummary = context.workSummary
                )
        }
    }

    private fun formatDuration(ms: Long): String {
        val hours = ms / (60 * 60 * 1000)
        val minutes = (ms % (60 * 60 * 1000)) / (60 * 1000)
        return when {
            hours > 0 -> "${hours}h ${minutes}m"
            minutes > 0 -> "${minutes}m"
            else -> "<1m"
        }
    }
}

/**
 * Observable context at recovery time.
 */
data class RecoveryContext(
    val staleDurationMs: Long = 0,
    val hadActiveTimer: Boolean = false,
    val wasPaused: Boolean = false,
    val hadPendingSave: Boolean = false,
    val wasInDifferentWorkspace: Boolean = false,
    val hasMeaningfulWork: Boolean = false,
    val saveAlreadyCompleted: Boolean = false,
    val workSummary: String = "",
    val lastPhase: JobPhase = JobPhase.SETUP
)

/**
 * Deterministic recovery action — same context always produces same action.
 */
sealed class RecoveryAction {
    abstract val reason: String

    /** Resume silently without user prompt */
    data class SilentResume(
        val adjustedElapsedMs: Long,
        override val reason: String
    ) : RecoveryAction()

    /** Resume but warn about timer drift */
    data class OfferResumeWithDriftWarning(
        val driftMs: Long,
        override val reason: String
    ) : RecoveryAction()

    /** Show recovery dialog — user chooses resume or discard */
    data class OfferRecoveryOrDiscard(
        override val reason: String,
        val staleDurationMs: Long,
        val preservedWorkSummary: String
    ) : RecoveryAction()

    /** Retry a previously failed save */
    data class RetrySave(
        override val reason: String
    ) : RecoveryAction()

    /** Discard silently — nothing valuable to recover */
    data class SilentDiscard(
        override val reason: String
    ) : RecoveryAction()
}

