package com.example.fieldtrack.core.session.identityfoundation
import com.example.fieldtrack.data.local.entity.SessionEntity import com.example.fieldtrack.data.local.entity.UserEntity import com.example.fieldtrack.data.repository.SessionRepository import com.example.fieldtrack.data.repository.UserRepository import java.util.UUID import kotlinx.coroutines.flow.MutableStateFlow import kotlinx.coroutines.flow.StateFlow import kotlinx.coroutines.flow.asStateFlow
/** * R36 — identity/session architecture coordinator. * * Scope in this phase: * - Restore latest session on app launch. * - Logout clears persisted session. * - No org join/invite/role switching orchestration yet. */ class SessionManager( private val userRepository: UserRepository, private val sessionRepository: SessionRepository ) {
private val _state = MutableStateFlow(IdentitySessionState.UNAUTHENTICATED) val state: StateFlow<IdentitySessionState> = _state.asStateFlow()
private val _currentSession = MutableStateFlow<SessionEntity?>(null) val currentSession: StateFlow<SessionEntity?> = _currentSession.asStateFlow()
suspend fun restoreSessionOnLaunch() { val session = sessionRepository.getLatestSession() if (session == null) { _currentSession.value = null _state.value = IdentitySessionState.UNAUTHENTICATED return }
val user = userRepository.getUserById(session.userId) if (user == null) { sessionRepository.clearSession() _currentSession.value = null _state.value = IdentitySessionState.UNAUTHENTICATED return }
if (user.status.equals(SUSPENDED_STATUS, ignoreCase = true)) { _currentSession.value = session _state.value = IdentitySessionState.SUSPENDED return }
val refreshed = session.copy(lastActiveAt = System.currentTimeMillis()) sessionRepository.upsertSession(refreshed) _currentSession.value = refreshed _state.value = IdentitySessionState.AUTHENTICATED }
suspend fun authenticate( userId: String, mobileNumber: String, displayName: String, activeRole: String ): SessionEntity? { _state.value = IdentitySessionState.AUTHENTICATING
val now = System.currentTimeMillis() val existing = userRepository.getUserById(userId) val user = UserEntity( userId = userId, mobileNumber = mobileNumber, displayName = displayName, status = existing?.status ?: ACTIVE_STATUS, createdAt = existing?.createdAt ?: now, updatedAt = now ) userRepository.upsertUser(user)
if (user.status.equals(SUSPENDED_STATUS, ignoreCase = true)) { _currentSession.value = null _state.value = IdentitySessionState.SUSPENDED return null }
val session = SessionEntity( sessionId = UUID.randomUUID().toString(), userId = userId, activeOrganizationId = null, activeRole = activeRole, loginAt = now, lastActiveAt = now ) sessionRepository.upsertSession(session) _currentSession.value = session _state.value = IdentitySessionState.AUTHENTICATED return session }
suspend fun logout() { sessionRepository.clearSession() _currentSession.value = null _state.value = IdentitySessionState.UNAUTHENTICATED }
companion object { const val ACTIVE_STATUS = "ACTIVE" const val SUSPENDED_STATUS = "SUSPENDED" } }

package com.example.fieldtrack.core.session.identityfoundation
import com.example.fieldtrack.data.local.entity.SessionEntity import com.example.fieldtrack.data.local.entity.UserEntity import com.example.fieldtrack.data.repository.SessionRepository import com.example.fieldtrack.data.repository.UserRepository import java.util.UUID import kotlinx.coroutines.flow.MutableStateFlow import kotlinx.coroutines.flow.StateFlow import kotlinx.coroutines.flow.asStateFlow
/** * R36 — identity/session architecture coordinator. * * Scope in this phase: * - Restore latest session on app launch. * - Logout clears persisted session. * - No org join/invite/role switching orchestration yet. */ class SessionManager( private val userRepository: UserRepository, private val sessionRepository: SessionRepository ) {
private val _state = MutableStateFlow(IdentitySessionState.UNAUTHENTICATED) val state: StateFlow<IdentitySessionState> = _state.asStateFlow()
private val _currentSession = MutableStateFlow<SessionEntity?>(null) val currentSession: StateFlow<SessionEntity?> = _currentSession.asStateFlow()
suspend fun restoreSessionOnLaunch() { val session = sessionRepository.getLatestSession() if (session == null) { _currentSession.value = null _state.value = IdentitySessionState.UNAUTHENTICATED return }
val user = userRepository.getUserById(session.userId) if (user == null) { sessionRepository.clearSession() _currentSession.value = null _state.value = IdentitySessionState.UNAUTHENTICATED return }
if (user.status.equals(SUSPENDED_STATUS, ignoreCase = true)) { _currentSession.value = session _state.value = IdentitySessionState.SUSPENDED return }
val refreshed = session.copy(lastActiveAt = System.currentTimeMillis()) sessionRepository.upsertSession(refreshed) _currentSession.value = refreshed _state.value = IdentitySessionState.AUTHENTICATED }
suspend fun authenticate( userId: String, mobileNumber: String, displayName: String, activeRole: String ): SessionEntity? { _state.value = IdentitySessionState.AUTHENTICATING
val now = System.currentTimeMillis() val existing = userRepository.getUserById(userId) val user = UserEntity( userId = userId, mobileNumber = mobileNumber, displayName = displayName, status = existing?.status ?: ACTIVE_STATUS, createdAt = existing?.createdAt ?: now, updatedAt = now ) userRepository.upsertUser(user)
if (user.status.equals(SUSPENDED_STATUS, ignoreCase = true)) { _currentSession.value = null _state.value = IdentitySessionState.SUSPENDED return null }
val session = SessionEntity( sessionId = UUID.randomUUID().toString(), userId = userId, activeOrganizationId = null, activeRole = activeRole, loginAt = now, lastActiveAt = now ) sessionRepository.upsertSession(session) _currentSession.value = session _state.value = IdentitySessionState.AUTHENTICATED return session }
/** * R40 — OTP-first login surface. * * If a user with this mobile number exists, it reuses that user id * (device replacement / relogin path). Otherwise, it creates one. */ suspend fun authenticateWithOtp( mobileNumber: String, defaultRole: String = "OPERATOR" ): SessionEntity? { val normalized = mobileNumber.trim() val existingByMobile = userRepository.getUserByMobileNumber(normalized) val resolvedUserId = existingByMobile?.userId ?: "u_${UUID.randomUUID()}" val resolvedName = existingByMobile?.displayName?.takeIf { it.isNotBlank() } ?: "Operator" return authenticate( userId = resolvedUserId, mobileNumber = normalized, displayName = resolvedName, activeRole = defaultRole ) }
suspend fun updateProfile(displayName: String) { val session = _currentSession.value ?: return userRepository.updateDisplayName(session.userId, displayName.trim()) }
suspend fun setActiveContext( activeOrganizationId: String?, activeRole: String ): SessionEntity? { val current = _currentSession.value ?: return null val updated = current.copy( activeOrganizationId = activeOrganizationId, activeRole = activeRole, lastActiveAt = System.currentTimeMillis() ) sessionRepository.upsertSession(updated) _currentSession.value = updated return updated }
suspend fun logout() { sessionRepository.clearSession() _currentSession.value = null _state.value = IdentitySessionState.UNAUTHENTICATED }
companion object { const val ACTIVE_STATUS = "ACTIVE" const val SUSPENDED_STATUS = "SUSPENDED" } }

