import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import com.example.fieldtrack.data.local.entity.JobEntity
import com.example.fieldtrack.data.local.entity.MachineType
import com.example.fieldtrack.data.local.entity.PaymentEntity
import com.example.fieldtrack.data.local.entity.PricingMode
import com.example.fieldtrack.data.model.toSegmentGroups
import com.example.fieldtrack.util.CalculationUtils
import com.example.fieldtrack.util.DateTimeUtils

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SummaryScreen(
    viewModel: SummaryViewModel,
    onNavigateBack: () -> Unit,
    onJobClick: (Long) -> Unit = {},
    onCustomerClick: (String) -> Unit = {},
    modifier: Modifier = Modifier
) {
    val uiState by viewModel.uiState.collectAsState()
    val snackbarHostState = remember { SnackbarHostState() }

    LaunchedEffect(uiState.errorMessage) {
        uiState.errorMessage?.let { message ->
            snackbarHostState.showSnackbar(message)
            viewModel.clearError()
        }
    }

    // Advanced filter bottom sheet
    if (uiState.showFilterSheet) {
        AdvancedFilterSheet(
            currentFilter = uiState.advancedFilter,
            machines = uiState.machines,
            onApply = { viewModel.applyAdvancedFilter(it) },
            onReset = { viewModel.resetAdvancedFilter() },
            onDismiss = { viewModel.hideFilterSheet() }
        )
    }

    // Job Info bottom sheet (for paid jobs)
    if (uiState.showJobInfoSheet && uiState.selectedJobForInfo != null) {
        val infoJob = uiState.selectedJobForInfo!!
        val infoCustomerName = infoJob.customerId
            ?.let { uiState.customerMap[it]?.name }
            ?: "Unassigned"
        JobInfoSheet(
            job = infoJob,
            customerName = infoCustomerName,
            payments = uiState.jobInfoPayments,
            onDismiss = { viewModel.hideJobInfo() },
            onViewFullDetails = {
                viewModel.hideJobInfo()
                infoJob.customerId?.let { onCustomerClick(it) }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("${uiState.selectedDateFilter.displayName} Jobs") },
                navigationIcon = {
                    IconButton(onClick = onNavigateBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                }
            )
        },
        snackbarHost = { SnackbarHost(snackbarHostState) }
    ) { paddingValues ->
        if (uiState.isLoading) {
            Box(Modifier.fillMaxSize().padding(paddingValues), contentAlignment = Alignment.Center) {
                CircularProgressIndicator()
            }
        } else {
            LazyColumn(
                modifier = Modifier.fillMaxSize().padding(paddingValues).padding(horizontal = 16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                item {
                    Spacer(Modifier.height(4.dp))

                    // Date filter chips
                    Text(" Date Range", style = MaterialTheme.typography.titleSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant)
                    Spacer(Modifier.height(4.dp))
                    LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        items(DateFilter.entries) { filter ->
                            FilterChip(
                                selected = uiState.selectedDateFilter == filter,
                                onClick = { viewModel.setDateFilter(filter) },
                                label = { Text(filter.displayName) },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = MaterialTheme.colorScheme.primaryContainer
                                )
                            )
                        }
                    }

                    Spacer(Modifier.height(12.dp))

                    // Summary Card
                    SummaryCard(
                        totalEarnings = uiState.totalEarnings,
                        paidAmount = uiState.paidAmount,
                        unpaidAmount = uiState.unpaidAmount,
                        jobCount = uiState.jobCount,
                        label = uiState.selectedDateFilter.displayName
                    )

                    Spacer(Modifier.height(12.dp))

                    // Payment filter chips
                    Text(" Payment Status", style = MaterialTheme.typography.titleSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant)
                    Spacer(Modifier.height(4.dp))
                    LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        items(PaymentFilter.entries) { filter ->
                            FilterChip(
                                selected = uiState.selectedPaymentFilter == filter,
                                onClick = { viewModel.setPaymentFilter(filter) },
                                label = {
                                    Text(when (filter) {
                                        PaymentFilter.ALL -> " All"
                                        PaymentFilter.UNPAID -> "⏳ Unpaid"
                                        PaymentFilter.PARTIAL -> "⚠️ Partial"
                                        PaymentFilter.PAID -> "✅ Paid"
                                    })
                                },
                                colors = FilterChipDefaults.filterChipColors(
                                    selectedContainerColor = when (filter) {
                                        PaymentFilter.ALL -> MaterialTheme.colorScheme.primaryContainer
                                        PaymentFilter.UNPAID -> MaterialTheme.colorScheme.errorContainer
                                        PaymentFilter.PARTIAL -> MaterialTheme.colorScheme.secondaryContainer
                                        PaymentFilter.PAID -> MaterialTheme.colorScheme.tertiaryContainer
                                    }
                                )
                            )
                        }
                    }

                    Spacer(Modifier.height(12.dp))

                    // Advanced filters button + clear
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        if (uiState.jobs.isNotEmpty()) {
                            Text("Jobs (${uiState.jobs.size})",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold)
                        } else {
                            Spacer(Modifier.weight(1f))
                        }
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            if (uiState.advancedFilter.isActive) {
                                TextButton(onClick = { viewModel.resetAdvancedFilter() }) {
                                    Text("✕ Clear", color = MaterialTheme.colorScheme.error)
                                }
                            }
                            OutlinedButton(
                                onClick = { viewModel.showFilterSheet() },
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                val count = uiState.advancedFilter.activeFilterCount
                                Text(
                                    if (count > 0) " Filters ($count) ●" else " Filters"
                                )
                            }
                        }
                    }

                    // Active filter summary (compact text below button)
                    if (uiState.advancedFilter.isActive) {
                        Text(
                            text = uiState.advancedFilter.summaryText,
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.primary,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.padding(top = 4.dp)
                        )
                    }
                }

                if (uiState.jobs.isEmpty()) {
                    item { EmptyJobsMessage() }
                } else if (uiState.jobListMode == JobListMode.GROUPED_BY_CUSTOMER) {
                    // Grouped by customer mode — no expand, info icon opens sheet
                    items(
                        items = uiState.customerJobGroups,
                        key = { it.customerId ?: "unassigned" }
                    ) { group ->
                        CustomerGroupRow(
                            group = group,
                            onClick = {
                                if (group.customerId != null) onCustomerClick(group.customerId)
                            },
                            onInfoClick = { viewModel.showGroupInfo(group) }
                        )
                    }
                } else {
                    items(items = uiState.jobs, key = { it.id }) { job ->
                        val customerName = job.customerId
                            ?.let { uiState.customerMap[it]?.name }
                            ?: "Unassigned"
                        JobCard(
                            job = job,
                            customerName = customerName,
                            onClick = { onJobClick(job.id) },
                            onDelete = { viewModel.deleteJob(job) },
                            onInfoClick = { viewModel.showJobInfo(job) }
                        )
                    }
                }

                item { Spacer(Modifier.height(120.dp)) }
            }
        }
    }
}

@Composable
private fun SummaryCard(
    totalEarnings: Double,
    paidAmount: Double,
    unpaidAmount: Double,
    jobCount: Int,
    label: String
) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(20.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer)
    ) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(" $label Earnings",
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.onPrimaryContainer)
            Spacer(Modifier.height(12.dp))
            Text(CalculationUtils.formatCurrency(totalEarnings),
                style = MaterialTheme.typography.displayMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onPrimaryContainer)
            Spacer(Modifier.height(8.dp))
            Text("$jobCount ${if (jobCount == 1) "job" else "jobs"}",
                style = MaterialTheme.typography.bodyLarge,
                color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f))

            if (totalEarnings > 0) {
                Spacer(Modifier.height(16.dp))
                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceEvenly) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text("✅ Collected", style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.7f))
                        Text(CalculationUtils.formatCurrencyShort(paidAmount),
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onPrimaryContainer)
                    }
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text("⏳ Pending", style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.7f))
                        Text(CalculationUtils.formatCurrencyShort(unpaidAmount),
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                            color = if (unpaidAmount > 0) MaterialTheme.colorScheme.error
                                    else MaterialTheme.colorScheme.onPrimaryContainer)
                    }
                }
            }
        }
    }
}

@Composable
private fun JobCard(
    job: JobEntity,
    customerName: String = "Unassigned",
    onClick: () -> Unit,
    onDelete: () -> Unit,
    onInfoClick: (() -> Unit)? = null
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() },
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            // === Header: Customer name + Total amount + info icon ===
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = customerName,
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false)
                )
                Row(verticalAlignment = Alignment.CenterVertically) {
                    if (onInfoClick != null && job.isFullyPaid) {
                        IconButton(
                            onClick = onInfoClick,
                            modifier = Modifier.size(32.dp)
                        ) {
                            Icon(
                                Icons.Outlined.Info,
                                contentDescription = "Info",
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                        Spacer(Modifier.width(4.dp))
                    }
                    Text(
                        text = CalculationUtils.formatCurrencyShort(job.totalAmount),
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                }
            }

            // === Second line: Machine icon + Segment summary ===
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = getMachineEmoji(job.machineType.name),
                    style = MaterialTheme.typography.titleMedium
                )
                val segments = remember(job.segmentsJson) {
                    com.example.fieldtrack.util.SegmentSerializer.fromJson(job.segmentsJson)
                }
                if (segments.isNotEmpty()) {
                    com.example.fieldtrack.ui.components.SegmentSummaryCompact(
                        segments = segments,
                        showTotal = false,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                } else {
                    // Fallback: legacy compact summary
                    val fallback = when (job.derivedPricingMode) {
                        PricingMode.TIME -> {
                            val mins = job.durationMinutes ?: 0
                            val h = mins / 60; val m = mins % 60
                            val dur = when {
                                h > 0 && m > 0 -> "${h}h ${m}m"
                                h > 0 -> "${h}h"
                                else -> "${m}m"
                            }
                            dur
                        }
                        PricingMode.TRIP -> "${job.tripCount ?: 0} trips"
                        PricingMode.DISTANCE -> "${job.distanceKm ?: 0.0} km"
                        PricingMode.TRIP_AND_DISTANCE -> "${job.tripCount ?: 0} trips • ${job.distanceKm ?: 0.0} km"
                    }
                    Text(
                        text = fallback,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            }

            // === Third line: Payment status ===
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                val paymentText = when {
                    job.isFullyPaid -> "✅ Paid"
                    job.paidAmount > 0 -> "Paid ${CalculationUtils.formatCurrencyShort(job.paidAmount)} • Due ${CalculationUtils.formatCurrencyShort(job.remainingAmount)}"
                    else -> "Due ${CalculationUtils.formatCurrencyShort(job.remainingAmount)}"
                }
                val paymentColor = when {
                    job.isFullyPaid -> MaterialTheme.colorScheme.tertiary
                    job.paidAmount > 0 -> MaterialTheme.colorScheme.secondary
                    else -> MaterialTheme.colorScheme.error
                }
                Text(
                    text = paymentText,
                    style = MaterialTheme.typography.bodySmall,
                    color = paymentColor,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false)
                )

                // Date (low emphasis)
                Text(
                    text = DateTimeUtils.formatDate(job.createdAt),
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                )
            }
        }
    }
}

@Composable
private fun EmptyJobsMessage() {
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
    ) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(32.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text("", style = MaterialTheme.typography.displayMedium)
            Spacer(Modifier.height(16.dp))
            Text("No jobs found for this period",
                style = MaterialTheme.typography.titleMedium, textAlign = TextAlign.Center)
            Spacer(Modifier.height(8.dp))
            Text("Start a new job from the home screen\nor try a different date range",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant, textAlign = TextAlign.Center)
        }
    }
}

private fun getMachineEmoji(machineType: String): String {
    return when (machineType) {
        "TRACTOR" -> ""
        "TROLLEY" -> ""
        "HARVESTER" -> ""
        else -> ""
    }
}

@Composable
private fun CustomerGroupRow(
    group: CustomerJobGroup,
    onClick: () -> Unit,
    onInfoClick: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() },
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.5f)
        )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = group.customerName,
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "${group.jobs.size} job${if (group.jobs.size != 1) "s" else ""}",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    if (group.remainingAmount > 0) {
                        Text(
                            text = "• Due ${CalculationUtils.formatCurrencyShort(group.remainingAmount)}",
                            style = MaterialTheme.typography.bodySmall,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.error
                        )
                    }
                }
            }

            Text(
                text = CalculationUtils.formatCurrencyShort(group.totalAmount),
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(Modifier.width(4.dp))

            IconButton(
                onClick = onInfoClick,
                modifier = Modifier.size(32.dp)
            ) {
                Icon(
                    Icons.Outlined.Info,
                    contentDescription = "Info",
                    tint = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.size(20.dp)
                )
            }
        }
    }
}

// ================== Job Info Bottom Sheet ==================

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun JobInfoSheet(
    job: JobEntity,
    customerName: String,
    payments: List<PaymentEntity>,
    onDismiss: () -> Unit,
    onViewFullDetails: () -> Unit
) {
    ModalBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = rememberModalBottomSheetState()
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 20.dp)
                .padding(bottom = 32.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // === HEADER ===
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(
                        text = customerName,
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        text = "✅ Collected",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.tertiary
                    )
                }
                Text(
                    text = CalculationUtils.formatCurrencyShort(job.totalAmount),
                    style = MaterialTheme.typography.headlineSmall,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )
            }

            HorizontalDivider()

            // === SECTION: WORK ===
            Text(
                text = "Work",
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = getMachineEmoji(job.machineType.name),
                    style = MaterialTheme.typography.titleMedium
                )
                Text(
                    text = job.machineType.displayName,
                    style = MaterialTheme.typography.bodyMedium
                )
            }

            // Segment summary
            val segments = remember(job.segmentsJson) {
                com.example.fieldtrack.util.SegmentSerializer.fromJson(job.segmentsJson)
            }
            if (segments.isNotEmpty()) {
                com.example.fieldtrack.ui.components.SegmentSummaryCompact(
                    segments = segments,
                    showTotal = true
                )
                // Grouped breakdown if multiple rates
                val groups = remember(segments) {
                    segments.toSegmentGroups()
                }
                if (groups.size > 1) {
                    Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        groups.forEach { group ->
                            val label = when (group.type) {
                                PricingMode.TRIP -> "${group.totalQuantity.toInt()} trips × ${CalculationUtils.formatCurrencyShort(group.rate)}"
                                PricingMode.TIME -> {
                                    val mins = group.totalQuantity.toInt()
                                    val h = mins / 60; val m = mins % 60
                                    val dur = when {
                                        h > 0 && m > 0 -> "${h}h ${m}m"
                                        h > 0 -> "${h}h"
                                        else -> "${m}m"
                                    }
                                    "$dur × ${CalculationUtils.formatCurrencyShort(group.rate)}/hr"
                                }
                                else -> "${group.totalQuantity.toInt()} × ${CalculationUtils.formatCurrencyShort(group.rate)}"
                            }
                            Text(
                                text = "  $label = ${CalculationUtils.formatCurrencyShort(group.totalAmount)}",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                }
            } else {
                // Fallback legacy summary
                val fallback = when (job.derivedPricingMode) {
                    PricingMode.TIME -> {
                        val mins = job.durationMinutes ?: 0
                        val h = mins / 60; val m = mins % 60
                        val dur = when {
                            h > 0 && m > 0 -> "${h}h ${m}m"
                            h > 0 -> "${h}h"
                            else -> "${m}m"
                        }
                        "$dur @ ${CalculationUtils.formatCurrencyShort(job.rate)}/min"
                    }
                    PricingMode.TRIP -> "${job.tripCount ?: 0} trips @ ${CalculationUtils.formatCurrencyShort(job.rate)}/trip"
                    PricingMode.DISTANCE -> "${job.distanceKm ?: 0.0} km @ ${CalculationUtils.formatCurrencyShort(job.rate)}/km"
                    PricingMode.TRIP_AND_DISTANCE -> "${job.tripCount ?: 0} trips • ${job.distanceKm ?: 0.0} km"
                }
                Text(
                    text = fallback,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }

            // === SECTION: PAYMENTS ===
            if (payments.isNotEmpty()) {
                HorizontalDivider()
                Text(
                    text = "Payments",
                    style = MaterialTheme.typography.titleSmall,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    payments.forEach { payment ->
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "${payment.method.emoji} ${CalculationUtils.formatCurrencyShort(payment.amount)}",
                                style = MaterialTheme.typography.bodyMedium
                            )
                            Text(
                                text = DateTimeUtils.formatDate(payment.paidAt) + " " + DateTimeUtils.formatTime(payment.paidAt),
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                            )
                        }
                        if (!payment.note.isNullOrBlank()) {
                            Text(
                                text = "  \"${payment.note}\"",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                            )
                        }
                    }
                }
            }

            // === SECTION: META ===
            HorizontalDivider()
            Text(
                text = "Job date: ${DateTimeUtils.formatDate(job.createdAt)}",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
            )

            // === FOOTER ===
            if (job.customerId != null) {
                Spacer(Modifier.height(8.dp))
                Button(
                    onClick = onViewFullDetails,
                    modifier = Modifier.fillMaxWidth().height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("View Full Details", fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

// ================== Advanced Filter Bottom Sheet ==================

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun AdvancedFilterSheet(
    currentFilter: JobFilterState,
    machines: List<com.example.fieldtrack.data.local.entity.MachineEntity>,
    onApply: (JobFilterState) -> Unit,
    onReset: () -> Unit,
    onDismiss: () -> Unit
) {
    // Local mutable copy of filter state
    var machineTypes by remember { mutableStateOf(currentFilter.machineTypes) }
    var machineIds by remember { mutableStateOf(currentFilter.machineIds) }
    var pricingModes by remember { mutableStateOf(currentFilter.pricingModes) }
    var sortBy by remember { mutableStateOf(currentFilter.sortBy) }

    ModalBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = rememberModalBottomSheetState()
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 20.dp)
                .padding(bottom = 32.dp)
        ) {
            // Header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(" Filters",
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Bold)
                TextButton(onClick = {
                    machineTypes = emptySet()
                    machineIds = emptySet()
                    pricingModes = emptySet()
                    sortBy = SortOption.NEWEST
                    onReset()
                }) { Text("Reset") }
            }

            Spacer(Modifier.height(16.dp))

            // Machine Type (multi-select)
            Text(" Machine Type",
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant)
            Spacer(Modifier.height(8.dp))
            Row(
                modifier = Modifier.horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                MachineType.entries.forEach { type ->
                    FilterChip(
                        selected = type in machineTypes,
                        onClick = {
                            machineTypes = if (type in machineTypes) {
                                // Drop ids tied to this type
                                val droppedIds = machines
                                    .filter { runCatching { MachineType.valueOf(it.type) }.getOrNull() == type }
                                    .map { it.machineId }
                                    .toSet()
                                machineIds = machineIds - droppedIds
                                machineTypes - type
                            } else machineTypes + type
                        },
                        label = { Text(type.displayName) }
                    )
                }
            }

            // ============ Machines (specific) — only when types selected ============
            if (machineTypes.isNotEmpty()) {
                val candidates = remember(machines, machineTypes) {
                    machines.filter {
                        runCatching { MachineType.valueOf(it.type) }.getOrNull() in machineTypes
                    }.sortedBy { it.name.lowercase() }
                }
                if (candidates.isNotEmpty()) {
                    Spacer(Modifier.height(16.dp))
                    Text(" Machines",
                        style = MaterialTheme.typography.titleSmall,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurfaceVariant)
                    Spacer(Modifier.height(8.dp))
                    Row(
                        modifier = Modifier.horizontalScroll(rememberScrollState()),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        candidates.forEach { m ->
                            FilterChip(
                                selected = m.machineId in machineIds,
                                onClick = {
                                    machineIds = if (m.machineId in machineIds)
                                        machineIds - m.machineId else machineIds + m.machineId
                                },
                                label = { Text(m.name) }
                            )
                        }
                    }
                }
            }

            Spacer(Modifier.height(16.dp))

            // Work Type (pricing mode, multi-select)
            Text("⚙️ Work Type",
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant)
            Spacer(Modifier.height(8.dp))
            Row(
                modifier = Modifier.horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                val modes = listOf(PricingMode.TIME, PricingMode.TRIP, PricingMode.TRIP_AND_DISTANCE)
                modes.forEach { mode ->
                    val label = when (mode) {
                        PricingMode.TIME -> "⏱️ Time Based"
                        PricingMode.TRIP -> " Trip Based"
                        PricingMode.TRIP_AND_DISTANCE -> " Trip+Distance"
                        else -> mode.displayName
                    }
                    FilterChip(
                        selected = mode in pricingModes,
                        onClick = {
                            pricingModes = if (mode in pricingModes)
                                pricingModes - mode else pricingModes + mode
                        },
                        label = { Text(label) }
                    )
                }
            }

            Spacer(Modifier.height(16.dp))

            // Sort By
            Text(" Sort By",
                style = MaterialTheme.typography.titleSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant)
            Spacer(Modifier.height(8.dp))
            Row(
                modifier = Modifier.horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                SortOption.entries.forEach { option ->
                    FilterChip(
                        selected = sortBy == option,
                        onClick = { sortBy = option },
                        label = { Text(option.displayName) },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = MaterialTheme.colorScheme.primaryContainer
                        )
                    )
                }
            }

            Spacer(Modifier.height(24.dp))

            // Apply button
            androidx.compose.material3.Button(
                onClick = {
                    onApply(JobFilterState(
                        machineTypes = machineTypes,
                        machineIds = machineIds,
                        pricingModes = pricingModes,
                        sortBy = sortBy
                    ))
                },
                modifier = Modifier.fillMaxWidth().height(52.dp),
                shape = RoundedCornerShape(16.dp)
            ) {
                Text("Apply Filters", fontWeight = FontWeight.Bold)
            }
        }
    }
}

