package com.example.fieldtrack.domain.observability
import com.example.fieldtrack.domain.event.OperationalEventRecorder import com.example.fieldtrack.domain.invariant.InvariantCheckState import com.example.fieldtrack.domain.invariant.InvariantViolation import com.example.fieldtrack.domain.invariant.OperationalInvariants import com.example.fieldtrack.domain.job.JobPhase import com.example.fieldtrack.domain.session.WorkspaceLifecycleState
/** * BEHAVIORAL DETERMINISM — PART 9: Operational Debug Overlay. * * Produces a compact snapshot of the entire operational state for * developer debugging. Hidden behind a debug flag — NEVER visible * in production. * * Pure logic. The snapshot is a data class that can be rendered * by any debug overlay composable. */ object OperationalDebugSnapshot {
/** Master debug flag — must be false in production builds */ var isDebugEnabled: Boolean = false private set
/** Enable debug mode (call only from debug builds) */ fun enableDebug() { isDebugEnabled = true }
/** * Capture the current operational state as a debug snapshot. * Returns null if debug is not enabled. */ fun capture(state: DebugInputState): DebugSnapshot? { if (!isDebugEnabled) return null
val invariantState = InvariantCheckState( phase = state.phase, isTimerTicking = state.isTimerTicking, timerStartTimeMs = state.timerStartTimeMs, activeTimerCount = state.activeTimerCount, isSaveInProgress = state.isSaveInProgress, hasWorkspace = state.hasWorkspace, hasValidJobData = state.hasValidJobData, machineId = state.machineId, lockedMachineId = state.lockedMachineId, isMachineLocked = state.isMachineLocked, segmentCount = state.segmentCount, segmentTotal = state.segmentTotal, calculatedTotal = state.calculatedTotal, paidAmount = state.paidAmount, snapshotVersion = state.snapshotVersion, previousSnapshotVersion = state.previousSnapshotVersion )
val violations = OperationalInvariants.validateAll(invariantState)
val lastEvent = OperationalEventRecorder.lastEvent()
return DebugSnapshot( capturedAt = System.currentTimeMillis(), phase = state.phase, workspaceLifecycle = state.workspaceLifecycle, fatigueLevel = state.fatigueLevel, recoveryClassification = state.recoveryClassification, invariantViolations = violations, lastEventDescription = lastEvent?.let { "#${it.sequence} ${it.event::class.simpleName} @ ${it.recordedAt}" }, totalEventsRecorded = OperationalEventRecorder.totalRecorded(), activeTimerCount = state.activeTimerCount, segmentCount = state.segmentCount, calculatedTotal = state.calculatedTotal, snapshotVersion = state.snapshotVersion ) } }
/** * Input state for debug snapshot capture. */ data class DebugInputState( val phase: JobPhase = JobPhase.SETUP, val workspaceLifecycle: WorkspaceLifecycleState = WorkspaceLifecycleState.CREATED, val isTimerTicking: Boolean = false, val timerStartTimeMs: Long? = null, val activeTimerCount: Int = 0, val isSaveInProgress: Boolean = false, val hasWorkspace: Boolean = false, val hasValidJobData: Boolean = false, val machineId: String? = null, val lockedMachineId: String? = null, val isMachineLocked: Boolean = false, val segmentCount: Int = 0, val segmentTotal: Double = 0.0, val calculatedTotal: Double = 0.0, val paidAmount: Double = 0.0, val snapshotVersion: Int = 0, val previousSnapshotVersion: Int = 0, val fatigueLevel: Int = 0, val recoveryClassification: String? = null )
/** * Compact debug snapshot — developer overlay data. */ data class DebugSnapshot( val capturedAt: Long, val phase: JobPhase, val workspaceLifecycle: WorkspaceLifecycleState, val fatigueLevel: Int, val recoveryClassification: String?, val invariantViolations: List<InvariantViolation>, val lastEventDescription: String?, val totalEventsRecorded: Long, val activeTimerCount: Int, val segmentCount: Int, val calculatedTotal: Double, val snapshotVersion: Int ) { /** Compact single-line summary for overlay */ val summary: String get() { val violationTag = if (invariantViolations.isEmpty()) "✅" else "⚠️${invariantViolations.size}" return "$phase | WS:$workspaceLifecycle | $violationTag | E:$totalEventsRecorded | V:$snapshotVersion" }
/** Whether any critical violations exist */ val hasCriticalViolations: Boolean get() = invariantViolations.any { it.severity == com.example.fieldtrack.domain.invariant.ViolationSeverity.CRITICAL } }

package com.example.fieldtrack.domain.testing
import com.example.fieldtrack.domain.job.JobPhase import com.example.fieldtrack.domain.recovery.RecoveryAction import com.example.fieldtrack.domain.recovery.RecoveryContext import com.example.fieldtrack.domain.recovery.RecoveryReplayScenario
/** * BEHAVIORAL DETERMINISM — PART 10: Interruption Chaos Testing. * * Defines field-condition chaos scenarios for deterministic testing. * Each scenario is a pure function that produces a RecoveryContext, * which can be fed to RecoveryReplayScenario.classify() to verify * deterministic behavior. * * Pure logic, zero Android dependencies, fully testable. */ object InterruptionChaosScenarios {
/** All defined chaos scenarios */ val allScenarios: List<ChaosScenario> = listOf( killDuringFinish(), killDuringSwitch(), batteryDeathDuringTimer(), staleOvernightRecovery(), repeatedRapidTaps(), simultaneousWorkspaceUpdates(), saveRetriesUnderInterruption(), machineReassignmentEdgeCase(), pausedThenKilled(), noWorkPhantom() )
// ── Scenario Definitions ──
/** Kill app during finish/save flow */ fun killDuringFinish(): ChaosScenario = ChaosScenario( name = "Kill during finish", description = "App killed while save is in progress", context = RecoveryContext( staleDurationMs = 30_000, hadActiveTimer = false, wasPaused = false, hadPendingSave = true, hasMeaningfulWork = true, lastPhase = JobPhase.SAVING, workSummary = "3 trips @ ₹500" ), expectedActionType = RecoveryAction.RetrySave::class.simpleName!! )
/** Kill app during workspace switch */ fun killDuringSwitch(): ChaosScenario = ChaosScenario( name = "Kill during workspace switch", description = "App killed while switching between active jobs", context = RecoveryContext( staleDurationMs = 5_000, hadActiveTimer = true, wasPaused = false, hadPendingSave = false, wasInDifferentWorkspace = true, hasMeaningfulWork = true, lastPhase = JobPhase.RUNNING, workSummary = "Timer: 45m" ), expectedActionType = RecoveryAction.SilentResume::class.simpleName!! )
/** Battery death during active timer */ fun batteryDeathDuringTimer(): ChaosScenario = ChaosScenario( name = "Battery death during timer", description = "Device battery died while timer was running", context = RecoveryContext( staleDurationMs = 3 * 60 * 60 * 1000L, // 3 hours hadActiveTimer = true, wasPaused = false, hadPendingSave = false, hasMeaningfulWork = true, lastPhase = JobPhase.RUNNING, workSummary = "Timer: 2h 15m before death" ), expectedActionType = RecoveryAction.OfferResumeWithDriftWarning::class.simpleName!! )
/** Stale overnight recovery */ fun staleOvernightRecovery(): ChaosScenario = ChaosScenario( name = "Stale overnight recovery", description = "App not opened since yesterday evening, work was in progress", context = RecoveryContext( staleDurationMs = 14 * 60 * 60 * 1000L, // 14 hours hadActiveTimer = true, wasPaused = false, hadPendingSave = false, hasMeaningfulWork = true, lastPhase = JobPhase.RUNNING, workSummary = "Timer: 1h 30m, Customer: Raj Kumar" ), expectedActionType = RecoveryAction.OfferRecoveryOrDiscard::class.simpleName!! )
/** Repeated rapid taps on finish button */ fun repeatedRapidTaps(): ChaosScenario = ChaosScenario( name = "Repeated rapid taps", description = "Operator taps finish/save rapidly multiple times", context = RecoveryContext( staleDurationMs = 500, hadActiveTimer = false, wasPaused = false, hadPendingSave = false, hasMeaningfulWork = false, saveAlreadyCompleted = true, lastPhase = JobPhase.SAVED, workSummary = "Already saved" ), expectedActionType = RecoveryAction.SilentDiscard::class.simpleName!! )
/** Simultaneous workspace updates from background sync */ fun simultaneousWorkspaceUpdates(): ChaosScenario = ChaosScenario( name = "Simultaneous workspace updates", description = "Multiple workspace state changes arrive concurrently", context = RecoveryContext( staleDurationMs = 1_000, hadActiveTimer = true, wasPaused = false, hadPendingSave = false, hasMeaningfulWork = true, lastPhase = JobPhase.RUNNING, workSummary = "Timer: 30m running" ), expectedActionType = RecoveryAction.SilentResume::class.simpleName!! )
/** Save retries under repeated interruption */ fun saveRetriesUnderInterruption(): ChaosScenario = ChaosScenario( name = "Save retries under interruption", description = "Save fails, app killed, reopened, save must retry", context = RecoveryContext( staleDurationMs = 60_000, hadActiveTimer = false, wasPaused = false, hadPendingSave = true, hasMeaningfulWork = true, lastPhase = JobPhase.SAVING, workSummary = "5 trips @ ₹400, save pending" ), expectedActionType = RecoveryAction.RetrySave::class.simpleName!! )
/** Machine reassignment edge case */ fun machineReassignmentEdgeCase(): ChaosScenario = ChaosScenario( name = "Machine reassignment edge case", description = "Machine deleted while job using it is in progress", context = RecoveryContext( staleDurationMs = 10_000, hadActiveTimer = true, wasPaused = false, hadPendingSave = false, hasMeaningfulWork = true, lastPhase = JobPhase.RUNNING, workSummary = "Timer: 15m, Machine: deleted" ), expectedActionType = RecoveryAction.SilentResume::class.simpleName!! )
/** Paused then killed */ fun pausedThenKilled(): ChaosScenario = ChaosScenario( name = "Paused then killed", description = "Work paused, app killed shortly after", context = RecoveryContext( staleDurationMs = 30 * 60 * 1000L, // 30 minutes hadActiveTimer = false, wasPaused = true, hadPendingSave = false, hasMeaningfulWork = true, lastPhase = JobPhase.PAUSED, workSummary = "Timer: 45m paused" ), expectedActionType = RecoveryAction.SilentResume::class.simpleName!! )
/** Phantom workspace (no work) */ fun noWorkPhantom(): ChaosScenario = ChaosScenario( name = "No work phantom", description = "Workspace created but no work ever started", context = RecoveryContext( staleDurationMs = 60 * 60 * 1000L, hadActiveTimer = false, wasPaused = false, hadPendingSave = false, hasMeaningfulWork = false, lastPhase = JobPhase.SETUP, workSummary = "" ), expectedActionType = RecoveryAction.SilentDiscard::class.simpleName!! )
// ── Verification ──
/** * Verify that all scenarios produce the expected recovery action type. * Returns list of failed scenarios (empty = all pass). */ fun verifyAll(): List<ChaosVerificationResult> { return allScenarios.map { scenario -> val action = RecoveryReplayScenario.classify(scenario.context) val actualType = action::class.simpleName ?: "Unknown" ChaosVerificationResult( scenario = scenario, actualActionType = actualType, passed = actualType == scenario.expectedActionType ) } } }
/** * A single chaos test scenario definition. */ data class ChaosScenario( val name: String, val description: String, val context: RecoveryContext, val expectedActionType: String )
/** * Result of verifying a chaos scenario. */ data class ChaosVerificationResult( val scenario: ChaosScenario, val actualActionType: String, val passed: Boolean )

package com.example.fieldtrack.ui.screens.newjob

import android.content.Intent
import androidx.compose.animation.*
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.*import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import com.example.fieldtrack.data.model.PaymentSnapshot
import com.example.fieldtrack.data.model.PaymentStatus
import com.example.fieldtrack.ui.components.PaymentStatusChip
import com.example.fieldtrack.util.ShareCardGenerator
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import com.example.fieldtrack.util.CalculationUtils

/**
 * Post-save completion review sheet.
 * Calm, rewarding summary — the FINAL state after save.
 *
 * Design principles:
 * - NEVER auto-navigates — user explicitly decides next action
 * - Operational continuity first, exit last
 * - Share survives app backgrounding (doesn't dismiss sheet)
 * - Save state is immutable once shown
 * - Clean vertical scan for field users
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun WorkCompletionSheet(
    summary: WorkCompletionSummary,
    onDone: () -> Unit,
    onStartAnother: () -> Unit,
    onDismiss: () -> Unit,
    /** Callback with payment snapshot when payment is recorded. */
    onPaymentRecorded: (PaymentSnapshot) -> Unit = {},
    /** Active works remaining for this customer. */
    activeWorksCount: Int = 0,
    onContinueActiveWork: () -> Unit = {},
    /** PART 2: Repeat exact same work (same customer, work type, machine, rate). */
    onRepeatSameWork: () -> Unit = onStartAnother,
    /** PART 4: Quick operational note callback. */
    onNoteAdded: (String) -> Unit = {},
    /** PART 6: Resume work if finish was accidental — psychological safety. */
    onResumeWork: (() -> Unit)? = null,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)

    // Local state for payment flow
    var showPaymentSheet by remember { mutableStateOf(false) }
    var paymentSnapshot by remember { mutableStateOf(summary.paymentSnapshot) }

    // PART 4: Quick operator note
    var operatorNote by remember { mutableStateOf("") }
    var showNoteInput by remember { mutableStateOf(false) }

    // Completion confidence indicators
    var paymentRecorded by remember { mutableStateOf(false) }
    var summaryShared by remember { mutableStateOf(false) }

    // Share debounce — prevents duplicates
    var isSharing by remember { mutableStateOf(false) }

    ModalBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = sheetState
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 12.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // 1. HEADER — calm confirmation (compact)
            Text(
                text = "✔ Work Saved",
                style = MaterialTheme.typography.labelMedium,
                fontWeight = FontWeight.SemiBold,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(4.dp))

            // PART 4: Single-line operational summary for instant comprehension
            // Examples: "5h 20m • ₹8,500 work • Payment pending"
            //           "12 packets • ₹3,200 collected"
            val operationalParts = buildList {
                if (summary.elapsedFormatted.isNotBlank()) add(summary.elapsedFormatted)
                if (summary.tripCount > 0) add("${summary.tripCount} loads")
                add(summary.totalFormatted + " work")
                val status = when {
                    paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PAID -> "Collected"
                    paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PARTIAL -> "Partial"
                    else -> "Payment pending"
                }
                add(status)
            }
            Text(
                text = operationalParts.joinToString(" • "),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                maxLines = 1
            )

            Spacer(modifier = Modifier.height(8.dp))

            // 2. AMOUNT — hero number with tabular numerals for stable scanning
            Text(
                text = summary.totalFormatted,
                style = MaterialTheme.typography.headlineMedium.copy(
                    fontFeatureSettings = "tnum"
                ),
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )

            // 2b. Payment state — calm one-liner below amount
            val paymentLabel = when {
                paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PAID -> "✔ Payment collected"
                paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PARTIAL -> "◐ Partial payment recorded"
                else -> "○ Payment pending"
            }
            Text(
                text = paymentLabel,
                style = MaterialTheme.typography.bodySmall,
                color = when {
                    paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PAID -> MaterialTheme.colorScheme.tertiary
                    paymentRecorded -> MaterialTheme.colorScheme.onSurfaceVariant
                    else -> MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                }
            )

            Spacer(modifier = Modifier.height(8.dp))

            // PRIMARY ACTIONS — continuity first
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(10.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)
                ),
                elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    // Work type + machine (single line)
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = "${summary.workEmoji} ${summary.workType}",
                            style = MaterialTheme.typography.bodyLarge,
                            fontWeight = FontWeight.SemiBold
                        )
                        if (summary.machineName != null) {
                            Text(
                                text = " • ${summary.machineName}",
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }

                    // Duration or loads (one line max)
                    val detailParts = buildList {
                        if (summary.tripCount > 0) add("${summary.tripCount} loads")
                        if (summary.elapsedFormatted.isNotBlank()) add(summary.elapsedFormatted)
                        if (summary.customerName != null) add(summary.customerName)
                    }
                    if (detailParts.isNotEmpty()) {
                        Text(
                            text = detailParts.joinToString("  •  "),
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    // Payment status (shows after payment recorded)
                    if (paymentSnapshot != null) {
                        PaymentStatusChip(
                            status = paymentSnapshot!!.paymentStatus
                        )
                    }
                }
            }

            // 4. PART 4: Quick note — optional, lightweight
            if (!showNoteInput) {
                TextButton(
                    onClick = { showNoteInput = true },
                    modifier = Modifier.align(Alignment.Start)
                ) {
                    Text(
                        " Add note",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            } else {
                OutlinedTextField(
                    value = operatorNote,
                    onValueChange = { if (it.length <= 150) operatorNote = it },
                    modifier = Modifier.fillMaxWidth(),
                    placeholder = { Text("e.g. Will pay tomorrow, Diesel included...") },
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp),
                    textStyle = MaterialTheme.typography.bodySmall,
                    supportingText = if (operatorNote.isNotEmpty()) {
                        { Text("${operatorNote.length}/150", style = MaterialTheme.typography.labelSmall) }
                    } else null
                )
                // Auto-save note when typing stops
                LaunchedEffect(operatorNote) {
                    if (operatorNote.isNotBlank()) {
                        kotlinx.coroutines.delay(500)
                        onNoteAdded(operatorNote)
                    }
                }
            }

            // 5. Continuity context — calm secondary rows with financial memory
            // PART 4: Use consistent vocabulary — "Running", "Paused", never "active", "in progress"
            val continuityItems = buildList {
                if (summary.customerPendingAmount > 0) {
                    add("Pending ₹${CalculationUtils.formatIndianGrouping(kotlin.math.round(summary.customerPendingAmount).toLong())} after this")
                } else if (paymentRecorded || summary.total <= 0) {
                    add("✓ Everything collected")
                }
                if (activeWorksCount > 0) {
                    // PART 4: "running" not "active"
                    add("$activeWorksCount other work${if (activeWorksCount != 1) "s" else ""} running")
                }
                summary.machineOtherActiveLabel?.let { add(it) }
            }
            if (continuityItems.isNotEmpty()) {
                Spacer(modifier = Modifier.height(6.dp))
                continuityItems.forEach { label ->
                    Text(
                        text = label,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                        modifier = Modifier.padding(vertical = 1.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Confidence indicators
            AnimatedVisibility(
                visible = paymentRecorded || summaryShared,
                enter = fadeIn() + expandVertically(),
                exit = fadeOut() + shrinkVertically()
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 8.dp),
                    horizontalArrangement = Arrangement.Center,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (paymentRecorded) {
                        Text(
                            text = "✔ Payment",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                    if (paymentRecorded && summaryShared) {
                        Text("  •  ", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.outlineVariant)
                    }
                    if (summaryShared) {
                        Text(
                            text = "✔ Shared",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                }
            }

            // PRIMARY ACTIONS — continuity first

            // Continue Active Work (only if same customer has remaining jobs)
            if (activeWorksCount > 0) {
                Button(
                    onClick = onContinueActiveWork,
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("Continue Working", fontWeight = FontWeight.SemiBold)
                }
                Spacer(modifier = Modifier.height(4.dp))
            }

            // Repeat Same Work — most common action after save
            Button(
                onClick = onRepeatSameWork,
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp)
            ) {
                Text(
                    "Repeat ${summary.workType}",
                    fontWeight = FontWeight.SemiBold
                )
            }

            Spacer(modifier = Modifier.height(4.dp))

            // Secondary row: Share + Collect + Done — all equal weight, compact
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                OutlinedButton(
                    onClick = onStartAnother,
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text("New Work", style = MaterialTheme.typography.labelMedium)
                }

                FilledTonalButton(
                    onClick = { showPaymentSheet = true },
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text(
                        if (paymentRecorded) "✔ Collected" else " Collect",
                        style = MaterialTheme.typography.labelMedium
                    )
                }

                OutlinedButton(
                    onClick = onDone,
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text(
                        if (paymentRecorded) "Done ✓" else "Later",
                        style = MaterialTheme.typography.labelMedium
                    )
                }
            }

            // Share — lightweight, bottom
            TextButton(
                onClick = {
                    if (isSharing) return@TextButton
                    isSharing = true
                    scope.launch {
                        try {
                            val status = paymentSnapshot?.paymentStatus ?: PaymentStatus.PENDING
                            val shareIntent = ShareCardGenerator.createShareIntent(
                                context = context,
                                summary = summary,
                                paymentStatus = status
                            )
                            context.startActivity(Intent.createChooser(shareIntent, "Share Summary"))
                            summaryShared = true
                        } finally {
                            delay(500)
                            isSharing = false
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                enabled = !isSharing
            ) {
                Text(
                    " Share summary",
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }

            // PART 6: Resume work — accidental finish safety net
            if (onResumeWork != null) {
                TextButton(
                    onClick = onResumeWork,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        "↩ Continue This Work",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))
        }
    }

    // Quick Payment Sheet
    if (showPaymentSheet) {
        QuickPaymentSheet(
            totalAmount = summary.total,
            onPaymentRecorded = { snapshot ->
                paymentSnapshot = snapshot
                paymentRecorded = true
                showPaymentSheet = false
                onPaymentRecorded(snapshot)
            },
            onDismiss = { showPaymentSheet = false }
        )
    }
}

