/**
 * Post-save completion review sheet.
 * Calm, rewarding summary — the FINAL state after save.
 *
 * Design principles:
 * - NEVER auto-navigates — user explicitly decides next action
 * - Operational continuity first, exit last
 * - Share survives app backgrounding (doesn't dismiss sheet)
 * - Save state is immutable once shown
 * - Clean vertical scan for field users
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun WorkCompletionSheet(
    summary: WorkCompletionSummary,
    onDone: () -> Unit,
    onStartAnother: () -> Unit,
    onDismiss: () -> Unit,
    /** Callback with payment snapshot when payment is recorded. */
    onPaymentRecorded: (PaymentSnapshot) -> Unit = {},
    /** Active works remaining for this customer. */
    activeWorksCount: Int = 0,
    onContinueActiveWork: () -> Unit = {},
    /** PART 2: Repeat exact same work (same customer, work type, machine, rate). */
    onRepeatSameWork: () -> Unit = onStartAnother,
    /** PART 4: Quick operational note callback. */
    onNoteAdded: (String) -> Unit = {},
    /** PART 6: Resume work if finish was accidental — psychological safety. */
    onResumeWork: (() -> Unit)? = null,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)

    // Local state for payment flow
    var showPaymentSheet by remember { mutableStateOf(false) }
    var paymentSnapshot by remember { mutableStateOf(summary.paymentSnapshot) }

    // PART 4: Quick operator note
    var operatorNote by remember { mutableStateOf("") }
    var showNoteInput by remember { mutableStateOf(false) }

    // Completion confidence indicators
    var paymentRecorded by remember { mutableStateOf(false) }
    var summaryShared by remember { mutableStateOf(false) }

    // Share debounce — prevents duplicates
    var isSharing by remember { mutableStateOf(false) }

    ModalBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = sheetState
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 24.dp, vertical = 12.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // 1. HEADER — calm confirmation (compact)
            Text(
                text = "✔ Work Saved",
                style = MaterialTheme.typography.labelMedium,
                fontWeight = FontWeight.SemiBold,
                color = MaterialTheme.colorScheme.primary
            )

            Spacer(modifier = Modifier.height(4.dp))

            // PART 4: Single-line operational summary for instant comprehension
            // Examples: "5h 20m • ₹8,500 work • Payment pending"
            //           "12 packets • ₹3,200 collected"
            val operationalParts = buildList {
                if (summary.elapsedFormatted.isNotBlank()) add(summary.elapsedFormatted)
                if (summary.tripCount > 0) add("${summary.tripCount} loads")
                add(summary.totalFormatted + " work")
                val status = when {
                    paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PAID -> "Collected"
                    paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PARTIAL -> "Partial"
                    else -> "Payment pending"
                }
                add(status)
            }
            Text(
                text = operationalParts.joinToString(" • "),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                maxLines = 1
            )

            Spacer(modifier = Modifier.height(8.dp))

            // 2. AMOUNT — hero number with tabular numerals for stable scanning
            Text(
                text = summary.totalFormatted,
                style = MaterialTheme.typography.headlineMedium.copy(
                    fontFeatureSettings = "tnum"
                ),
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )

            // 2b. Payment state — calm one-liner below amount
            val paymentLabel = when {
                paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PAID -> "✔ Payment collected"
                paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PARTIAL -> "◐ Partial payment recorded"
                else -> "○ Payment pending"
            }
            Text(
                text = paymentLabel,
                style = MaterialTheme.typography.bodySmall,
                color = when {
                    paymentRecorded && paymentSnapshot?.paymentStatus == PaymentStatus.PAID -> MaterialTheme.colorScheme.tertiary
                    paymentRecorded -> MaterialTheme.colorScheme.onSurfaceVariant
                    else -> MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                }
            )

            Spacer(modifier = Modifier.height(8.dp))

            // PRIMARY ACTIONS — continuity first
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(10.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)
                ),
                elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    // Work type + machine (single line)
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = "${summary.workEmoji} ${summary.workType}",
                            style = MaterialTheme.typography.bodyLarge,
                            fontWeight = FontWeight.SemiBold
                        )
                        if (summary.machineName != null) {
                            Text(
                                text = " • ${summary.machineName}",
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }

                    // Duration or loads (one line max)
                    val detailParts = buildList {
                        if (summary.tripCount > 0) add("${summary.tripCount} loads")
                        if (summary.elapsedFormatted.isNotBlank()) add(summary.elapsedFormatted)
                        if (summary.customerName != null) add(summary.customerName)
                    }
                    if (detailParts.isNotEmpty()) {
                        Text(
                            text = detailParts.joinToString("  •  "),
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    // Payment status (shows after payment recorded)
                    if (paymentSnapshot != null) {
                        PaymentStatusChip(
                            status = paymentSnapshot!!.paymentStatus
                        )
                    }
                }
            }

            // 4. PART 4: Quick note — optional, lightweight
            if (!showNoteInput) {
                TextButton(
                    onClick = { showNoteInput = true },
                    modifier = Modifier.align(Alignment.Start)
                ) {
                    Text(
                        " Add note",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            } else {
                OutlinedTextField(
                    value = operatorNote,
                    onValueChange = { if (it.length <= 150) operatorNote = it },
                    modifier = Modifier.fillMaxWidth(),
                    placeholder = { Text("e.g. Will pay tomorrow, Diesel included...") },
                    singleLine = true,
                    shape = RoundedCornerShape(12.dp),
                    textStyle = MaterialTheme.typography.bodySmall,
                    supportingText = if (operatorNote.isNotEmpty()) {
                        { Text("${operatorNote.length}/150", style = MaterialTheme.typography.labelSmall) }
                    } else null
                )
                // Auto-save note when typing stops
                LaunchedEffect(operatorNote) {
                    if (operatorNote.isNotBlank()) {
                        kotlinx.coroutines.delay(500)
                        onNoteAdded(operatorNote)
                    }
                }
            }

            // 5. Continuity context — calm secondary rows with financial memory
            // PART 4: Use consistent vocabulary — "Running", "Paused", never "active", "in progress"
            val continuityItems = buildList {
                if (summary.customerPendingAmount > 0) {
                    add("Pending ₹${CalculationUtils.formatIndianGrouping(kotlin.math.round(summary.customerPendingAmount).toLong())} after this")
                } else if (paymentRecorded || summary.total <= 0) {
                    add("✓ Everything collected")
                }
                if (activeWorksCount > 0) {
                    // PART 4: "running" not "active"
                    add("$activeWorksCount other work${if (activeWorksCount != 1) "s" else ""} running")
                }
                summary.machineOtherActiveLabel?.let { add(it) }
            }
            if (continuityItems.isNotEmpty()) {
                Spacer(modifier = Modifier.height(6.dp))
                continuityItems.forEach { label ->
                    Text(
                        text = label,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                        modifier = Modifier.padding(vertical = 1.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            // PRIMARY ACTIONS — continuity first

            // Continue Active Work (only if same customer has remaining jobs)
            if (activeWorksCount > 0) {
                Button(
