                    )
                }
            }

            // Share — lightweight, bottom
            TextButton(
                onClick = {
                    if (isSharing) return@TextButton
                    isSharing = true
                    scope.launch {
                        try {
                            val status = paymentSnapshot?.paymentStatus ?: PaymentStatus.PENDING
                            val shareIntent = ShareCardGenerator.createShareIntent(
                                context = context,
                                summary = summary,
                                paymentStatus = status
